// History — AQA GCSE History 8145 (KS3 foundations Y7–9, GCSE options Y10–11).
// Options: Germany 1890–1945 (period study 1A), Conflict and tension 1918–1939 (wider world depth study 1B),
// Britain: Health and the people c1000–present (thematic study 2A), Elizabethan England c1568–1603 (British depth study 2B).
const subject = { id: 'history', name: 'History', board: 'AQA', spec: '8145', color: '#b45309', icon: '📜', tiers: false };
const strands = [
  { id: 'hist-ks3', name: 'British History 1066–1900 (KS3)', color: '#a16207', icon: '🏰' },
  { id: 'hist-c20', name: 'The Twentieth Century (KS3)', color: '#64748b', icon: '🎖️' },
  { id: 'hist-germany', name: 'Germany 1890–1945', color: '#dc2626', icon: '🦅' },
  { id: 'hist-conflict', name: 'Conflict and Tension 1918–1939', color: '#7c3aed', icon: '🕊️' },
  { id: 'hist-health', name: 'Health and the People', color: '#059669', icon: '⚕️' },
  { id: 'hist-elizabeth', name: 'Elizabethan England', color: '#d97706', icon: '👑' },
  { id: 'hist-skills', name: 'Historical Skills', color: '#2563eb', icon: '🔎' },
];
const topics = [];
const styles = {};
const learn = {};
module.exports = { subject, strands, topics, styles, learn };

// ---- helpers ----
const M = (q, options, correct, explain, hint) => ({ type: 'mcq', q, options, correct, explain, ...(hint ? { hint } : {}) });
const MU = (q, options, correct, explain, hint) => ({ type: 'multi', q, options, correct, explain, ...(hint ? { hint } : {}) });
const T = (q, correct, explain, hint) => ({ type: 'tf', q, correct, explain, ...(hint ? { hint } : {}) });
const S = (q, answer, accept, explain, keywords, hint) => ({ type: 'short', q, answer, accept: [answer, ...(accept || [])], explain, ...(keywords ? { keywords } : {}), ...(hint ? { hint } : {}) });
const O = (q, options, explain, hint) => ({ type: 'order', q, options, explain, ...(hint ? { hint } : {}) });
const W = (source, it) => ({ ...it, q: source + it.q });
const src = (attr, text) => `<blockquote><i>${attr}</i><br>${text}</blockquote>`;
function addTopic(t, styleList, L) {
  t.tier = 'FH';
  t.styles = styleList.map((_, i) => `${t.id}-${i + 1}`);
  topics.push(t);
  styleList.forEach((s, i) => {
    const id = `${t.id}-${i + 1}`;
    styles[id] = { id, topicId: t.id, name: s.name, intro: s.intro, items: s.items };
  });
  learn[t.id] = { ...L, specRef: L.specRef || t.specRef };
}
const timeline = (rows) => `<table class="qt"><tr><th>Date</th><th>Event</th></tr>${rows.map(([d, e]) => `<tr><td>${d}</td><td>${e}</td></tr>`).join('')}</table>`;
const people = (rows) => `<table class="qt"><tr><th>Person</th><th>Why they matter</th></tr>${rows.map(([p, w]) => `<tr><td><b>${p}</b></td><td>${w}</td></tr>`).join('')}</table>`;
const worked = (q, steps, a) => `<div class="worked"><div class="wq">${q}</div><ol>${steps.map((s) => `<li>${s}</li>`).join('')}</ol><div class="wa">${a}</div></div>`;
// Extra practice items appended to a style's items array after its topic is added.
const more = (sid, items) => { styles[sid].items.push(...items); };

// =====================================================================
// YEAR 7 — The Norman Conquest
// =====================================================================
addTopic(
  { id: 'hist-y7-norman-conquest', strand: 'hist-ks3', year: 7, term: 1, name: 'The Norman Conquest',
    summary: 'Why there was a succession crisis in 1066, how William of Normandy won, and how the Normans took control of England.',
    specRef: 'DfE KS3 History: the development of Church, state and society in Medieval Britain 1066–1509' },
  [
    { name: '1066: claimants and battles', intro: 'When Edward the Confessor died childless in January 1066, four men had a claim to the throne. Two invasions and three battles decided who would rule England.',
      items: [
        M('Whose death in January 1066 caused the succession crisis?', ['Edward the Confessor', 'Harold Godwinson', 'Alfred the Great', 'Cnut'], 0, 'Edward the Confessor died on 5 January 1066 without children, so there was no obvious heir. Harold Godwinson was a claimant, not the dead king; Alfred and Cnut had died long before.'),
        M('Who was crowned King of England the day after Edward died?', ['Harold Godwinson', 'William of Normandy', 'Harald Hardrada', 'Edgar Atheling'], 0, 'Harold Godwinson, Earl of Wessex and the most powerful noble in England, was chosen by the Witan and crowned on 6 January 1066. William and Hardrada had to invade to press their claims; Edgar was too young and had little support.'),
        M('Which claimant was King of Norway?', ['Harald Hardrada', 'Harold Godwinson', 'William of Normandy', 'Tostig'], 0, 'Harald Hardrada was King of Norway and based his claim on an earlier deal between Viking kings. Tostig was Harold Godwinson’s exiled brother, who joined Hardrada.'),
        M('Why did William of Normandy believe he should be king?', ['He said Edward had promised him the throne and Harold had sworn an oath to support him', 'He was Edward’s eldest son', 'He had been chosen by the Witan', 'He had won the Battle of Fulford'], 0, 'William claimed Edward promised him the crown (around 1051) and that Harold swore an oath on holy relics to support him (around 1064). Edward had no children, and the Witan chose Harold, not William.'),
        M('Which claimant had the strongest <i>blood</i> claim but was only a teenager?', ['Edgar Atheling', 'Harold Godwinson', 'William of Normandy', 'Harald Hardrada'], 0, 'Edgar Atheling was Edward the Confessor’s great-nephew, so he was a blood relative of the old royal family, but he was young and had no army.'),
        S('In which year did the Battle of Hastings take place?', '1066', [], 'The Battle of Hastings was fought on 14 October 1066, near the town of Hastings in Sussex.'),
        M('Where did Harold Godwinson defeat Harald Hardrada and Tostig in September 1066?', ['Stamford Bridge', 'Hastings', 'Fulford', 'Pevensey'], 0, 'Harold marched north and won at Stamford Bridge (25 September 1066). Fulford (20 September) was a battle Hardrada won against the northern earls; Pevensey is where William landed.'),
        O('Put these events of 1066 in chronological order.', ['Edward the Confessor dies', 'Harold Godwinson is crowned', 'Battle of Stamford Bridge', 'William lands at Pevensey', 'Battle of Hastings', 'William is crowned at Westminster Abbey'], 'January: Edward dies and Harold is crowned. 25 September: Stamford Bridge. 28 September: William lands. 14 October: Hastings. 25 December: William is crowned.'),
        T('William of Normandy landed in England while Harold was in the north fighting the Vikings.', true, 'True. William landed at Pevensey on 28 September 1066, three days after Stamford Bridge, so Harold had to march his tired army back south.'),
        MU('Which TWO factors help explain why William won the Battle of Hastings?', ['Harold’s army was tired after marching north and back', 'The Normans used feigned retreats to break the shield wall', 'William had a much larger fleet of longships than Hardrada', 'Harold’s army had more cavalry', 'The battle was fought in Normandy'], [0, 1], 'Harold’s men had fought at Stamford Bridge and marched about 250 miles south; the Normans pretended to flee, so some English broke the shield wall to chase them. The English had few or no cavalry, and the battle was in Sussex.'),
        M('What English battle tactic held off the Normans for much of the day at Hastings?', ['The shield wall on top of a ridge', 'A cavalry charge', 'Longbow volleys', 'Cannon fire'], 0, 'The English housecarls formed a shield wall on Senlac ridge. Longbows were not used in great numbers until later and cannons did not yet exist in England.'),
        M('Who was Tostig?', ['Harold Godwinson’s exiled brother who joined Harald Hardrada', 'William’s half-brother', 'The Archbishop of Canterbury', 'A Norman knight'], 0, 'Tostig had been Earl of Northumbria but was exiled in 1065. He joined Hardrada’s invasion and died at Stamford Bridge. William’s half-brother was Bishop Odo.'),
        T('The Pope supported William’s invasion and sent him a papal banner.', true, 'True. The Pope gave William a papal banner, which made the invasion look like a holy cause and encouraged knights to join him.'),
        S('On what day of the year was William crowned king in 1066? (two words)', 'Christmas Day', ['christmas', '25 december', '25th december', 'december 25'], 'William was crowned in Westminster Abbey on Christmas Day, 25 December 1066.'),
        M('Which statement best explains why the timing of the invasions was a problem for Harold?', ['Two invasions came within weeks of each other at opposite ends of England', 'Both invasions came in winter', 'William and Hardrada landed together', 'He had disbanded the fyrd in January'], 0, 'Hardrada landed in the north in September and William in the south days later, so Harold could not be in both places. He had stood down the fyrd (part-time army) in early September, not January, because of the harvest.'),
        T('Harold Godwinson died at the Battle of Hastings.', true, 'True. Harold was killed at Hastings; the Bayeux Tapestry shows a figure with an arrow near the eye, though historians debate exactly how he died.'),
      ] },
    { name: 'Norman control of England', intro: 'Winning one battle did not mean controlling a country. William used castles, brutal force, a new landholding system and the Domesday Book to rule England.',
      items: [
        M('What was a motte and bailey castle?', ['A wooden tower on an earth mound with a fenced courtyard below', 'A stone palace with no walls', 'A fortified church', 'A Roman fort reused by the Saxons'], 0, 'The motte was the mound with a keep on top; the bailey was the enclosed yard. They were quick to build from earth and timber, which is why William built hundreds of them soon after 1066. Stone keeps came later.'),
        M('Why were motte and bailey castles built so quickly after 1066?', ['They used earth and timber and local forced labour', 'They were bought from Normandy ready-made', 'Saxons volunteered to build them', 'They were made from stone taken from churches'], 0, 'Earth and wood were easy to find, and English workers were forced to build them, so a castle could go up in weeks. Stone castles took years.'),
        M('What was the Harrying of the North (1069–70)?', ['William’s destruction of villages, crops and animals in northern England after a rebellion', 'A Viking raid on York', 'A famine caused by bad weather', 'The building of castles in the north'], 0, 'After rebels and Danes took York, William’s soldiers burned land between York and Durham. Thousands died of starvation. It was a deliberate punishment, not a natural famine.'),
        S('Which great survey of land and property did William order in 1085 (completed 1086)?', 'Domesday Book', ['domesday', 'the domesday book', 'doomsday book'], 'The Domesday Book recorded who held land, how many people, animals and ploughs there were, and what it was worth, so William knew what tax and service he could demand.'),
        M('What was the main purpose of the Domesday Book?', ['To find out what land and wealth there was so it could be taxed', 'To record the history of the Battle of Hastings', 'To list all the castles in England', 'To translate the Bible into English'], 0, 'It was a record for taxation and to settle land disputes. It does not describe the battle or list castles.'),
        O('Put the feudal system in order from top to bottom.', ['King', 'Barons (tenants-in-chief)', 'Knights', 'Peasants (villeins)'], 'The king owned all land and granted it to barons; barons granted land to knights; peasants worked the land. Each level owed service and loyalty to the one above.'),
        M('In the feudal system, what did a knight owe in return for land?', ['Military service', 'Nothing at all', 'A share of the castle', 'Payment to the peasants'], 0, 'Knights held land in return for fighting for their lord (usually around 40 days a year). Peasants owed labour; lords owed loyalty and service to the king.'),
        T('By 1086 most land in England was held by Normans rather than Anglo-Saxons.', true, 'True. The Domesday Book shows that by 1086 only a tiny proportion of land was still held by English lords; William had replaced the Anglo-Saxon nobility with his own followers.'),
        M('Who led a rebellion from the Isle of Ely in 1070–71?', ['Hereward the Wake', 'Edgar Atheling', 'Bishop Odo', 'Harold Hardrada'], 0, 'Hereward the Wake resisted from the marshes around Ely until 1071. Edgar was involved in the northern rebellion of 1069; Odo was William’s half-brother; Hardrada died in 1066.'),
        MU('Which TWO were ways William controlled the Church in England?', ['He replaced English bishops with Normans', 'He appointed Lanfranc as Archbishop of Canterbury', 'He closed all the monasteries', 'He made the Church Protestant', 'He banned church services'], [0, 1], 'William appointed Norman bishops and made Lanfranc Archbishop of Canterbury (1070). Monasteries were closed by Henry VIII, and Protestantism came in the 1500s.'),
        M('Which famous stone keep in London was begun by William?', ['The White Tower (Tower of London)', 'Windsor Round Tower', 'Hampton Court', 'Buckingham Palace'], 0, 'The White Tower at the Tower of London was started in the 1070s to dominate London. Hampton Court is Tudor and Buckingham Palace is much later.'),
        T('After 1066 the main language of the king’s court and government became Norman French and Latin.', true, 'True. The Norman nobles spoke French, and official documents were written in Latin; English continued as the language of ordinary people.'),
        M('Which word means a peasant who was not free and was tied to his lord’s land?', ['Villein', 'Baron', 'Thegn', 'Sheriff'], 0, 'A villein was an unfree peasant who worked the lord’s land and could not leave without permission. A thegn was an Anglo-Saxon noble; a sheriff ran a shire for the king.'),
        M('Which best describes William’s methods of control?', ['A mix of force (castles, harrying) and organisation (feudal system, Domesday)', 'Mostly peaceful agreements with English earls', 'Ruling only through the Church', 'Leaving the Anglo-Saxon nobility in charge'], 0, 'William used both: terror and castles to crush resistance, plus land grants and the Domesday Book to organise the country. He removed rather than relied on English earls after the rebellions.'),
        S('In what year was the Domesday survey completed?', '1086', [], 'The survey was ordered at Christmas 1085 and carried out in 1086, a year before William died (1087).'),
        T('William’s rule faced no rebellions after 1066.', false, 'False. There were rebellions in Exeter (1068), the north (1069–70), Ely (1070–71) and the Revolt of the Earls (1075).'),
      ] },
    { name: 'Evidence: the Bayeux Tapestry and chronicles', intro: 'Our knowledge of 1066 comes from sources made by people with a point of view. Ask who made a source, when and why.',
      items: [
        M('What is the Bayeux Tapestry?', ['A long embroidered cloth telling the story of the Norman Conquest', 'A Saxon law book', 'A painting in Westminster Abbey', 'A Viking saga'], 0, 'It is an embroidery about 70 metres long showing events from about 1064 to the Battle of Hastings. It is stitched, not painted.'),
        M('Who probably commissioned the Bayeux Tapestry?', ['Bishop Odo, William’s half-brother', 'Harold Godwinson', 'Edward the Confessor', 'Harald Hardrada'], 0, 'Most historians think Bishop Odo of Bayeux ordered it in the 1070s. This matters because it shows the Norman view of events.'),
        M('Why might the Bayeux Tapestry be biased?', ['It was made for the Norman winners and shows Harold breaking an oath', 'It was made by Vikings who hated the Normans', 'It was made 500 years later', 'It was made by Harold’s family'], 0, 'Made for Odo, it presents William as the rightful king and Harold as an oath-breaker. It was made within about 10–20 years, not centuries later.'),
        W(src('Source A: a summary of a scene in the Bayeux Tapestry (1070s).', 'Harold is shown placing his hands on two boxes of holy relics while William sits on a throne watching. The caption says Harold made an oath to Duke William.'), M('What message does Source A give?', ['Harold promised to support William, so he later broke a holy oath', 'William promised the throne to Harold', 'Harold was crowned in Normandy', 'William and Harold fought a duel'], 0, 'The scene shows Harold swearing on relics, which supports William’s claim that Harold was a perjurer (oath-breaker). The source is Norman, so this is the message it wanted to send.')),
        W(src('Source B: from the Anglo-Saxon Chronicle, written by English monks, describing 1066.', 'Then Harold the King gathered a great army and fought against William, and there were many killed on both sides. The French had possession of the place of slaughter, as God granted them because of the nation’s sins.'), M('What does Source B suggest about how the English monks explained the defeat?', ['They saw it as God’s punishment for the sins of the English', 'They blamed Harold’s poor tactics only', 'They said the Normans cheated', 'They said nobody died'], 0, 'The chronicler says God gave victory to the French because of the nation’s sins: a religious explanation typical of medieval monks.')),
        T('A source that is biased is useless to a historian.', false, 'False. A biased source is still useful — it tells us what its maker wanted people to believe. The Bayeux Tapestry is very useful for the Norman point of view.'),
        M('What is a <b>primary</b> source?', ['A source from the time being studied', 'A source written by a modern historian', 'The most important source', 'A source with no bias'], 0, 'Primary means it comes from the period itself (e.g. the Domesday Book). It does not mean "most important" and it can still be biased.'),
        M('Which of these is a secondary source about 1066?', ['A modern textbook chapter on Hastings', 'The Domesday Book', 'The Bayeux Tapestry', 'The Anglo-Saxon Chronicle'], 0, 'A secondary source is made later by someone who was not there, using primary sources. The others were all made in the 11th century.'),
        S('What word describes a one-sided view in a source?', 'Bias', ['biased', 'one-sided'], 'Bias means a source favours one side. Ask who made it, when, and why, to judge how far it is biased.'),
        MU('Which TWO questions help you judge the provenance of a source?', ['Who made it?', 'Why was it made?', 'How long is it?', 'What colour is it?', 'Is it printed in modern type?'], [0, 1], 'Provenance means where a source came from: its author, date and purpose. Length or colour do not tell you about reliability.'),
        O('Put these sources in the order they were made.', ['Anglo-Saxon Chronicle entry for 1066', 'Bayeux Tapestry (1070s)', 'Domesday Book (1086)', 'A school textbook on the Normans (2010s)'], 'The Chronicle entries were written soon after 1066; the Tapestry dates from the 1070s; Domesday from 1086; a modern textbook is secondary and recent.'),
        M('Which century does the year 1066 fall in?', ['11th century', '10th century', '12th century', '16th century'], 0, 'The 11th century covers 1001–1100. A common error is to say "10th" because 1066 begins with 10.'),
        T('The Bayeux Tapestry was probably made by English embroiderers.', true, 'True. Many historians think it was stitched in England, possibly at Canterbury, though it was commissioned by a Norman.'),
        M('A historian wants to know how many ploughs a village had in 1086. Which source is most useful?', ['The Domesday Book', 'The Bayeux Tapestry', 'A chronicle of the Battle of Hastings', 'A Viking saga'], 0, 'The Domesday Book recorded ploughs, people, animals and value of land, village by village. The Tapestry is about the conquest story.'),
        S('What word means the origin of a source — who made it, when and why?', 'Provenance', ['provenence'], 'Provenance is the origin of a source. In GCSE questions you use it to judge how useful a source is.'),
      ] },
  ],
  {
    overview: 'In 1066 England had three kings in one year. When Edward the Confessor died without an heir, Harold Godwinson, Harald Hardrada and William of Normandy fought for the crown. William won at Hastings and then used force and organisation to make Norman rule permanent.',
    objectives: ['I can explain the claims of the four claimants to the throne in 1066.', 'I can describe the battles of Fulford, Stamford Bridge and Hastings in order.', 'I can explain why William won the Battle of Hastings.', 'I can describe how William controlled England after 1066.', 'I can evaluate the Bayeux Tapestry as a source.'],
    keyWords: [
      { term: 'Witan', def: 'The council of nobles and churchmen that advised Anglo-Saxon kings and helped choose a new king.' },
      { term: 'Claimant', def: 'A person who claims a right to the throne.' },
      { term: 'Housecarl', def: 'A full-time, well-armed Anglo-Saxon soldier.' },
      { term: 'Fyrd', def: 'Part-time Anglo-Saxon army of farmers called up in emergencies.' },
      { term: 'Motte and bailey', def: 'An early Norman castle: a wooden keep on a mound (motte) above a fenced yard (bailey).' },
      { term: 'Feudal system', def: 'A system where land was granted in return for loyalty and service.' },
      { term: 'Domesday Book', def: 'William’s 1086 survey of land and wealth in England.' },
      { term: 'Harrying of the North', def: 'William’s deliberate destruction of northern England in 1069–70 after a rebellion.' },
    ],
    sections: [
      { title: 'The succession crisis', html: '<p>Edward the Confessor died on <b>5 January 1066</b> with no children. Four men claimed the throne:</p>' + people([['Harold Godwinson', 'Earl of Wessex; richest noble; said Edward named him on his deathbed; chosen by the Witan.'], ['William of Normandy', 'Edward’s cousin once removed; said Edward promised him the crown and Harold swore an oath to support him.'], ['Harald Hardrada', 'King of Norway; claim based on a deal between earlier Viking kings; backed by Tostig.'], ['Edgar Atheling', 'Edward’s great-nephew; closest blood relative but a teenager with no army.']]) + '<div class="note">Different claims rested on different things: blood, promise, oath, choice of the Witan and military strength.</div>' },
      { title: 'Three battles in one autumn', html: timeline([['5 Jan 1066', 'Edward the Confessor dies'], ['6 Jan 1066', 'Harold Godwinson crowned'], ['20 Sep 1066', 'Battle of Fulford – Hardrada beats the northern earls'], ['25 Sep 1066', 'Battle of Stamford Bridge – Harold defeats Hardrada and Tostig'], ['28 Sep 1066', 'William lands at Pevensey'], ['14 Oct 1066', 'Battle of Hastings – Harold killed'], ['25 Dec 1066', 'William crowned in Westminster Abbey']]) + '<p><b>Why William won:</b> Harold’s army was tired from marching north and back; some English broke the shield wall to chase Normans in <b>feigned retreats</b>; William had cavalry and archers; Harold was killed late in the day; and William had planned carefully and had the Pope’s banner.</p>' },
      { title: 'Taking control', html: '<ul><li><b>Castles</b> – hundreds of motte and baileys built quickly; later stone keeps such as the White Tower.</li><li><b>Force</b> – rebellions crushed; the <b>Harrying of the North</b> (1069–70) caused mass starvation.</li><li><b>Feudal system</b> – land given to loyal Normans in return for knights and loyalty.</li><li><b>Church</b> – Norman bishops; Lanfranc made Archbishop of Canterbury (1070).</li><li><b>Domesday Book</b> (1086) – record of land and wealth for tax.</li></ul><div class="rule">Consequence: by 1086 the English nobility had been almost completely replaced by Normans.</div>' },
      { title: 'Model answer: explaining a cause', html: worked('Explain why William won the Battle of Hastings. (8 marks)', ['Pick two or three reasons (e.g. Harold’s tired army; Norman tactics; luck).', 'For each: make the point, give specific evidence, then explain HOW it led to victory.', 'Link reasons and say which mattered most.'], 'Model paragraph: One reason William won was that Harold’s army was exhausted. Only three weeks earlier Harold had fought at Stamford Bridge near York and then marched about 250 miles south. Many of his best housecarls had been killed or wounded, and he did not wait for all of the fyrd to arrive. This meant the English shield wall was held by tired men, and once some of them chased the Normans during the feigned retreats, the wall had gaps that William’s cavalry could exploit.') },
    ],
    mistakes: ['Saying William was Edward’s son — Edward had no children.', 'Mixing up Harold Godwinson (English) with Harald Hardrada (Norwegian).', 'Thinking the Bayeux Tapestry is a painting or is useless because it is biased.', 'Forgetting that the Battle of Stamford Bridge came before Hastings.'],
    examTips: ['For "explain why" questions, every reason needs evidence AND an explanation of how it caused the outcome.', 'Use precise dates — 14 October 1066 is better than "in 1066".', 'When judging a source, comment on its content and its provenance (who, when, why).'],
    realLife: 'Many English words (beef, castle, justice) and many towns’ castles date from the Norman Conquest.',
  },
);

// ---- extra practice: The Norman Conquest ----
more('hist-y7-norman-conquest-1', [
  M('Which two English earls were defeated by Harald Hardrada and Tostig at Fulford on 20 September 1066?', ['Edwin and Morcar', 'Gyrth and Leofwine', 'Odo and Lanfranc', 'Hereward and Waltheof'], 0, 'Edwin (Earl of Mercia) and Morcar (Earl of Northumbria) lost at Fulford, near York. Gyrth and Leofwine were Harold’s brothers who died at Hastings; Odo and Lanfranc were Norman churchmen; Hereward and Waltheof were later rebels.'),
  S('At which place on the Sussex coast did William land on 28 September 1066?', 'Pevensey', [], 'William landed unopposed at Pevensey, then moved to Hastings and built a wooden castle there while he waited for Harold.'),
  M('What was the Witan?', ['A council of nobles and churchmen who advised the king and helped choose a new one', 'The Norman army’s cavalry', 'A Viking longship', 'The king’s tax on land'], 0, 'The Witan (or Witenagemot) advised Anglo-Saxon kings. Its choice of Harold in January 1066 gave him an important claim. It was not an army, a ship or a tax.'),
  M('What was the fyrd?', ['A part-time army of farmers called up when needed', 'The king’s full-time bodyguard', 'A group of hired Norman knights', 'A line of ships guarding the coast'], 0, 'The fyrd were ordinary freemen who fought when called up. The full-time, well-armed professionals were the housecarls. The fyrd’s need to go home for the harvest weakened Harold in September 1066.'),
  T('Harald Hardrada survived the Battle of Stamford Bridge and sailed home to Norway.', false, 'False. Hardrada and Tostig were both killed at Stamford Bridge. So many Norwegians died that only a small part of their fleet was needed to take the survivors home.'),
  M('Why did William’s fleet wait for weeks before crossing the Channel in 1066?', ['The wind was blowing the wrong way', 'He was waiting for Harold to invite him', 'His ships had not yet been designed', 'The Pope had told him to wait until winter'], 0, 'William’s ships needed a southerly wind. The delay was lucky for him: by the time he crossed, Harold was in the north fighting Hardrada, so the south coast was undefended.'),
  MU('Which TWO kinds of troops did William have at Hastings that Harold’s army largely lacked?', ['Mounted knights (cavalry)', 'Large numbers of archers', 'Housecarls with two-handed axes', 'Musketeers', 'Soldiers armed with cannon'], [0, 1], 'William combined archers, infantry and cavalry. Harold’s army fought on foot, with few archers. Housecarls were English, and guns and cannon were not used in battle in England for centuries.'),
  M('What weapon is most associated with the English housecarls?', ['The two-handed battle axe', 'The crossbow', 'The longbow', 'The pike'], 0, 'Housecarls carried large two-handed axes, which could kill a horse and rider with one blow. Crossbows were used by some Normans; the longbow and pike became important in later medieval warfare.'),
  M('During the Battle of Hastings, why did William push back his helmet so his face could be seen?', ['A rumour had spread that he had been killed', 'He wanted to surrender', 'He was too hot to fight', 'He was signalling the English to charge'], 0, 'When some Normans thought William was dead they began to panic. He lifted his helmet to show he was alive, which steadied his army. Keeping control of his troops was a key reason for his victory.'),
  S('Give the name traditionally used for the ridge where the English stood at Hastings. (one word)', 'Senlac', ['senlac hill', 'senlac ridge'], 'The English took position on Senlac Hill (or Senlac Ridge). Standing on high ground made the Normans attack uphill, which helps explain why the battle lasted so long.'),
  M('How, according to Norman accounts, did Harold end up at William’s court in about 1064?', ['He was shipwrecked on the French coast and handed over to William', 'He was sent as a prisoner after Stamford Bridge', 'He went to Normandy to be crowned', 'He fled from Edward the Confessor'], 0, 'Harold was shipwrecked in Ponthieu, captured by the local count and handed to William. While there he fought for William and, the Normans said, swore the oath. Stamford Bridge was not until 1066.'),
  M('Roughly how long did the Battle of Hastings last?', ['Most of a day, from morning until dusk', 'About ten minutes', 'Three weeks', 'Six months'], 0, 'The battle began in the morning and lasted until around dusk, which was unusually long for a medieval battle. It shows how strong the English shield wall was.'),
  T('After Harold’s death, some English leaders proclaimed Edgar Atheling king, but he submitted to William before he could be crowned.', true, 'True. Edgar was chosen in London, but as William advanced the English leaders, including Edgar, submitted to him at Berkhamsted before Christmas 1066.'),
  O('Put these events in chronological order.', ['Edward the Confessor is said to promise the throne to William (c.1051)', 'Harold swears an oath to William in Normandy (c.1064)', 'Tostig is exiled from England (1065)', 'Harold Godwinson is crowned (January 1066)'], 'The Norman claim begins with Edward’s promise around 1051, then Harold’s oath around 1064. Tostig was exiled after a revolt in Northumbria in 1065. Harold was crowned in January 1066 after Edward died.'),
  W(src('Source A: adapted from a history of Duke William written in the 1070s by one of his chaplains.', 'The duke rode at the front, braver than any of his men. He was the rightful heir, and the perjurer Harold was justly struck down.'), M('Why should a historian be careful about using Source A?', ['It was written by William’s own chaplain, who wanted to praise him and justify the conquest', 'It was written by an English monk who hated the Normans', 'It was written centuries after the battle', 'It contains no opinions at all'], 0, 'The writer worked for William, so he praises his bravery and calls Harold a perjurer (oath-breaker). It was written soon after 1066, not centuries later, and it is full of opinion. It is still useful for showing the Norman view.')),
  T('Two of Harold’s brothers, Gyrth and Leofwine, were also killed at the Battle of Hastings.', true, 'True. The death of Harold and his brothers left the English without obvious leaders, which made it easier for William to take control after the battle.'),
]);
more('hist-y7-norman-conquest-2', [
  M('Which English earl was executed after the Revolt of the Earls (1075)?', ['Waltheof', 'Harold Godwinson', 'Edgar Atheling', 'Hereward the Wake'], 0, 'Waltheof was beheaded in 1076, the only English earl William executed. Harold died in battle in 1066; Edgar survived and was eventually reconciled; Hereward’s fate is uncertain.'),
  M('Which city in the south-west rebelled in 1068 and was besieged by William for 18 days?', ['Exeter', 'York', 'Durham', 'Norwich'], 0, 'Exeter refused to accept William in 1068 and held out for 18 days before surrendering. William then built a castle there. York was the centre of the northern rebellion of 1069.'),
  M('Which area of Hampshire did William turn into a royal hunting forest?', ['The New Forest', 'Sherwood Forest', 'The Lake District', 'The Fens'], 0, 'William created the New Forest for hunting. Harsh forest laws punished anyone who hunted deer or cut wood there, which made the Normans unpopular.'),
  M('What was the job of a sheriff in Norman England?', ['To run a shire for the king, collecting taxes and keeping order', 'To lead prayers in the parish church', 'To command the king’s fleet', 'To write the Domesday Book alone'], 0, 'Sheriffs (shire-reeves) were royal officials who collected taxes, ran courts and kept order. William kept this Anglo-Saxon office but gave most of the posts to Normans.'),
  M('What was the <i>murdrum</i> fine?', ['A heavy fine paid by a whole area if a Norman was murdered and the killer was not found', 'A tax paid by Normans to the English', 'A fine for missing church', 'A payment to buy freedom from villeinage'], 0, 'The murdrum fine made local English communities responsible for the safety of Normans, so they had a strong reason to hand over killers. It shows how few Normans there were and how unsafe they felt.'),
  T('The Normans introduced trial by combat to England.', true, 'True. In trial by combat the accused and the accuser (or their champions) fought, and God was believed to give victory to the innocent. The Anglo-Saxons already used trial by ordeal.'),
  M('Why did the Normans gradually replace wooden castles with stone ones?', ['Stone was stronger and could not be burned or rot', 'Wood had become illegal', 'Stone castles were quicker to build', 'The Pope ordered it'], 0, 'Wooden keeps could be set on fire and rotted over time. Stone keeps lasted far longer and showed Norman power permanently, but they took years to build, which is why wooden castles came first.'),
  M('Which northern cathedral, begun in 1093, is a famous example of Norman building?', ['Durham Cathedral', 'St Paul’s Cathedral', 'Liverpool Cathedral', 'Westminster Cathedral'], 0, 'Durham Cathedral, with its huge round arches and pillars, was begun in 1093. The current St Paul’s was built after the Great Fire of 1666; Liverpool and Westminster cathedrals are modern.'),
  S('What name was given to the barons who held their land directly from the king? (three words, tenants-in-…)', 'tenants-in-chief', ['tenants in chief', 'tenant in chief', 'tenant-in-chief'], 'Tenants-in-chief held land directly from the king and in return provided knights. There were only about 200 of them, almost all Normans by 1086.'),
  T('A Danish fleet sent by King Sweyn of Denmark joined the northern rebels in 1069.', true, 'True. The Danes helped the rebels capture York. William paid the Danes to leave and then carried out the Harrying of the North.'),
  M('What happened when William I died in 1087?', ['His son William Rufus became King of England and his eldest son Robert got Normandy', 'Edgar Atheling became king', 'England was ruled by the Pope', 'Harold Godwinson’s son became king'], 0, 'William divided his lands: Robert Curthose took Normandy and William II (Rufus) became King of England. Norman rule of England continued.'),
  MU('Which TWO were features of a motte and bailey castle?', ['A wooden keep on top of an earth mound', 'A wooden fence (palisade) around the yard', 'Gun towers for cannon', 'Rings of stone walls one inside another', 'Large glass windows'], [0, 1], 'Early castles had a keep on the motte and a palisade around the bailey. Concentric stone walls came later (e.g. in the 1200s), and cannon and glass windows did not belong to 11th-century castles.'),
  O('Put these events in chronological order.', ['Rebellion in Exeter', 'Harrying of the North', 'Hereward’s resistance at Ely ends', 'Revolt of the Earls', 'Domesday survey carried out'], 'Exeter rebelled in 1068; the Harrying took place in 1069–70; Ely fell in 1071; the Revolt of the Earls was 1075; the Domesday survey was 1086.'),
  M('Why did William create powerful earldoms on the Welsh border, such as Chester, Shrewsbury and Hereford?', ['To defend England against Welsh raids', 'To give land back to Anglo-Saxon earls', 'Because no one lived there', 'To prepare an invasion of Ireland'], 0, 'These ‘marcher’ lords were trusted Normans given strong powers to guard the frontier with Wales. They were not English earls, and the areas were populated.'),
  S('What name is given to the ceremony of 1086 at which major landholders swore loyalty directly to William? (Oath of …)', 'Oath of Salisbury', ['salisbury oath', 'salisbury'], 'At the Oath of Salisbury in 1086, landholders swore loyalty to the king himself, not only to their own lord, strengthening William’s control.'),
  M('In the Domesday Book many villages in Yorkshire were described as ‘waste’. What does this most likely show?', ['The lasting damage done by the Harrying of the North', 'That Yorkshire had never been farmed', 'That the commissioners did not visit the north at all', 'That Yorkshire was the richest county'], 0, 'Sixteen years after the Harrying, much of Yorkshire was still recorded as waste, with little or no value. This is strong evidence of how destructive William’s punishment was.'),
]);
more('hist-y7-norman-conquest-3', [
  W(src('Source C: adapted from a monk, born in England to a Norman father and English mother, writing in Normandy in the 1120s–30s.', 'I have often praised William, but I cannot praise him for this. He made innocent children and the old die of hunger along with the guilty.'), M('Why is Source C especially valuable as evidence about the Harrying of the North?', ['A writer who usually admired William still condemned the Harrying', 'It was written by William himself', 'It was written during the Harrying by an eyewitness', 'It describes the Battle of Hastings'], 0, 'When a writer who is generally on William’s side criticises him, it suggests the Harrying really was shocking. The writer was born in 1075, so he was not an eyewitness; he wrote about 50 years later.')),
  M('Why do historians disagree about exactly how Harold died?', ['The Bayeux Tapestry scene is unclear and was later restored, and written accounts differ', 'Harold was never at Hastings', 'Nobody wrote about the battle', 'Harold’s body was found in Norway'], 0, 'The Tapestry shows one figure with an arrow near the eye and another being cut down, and the arrow may have been altered in restoration. Chroniclers give different versions. This is a good example of evidence that needs careful interpretation.'),
  M('Why is the Domesday Book usually seen as a fairly reliable source about land and wealth?', ['Commissioners checked information with sworn juries of local people', 'It was written by Harold Godwinson', 'It was made from memory 200 years later', 'It only recorded the king’s own estates'], 0, 'Royal commissioners questioned local juries under oath and checked the results. Some people may still have under-declared to avoid tax, so it is reliable but not perfect.'),
  T('The Anglo-Saxon Chronicle was written in Old English rather than Latin.', true, 'True. Unusually for the time, the Chronicle was written in the English of the day. Most official and church writing in Europe was in Latin.'),
  M('The Bayeux Tapestry shows horses being unloaded from William’s ships. What can be inferred from this?', ['The Normans brought their warhorses across the Channel for cavalry', 'The English sold horses to the Normans', 'Horses were used to row the ships', 'The Normans had no cavalry'], 0, 'An inference is a conclusion you work out from the evidence. Transporting horses by sea was difficult, so this scene suggests cavalry was very important to William’s plan.'),
  M('What did William build on the site of the Battle of Hastings, partly as an act of penance?', ['Battle Abbey', 'The Tower of London', 'Durham Cathedral', 'Westminster Abbey'], 0, 'Church leaders ordered penance for the killing at Hastings, and William founded Battle Abbey there; its altar is said to mark where Harold fell. The building is physical evidence of where the battle was fought. Westminster Abbey was built by Edward the Confessor.'),
  T('The Domesday Book covers every part of what is now England.', false, 'False. London, Winchester and most of the far north (such as Northumberland and Durham) were left out. A historian must know a source’s gaps as well as what it contains.'),
  S('What name is given to a year-by-year record of events, often kept by monks?', 'Chronicle', ['a chronicle', 'chronicles', 'annals'], 'A chronicle records events year by year. The Anglo-Saxon Chronicle is a key example. Chroniclers often added their own religious explanations.'),
  W(src('Source D: an imaginary village entry written in the style of the Domesday Book.', 'Here there are 12 villeins, 5 smallholders and 4 ploughs. There is a mill and woodland for 20 pigs. In the time of King Edward it was worth £4; now it is worth £2.'), M('What can you infer from Source D?', ['The village was worth less in 1086 than before the Conquest, perhaps because of damage or disruption', 'The village had no farmland', 'The village was richer after 1066', 'The village was entirely Norman'], 0, 'The value halved from £4 to £2, so something reduced its wealth — perhaps fighting, harrying or loss of people. The ploughs show it was farmed, and nothing tells us everyone was Norman.')),
  MU('Which TWO of these were made by people on the Norman side?', ['The Bayeux Tapestry', 'A biography of Duke William written by his chaplain', 'The Anglo-Saxon Chronicle', 'A modern documentary about 1066', 'A prayer written by an English monk in 1050'], [0, 1], 'The Tapestry was commissioned by Bishop Odo and the biography was written by William’s chaplain, so both show the Norman view. The Chronicle was written by English monks, a documentary is modern, and a prayer from 1050 is before the Conquest.'),
  M('A Victorian painting of Harold’s death at Hastings is most useful as evidence of…', ['How people in the 1800s imagined and felt about 1066', 'Exactly what Harold looked like', 'What weapons were used in 1066', 'The words spoken at the battle'], 0, 'A painting made 800 years later cannot show what really happened, but it tells us about Victorian attitudes, such as pride in Anglo-Saxon heroes. This is an interpretation, not a primary source for 1066.'),
  M('Why are the captions on the Bayeux Tapestry written in Latin?', ['Latin was the shared written language of educated churchmen across Europe', 'Most English peasants spoke Latin', 'The Vikings spoke Latin', 'The Normans had no other language'], 0, 'Latin was the written language of the Church and of learning across Europe. Ordinary English people spoke English and most could not read at all; the Normans spoke French.'),
  M('For which of these is the Bayeux Tapestry probably most reliable?', ['The appearance of armour, weapons and ships in the 11th century', 'Whether Edward really promised the throne to William', 'What Harold was thinking when he swore the oath', 'How English monks felt about the Conquest'], 0, 'The embroiderers knew what armour, weapons and ships looked like, so these details are likely accurate. The political story (promises and oaths) is where the Norman bias matters most, and the Tapestry cannot tell us about thoughts or English feelings.'),
  O('Put these steps for analysing a source in a sensible order.', ['Read the caption to find out who made it, when and why', 'Describe what the source shows or says', 'Make inferences from the content', 'Judge how useful and reliable it is for the enquiry'], 'Start with provenance, then content, then inference, then judgement. Jumping straight to "it is biased" without reading what it says is a common mistake.'),
  T('The Bayeux Tapestry shows only the Battle of Hastings.', false, 'False. It begins with Harold’s journey to Normandy around 1064, shows his oath, Edward’s death, Harold’s coronation and the invasion preparations, then ends with the battle. The ending is missing.'),
]);
// =====================================================================
// YEAR 7 — Medieval England: Church, Crown and people
// =====================================================================
addTopic(
  { id: 'hist-y7-medieval-england', strand: 'hist-ks3', year: 7, term: 2, name: 'Medieval England: Church, Crown and People',
    summary: 'Challenges to royal power from the Church, the barons and the peasants, and the impact of the Black Death.',
    specRef: 'DfE KS3 History: Medieval Britain 1066–1509 (Church, Magna Carta, Black Death, Peasants’ Revolt)' },
  [
    { name: 'Church and Crown: Becket and Magna Carta', intro: "Medieval kings were powerful but not all-powerful. The Church and the barons both challenged them, most famously Thomas Becket against Henry II and the barons against King John.",
      items: [
        M("Why was the Church so powerful in medieval England?", ["People believed it decided whether souls went to Heaven, and it owned land and collected tithes", "It controlled the army", "It elected the king", "It was paid for by the Normans only"], 0, "The Church taught that its sacraments helped souls avoid Hell and reduce time in Purgatory; it owned about a quarter of the land and took a tithe (a tenth) of produce. It did not control the army or choose the king."),
        S("What name was given to the tax of one tenth of a person's produce paid to the Church?", "Tithe", ["tithes"], "A tithe was a tenth of crops, animals or income given to the Church each year."),
        M("Who was Thomas Becket?", ["Archbishop of Canterbury who quarrelled with Henry II", "A baron who forced King John to seal Magna Carta", "Leader of the Peasants' Revolt", "A Norman knight at Hastings"], 0, "Becket was Henry II's chancellor and friend, made Archbishop of Canterbury in 1162. He then defended the Church against the king, especially over church courts."),
        M("What was the main issue in the quarrel between Henry II and Becket?", ["Whether clergy accused of crimes should be tried in church courts or royal courts", "Who should be the next king", "Whether England should become Protestant", "The price of wool"], 0, "Henry wanted 'criminous clerks' (clergy accused of crimes) punished by royal courts; church courts gave lighter sentences. Protestantism did not exist until the 1500s."),
        S("In which cathedral was Thomas Becket murdered in 1170?", "Canterbury Cathedral", ["canterbury"], "Four knights killed Becket in Canterbury Cathedral on 29 December 1170 after hearing Henry's angry words."),
        T("After Becket's murder, Henry II did public penance and was whipped by monks at Canterbury.", true, "True. In 1174 Henry walked barefoot to Becket's tomb and was flogged by monks, showing how strong the Church's influence was. Becket was made a saint in 1173."),
        M("Which king sealed Magna Carta?", ["King John", "Henry II", "Richard I", "Edward I"], 0, "King John sealed Magna Carta at Runnymede in June 1215. Richard I was his brother (the Lionheart); Henry II was his father."),
        S("In which year was Magna Carta sealed?", "1215", [], "Magna Carta was sealed at Runnymede, near Windsor, in June 1215."),
        MU("Which TWO reasons made the barons angry with King John?", ["High taxes such as scutage to pay for wars", "He lost Normandy to the French king in 1204", "He closed the monasteries", "He executed Thomas Becket", "He introduced a poll tax in 1381"], [0, 1], "John raised heavy taxes and lost Normandy (where many barons had land). He also quarrelled with the Pope. Becket died under Henry II; the monasteries were closed by Henry VIII; the poll tax revolt was in 1381."),
        M("Clause 39 of Magna Carta is famous because it said…", ["No free man could be imprisoned or punished except by lawful judgement or the law of the land", "Everyone could vote", "Women could become barons", "The king must be elected every five years"], 0, "Clause 39 is the root of the idea of fair trial and the rule of law. Magna Carta did not give votes or create elections."),
        T("Magna Carta immediately ended conflict between King John and the barons.", false, "False. The Pope annulled it within weeks and civil war (the First Barons' War) broke out. It was reissued after John's death in 1216, 1217 and 1225."),
        M("Why is Magna Carta seen as important today?", ["It established that the king was not above the law", "It gave all peasants their freedom", "It created the House of Commons", "It made England a republic"], 0, "Its long-term importance is the principle that rulers must obey the law. Most clauses protected barons, not peasants, and it did not create Parliament or a republic."),
        M("Whose parliament of 1265 included knights and townsmen (burgesses) for the first time?", ["Simon de Montfort", "King John", "Wat Tyler", "Thomas Becket"], 0, "Simon de Montfort, leading a rebellion against Henry III, summoned knights and burgesses in 1265 — an early step towards the House of Commons."),
        O("Put these events in chronological order.", ["Murder of Thomas Becket", "King John loses Normandy", "Magna Carta sealed", "Simon de Montfort's Parliament"], "1170 Becket murdered; 1204 Normandy lost; 1215 Magna Carta; 1265 de Montfort's Parliament."),
        M("Medieval Christians believed that souls not yet ready for Heaven went to a place of cleansing called…", ["Purgatory", "Limbo", "Valhalla", "Paradise"], 0, "Purgatory was where souls were purified. People paid for prayers and went on pilgrimages to shorten time there. Valhalla belongs to Norse belief."),
        S("What is the name for a religious journey to a holy place, such as Becket's shrine?", "Pilgrimage", ["pilgrimages"], "A pilgrimage was a journey to a shrine; Canterbury became one of the most popular after Becket was made a saint."),
      ] },
    { name: 'The Black Death, 1348–49', intro: "The Black Death reached England in 1348 and killed between a third and a half of the population. Medieval people explained it through religion and bad air; its consequences changed society.",
      items: [
        S("In which year did the Black Death arrive in England?", "1348", [], "The plague reached England in the summer of 1348, probably through a port in Dorset (Melcombe, now part of Weymouth)."),
        M("Roughly what proportion of England's population died in the Black Death?", ["Between a third and a half", "About one in a hundred", "Nine out of ten", "Nobody in towns"], 0, "Estimates suggest 30–50% died. It was the worst disaster in English history in terms of deaths."),
        M("What do we now know caused the Black Death?", ["Bacteria spread mainly by fleas carried on rats, and by coughing in the pneumonic form", "Bad air from rotting rubbish", "The alignment of the planets", "God's punishment for sin"], 0, "The bacterium (Yersinia pestis) was carried by fleas on black rats; the pneumonic form spread through coughing. The other answers were medieval explanations, not the real cause."),
        MU("Which TWO were explanations that people in 1348 gave for the Black Death?", ["God was punishing people for their sins", "Miasma — bad air", "Bacteria spread by fleas", "A virus from bats", "Germs in drinking water identified by microscopes"], [0, 1], "Medieval people blamed God and miasma (and the planets). Germ theory and bacteria were not understood until the 1860s–80s."),
        M("Who were the flagellants?", ["People who whipped themselves in public to show God they were sorry for sins", "Doctors who cut patients to remove blood", "Soldiers who guarded towns", "Rats that carried the plague"], 0, "Flagellants believed that punishing themselves would persuade God to end the plague. Bloodletting was a different (Galenic) treatment."),
        T("Medieval doctors were able to cure the Black Death with antibiotics.", false, "False. Antibiotics such as penicillin were not developed until the 20th century. Medieval treatments like bloodletting and herbs did not work."),
        M("What was the main economic consequence of the Black Death for surviving peasants?", ["There was a labour shortage, so peasants could demand higher wages", "Wages fell because there were too many workers", "All peasants became knights", "Farming stopped completely for 100 years"], 0, "So many died that lords were short of workers, so labourers could ask for higher pay or move to better offers."),
        S("Which 1351 law tried to keep wages at their pre-plague level? (three words: Statute of …)", "Statute of Labourers", ["statute of labourer", "labourers"], "The Statute of Labourers (1351), following the Ordinance of 1349, tried to freeze wages and stop peasants moving. It caused resentment."),
        T("The Black Death helped to weaken the feudal system in the long term.", true, "True. With fewer workers, peasants had more bargaining power, and many villeins were able to become free tenants or wage labourers over time."),
        M("Which symptom gave bubonic plague its name?", ["Buboes — swellings in the armpits and groin", "Black teeth", "Blue skin", "Hair loss"], 0, "'Buboes' were painful swellings of the lymph nodes. Some victims also had black patches on the skin."),
        M("Which of these was a typical medieval reaction to the plague in towns?", ["Praying, processions and carrying sweet-smelling herbs", "Vaccinating children", "Building sewers like Bazalgette's", "Testing water for germs"], 0, "People prayed and tried to block miasma with herbs (posies). Vaccination came in 1796 and sewers in London in the 1860s."),
        O("Put these in chronological order.", ["The Black Death reaches England", "Ordinance of Labourers", "Statute of Labourers", "The Peasants' Revolt"], "1348 plague; 1349 Ordinance; 1351 Statute; 1381 Peasants' Revolt."),
        M("Why might the Black Death have made some people question the Church?", ["Priests died too and prayers did not stop the disease", "The Church banned praying", "The Pope said the plague was caused by rats", "Churches were all closed by the king"], 0, "Many priests died and prayer did not work, which led some to doubt the Church's power, although most people remained devout."),
        T("The plague returned to England several more times after 1348–49.", true, "True. There were further outbreaks, e.g. in 1361 and repeatedly until the Great Plague of 1665."),
        S("What medieval word means 'bad air' that was thought to cause disease?", "Miasma", ["miasmas"], "Miasma theory said disease was caused by foul-smelling air from rotting matter. It lasted until germ theory in the 1860s."),
      ] },
    { name: "The Peasants' Revolt, 1381", intro: "In 1381 peasants from Essex and Kent marched on London. Anger at the poll tax, low wages and serfdom led to a revolt that briefly shook the government of the 14-year-old Richard II.",
      items: [
        S("In which year did the Peasants' Revolt take place?", "1381", [], "The revolt began in Essex in late May 1381 and reached London in June."),
        M("Which tax was the immediate (short-term) trigger of the revolt?", ["The poll tax", "The tithe", "Ship money", "Income tax"], 0, "A third poll tax, set at one shilling per adult in 1380, was the trigger. Ship money was Charles I's tax in the 1630s; income tax began in 1799."),
        M("Who was king during the Peasants' Revolt?", ["Richard II, aged 14", "Edward III", "Henry V", "King John"], 0, "Richard II became king in 1377 aged 10, so he was 14 in 1381. Edward III was his grandfather."),
        M("Who was the main leader of the rebels who met the king?", ["Wat Tyler", "John Ball", "Simon de Montfort", "Thomas Becket"], 0, "Wat Tyler led the Kentish rebels and spoke for them at Mile End and Smithfield. John Ball was the radical preacher who inspired them."),
        M("John Ball was famous for…", ["Preaching that all people were created equal by God", "Collecting the poll tax", "Killing Wat Tyler", "Writing Magna Carta"], 0, "Ball was a priest who preached that God had not created lords and serfs — an argument for equality. The Lord Mayor, William Walworth, killed Tyler."),
        MU("Which TWO were long-term causes of the revolt?", ["Anger at the Statute of Labourers keeping wages low", "Resentment at serfdom (villeins not being free)", "Henry VIII closing the monasteries", "The Spanish Armada", "The Gunpowder Plot"], [0, 1], "After the Black Death peasants wanted higher wages and freedom; the Statute of Labourers and serfdom stood in the way. The other options happened much later."),
        M("What happened at Smithfield on 15 June 1381?", ["Wat Tyler was killed and the king persuaded the rebels to go home", "Richard II was captured", "The rebels burned Canterbury Cathedral", "Parliament abolished the poll tax"], 0, "Tyler was struck down by William Walworth; Richard rode forward and told the rebels he would be their leader, and they dispersed."),
        T("Richard II kept all the promises he made to the rebels.", false, "False. Richard cancelled the charters of freedom and leaders such as John Ball were executed."),
        M("Which important official was killed by rebels at the Tower of London?", ["Simon Sudbury, Archbishop of Canterbury", "Wat Tyler", "Richard II", "Thomas Becket"], 0, "Sudbury was Archbishop and also Chancellor, responsible for the poll tax, so the rebels beheaded him on Tower Hill."),
        T("Many of the rebels were not the poorest peasants but villagers with some property and craftsmen.", true, "True. Historians note many rebels were fairly prosperous villagers, artisans and even some priests, angry about restrictions on their freedom."),
        M("What was one long-term consequence of the revolt?", ["Poll taxes were not used again for centuries and serfdom gradually died out", "Peasants were given the vote", "Feudalism became stronger than ever", "Richard II abdicated immediately"], 0, "Governments avoided poll taxes until the 1990s 'community charge', and serfdom declined over the next century. There was no vote for peasants."),
        O("Put these events of 1381 in order.", ["Revolt breaks out in Essex", "Rebels enter London", "Meeting at Mile End", "Wat Tyler killed at Smithfield"], "Late May: Essex; 13 June: London; 14 June: Mile End; 15 June: Smithfield."),
        S("What word describes an unfree peasant tied to a lord's land?", "Serf", ["villein", "serfs"], "Serfs (villeins) owed labour to their lord and needed permission to leave or marry. Ending serfdom was a key rebel demand."),
        M("Which statement is a <b>short-term</b> cause of the revolt?", ["Tax collectors arrived in Essex villages in 1381 to enforce the poll tax", "The Black Death of 1348", "The Norman Conquest", "The growth of the wool trade over 200 years"], 0, "A short-term cause happens just before the event and triggers it. The Black Death is a long-term cause."),
        W(src("Source A: a chronicle written by a monk in the 1380s.", "The rebels, wicked men who had no fear of God, rose against their lords and burned the houses of good men."), T("Based on its author, a monk writing in the 1380s, Source A is likely to be sympathetic to the rebels.", false, "False. Source A calls the rebels 'wicked men'. Most chroniclers were monks and part of the landowning Church, so they usually described the rebels as wicked or foolish. This makes their accounts one-sided.")),
        T("Most surviving chronicles of the Peasants' Revolt were written by the rebels themselves.", false, "False. Most peasants could not write; the chronicles were written by monks and clerks from the ruling classes, so we see the revolt mainly through their hostile eyes."),
      ] },
  ],
  {
    overview: "Medieval kings faced challenges from three directions: the Church (Becket), the barons (Magna Carta) and the peasants (1381). The Black Death of 1348 killed up to half the population and changed the balance of power between lords and workers.",
    objectives: ["I can explain why the Church was powerful in medieval England.", "I can explain why Henry II quarrelled with Becket and why John sealed Magna Carta.", "I can describe the causes, beliefs about and consequences of the Black Death.", "I can explain the causes and outcome of the Peasants' Revolt."],
    keyWords: [
      { term: 'Tithe', def: 'A tenth of a person’s produce or income paid to the Church.' },
      { term: 'Purgatory', def: 'In medieval Catholic belief, a place where souls were cleansed before Heaven.' },
      { term: 'Magna Carta', def: 'The "Great Charter" of 1215 limiting the power of King John.' },
      { term: 'Miasma', def: 'Bad air, believed to cause disease.' },
      { term: 'Flagellant', def: 'Someone who whipped themselves to show penance to God.' },
      { term: 'Poll tax', def: 'A tax charged per head at the same rate on rich and poor.' },
      { term: 'Serf / villein', def: 'An unfree peasant bound to a lord’s land.' },
    ],
    sections: [
      { title: 'Church and Crown', html: "<p>The medieval Church was the richest and most powerful institution in Europe. Everyone paid <b>tithes</b>, and the Church taught that its sacraments, prayers and pilgrimages helped souls reach Heaven.</p><p><b>Henry II v Becket:</b> Henry made his friend Thomas Becket Archbishop of Canterbury in 1162, expecting support. Becket instead defended church courts. In 1170 four knights, hearing the king's furious words, murdered Becket in Canterbury Cathedral. Becket became a saint (1173) and Henry did penance (1174) — a sign of the Church's power.</p><p><b>John and Magna Carta:</b> John lost Normandy (1204), quarrelled with the Pope and charged high taxes. The barons rebelled and forced him to seal <b>Magna Carta</b> at Runnymede in June 1215. Clause 39 promised lawful judgement for free men.</p><div class=\"rule\">Magna Carta's lasting idea: the monarch is not above the law.</div>" },
      { title: 'The Black Death', html: "<p>The plague reached England in <b>1348</b> and killed between a third and half of the people. It was caused by bacteria spread by fleas on rats, but people at the time blamed <b>God's punishment</b>, <b>miasma</b> and the planets. Treatments included prayer, flagellation, herbs and bloodletting — none worked.</p><p><b>Consequences:</b> a labour shortage meant surviving peasants demanded higher wages. The government passed the <b>Statute of Labourers (1351)</b> to keep wages down, which caused anger.</p>" },
      { title: "The Peasants' Revolt", html: timeline([["1348", "Black Death arrives"], ["1351", "Statute of Labourers"], ["1377", "Richard II becomes king aged 10; first poll tax"], ["1380", "Third poll tax: 1 shilling per adult"], ["May 1381", "Revolt begins in Essex, spreads to Kent"], ["14 June 1381", "Richard meets rebels at Mile End; Archbishop Sudbury killed"], ["15 June 1381", "Wat Tyler killed at Smithfield; rebels go home"]]) + people([["Wat Tyler", "Leader of the Kentish rebels; killed at Smithfield."], ["John Ball", "Radical priest who preached equality; executed."], ["Richard II", "14-year-old king who calmed the rebels then broke his promises."]]) + "<p><b>Long-term causes:</b> serfdom and low wages after the Black Death. <b>Short-term trigger:</b> the 1380 poll tax and harsh collectors.</p>" },
      { title: 'Model answer: consequences', html: worked("Explain the consequences of the Black Death for ordinary people. (8 marks)", ["Choose two consequences (economic; religious/social).", "Give specific detail for each.", "Explain the effect on people's lives and link to later events."], "Model paragraph: One consequence was that surviving peasants gained more bargaining power. Because between a third and half of the population died, lords did not have enough labourers to farm their land. Peasants could therefore demand higher wages or leave for a lord who would pay more. The government tried to stop this with the Statute of Labourers in 1351, but this made peasants resentful and helped to cause the Peasants' Revolt thirty years later.") },
    ],
    mistakes: ["Thinking Magna Carta gave rights to everyone — most clauses protected barons and free men.", "Saying medieval people knew rats caused the plague.", "Confusing long-term causes (Black Death, serfdom) with the short-term trigger (poll tax) of 1381.", "Assuming Henry II personally killed Becket."],
    examTips: ["Separate long-term and short-term causes and show how they link.", "Use the specific names: Wat Tyler, John Ball, Richard II, Statute of Labourers.", "In consequence questions, explain the effect, not just the event."],
    realLife: "Clause 39 of Magna Carta still underpins the idea of a fair trial in Britain, the USA and elsewhere.",
  },
);

// ---- extra practice: Medieval England ----
more('hist-y7-medieval-england-1', [
  M('What job did Thomas Becket hold before Henry II made him Archbishop of Canterbury?', ['Chancellor, the king’s chief minister', 'Abbot of Westminster', 'Sheriff of London', 'Pope'], 0, 'Becket was Henry’s Chancellor and close friend. Henry expected him to stay loyal as archbishop, but Becket defended the Church instead, which caused the quarrel.'),
  M('Why did Henry II object to church courts?', ['They gave much lighter punishments to clergy who committed crimes', 'They were run by the barons', 'They only tried women', 'They used the king’s judges'], 0, 'Clergy could claim ‘benefit of clergy’ and be tried in church courts, which could not sentence them to death. Henry wanted ‘criminous clerks’ punished in royal courts.'),
  M('What were the Constitutions of Clarendon (1164)?', ['Rules by which Henry II tried to limit the power of the Church courts', 'The first version of Magna Carta', 'A list of Becket’s miracles', 'The rules of a monastery'], 0, 'The Constitutions set out royal rights over the Church, including trying criminal clergy in royal courts. Becket refused to accept them and fled into exile.'),
  T('Becket was murdered by four knights who had heard Henry II’s angry words about him.', true, 'True. Henry is reported to have raged against Becket, and four knights rode to Canterbury and killed him in the cathedral in December 1170. Whether Henry meant them to do it is still debated.'),
  S('In which year was Thomas Becket made a saint?', '1173', [], 'Becket was canonised in 1173, only about two years after his death. His shrine at Canterbury became one of the most important pilgrimage sites in Europe.'),
  M('Which important French territory did King John lose to the King of France in 1204?', ['Normandy', 'Calais', 'Gascony', 'Brittany'], 0, 'Losing Normandy damaged John’s reputation and cost many barons their French lands. Calais was lost much later (1558) and Gascony stayed English until 1453.'),
  M('What was the result of the Battle of Bouvines (1214)?', ['John’s allies were defeated, ending his hopes of winning back his French lands', 'John conquered Paris', 'The barons crowned a new king', 'The Pope declared John a saint'], 0, 'The defeat at Bouvines left John with huge debts and no victory to show for his heavy taxes. Within a year the barons were in rebellion.'),
  M('Why did Pope Innocent III place England under an interdict in 1208?', ['John refused to accept Stephen Langton as Archbishop of Canterbury', 'John had become a Protestant', 'John had murdered Becket', 'John refused to go on crusade with Richard I'], 0, 'An interdict stopped most church services in England. John eventually gave way in 1213. Becket had been killed under Henry II, and Protestantism did not exist yet.'),
  S('In which meadow beside the Thames did King John agree to Magna Carta in 1215?', 'Runnymede', ['runnymede meadow'], 'Magna Carta was agreed at Runnymede, near Windsor, in June 1215.'),
  M('What happened to Magna Carta within a few months of 1215?', ['The Pope cancelled it and civil war (the First Barons’ War) broke out', 'It was made the law of every country in Europe', 'John kept every clause until he died', 'The barons burned it at Runnymede'], 0, 'John asked the Pope to annul the charter, and fighting resumed. The charter survived because it was reissued in the name of John’s young son, Henry III.'),
  T('Magna Carta was reissued several times under Henry III, including in 1216, 1217 and 1225.', true, 'True. The reissues, especially in 1225, turned it into a lasting statement of law that later kings confirmed.'),
  M('What happened to Simon de Montfort?', ['He defeated Henry III at Lewes in 1264 but was killed at Evesham in 1265', 'He became king in 1265', 'He was murdered in Canterbury Cathedral', 'He signed Magna Carta as king'], 0, 'De Montfort captured Henry III at Lewes and called his famous parliament in 1265, but Prince Edward defeated and killed him at Evesham later that year.'),
  O('Put these events in chronological order.', ['Murder of Thomas Becket', 'Magna Carta agreed', 'Simon de Montfort’s parliament', 'Edward I’s ‘Model Parliament’'], 'Becket died in 1170; Magna Carta was 1215; de Montfort’s parliament was 1265; Edward I’s Model Parliament was 1295.'),
  MU('Which TWO were jobs of a medieval parish priest?', ['Holding church services such as Mass', 'Baptising, marrying and burying villagers', 'Commanding the local army', 'Collecting customs duties at ports for the king', 'Choosing the next king'], [0, 1], 'The parish priest led worship and carried out the key ceremonies of life, as well as collecting tithes. He did not lead armies, collect customs or choose kings.'),
  W(src('Source A: adapted from a chronicle written by a monk at St Albans Abbey in the 1200s.', 'John was a tyrant rather than a king. He robbed the churches and was cruel to his own people.'), M('Why might a monastic chronicler be especially hostile to King John?', ['John had quarrelled with the Pope and taxed the Church heavily', 'John had built many new monasteries', 'Monks were paid by John to write about him', 'John had made the monk an archbishop'], 0, 'During the interdict John seized Church property, so monks had a reason to dislike him. That does not make the source useless, but its tone must be judged in the light of its author.')),
  M('Which of these was an important role of medieval monasteries?', ['Caring for the sick and poor, offering hospitality and copying books', 'Running the king’s army', 'Collecting the poll tax', 'Printing newspapers'], 0, 'Monks and nuns prayed, cared for the poor and sick, gave travellers shelter and copied manuscripts by hand. Printing did not reach England until the 1470s.'),
]);
more('hist-y7-medieval-england-2', [
  M('Where did the Black Death first arrive in England in June 1348?', ['A port in Dorset (Melcombe, now part of Weymouth)', 'York', 'Dover', 'Newcastle'], 0, 'The plague came by ship to Melcombe in Dorset in the summer of 1348, then spread across the country, reaching London by the autumn.'),
  M('How did the pneumonic form of plague spread?', ['From person to person through coughing and breathing', 'Only through flea bites', 'By eating fruit', 'Through bad smells'], 0, 'Bubonic plague was spread by flea bites, but the pneumonic form infected the lungs and passed through the air from person to person. It was even more deadly.'),
  T('The Black Death reached Europe from Asia along trade routes.', true, 'True. The plague spread from central Asia along trade routes and arrived in Europe in 1347 through Mediterranean ports, then moved north.'),
  S('Name the bacterium that caused the plague. (two words)', 'Yersinia pestis', ['yersinia'], 'Yersinia pestis bacteria lived in fleas carried by rats. Nobody in the 1300s knew about bacteria; germ theory came in the 1860s.', [['yersinia']]),
  M('How did the Black Death affect the Church?', ['Many priests died, and some were replaced by poorly educated men', 'All priests survived because God protected them', 'The Church closed every parish church permanently', 'The Pope moved to England'], 0, 'Priests caught the plague while caring for the dying, so many died. Shortages led to less trained replacements, which may have weakened respect for the Church.'),
  M('What happened to some villages after the Black Death?', ['They were abandoned and became ‘deserted villages’', 'They became large cities overnight', 'They were taken over by Vikings', 'Their populations doubled'], 0, 'With so many deaths, some villages were left empty or their survivors moved away. Many ‘lost villages’ in England date from this period and later changes in farming.'),
  M('Why were surviving labourers able to demand higher wages after the Black Death?', ['There were far fewer workers, so lords competed to hire them', 'The king ordered all wages doubled', 'Money became worthless', 'The Church paid their wages'], 0, 'A shortage of labour gave workers bargaining power. The government actually tried to stop wage rises with the Ordinance (1349) and Statute (1351) of Labourers.'),
  W('<table class="qt"><tr><th>Year</th><th>Estimated population of England</th></tr><tr><td>c.1300</td><td>about 4.5–5 million</td></tr><tr><td>c.1377</td><td>about 2.5 million</td></tr></table>', M('What does the table suggest?', ['The population fell by roughly half during the 1300s', 'The population doubled during the 1300s', 'The population stayed the same', 'The population fell by about one tenth'], 0, 'From about 5 million to about 2.5 million is roughly a halving. The Black Death and later outbreaks were the main cause, along with famine earlier in the century. These are estimates, so historians give ranges.')),
  O('Put these in chronological order.', ['The plague reaches Dorset', 'The plague reaches London', 'The Ordinance of Labourers', 'The Statute of Labourers'], 'June 1348 Dorset; autumn 1348 London; June 1349 the Ordinance of Labourers; 1351 the Statute of Labourers, which made the wage controls law passed by Parliament.'),
  MU('Which TWO were medieval ways of trying to avoid or treat the plague?', ['Carrying sweet-smelling herbs or flowers', 'Bleeding patients to rebalance the humours', 'Taking antibiotics', 'Vaccination', 'Adding chlorine to drinking water'], [0, 1], 'People believed in miasma (bad air) and the four humours, so they carried posies and used bloodletting. Antibiotics, vaccination and water chlorination were all developed centuries later.'),
  T('The Black Death killed only poor people.', false, 'False. Rich and powerful people died too, including Edward III’s daughter Joan (1348) and two Archbishops of Canterbury in 1349. The poor, living in crowded conditions, were still more at risk.'),
  W(src('Source A: an imaginary account in the style of a monk writing in 1349.', 'So many labourers have died that the crops stand rotting in the fields, and sheep wander without shepherds. Those who remain ask for double the wages of before.'), M('What can you infer from Source A?', ['The plague caused a serious shortage of workers, which gave survivors more bargaining power', 'There was too much labour and wages fell', 'The harvest was the best in history', 'Sheep caused the plague'], 0, 'Rotting crops and unattended sheep show there were not enough workers, and the demand for double wages shows survivors could bargain. Nothing suggests sheep caused the disease.')),
  M('Why did the plague spread especially quickly in medieval towns?', ['Crowded housing, dirty streets and rats made infection easy', 'Towns had no doctors at all', 'Townspeople never travelled', 'Towns were built of stone'], 0, 'Packed houses, rubbish and sewage in the streets attracted rats and fleas, and close contact spread the pneumonic form. Some towns did have physicians, but their treatments did not work.'),
  M('Which long-term change in farming became more common after the Black Death?', ['Some landowners switched from crops to sheep farming, which needed fewer workers', 'Farming stopped in England for 100 years', 'Tractors were introduced', 'All land was given to peasants by the king'], 0, 'Sheep needed fewer labourers than crops, so with workers scarce some lords turned fields into pasture. Wool became even more important to England’s economy.'),
  T('King Edward III ordered the streets of London to be cleaned during the plague.', true, 'True. In 1349 the king wrote to the Mayor of London complaining of filth in the streets. People linked bad smells (miasma) to disease, so cleaning seemed a sensible response.'),
]);
more('hist-y7-medieval-england-3', [
  M('How much was the poll tax of 1380–81 for each person over the age of 15?', ['One shilling (12 pence)', 'One penny', 'One pound', 'Nothing for peasants'], 0, 'The third poll tax charged 12d per person, three times the 4d of 1377, and the same for rich and poor alike. This made it deeply resented.'),
  M('In which two counties did the Peasants’ Revolt begin?', ['Essex and Kent', 'Yorkshire and Lancashire', 'Cornwall and Devon', 'Norfolk and Lincolnshire'], 0, 'The revolt started in Essex (at Brentwood, near Fobbing) and Kent, near London, then spread to other areas including East Anglia.'),
  M('What did Richard II promise the rebels at Mile End on 14 June 1381?', ['To end serfdom and pardon them', 'To make Wat Tyler Archbishop', 'To raise the poll tax', 'To give up the throne'], 0, 'Richard granted charters of freedom at Mile End. After the revolt collapsed, the promises were cancelled.'),
  M('Which grand London palace, belonging to the king’s uncle John of Gaunt, did the rebels destroy?', ['The Savoy Palace', 'Hampton Court', 'Buckingham Palace', 'The Tower of London'], 0, 'John of Gaunt was widely blamed for the poll taxes, so rebels burned his Savoy Palace. Hampton Court and Buckingham Palace were built much later; the Tower was entered but not destroyed.'),
  M('Who attacked Wat Tyler at Smithfield, leading to his death?', ['William Walworth, the Lord Mayor of London', 'John Ball', 'Richard II himself', 'Simon de Montfort'], 0, 'Walworth struck Tyler after an argument in the king’s presence; Tyler was then killed. John Ball was a rebel preacher, and de Montfort had died over a century earlier.'),
  S('How old was Richard II at the time of the Peasants’ Revolt?', '14', ['fourteen', '14 years old'], 'Richard II was only 14. His courage at Smithfield, riding forward to the rebels, became famous, but the government quickly took revenge afterwards.'),
  W(src('Source B: a saying used in John Ball’s preaching, 1381.', 'When Adam delved and Eve span, who was then the gentleman?'), M('What was the message of this saying?', ['God created all people equal, so there should be no lords and serfs', 'Women should do all the farm work', 'Gentlemen were created first by God', 'Peasants should pay more taxes'], 0, '‘Delved’ means dug and ‘span’ means spun thread. Ball argued that at the Creation there were no lords, so serfdom was not God’s plan. It was a radical idea in 1381.')),
  T('John Ball was executed after the revolt.', true, 'True. Ball was tried and executed at St Albans in July 1381. Many other rebels were also hanged as the government restored control.'),
  M('Why did the government need so much money in the years before 1381?', ['To pay for the Hundred Years War with France', 'To build the Tower of London', 'To pay for the Black Death', 'To fund the Reformation'], 0, 'Fighting France was very expensive, and English defeats made the taxes feel even worse. The Tower was built in the 1070s and the Reformation was in the 1500s.'),
  M('Why did rebels burn manor records and legal documents?', ['To destroy written proof of their duties as serfs', 'Because they needed firewood', 'To hide the king’s taxes from the Pope', 'Because they could not read and disliked books'], 0, 'Manor rolls recorded which peasants were unfree and what labour they owed. Destroying them was an attack on serfdom itself, showing the rebels had clear aims.'),
  O('Put these events of 1381 in chronological order.', ['Villagers attack tax collectors at Brentwood', 'Rebels enter London', 'Richard II meets rebels at Mile End', 'Wat Tyler is killed at Smithfield', 'John Ball is executed'], 'Brentwood (30 May); London (13 June); Mile End (14 June); Smithfield (15 June); Ball’s execution (July).'),
  MU('Which TWO were consequences of the Peasants’ Revolt?', ['No poll tax was used again for centuries', 'Serfdom continued to decline over the following century', 'Ordinary peasants won the right to vote', 'Richard II abolished the monarchy', 'Wat Tyler became Lord Mayor of London'], [0, 1], 'Governments avoided poll taxes for a very long time, and serfdom slowly disappeared as labour stayed scarce. Peasants did not get the vote, Richard remained king and Tyler was killed.'),
  W(src('Source C: adapted from a chronicle written by a royal clerk soon after 1381.', 'The wild and wicked commons rose like mad dogs, burning and killing without reason.'), M('Why does Source C describe the rebels so negatively?', ['It was written by someone who served the king and saw the revolt as a dangerous threat to order', 'It was written by Wat Tyler', 'The writer was a peasant who had joined the revolt', 'It was written in the 20th century'], 0, 'A royal clerk would support the king and lords. Calling the rebels ‘mad dogs’ and saying they acted ‘without reason’ ignores their clear demands, such as ending serfdom.')),
  T('Women took part in the Peasants’ Revolt.', true, 'True. Court records name some women among the rebels, showing the revolt involved whole communities, not only men.'),
  M('Which rebel leader is traditionally named alongside Wat Tyler?', ['Jack Straw', 'Hereward the Wake', 'Robert Aske', 'Jack Cade'], 0, 'Jack Straw is named as a rebel leader in 1381. Hereward fought the Normans; Robert Aske led the Pilgrimage of Grace (1536); Jack Cade led a later rebellion in 1450.'),
]);
// =====================================================================
// YEAR 7 — Historical skills: chronology, sources and interpretations
// =====================================================================
addTopic(
  { id: 'hist-y7-chronology-sources', strand: 'hist-skills', year: 7, term: 3, name: 'Thinking Like a Historian: Chronology and Sources',
    summary: 'Using dates, centuries and periods accurately, and making inferences from sources and interpretations.',
    specRef: 'DfE KS3 History: chronological knowledge, historical concepts and methods of enquiry' },
  [
    { name: 'Chronology: dates, centuries and periods', intro: "Chronology means putting things in time order. Historians use centuries, decades and named periods, and you must be able to convert between them quickly.",
      items: [
        M("Which century is the year 1215 in?", ["13th century", "12th century", "15th century", "21st century"], 0, "Add one to the first two digits: 12 + 1 = 13th century (1201–1300). Saying '12th' is the classic mistake."),
        M("Which century is the year 1588 in?", ["16th century", "15th century", "17th century", "18th century"], 0, "15 + 1 = 16th century (1501–1600). The Spanish Armada was in the 16th century."),
        S("Which century are we living in now? (e.g. 21st)", "21st", ["21st century", "twenty first", "twenty-first", "21"], "We live in the 21st century (2001–2100)."),
        M("The '1640s' means…", ["The decade 1640–1649", "The century 1600–1699", "Only the year 1640", "The years 1540–1640"], 0, "A decade is ten years; the 1640s are 1640–49 — the decade of the English Civil War."),
        M("What does AD stand for?", ["Anno Domini — in the year of the Lord", "After Death", "Ancient Date", "Anglo Dynasty"], 0, "AD (Anno Domini) counts years from the traditional date of Jesus' birth. 'After Death' is a common misconception. CE (Common Era) is the same count."),
        T("BC dates count backwards, so 300 BC is earlier than 100 BC.", true, "True. BC years count down towards year 1, so the bigger the BC number, the earlier the date."),
        O("Put these periods in chronological order.", ["Roman Britain", "Anglo-Saxon England", "Norman England", "Tudor England", "Victorian Britain"], "Romans AD 43–410; Anglo-Saxons c.410–1066; Normans from 1066; Tudors 1485–1603; Victorians 1837–1901."),
        O("Put these dates in chronological order.", ["55 BC", "AD 43", "1066", "1485", "1914"], "BC comes before AD: Caesar's raid 55 BC; Roman invasion AD 43; Norman Conquest 1066; Bosworth 1485; First World War 1914."),
        M("What is an 'anachronism'?", ["Something placed in the wrong time period", "A very old document", "A list of kings", "An unbiased source"], 0, "An anachronism is something out of its time, e.g. a Norman knight with a mobile phone or a Tudor using a train."),
        M("Which of these is an anachronism in a picture of the Battle of Hastings?", ["A soldier holding a musket", "A knight on horseback", "An archer with a bow", "A man with a kite-shaped shield"], 0, "Muskets (guns) were not used until centuries later. Horses, bows and kite shields were all used in 1066."),
        M("How many years are in a millennium?", ["1,000", "100", "10", "10,000"], 0, "A millennium is 1,000 years; a century is 100; a decade is 10."),
        S("What word means a period of 100 years?", "Century", ["centuries"], "A century is 100 years. The 19th century is 1801–1900."),
        M("Which of these is the 'early modern' period in British history?", ["c.1500–1750 (Tudors and Stuarts)", "c.1066–1500", "1900–2000", "AD 43–410"], 0, "Historians often call c.1500–1750 'early modern'; 1066–1500 is 'medieval'."),
        T("The 19th century includes the year 1850.", true, "True. The 19th century runs 1801–1900, so 1850 is in the middle of it — the age of Victoria."),
        M("The phrase 'c.1000' means…", ["About the year 1000 — the exact date is not certain", "Exactly the year 1000", "1000 BC", "100 years after 1000"], 0, "c. stands for circa, Latin for 'about'. It is used when an exact date is unknown."),
        O("Put these monarchs in chronological order.", ["William I", "King John", "Henry VIII", "Elizabeth I", "Queen Victoria"], "William I (1066–87), John (1199–1216), Henry VIII (1509–47), Elizabeth I (1558–1603), Victoria (1837–1901)."),
      ] },
    { name: 'Sources: evidence and inference', intro: "A source is anything from the past that gives evidence. An inference is something you work out from a source that it does not say directly.",
      items: [
        M("Which of these is a primary source for the Victorian period?", ["A photograph of a factory taken in 1870", "A 2020 documentary about Victorians", "A modern historian's book", "A website summary"], 0, "Primary sources come from the time. The other options were made later, so they are secondary."),
        M("What is an inference?", ["Something you work out from a source that it does not state directly", "A direct quotation", "A false statement", "The date of a source"], 0, "Inference means reading between the lines, e.g. a sermon against gambling suggests gambling was common."),
        W(src("Source A: a notice displayed in a factory, 1840s.", "Any worker arriving after the bell will lose a quarter of a day's wages. Talking at the machines is forbidden."), M("What can you infer from Source A?", ["Factory owners imposed strict discipline and fines on workers", "Workers were paid very well", "Factories were quiet and empty", "Workers could choose their own hours"], 0, "The fines for lateness and the ban on talking suggest strict control. Nothing suggests high pay or free hours.")),
        W(src("Source B: a parish record, 1665.", "Burials this month: 142. In the same month last year: 11."), M("What can you infer from Source B?", ["Something caused many more deaths in 1665, such as an epidemic", "The parish was getting smaller because of emigration", "Fewer people died in 1665", "The record must be wrong"], 0, "A rise from 11 to 142 burials suggests a disaster — 1665 was the year of the Great Plague in London. It is an inference supported by the figures.")),
        M("What does 'provenance' mean?", ["Where a source comes from: who made it, when, and why", "How long a source is", "Whether a source is true", "The place a source is kept now"], 0, "Provenance (author, date, purpose, audience) helps you judge how useful and reliable a source is."),
        T("A source can be unreliable but still useful.", true, "True. An unreliable source, such as propaganda, is very useful for showing what its maker wanted people to think."),
        MU("Which TWO things should you consider when judging how useful a source is?", ["Its content — what it tells you", "Its provenance — who made it, when and why", "How old the paper looks", "Whether it agrees with your opinion", "How many words it contains"], [0, 1], "AQA usefulness questions reward analysis of content and provenance, using your own knowledge of the context."),
        M("A diary written in secret is often considered more honest than a public speech because…", ["The writer did not expect anyone else to read it", "Diaries are always written by experts", "Speeches cannot be primary sources", "Diaries are longer"], 0, "A private diary has less reason to persuade an audience, though the writer may still be mistaken or only know part of the story."),
        S("What word describes material created to persuade people to believe something, often one-sided?", "Propaganda", [], "Propaganda is deliberately persuasive information, common in wartime posters and newspapers."),
        M("Which question is about a source's PURPOSE?", ["Why was this source made?", "When was this source made?", "Where is it kept now?", "How many pages has it got?"], 0, "Purpose is the reason it was produced — to inform, persuade, record, entertain or criticise."),
        T("A secondary source cannot be useful because its author was not there.", false, "False. Secondary sources by historians draw on many primary sources and can give an overview, though they are interpretations."),
        W(src("Source C: a cartoon in a British newspaper, 1830s, described.", "A thin child stands beside a huge spinning machine while a fat, well-dressed mill owner counts coins in the background."), M("What is the cartoonist's message?", ["Mill owners grew rich by exploiting child workers", "Children enjoyed factory work", "Machines were dangerous only for adults", "Mill owners were poor"], 0, "The contrast between the thin child and the fat owner counting money criticises exploitation. Cartoons use exaggeration and contrast to make a point.")),
        M("What is 'corroboration'?", ["Checking whether other sources support what one source says", "Writing a source yourself", "Destroying a biased source", "Translating a source"], 0, "Cross-referencing sources helps historians decide whether a claim is reliable."),
        S("What kind of source is a painting, photograph or poster: written or visual?", "Visual", ["visual source", "visual sources"], "Visual sources include paintings, cartoons, photos and posters. Read them by looking at details, symbols and captions."),
        M("A government poster from 1915 urging men to join the army is most useful for showing…", ["How the government tried to encourage recruitment", "Exactly how many men joined", "What trench life was really like", "The views of German soldiers"], 0, "Its provenance (government, wartime) means it shows the methods and messages of recruitment, not statistics or trench conditions."),
      ] },
    { name: 'Interpretations: why historians disagree', intro: "An interpretation is a view of the past created later by a historian, film-maker or writer. Interpretations differ because of the sources used, the focus chosen and when and why they were written.",
      items: [
        M("What is a historical interpretation?", ["A later view or explanation of the past", "A source made at the time", "A list of facts with no opinion", "A date in a timeline"], 0, "Interpretations are views created after the event, e.g. a historian's argument. Sources from the time are primary sources."),
        MU("Which TWO reasons can explain why historians disagree?", ["They use different sources", "They focus on different factors or people", "One of them must be lying", "History never changes", "They were both present at the event"], [0, 1], "Different evidence, focus, and the time and context in which they write lead to different interpretations. Disagreement does not mean lying."),
        M("Which statement is an OPINION rather than a fact?", ["King John was the worst king in English history", "King John sealed Magna Carta in 1215", "King John died in 1216", "King John was Henry II's son"], 0, "'Worst' is a judgement that people can argue about. The others can be checked against evidence."),
        T("An interpretation written in the 1950s might reflect the attitudes of the 1950s.", true, "True. Historians are influenced by their own time; e.g. older histories often ignored women and ordinary people."),
        M("Victorian historians often praised Elizabeth I as a heroic Protestant queen. Why?", ["They lived in a confident Protestant Britain with a powerful queen of its own", "They had found new letters proving it", "They were all Catholics", "Elizabeth had paid them"], 0, "Context shapes interpretations. Victorian Britain was proud of its Protestant, imperial identity and saw Elizabeth's reign as a golden age."),
        S("What word describes the purpose and situation in which an interpretation was produced (for example, wartime Britain)?", "Context", [], "Context means the circumstances of the time. Always ask: what was happening when this interpretation was created?"),
        M("Which type of interpretation is most likely to exaggerate for dramatic effect?", ["A Hollywood film", "An academic history book", "A museum catalogue", "A census record"], 0, "Films entertain audiences, so they may add romance or drama. A census is a primary source, not an interpretation."),
        T("If two historians disagree, one must be using fake evidence.", false, "False. They may select different evidence, weigh it differently or ask different questions."),
        M("Historian A says the Black Death was a disaster for peasants. Historian B says it improved peasants' lives in the long run. Why might both be partly right?", ["A focuses on the deaths in 1348–49, B on higher wages later", "One of them made it up", "They are writing about different countries", "Peasants did not exist"], 0, "Both use evidence: huge death tolls in the short term, but labour shortages raised wages later. Different time-frames give different views."),
        M("When asked 'How convincing is an interpretation?', you should…", ["Test it against your own knowledge — what supports it and what challenges it", "Copy out the interpretation", "Just say whether you like it", "Describe the author's appearance"], 0, "Convincing = how well it fits the evidence you know. Use precise facts that support or challenge it."),
        S("What is a word for a view of the past that is deliberately one-sided, e.g. written to support a ruler?", "Biased", ["bias", "one-sided", "propaganda"], "A biased interpretation selects evidence to support a particular view."),
        O("Put the steps for analysing an interpretation in a sensible order.", ["Read it and identify its main argument", "Note the author, date and purpose", "Use your knowledge to find support", "Use your knowledge to find challenges", "Reach a judgement on how convincing it is"], "Identify the argument, consider provenance, test it with knowledge on both sides, then judge."),
        M("A textbook says 'The Normans brought order and progress.' Another says 'The Normans brought terror and destruction.' Which evidence could support the second view?", ["The Harrying of the North, 1069–70", "The building of cathedrals", "The Domesday Book organising taxation", "The use of Latin in documents"], 0, "The Harrying of the North caused mass starvation, supporting 'terror'. Cathedrals and Domesday fit the 'order' view."),
        T("Interpretations can change when new evidence is discovered.", true, "True. For example, archaeology and DNA evidence (such as the 2012 discovery of Richard III's skeleton) have changed views of the past."),
        M("Which question best tests an interpretation?", ["What evidence is there for and against this view?", "How many pages is the book?", "Is the author famous?", "Is it written in the present tense?"], 0, "Weighing evidence is the core historical skill. Fame or length do not make an interpretation correct."),
      ] },
  ],
  {
    overview: "History is built from evidence. Before studying any period you need three tools: chronology (placing events in time), source skills (inference, content and provenance) and interpretation skills (understanding why views of the past differ). These are tested throughout the AQA GCSE.",
    objectives: ["I can convert years to centuries and order dates including BC/AD.", "I can make inferences from written and visual sources.", "I can judge a source's usefulness using content and provenance.", "I can explain why interpretations of the past differ."],
    keyWords: [
      { term: 'Chronology', def: 'The order in which events happened.' },
      { term: 'Century', def: 'A period of 100 years (e.g. the 16th century = 1501–1600).' },
      { term: 'Primary source', def: 'Evidence from the time being studied.' },
      { term: 'Secondary source', def: 'Material created later about the past.' },
      { term: 'Inference', def: 'A conclusion you work out from a source that it does not state directly.' },
      { term: 'Provenance', def: 'Who made a source, when, and why.' },
      { term: 'Interpretation', def: 'A later view or explanation of the past.' },
      { term: 'Anachronism', def: 'Something placed in the wrong period.' },
    ],
    sections: [
      { title: 'Chronology', html: "<div class=\"rule\">Century rule: take the first two digits and add one. 1066 → 10 + 1 = 11th century. 1900 is the last year of the 19th century.</div><p>BC dates count down to year 1; AD (or CE) dates count up. There is no year 0.</p><table class=\"qt\"><tr><th>Period</th><th>Approximate dates</th></tr><tr><td>Roman Britain</td><td>AD 43–410</td></tr><tr><td>Anglo-Saxon England</td><td>c.410–1066</td></tr><tr><td>Medieval (Norman to Plantagenet)</td><td>1066–1485</td></tr><tr><td>Tudors</td><td>1485–1603</td></tr><tr><td>Stuarts</td><td>1603–1714</td></tr><tr><td>Georgians</td><td>1714–1837</td></tr><tr><td>Victorians</td><td>1837–1901</td></tr></table>" },
      { title: 'Working with sources', html: "<p>Ask three questions of any source:</p><ol><li><b>Content</b> — what does it say or show? What can I infer?</li><li><b>Provenance</b> — who made it, when, why and for whom?</li><li><b>Context</b> — what do I know about the time that helps explain it?</li></ol><div class=\"note\">Never call a source useless just because it is biased. Ask: what is it useful <i>for</i>?</div>" },
      { title: 'Interpretations', html: "<p>Interpretations differ because historians use different <b>evidence</b>, focus on different <b>factors</b>, and write in different <b>contexts</b>. To judge an interpretation, test its argument against your own knowledge: what supports it and what challenges it?</p>" },
      { title: 'Model answer: making an inference', html: worked("Give two things you can infer from Source A (the 1840s factory notice).", ["Pick a detail from the source.", "State what it suggests.", "Quote or describe the detail that supports it."], "Inference 1: Factory owners controlled workers strictly. Detail: workers lost a quarter of a day's pay for arriving after the bell.<br>Inference 2: Workers had little freedom at work. Detail: talking at the machines was forbidden.") },
    ],
    mistakes: ["Saying 1066 is in the 10th century — it is the 11th.", "Calling a source useless because it is biased.", "Describing a source without making an inference.", "Treating interpretations as facts rather than arguments."],
    examTips: ["AQA 'infer' questions want a clear inference plus a supporting detail from the source.", "In usefulness questions always use both content and provenance, backed by your own knowledge.", "In interpretation questions, judge how convincing — support AND challenge."],
    realLife: "Checking the provenance of what you read online is the same skill historians use with sources.",
  },
);

// ---- extra practice: Chronology and Sources ----
more('hist-y7-chronology-sources-1', [
  M('Which century is the year 1914 in?', ['20th century', '19th century', '21st century', '14th century'], 0, 'The 20th century runs from 1901 to 2000, so 1914 is in it. The trap is to read the first two digits (19) and say ‘19th’; you add one to get the century.'),
  M('Which century is the year 1801 in?', ['19th century', '18th century', '8th century', '20th century'], 0, 'Add one to the first two digits: 18 + 1 = 19, so 1801 is in the 19th century (1801–1900).'),
  S('In which decade is the year 1969? (e.g. 1920s)', '1960s', ['the 1960s', 'sixties', 'the sixties', '60s'], 'A decade is ten years. 1960–1969 are the 1960s, so 1969 is the last year of that decade.'),
  { type: 'number', q: 'How many years passed between the Battle of Hastings (1066) and Magna Carta (1215)?', value: 149, tol: 0, unit: 'years', answer: '149 years', steps: ['For two AD dates, subtract the earlier from the later.', '1215 − 1066 = 149', 'Answer: 149 years'], explain: 'Subtract the earlier date from the later one: 1215 − 1066 = 149 years. Working out gaps like this helps you see how far apart events really were.' },
  M('What do the letters BCE and CE stand for?', ['Before Common Era and Common Era', 'Before Christ Ended and Christ Era', 'British Calendar Era and Calendar Era', 'Before Century Era and Century Era'], 0, 'BCE and CE are non-religious alternatives to BC and AD. The numbers are the same: 1066 CE is the same year as AD 1066.'),
  T('There is no year 0: 1 BC is followed directly by AD 1.', true, 'True. The calendar jumps from 1 BC to AD 1. This is why the 1st century is AD 1–100 and why centuries end in a ‘00’ year.'),
  M('Roughly which dates are usually given for the medieval period (the Middle Ages) in Britain?', ['c.500–c.1500', 'c.1500–c.1750', '1066–1215', '1750–1900'], 0, 'The Middle Ages run roughly from the end of Roman Britain to around 1500 (often ending with the Tudors in 1485). 1500–1750 is usually called early modern.'),
  M('Which years did Queen Victoria reign, giving us the ‘Victorian’ period?', ['1837–1901', '1714–1760', '1558–1603', '1901–1910'], 0, 'Victoria reigned from 1837 to 1901, the longest reign before Elizabeth II. 1558–1603 was Elizabeth I; 1901–1910 was Edward VII.'),
  O('Put these events in chronological order.', ['Julius Caesar’s first expedition to Britain (55 BC)', 'The Roman conquest of Britain begins under Claudius (AD 43)', 'Roman rule in Britain ends (c. AD 410)', 'The Norman Conquest (1066)'], 'BC dates come before AD dates. Caesar’s raids were in 55 and 54 BC; Claudius invaded in AD 43; Roman rule ended around 410; the Normans arrived in 1066.'),
  M('What does ‘contemporary’ mean when describing a source?', ['From the same time as the events it describes', 'Very modern', 'Written by a famous historian', 'Completely reliable'], 0, 'A contemporary source was made at the time of the events. In everyday speech ‘contemporary’ can mean ‘modern’, but in history it means ‘of the same time’.'),
  S('What word means a list or diagram of events in date order?', 'Timeline', ['time line', 'a timeline', 'chronology'], 'A timeline shows events in chronological order. Chronology is the wider skill of placing events in order and understanding how far apart they are.'),
  M('What is a dynasty?', ['A series of rulers from the same family', 'A single long battle', 'A type of castle', 'A law passed by Parliament'], 0, 'Examples are the Normans, Plantagenets, Tudors and Stuarts. Using dynasties helps you organise the past into periods.'),
  MU('Which TWO of these years are in the 16th century?', ['1509', '1588', '1485', '1603', '1715'], [0, 1], 'The 16th century is 1501–1600. 1509 (Henry VIII’s accession) and 1588 (the Armada) are in it. 1485 is the 15th century, 1603 the 17th and 1715 the 18th.'),
  M('In history, what does ‘continuity’ mean?', ['Things staying the same over time', 'Things changing suddenly', 'A list of dates', 'A type of primary source'], 0, 'Continuity is the opposite of change. For example, most people stayed farmers from the Normans to the 1700s. GCSE questions often ask about both change and continuity.'),
  M('What is a ‘turning point’?', ['An event after which things changed significantly', 'Any event that happened in a war', 'The last event of a period', 'An event nobody remembers'], 0, 'A turning point marks a major change in direction, such as 1066 or the break with Rome. Not every event is a turning point; you need to show what was different afterwards.'),
]);
more('hist-y7-chronology-sources-2', [
  M('What is the difference between a source being <i>reliable</i> and being <i>useful</i>?', ['Reliable means you can trust it; useful means it helps answer a particular question', 'They mean exactly the same thing', 'Reliable sources are always primary; useful ones are always secondary', 'Useful means it is long; reliable means it is short'], 0, 'A biased source can be unreliable about facts but very useful for showing attitudes. Always link usefulness to the question being asked.'),
  W(src('Source C: an imaginary statement in the style of evidence given to an 1832 parliamentary inquiry into factory children.', 'I started at the mill when I was eight. We worked from six in the morning till eight at night. If we fell asleep the overseer beat us with a strap.'), M('What can you infer from Source C?', ['Children worked very long hours and were harshly disciplined', 'Children enjoyed short working days', 'Factories had no adult supervisors', 'Children only worked at weekends'], 0, 'Six until eight is a fourteen-hour day, and the strap shows physical punishment. An inference goes beyond copying the words to state what they show.')),
  M('Why might evidence given to a reform committee in the 1830s be exaggerated?', ['The committee was set up by reformers who wanted shocking evidence to change the law', 'Witnesses were paid by mill owners to praise factories', 'Nobody in the 1830s could speak English', 'It was written 200 years later'], 0, 'Reformers chose witnesses who would support their case. This does not make the evidence false, but a historian should cross-reference it with other sources such as factory records.'),
  M('Why might a photograph not show the full truth?', ['The photographer chose what to include, and it may have been posed or staged', 'Cameras always lie', 'Photographs are secondary sources', 'Photographs cannot be dated'], 0, 'Photos are selective: they show one moment from one angle, and early photos often needed people to pose. They are still very useful if you think about who took them and why.'),
  T('A source written long after events may be affected by hindsight.', true, 'True. Hindsight is knowing what happened next. A memoir written decades later may change details or explain events with knowledge the writer did not have at the time.'),
  M('Why are there few written sources by medieval peasants?', ['Most peasants could not read or write', 'Peasants were banned from owning paper', 'All peasant writing was destroyed by Henry VIII', 'Peasants wrote only in Chinese'], 0, 'Literacy was mostly limited to clergy and some nobles. Historians learn about peasants from manor records, court rolls and archaeology, which were mainly produced by others.'),
  S('What word describes a person who saw an event with their own eyes?', 'Eyewitness', ['an eyewitness', 'eye witness', 'witness'], 'An eyewitness was present at an event. Their account can be detailed but may still be limited by what they saw, their memory and their point of view.'),
  M('Which of these is an example of archaeological evidence?', ['Skeletons and pottery found in an excavated village', 'A modern textbook', 'A television documentary', 'A Victorian novel'], 0, 'Archaeology studies physical remains. It is especially useful for groups who left few written records. The other options are later interpretations or fiction.'),
  M('What is a census most useful for?', ['Finding out who lived in a household, their ages and jobs', 'Learning what people thought about the king', 'Finding out what people ate for breakfast', 'Discovering the causes of wars'], 0, 'The census, taken every ten years in Britain since 1801 (with names from 1841), records people, ages, jobs and birthplaces. It does not record opinions.'),
  M('In source work, what does ‘context’ mean?', ['What was happening at the time the source was made', 'The number of words in the source', 'The colour of a picture', 'The name of the library where it is kept'], 0, 'Context is the historical background. Using your own knowledge of the context helps you explain why a source says what it does and how far it is accurate.'),
  MU('Which TWO features could make a source less reliable?', ['The author wanted to persuade readers to a point of view', 'The author was writing many years later from memory', 'It is written in old-fashioned language', 'It is handwritten', 'It is short'], [0, 1], 'Purpose and distance in time affect reliability. Old language, handwriting or length do not by themselves make a source more or less trustworthy.'),
  O('Put these steps of a historical enquiry in a sensible order.', ['Ask a clear question', 'Find relevant sources', 'Compare and cross-reference the sources', 'Reach a supported conclusion'], 'Historians begin with a question, gather evidence, test sources against each other and then reach a conclusion they can support.'),
  W(src('Source D: a description of a cartoon from the 1830s.', 'A huge, well-fed factory owner sits in a comfortable chair, which rests on the backs of small, thin children bent double.'), M('What is the cartoonist’s message?', ['Factory owners grew rich by exploiting child workers', 'Children enjoyed working in factories', 'Factory owners were poor', 'Furniture was badly made in the 1830s'], 0, 'The contrast between the fat owner and the thin children carrying him shows that the owner’s comfort depends on the children’s suffering. Cartoons use exaggeration and symbols to make a point.')),
  T('Official government statistics are always completely accurate.', false, 'False. Statistics depend on how information was collected. People could avoid counting, officials made mistakes and some figures were estimates. They are useful but need checking.'),
  M('A small number of letters written by one rich family survive. What is a key limitation for a historian?', ['They may not be typical of how most people lived', 'They cannot be primary sources', 'Letters are always lies', 'They are too recent'], 0, 'One family’s experience may not represent everyone, especially poorer people. Historians ask whether a source is typical before drawing general conclusions.'),
]);
more('hist-y7-chronology-sources-3', [
  M('What is the main difference between a primary source and an interpretation?', ['A source comes from the time; an interpretation is a later view of the past', 'Interpretations are always pictures', 'Sources are always true; interpretations are always false', 'There is no difference'], 0, 'A source is evidence from the period. An interpretation is a deliberate later explanation or portrayal of the past, built from evidence and the author’s ideas.'),
  MU('Which TWO of these are interpretations rather than primary sources?', ['A museum display about the Tudors written in 2015', 'A historical novel set during the Civil War', 'A letter written by a soldier in 1643', 'The Domesday Book', 'A Victorian factory wage book'], [0, 1], 'The museum display and the novel are later views of the past. The letter, Domesday Book and wage book were created at the time, so they are primary sources.'),
  M('One historian studies Tudor monarchs; another studies Tudor villagers. Why might their interpretations of the period differ?', ['They focus on different people and use different evidence', 'One of them must be lying', 'Tudor history has no evidence', 'They studied different centuries'], 0, 'The focus of a historian shapes their conclusions. History from the top (rulers) and from below (ordinary people) can give different pictures of the same period.'),
  W(src('Interpretation A: a historian writing in the 1900s.', 'King John was a cruel and treacherous tyrant whom no one could trust.') + src('Interpretation B: a historian writing in the 1990s.', 'John was a hard-working ruler who faced huge problems, though his suspicious nature made them worse.'), M('How do Interpretations A and B differ?', ['A is entirely hostile; B is more balanced, blaming circumstances as well as John', 'Both say John was a hero', 'A praises John; B condemns him', 'They agree completely'], 0, 'A sees John only as a tyrant. B accepts some of his faults but stresses his hard work and difficult situation. Comment on tone and emphasis, not just on facts.')),
  M('Why might the historians in the previous question have reached different views of King John?', ['Earlier historians relied heavily on hostile monk chronicles, while later historians used government records too', 'King John lived in two different centuries', 'One historian was a friend of King John', 'Records about John were only discovered in 2020'], 0, 'Monastic chroniclers disliked John. Later historians studied administrative records showing his hard work, which led to a more balanced view.'),
  M('What is a ‘revisionist’ historian?', ['One who challenges and changes an accepted interpretation', 'One who copies earlier historians exactly', 'One who only studies revision guides', 'One who refuses to use evidence'], 0, 'Revisionists re-examine the evidence and offer a new view. Their ideas are then tested and debated, so interpretations keep developing.'),
  M('A film about the Tudors adds a dramatic love scene that is not mentioned in any evidence. Why?', ['To entertain an audience', 'Because new evidence was found', 'To make the film more historically accurate', 'Because historians required it'], 0, 'Films and novels are made to entertain, so they may invent scenes. That makes them useful for showing how the past is remembered, but weak as evidence of what happened.'),
  T('An interpretation can be supported by evidence and still be only partly right.', true, 'True. Historians select evidence. An interpretation may be well supported on one issue but miss other factors, which is why ‘how far’ judgements matter.'),
  M('Some historians argue the Industrial Revolution made life better for workers; others argue it made life worse at first. What is this debate mainly about?', ['Living standards during industrialisation', 'The date of the Battle of Hastings', 'Whether factories existed', 'The causes of the Black Death'], 0, 'This is the ‘standard of living’ debate: optimists point to cheaper goods and rising wages later; pessimists point to slums, disease and long hours in the early decades.'),
  O('Put these steps for judging how convincing an interpretation is in a sensible order.', ['Identify the main claim of the interpretation', 'Recall relevant knowledge of the period', 'Test the claim against that knowledge and evidence', 'Reach a judgement on how convincing it is'], 'First understand what is being argued, then bring in what you know, test the argument against evidence, and finally make a clear judgement.'),
  S('What word means knowing what happened after an event, which can change how we judge it?', 'Hindsight', ['hind sight'], 'Hindsight can help historians see long-term consequences, but it can also make outcomes seem more obvious than they were to people at the time.'),
  M('A historian writing in Britain in 1945 praises Churchill as the nation’s saviour. What is the most important context?', ['Britain had just won the Second World War under his leadership', 'Churchill had just died', 'The historian had never heard of Churchill', 'It was written during the Norman Conquest'], 0, 'Writing just after victory, with strong national pride, would encourage praise. Churchill died in 1965. Context helps explain why an interpretation says what it does.'),
  M('Which phrase shows a historian is being careful about the strength of their evidence?', ['‘The evidence suggests that…’', '‘It is completely certain that…’', '‘Everyone knows that…’', '‘Obviously…’'], 0, 'Good historians match their language to the evidence. Words like ‘suggests’ or ‘probably’ show caution where the evidence is limited.'),
  T('Historians usually agree on basic facts such as dates, but often disagree about causes and significance.', true, 'True. Few people dispute that Hastings was in 1066, but historians argue about why William won and how much the Conquest changed England.'),
  M('Interpretation C about Charles I uses only evidence written by his supporters. What is its main weakness?', ['It is based on selective evidence and may be one-sided', 'It uses too many sources', 'It is too recent', 'It contains no opinions'], 0, 'Using only one side’s evidence makes an interpretation unbalanced. A convincing interpretation tests its argument against evidence from different viewpoints.'),
]);
// =====================================================================
// YEAR 8 — The Tudors and the Reformation
// =====================================================================
addTopic(
  { id: 'hist-y8-tudors-reformation', strand: 'hist-ks3', year: 8, term: 1, name: 'The Tudors and the Reformation',
    summary: 'How the Tudors won the throne, why Henry VIII broke with Rome, and how religion see-sawed under Edward VI, Mary I and Elizabeth I.',
    specRef: 'DfE KS3 History: the development of Church, state and society in Britain 1509–1745 (Renaissance and Reformation)' },
  [
    { name: 'Henry VII, Henry VIII and the break with Rome', intro: "Henry VII won the crown at Bosworth in 1485. His son Henry VIII broke away from the Pope in the 1530s, mainly because he wanted a male heir and a new marriage.",
      items: [
        M("At which battle did Henry Tudor defeat Richard III in 1485?", ["Bosworth", "Hastings", "Towton", "Agincourt"], 0, "Henry Tudor won at Bosworth Field (22 August 1485), ending the Wars of the Roses. Agincourt (1415) was Henry V's victory in France."),
        M("Why did Henry VII marry Elizabeth of York?", ["To unite the houses of Lancaster and York and end the Wars of the Roses", "To gain land in Spain", "Because the Pope ordered him to", "To become Protestant"], 0, "The marriage joined Lancaster (Henry) and York (Elizabeth); the Tudor rose combined their red and white roses."),
        S("Who was Henry VIII's first wife?", "Catherine of Aragon", ["catherine", "katherine of aragon", "catherine of aragon"], "Catherine of Aragon, a Spanish princess, married Henry in 1509. Their only surviving child was Mary (born 1516)."),
        M("What was Henry VIII's main reason for wanting to end his first marriage?", ["He wanted a male heir and Catherine had not given him a son who survived", "Catherine had become Protestant", "Catherine wanted to rule alone", "The Pope ordered it"], 0, "Henry feared that without a son the Tudor dynasty could collapse into civil war. He also loved Anne Boleyn and argued that marrying his brother's widow was against the Bible."),
        M("Why would the Pope not grant Henry an annulment?", ["Catherine's nephew, Emperor Charles V, controlled Rome and the Pope", "The Pope was English", "Henry was already Protestant", "Annulments did not exist"], 0, "After the Sack of Rome in 1527, the Pope was under the power of Charles V, Catherine's nephew, so he could not risk offending him."),
        S("Which Act of 1534 made Henry VIII Supreme Head of the Church of England?", "Act of Supremacy", ["supremacy", "the act of supremacy"], "The Act of Supremacy (1534) declared the king, not the Pope, Supreme Head of the Church in England."),
        M("Which German monk began the Protestant Reformation in 1517?", ["Martin Luther", "John Calvin", "Thomas Cranmer", "Thomas More"], 0, "Luther's 95 Theses (1517) attacked the sale of indulgences. Calvin was a later Protestant reformer in Geneva; Cranmer and More were English."),
        M("Which of Henry's ministers failed to get the annulment and fell from power in 1529?", ["Cardinal Wolsey", "Thomas Cromwell", "Thomas Cranmer", "William Cecil"], 0, "Wolsey failed to persuade the Pope and was dismissed; he died in 1530 on the way to face treason charges. Cromwell then organised the break with Rome."),
        T("Henry VIII was given the title 'Defender of the Faith' by the Pope for attacking Martin Luther.", true, "True. In 1521 Pope Leo X gave Henry the title after he wrote a book defending Catholic teaching. British monarchs still use it."),
        O("Put Henry VIII's wives in the order he married them.", ["Catherine of Aragon", "Anne Boleyn", "Jane Seymour", "Anne of Cleves", "Catherine Howard", "Catherine Parr"], "Rhyme: divorced, beheaded, died, divorced, beheaded, survived — Aragon, Boleyn, Seymour, Cleves, Howard, Parr."),
        M("Which wife gave birth to Henry's son, the future Edward VI?", ["Jane Seymour", "Anne Boleyn", "Catherine of Aragon", "Catherine Parr"], 0, "Jane Seymour gave birth to Edward in October 1537 and died days later. Anne Boleyn was the mother of Elizabeth."),
        S("Which Archbishop of Canterbury annulled Henry's marriage to Catherine in 1533?", "Thomas Cranmer", ["cranmer"], "Cranmer, a reformer, declared the marriage invalid in May 1533 so Henry's marriage to Anne Boleyn could be recognised."),
        T("Breaking with Rome immediately made England a fully Protestant country.", false, "False. Henry changed who led the Church, but many Catholic beliefs, such as the Mass, remained. England became more Protestant under Edward VI."),
        MU("Which TWO were reasons for Henry VIII's break with Rome?", ["Desire for a male heir", "Desire for the Church's wealth and power", "Henry's belief in Calvin's ideas", "The Spanish Armada", "The Gunpowder Plot"], [0, 1], "Henry wanted a son and a new marriage; he also gained power and wealth by controlling the Church. The Armada (1588) and Gunpowder Plot (1605) came later."),
        S("In which year did Henry VIII become king?", "1509", [], "Henry VIII became king in April 1509 aged 17 and reigned until 1547."),
        M("What was Anne Boleyn's fate?", ["She was executed in 1536", "She outlived Henry", "She returned to Spain", "She became queen regnant"], 0, "Anne failed to give Henry a son and was executed on charges of adultery and treason in May 1536."),
      ] },
    { name: 'The Reformation and the dissolution of the monasteries', intro: "Between 1536 and 1540 Thomas Cromwell closed every monastery in England and Wales. This transferred huge wealth to the Crown and changed religious life — but it also provoked rebellion.",
      items: [
        M("Who organised the dissolution of the monasteries for Henry VIII?", ["Thomas Cromwell", "Cardinal Wolsey", "Robert Aske", "Thomas More"], 0, "Cromwell, the king's chief minister, sent commissioners to inspect monasteries and closed them between 1536 and 1540."),
        S("Between which years were the monasteries dissolved? Give the start year.", "1536", [], "The smaller monasteries were closed from 1536 and the larger ones by 1540."),
        MU("Which TWO were reasons for the dissolution?", ["The Crown wanted the monasteries' land and wealth", "Monasteries were seen as loyal to the Pope", "Monks had started a civil war", "Monasteries were all empty", "The Spanish wanted them closed"], [0, 1], "Henry needed money and saw monasteries as centres of papal loyalty. Reports of corruption were used as justification, though often exaggerated."),
        M("What was the Valor Ecclesiasticus (1535)?", ["A survey of the Church's wealth", "A Protestant prayer book", "A list of Henry's wives", "A law against heresy"], 0, "It recorded the value of church property, telling Cromwell exactly how much the monasteries were worth."),
        M("What was the Pilgrimage of Grace (1536)?", ["A large northern rebellion partly against the dissolution", "A trip to Canterbury", "Henry's tour of France", "A Protestant march to London"], 0, "Up to 30,000 people in Yorkshire and Lincolnshire rose up. Leader Robert Aske was later executed."),
        S("Who led the Pilgrimage of Grace?", "Robert Aske", ["aske"], "Robert Aske, a lawyer, led the rebels. Henry promised a pardon but later had Aske executed in 1537."),
        T("Some monastery land was sold to the gentry, giving them a reason to support the break with Rome.", true, "True. Wealthy families who bought monastery land had a stake in keeping England independent from the Pope."),
        M("What was one negative consequence of the dissolution for ordinary people?", ["Loss of care for the poor and sick that monks had provided", "Higher wages for everyone", "More schools in every village", "Free land for peasants"], 0, "Monasteries gave alms, hospital care and shelter; their closure contributed to poverty and vagrancy."),
        M("What was the Great Bible of 1539?", ["An official Bible in English placed in every parish church", "A Latin Bible for priests only", "A Protestant Bible banned by Henry", "A book of Catholic saints"], 0, "Cromwell ordered an English Bible in every church so ordinary people could hear scripture in their language — a Protestant idea."),
        M("Which belief is Catholic rather than Protestant?", ["The Pope is head of the Church", "The Bible should be in English", "Priests may marry", "Faith alone brings salvation"], 0, "Catholics accepted the Pope's authority. Protestants stressed the Bible in the vernacular, faith alone and married clergy."),
        MU("Which TWO are Protestant beliefs?", ["Salvation through faith alone", "Church services in the people's own language", "The Pope's authority", "Purgatory", "Seven sacraments"], [0, 1], "Protestants rejected the Pope, Purgatory and most sacraments (keeping only baptism and communion)."),
        T("Thomas Cromwell was executed in 1540.", true, "True. After arranging Henry's disastrous marriage to Anne of Cleves, Cromwell fell from favour and was executed in July 1540."),
        S("What word describes beliefs that go against the official teaching of the Church?", "Heresy", ["heresies", "heretical"], "Heresy could be punished by burning. Both Catholic and Protestant rulers burned heretics in the 1500s."),
        O("Put these in chronological order.", ["Luther's 95 Theses", "Act of Supremacy", "Pilgrimage of Grace", "Great Bible in English"], "1517; 1534; 1536; 1539."),
        M("Who was Thomas More?", ["A Catholic lawyer and former Lord Chancellor executed for refusing to accept Henry as head of the Church", "A Protestant preacher", "Leader of the Pilgrimage of Grace", "Henry VIII's son"], 0, "More refused the Oath of Supremacy and was executed in 1535. He was later made a Catholic saint."),
      ] },
    { name: 'The religious see-saw: Edward, Mary and Elizabeth', intro: "Between 1547 and 1559 England's official religion swung from Protestant to Catholic and back again. Each change brought new laws, persecution and resistance.",
      items: [
        M("What was the religion of Edward VI's government?", ["Strongly Protestant", "Strongly Catholic", "Muslim", "Puritan only"], 0, "Edward (1547–53) and his advisers made England firmly Protestant, e.g. the English Book of Common Prayer (1549)."),
        S("Which English prayer book was introduced under Edward VI in 1549?", "Book of Common Prayer", ["common prayer", "the book of common prayer", "prayer book"], "Cranmer's Book of Common Prayer replaced the Latin Mass with English services."),
        M("Who was queen for about nine days in July 1553?", ["Lady Jane Grey", "Mary I", "Anne Boleyn", "Mary Queen of Scots"], 0, "Protestant Lady Jane Grey was proclaimed queen to stop Catholic Mary, but Mary gained popular support and took the throne. Jane was executed in 1554."),
        M("What did Mary I do to religion in England?", ["Restored Catholicism and the Pope's authority", "Made England more Protestant", "Founded the Church of Scotland", "Banned all religion"], 0, "Mary (1553–58) brought back the Mass and reunited the English Church with Rome."),
        M("Why is Mary I sometimes called 'Bloody Mary'?", ["Around 280 Protestants were burned as heretics during her reign", "She fought many wars against France", "She executed all of Henry's wives", "She caused the Black Death"], 0, "About 280 Protestants were burned (1555–58), recorded vividly by Protestant writer John Foxe. Some historians argue the nickname reflects Protestant propaganda."),
        S("Whom did Mary I marry in 1554, causing fears of Spanish control?", "Philip of Spain", ["philip", "philip ii", "philip ii of spain"], "Mary married Philip (later Philip II of Spain). Fear of foreign influence sparked Wyatt's Rebellion (1554)."),
        T("Archbishop Thomas Cranmer was burned at the stake under Mary I.", true, "True. Cranmer was burned in Oxford in 1556, as were bishops Latimer and Ridley in 1555."),
        M("Which English territory in France was lost in 1558 under Mary?", ["Calais", "Normandy", "Gascony", "Brittany"], 0, "Calais, held since 1347, fell to the French in January 1558. Normandy had been lost in 1204."),
        S("In which year did Elizabeth I become queen?", "1558", [], "Elizabeth succeeded her half-sister Mary on 17 November 1558."),
        M("What was Elizabeth's title in her 1559 Act of Supremacy?", ["Supreme Governor of the Church of England", "Supreme Head of the Church", "Pope of England", "Defender of the Reformation"], 0, "'Governor' rather than 'Head' was less offensive to Catholics and to those who felt a woman should not head the Church."),
        M("Elizabeth's Religious Settlement of 1559 is often described as a 'middle way' because…", ["It was Protestant in belief but kept some Catholic features like bishops and vestments", "It banned both Catholics and Protestants", "It let each parish choose its own religion", "It made England Catholic again"], 0, "The Settlement was Protestant (English prayer book, royal supremacy) but kept bishops, some ceremonies and clergy vestments to reassure Catholics."),
        O("Put these monarchs in order of reign.", ["Henry VII", "Henry VIII", "Edward VI", "Mary I", "Elizabeth I"], "Henry VII 1485–1509; Henry VIII 1509–47; Edward VI 1547–53; Mary I 1553–58; Elizabeth I 1558–1603."),
        T("Edward VI and Elizabeth I were both children of Anne Boleyn.", false, "False. Elizabeth was Anne Boleyn's daughter; Edward was Jane Seymour's son; Mary was Catherine of Aragon's daughter."),
        M("Why was the religious see-saw difficult for ordinary people?", ["Their church services and beliefs kept changing by law, with punishments for refusing", "They had to move house each time", "Churches were closed for 20 years", "They had to learn Spanish"], 0, "Parishes had to strip and restore altars, images and service books with each change; refusing could mean fines or worse."),
        S("What name was given to Catholics who refused to attend Church of England services under Elizabeth?", "Recusants", ["recusant"], "Recusants were fined (12 pence per Sunday under the Act of Uniformity of 1559)."),
      ] },
  ],
  {
    overview: "The Tudors (1485–1603) transformed England. Henry VII founded a new dynasty; Henry VIII broke with the Pope to secure a male heir and control the Church; and his three children swung the country between Protestant and Catholic before Elizabeth's 'middle way' settled it.",
    objectives: ["I can explain why Henry VIII broke with Rome.", "I can describe and explain the dissolution of the monasteries.", "I can compare the religious policies of Edward VI, Mary I and Elizabeth I.", "I can use the terms Catholic, Protestant, Reformation and heresy accurately."],
    keyWords: [
      { term: 'Reformation', def: 'The 16th-century movement that split the Western Church into Catholic and Protestant.' },
      { term: 'Annulment', def: 'A declaration that a marriage was never valid.' },
      { term: 'Act of Supremacy', def: 'Law (1534) making Henry VIII head of the English Church; reissued 1559 for Elizabeth as Supreme Governor.' },
      { term: 'Dissolution', def: 'Closing down of the monasteries, 1536–40.' },
      { term: 'Protestant', def: 'Christian who rejected the Pope’s authority and stressed the Bible and faith.' },
      { term: 'Heresy', def: 'Beliefs that go against official Church teaching.' },
      { term: 'Recusant', def: 'A Catholic who refused to attend Church of England services.' },
    ],
    sections: [
      { title: 'Why did Henry VIII break with Rome?', html: "<ul><li><b>Succession:</b> no surviving son with Catherine of Aragon; fear of civil war.</li><li><b>Love:</b> Henry wanted to marry Anne Boleyn.</li><li><b>Religion:</b> he argued marrying his brother's widow was against Leviticus; reformers such as Cranmer influenced him.</li><li><b>Power and money:</b> controlling the Church gave him wealth and authority.</li></ul><p>The Pope, controlled by Catherine's nephew Charles V, refused. Parliament passed the <b>Act of Supremacy (1534)</b>.</p>" },
      { title: 'Key dates', html: timeline([["1485", "Battle of Bosworth; Henry VII king"], ["1509", "Henry VIII king; marries Catherine of Aragon"], ["1517", "Luther's 95 Theses"], ["1533", "Henry marries Anne Boleyn; Elizabeth born"], ["1534", "Act of Supremacy"], ["1536–40", "Dissolution of the monasteries; Pilgrimage of Grace 1536"], ["1547–53", "Edward VI: Protestant reforms"], ["1553–58", "Mary I: Catholic restoration; c.280 burnings"], ["1559", "Elizabeth's Religious Settlement"]]) },
      { title: 'Key people', html: people([["Henry VIII", "Broke with Rome; six wives; dissolved the monasteries."], ["Thomas Cromwell", "Chief minister; organised the break with Rome and the dissolution."], ["Thomas Cranmer", "Protestant Archbishop; annulled Henry's first marriage; wrote the Book of Common Prayer; burned 1556."], ["Mary I", "Catholic queen; married Philip of Spain; persecuted Protestants."], ["Elizabeth I", "Protestant 'middle way' settlement, 1559."]]) },
      { title: 'Model answer', html: worked("Explain why Henry VIII broke with the Catholic Church. (8 marks)", ["Identify two causes: succession and money/power.", "Support each with specific evidence.", "Explain how each pushed Henry to break with Rome; link them."], "Model paragraph: The most important reason was Henry's desire for a male heir. By the late 1520s Catherine of Aragon was in her forties and their only surviving child was Mary. Henry believed a woman could not hold the throne securely and feared a return to civil war like the Wars of the Roses. When the Pope refused an annulment, because he was under the control of Catherine's nephew Charles V, Henry had no way of remarrying legally except by rejecting the Pope's authority, which he did through the Act of Supremacy in 1534.") },
    ],
    mistakes: ["Thinking Henry VIII was a Protestant — he kept most Catholic beliefs.", "Mixing up Thomas Cromwell (Tudor) with Oliver Cromwell (Civil War).", "Forgetting that Lady Jane Grey came between Edward VI and Mary I.", "Saying Elizabeth was 'Supreme Head' — she was Supreme Governor."],
    examTips: ["Use specific laws and dates (Act of Supremacy 1534) as evidence.", "When explaining causes, rank them and explain your judgement.", "Avoid 'Henry just wanted a divorce' — show the political reasons."],
    realLife: "The Church of England, with the monarch as Supreme Governor, still exists today because of the Tudor Reformation.",
  },
);

// ---- extra practice: The Tudors and the Reformation ----
more('hist-y8-tudors-reformation-1', [
  M('What did the Tudor rose symbolise?', ['The union of the houses of Lancaster (red rose) and York (white rose)', 'England’s victory over Spain', 'The break with Rome', 'The union of England and Scotland'], 0, 'Henry VII (Lancaster) married Elizabeth of York, so the combined red and white rose stood for an end to the Wars of the Roses. Union with Scotland came under James I (crowns) and in 1707 (parliaments).'),
  M('Which two pretenders claimed to be royal princes and challenged Henry VII?', ['Lambert Simnel and Perkin Warbeck', 'Robert Aske and Thomas More', 'Wat Tyler and John Ball', 'Thomas Wyatt and Robert Kett'], 0, 'Simnel (defeated at Stoke in 1487) and Warbeck (executed in 1499) pretended to be Yorkist princes. Aske led the Pilgrimage of Grace; Tyler and Ball led the 1381 revolt; Wyatt and Kett rebelled under Mary and Edward VI.'),
  M('Which best describes Henry VII’s approach to money?', ['He was careful and left the Crown rich, using bonds to control nobles', 'He spent everything on foreign wars', 'He abolished all taxes', 'He sold the Crown jewels to the Pope'], 0, 'Henry VII built up royal wealth and made nobles pay bonds as a guarantee of good behaviour. His son Henry VIII spent much of this fortune on wars and palaces.'),
  S('Which book of the Bible did Henry VIII use to argue that marrying his brother’s widow was wrong?', 'Leviticus', ['book of leviticus'], 'Henry cited Leviticus, which says a man who marries his brother’s wife will be childless. Catherine had been married to Henry’s elder brother Arthur, who died in 1502.'),
  M('What was the Field of the Cloth of Gold (1520)?', ['A lavish meeting between Henry VIII and Francis I of France', 'A battle against Scotland', 'The site of Anne Boleyn’s execution', 'A new law about clothing'], 0, 'Henry and Francis tried to outdo each other with splendid tents and feasts near Calais. It was organised by Cardinal Wolsey and showed Henry’s wish to be a great European prince.'),
  M('What did the Act in Restraint of Appeals (1533) do?', ['Stopped legal cases, such as Henry’s marriage case, being appealed to the Pope in Rome', 'Made Elizabeth heir to the throne', 'Closed the larger monasteries', 'Allowed the Bible to be printed in English'], 0, 'The Act said England was an ‘empire’ and appeals could not go to Rome, so Cranmer could rule on Henry’s marriage in England. It was a key step before the Act of Supremacy (1534).'),
  T('Catherine of Aragon was the mother of the future Mary I.', true, 'True. Mary was born in 1516 and was Henry’s only surviving child with Catherine. She became queen in 1553.'),
  M('Which of Henry VIII’s marriages was annulled after about six months, partly because he found his bride unattractive?', ['His marriage to Anne of Cleves', 'His marriage to Jane Seymour', 'His marriage to Catherine Parr', 'His marriage to Catherine of Aragon'], 0, 'The 1540 marriage to Anne of Cleves was arranged by Thomas Cromwell for a German alliance. Its failure contributed to Cromwell’s downfall and execution that year.'),
  MU('Which TWO of Henry VIII’s wives were executed?', ['Anne Boleyn', 'Catherine Howard', 'Jane Seymour', 'Catherine Parr', 'Anne of Cleves'], [0, 1], 'Anne Boleyn (1536) and Catherine Howard (1542) were beheaded. Jane Seymour died after childbirth, Anne of Cleves was divorced and lived on comfortably, and Catherine Parr outlived Henry.'),
  S('In which year did Henry VIII die?', '1547', [], 'Henry VIII died in January 1547 and was succeeded by his nine-year-old son, Edward VI.'),
  O('Put these events in chronological order.', ['Battle of Bosworth', 'Henry VIII becomes king', 'Martin Luther publishes his 95 Theses', 'Act of Supremacy', 'Death of Henry VIII'], '1485 Bosworth; 1509 Henry VIII’s accession; 1517 Luther; 1534 Act of Supremacy; 1547 Henry’s death.'),
  M('What happened to Cardinal Wolsey after he failed to obtain Henry’s annulment?', ['He lost power and died in 1530 on his way to face a treason charge', 'He became Pope', 'He married Anne Boleyn', 'He led the Pilgrimage of Grace'], 0, 'Wolsey fell in 1529, was later arrested for treason and died at Leicester in 1530 before reaching London. His fall opened the way for Cromwell and Cranmer.'),
  M('Which wife of Henry VIII outlived him?', ['Catherine Parr', 'Jane Seymour', 'Anne Boleyn', 'Catherine Howard'], 0, 'Catherine Parr married Henry in 1543 and survived him. She was an educated Protestant sympathiser who helped bring his children back to court.'),
  W(src('Source A: an imaginary letter in the style of a foreign ambassador at Henry VIII’s court, 1530.', 'The king says God is punishing him, for all his sons by the queen have died. He is now determined to have a new wife, whatever the Pope may say.'), M('What does Source A suggest was driving Henry’s actions?', ['His belief that his marriage was cursed and his determination to have a male heir', 'His wish to become a Protestant preacher', 'A wish to make Catherine queen of France', 'Pressure from Parliament to keep his marriage'], 0, 'The source links Henry’s lack of a son to God’s punishment and shows he would defy the Pope. Both points match the wider evidence that the succession was central to the break with Rome.')),
  M('Why did Henry VIII need a male heir so badly?', ['Many feared a woman could not hold the throne securely, and the Wars of the Roses were in recent memory', 'The law said only a son could inherit the Crown’s land', 'His daughter Mary had died young', 'The Pope had ordered that kings must have sons'], 0, 'The last time England had a ruling queen (Matilda, 1100s) it led to civil war, and the Tudor dynasty was new. Mary did not die young: she became queen in 1553.'),
]);
more('hist-y8-tudors-reformation-2', [
  M('What were indulgences, which Martin Luther attacked in 1517?', ['Payments to the Church believed to reduce time in purgatory', 'English Bibles', 'Tax refunds from the king', 'Monastic rules about food'], 0, 'People bought indulgences to shorten the punishment of souls in purgatory. Luther argued that salvation came through faith alone, not through payments.'),
  M('Which monasteries were closed first, in 1536?', ['The smaller ones, with an income of under £200 a year', 'The largest and richest ones', 'Only those in Scotland', 'Only nunneries'], 0, 'The 1536 Act dissolved the lesser houses. The larger monasteries were closed between 1538 and 1540, mostly after ‘voluntary’ surrenders.'),
  M('What was the Act of Six Articles (1539)?', ['A law confirming key Catholic beliefs, showing Henry was not a full Protestant', 'A Protestant prayer book', 'A list of reasons to close monasteries', 'Henry’s divorce papers'], 0, 'The Six Articles upheld transubstantiation and clerical celibacy, with harsh punishments for denying them. It shows Henry broke with the Pope but kept much Catholic doctrine.'),
  M('Who translated the New Testament into English in the 1520s and was executed for heresy in 1536?', ['William Tyndale', 'Thomas More', 'Thomas Wolsey', 'John Knox'], 0, 'Tyndale’s English New Testament had to be smuggled into England at first. He was executed in the Low Countries. More attacked his work; Knox was a Scottish reformer.'),
  T('Robert Aske was executed after the Pilgrimage of Grace, despite Henry’s promises.', true, 'True. Henry promised a pardon and a parliament in the north, but after new risings in 1537 Aske and around 200 others were executed. Aske was hanged in chains at York.'),
  M('What often happened to monastery buildings after dissolution?', ['Lead was stripped from roofs and stone reused, leaving ruins such as Rievaulx and Fountains', 'They became Protestant universities overnight', 'They were left untouched until the 1900s', 'They were given back to the Pope'], 0, 'Valuable lead, bells and stone were sold. Many abbeys became ruins; some became parish churches or country houses for the new owners.'),
  MU('Which TWO were demands of the Pilgrimage of Grace?', ['Restoring the monasteries', 'Removing advisers such as Thomas Cromwell', 'Making England Protestant faster', 'Giving more power to the Pope over taxes in Scotland', 'Executing Mary Tudor'], [0, 1], 'The pilgrims wanted the monasteries restored and ‘evil counsellors’ like Cromwell removed. They were conservative in religion, so they did not want faster Protestant change.'),
  S('What word describes the Catholic belief that the bread and wine at Mass become the body and blood of Christ?', 'Transubstantiation', ['transubstantiation'], 'Catholics believe in transubstantiation; most Protestants rejected it, seeing communion as a remembrance. This was one of the most bitter disagreements of the Reformation.'),
  W(src('Source B: adapted from a report by one of Cromwell’s visitors to a monastery, 1535.', 'The monks here are idle and live loosely. They pretend to holiness but care more for their dinners than their prayers.'), M('Why might a historian treat Source B with caution?', ['Cromwell’s visitors were sent to find faults that would justify closing the monasteries', 'The visitor was a monk who loved the monastery', 'It was written after all monasteries had closed', 'Visitors never went inside monasteries'], 0, 'The visitations were rushed and the visitors knew what Cromwell wanted. Some faults were real, but the reports exaggerated to justify dissolution.')),
  M('Roughly how many monasteries, nunneries and friaries were dissolved in England and Wales?', ['About 800', 'About 8', 'About 80,000', 'About 8 million'], 0, 'Around 800 religious houses closed between 1536 and 1540. Their land and wealth made the Crown much richer for a time.'),
  T('Henry VIII remained largely Catholic in his beliefs even after breaking with Rome.', true, 'True. Henry rejected the Pope’s authority but kept the Mass, confession and priestly celibacy. Real Protestant change came under Edward VI.'),
  O('Put these events in chronological order.', ['Luther’s 95 Theses', 'Tyndale’s English New Testament printed', 'Act of Supremacy', 'Dissolution of the smaller monasteries', 'Act of Six Articles'], '1517 Luther; 1526 Tyndale’s New Testament; 1534 Act of Supremacy; 1536 smaller monasteries closed; 1539 Six Articles.'),
  M('Why did Protestants want the Bible in English?', ['So people could read God’s word for themselves without relying on priests', 'Because Latin had been banned by the Pope', 'Because monks could not read Latin', 'So that it could be sold abroad'], 0, 'Protestants believed scripture was the key authority and should be understood by ordinary people. Catholics relied more on the Church and priests to interpret it.'),
  M('How did Henry VIII use much of the wealth from the monasteries?', ['To pay for wars and coastal forts, and to reward supporters with land', 'To build new monasteries', 'To give every peasant a farm', 'To pay off the Pope'], 0, 'Henry spent heavily on wars with France and Scotland and on defensive forts. Much land was sold or granted to nobles and gentry, giving them a stake in the break with Rome.'),
  M('What was a chantry?', ['A chapel or fund paying priests to say prayers for the souls of the dead', 'A Protestant school', 'A type of monastery for women', 'A royal court of law'], 0, 'Chantries rested on belief in purgatory. Protestants rejected purgatory, so Edward VI’s government dissolved the chantries in 1547.'),
]);
more('hist-y8-tudors-reformation-3', [
  S('How old was Edward VI when he became king in 1547?', '9', ['nine', '9 years old'], 'Edward was nine, so the country was run by a regency council led first by the Duke of Somerset and then by the Duke of Northumberland.'),
  M('Who ruled as Lord Protector at the start of Edward VI’s reign?', ['Edward Seymour, Duke of Somerset', 'Thomas Cromwell', 'Cardinal Wolsey', 'Robert Dudley'], 0, 'Somerset was Edward’s uncle (brother of Jane Seymour). He fell in 1549 and was replaced by John Dudley, later Duke of Northumberland. Cromwell had been executed in 1540.'),
  T('The 1552 Book of Common Prayer was more Protestant than the 1549 version.', true, 'True. The 1552 book made clear that communion was a remembrance, not the Catholic Mass, and removed more traditional ceremonies.'),
  MU('Which TWO changes were made to churches under Edward VI?', ['Images and statues were removed and walls whitewashed', 'Stone altars were replaced by wooden communion tables', 'The Latin Mass was made compulsory', 'Monasteries were reopened', 'Priests were forbidden to marry'], [0, 1], 'Edward’s reformers removed images and altars to stress Protestant worship. The Latin Mass was replaced by English services, and priests were now allowed to marry.'),
  M('Where did the Prayer Book Rebellion of 1549 take place?', ['Devon and Cornwall', 'Yorkshire', 'Kent', 'Norfolk'], 0, 'People in the south-west rose against the new English prayer book; some Cornish speakers understood English poorly. Norfolk saw Kett’s Rebellion the same year.'),
  M('What was the main cause of Kett’s Rebellion in Norfolk (1549)?', ['Anger at enclosure of common land by landowners', 'Support for Mary Queen of Scots', 'The Spanish Armada', 'The poll tax'], 0, 'Robert Kett’s rebels camped outside Norwich and protested about enclosure and greedy landlords. It was mainly economic, unlike the religious Prayer Book Rebellion.'),
  M('Why was Lady Jane Grey executed in 1554?', ['Wyatt’s Rebellion convinced Mary she was a dangerous figurehead for Protestant plotters', 'She tried to marry Philip of Spain', 'She refused to leave England', 'She was found guilty of witchcraft'], 0, 'Jane had been spared at first, but after Wyatt’s Rebellion against the Spanish marriage, Mary’s advisers saw her as too dangerous to keep alive.'),
  M('What was Wyatt’s Rebellion (1554)?', ['A rising against Mary I’s planned marriage to Philip of Spain', 'A Catholic plot to free Mary Queen of Scots', 'A peasant revolt over the poll tax', 'A rebellion in Ireland'], 0, 'Sir Thomas Wyatt led rebels from Kent to London, fearing Spanish control. The rising failed and Elizabeth was briefly imprisoned in the Tower under suspicion.'),
  M('Roughly how many Protestants were burned for heresy under Mary I?', ['Around 280', 'Around 3', 'Around 28,000', 'None'], 0, 'About 280–300 people were burned between 1555 and 1558, many of them ordinary people in the south-east. This is why Protestant writers called her ‘Bloody Mary’.'),
  M('Who became Archbishop of Canterbury under Mary I and led the Catholic restoration?', ['Cardinal Reginald Pole', 'Thomas Cranmer', 'Matthew Parker', 'Thomas Wolsey'], 0, 'Pole replaced Cranmer, who was burned in 1556. Matthew Parker became Elizabeth’s first Archbishop of Canterbury. Wolsey was never archbishop of Canterbury.'),
  W(src('Source A: a description of a woodcut picture from a Protestant book of martyrs published in 1563.', 'A bishop stands calmly in the flames, hands raised in prayer, while a crowd of Catholic priests looks on and smiles.'), M('What was the main purpose of this image?', ['To present Protestant victims as heroic martyrs and Catholics as cruel', 'To show that burnings were fair', 'To praise Mary I', 'To record the exact words of the bishop'], 0, 'John Foxe’s book was Protestant propaganda published under Elizabeth. It shaped the memory of Mary’s reign for centuries, which historians must take into account.')),
  M('What did Elizabeth’s Act of Uniformity (1559) require?', ['Everyone to attend Church of England services using the Book of Common Prayer, or pay a fine', 'All churches to use the Latin Mass', 'Everyone to become Puritans', 'Priests to obey the Pope'], 0, 'Absence from church was fined 12 pence a week. The Act set the form of worship, while the Act of Supremacy set Elizabeth’s position as Supreme Governor.'),
  O('Put these events in chronological order.', ['Edward VI becomes king', 'The first English Book of Common Prayer', 'Lady Jane Grey’s nine days as queen', 'Mary I marries Philip of Spain', 'Elizabeth’s Religious Settlement'], '1547 Edward; 1549 first prayer book; July 1553 Jane Grey; 1554 Mary marries Philip; 1559 Settlement.'),
  T('Mary I had no children, so the throne passed to her half-sister Elizabeth.', true, 'True. Mary believed she was pregnant more than once, but no child was born. Her Protestant half-sister Elizabeth became queen in November 1558.'),
  M('Some recent historians argue Mary I’s Catholic restoration was quite successful in the parishes. Which evidence would best support this?', ['Records showing parishes quickly bought back Catholic items like altars and vestments', 'Foxe’s Book of Martyrs', 'The loss of Calais', 'Wyatt’s Rebellion'], 0, 'Churchwardens’ accounts show many parishes restoring Catholic worship willingly, which suggests support. Foxe’s book is hostile, and Calais and Wyatt are political rather than evidence of parish religion.'),
]);
// =====================================================================
// YEAR 8 — The English Civil War and Republic
// =====================================================================
addTopic(
  { id: 'hist-y8-civil-war', strand: 'hist-ks3', year: 8, term: 2, name: 'The English Civil War and Republic',
    summary: 'Why king and Parliament went to war in 1642, why Parliament won, and what happened from the execution of Charles I to the Restoration.',
    specRef: 'DfE KS3 History: causes and events of the civil wars; the Interregnum; the Restoration and Glorious Revolution' },
  [
    { name: 'Causes of the Civil War', intro: "Charles I believed in the Divine Right of Kings. Disputes over money, religion and power with Parliament grew from 1625 until war broke out in August 1642.",
      items: [
        M("What did the Divine Right of Kings mean?", ["Kings were chosen by God and answerable only to Him", "Parliament chose the king", "Kings had to obey the Pope", "The people elected the king"], 0, "Charles I believed his power came from God, so Parliament had no right to challenge him. This made compromise very hard."),
        M("What was the Personal Rule (1629–40)?", ["Eleven years when Charles ruled without calling Parliament", "Cromwell's rule as Lord Protector", "Rule by the Pope", "Rule by the army after 1649"], 0, "Charles dissolved Parliament in 1629 and governed without it until 1640; critics called it the 'Eleven Years' Tyranny'."),
        S("Which tax, traditionally paid by coastal areas, did Charles extend to the whole country in 1635?", "Ship money", ["ship money tax"], "Ship money paid for the navy. Charles collected it inland without Parliament's consent, which many saw as illegal."),
        M("Who refused to pay ship money and was put on trial in 1637?", ["John Hampden", "Oliver Cromwell", "Thomas Fairfax", "William Laud"], 0, "Hampden lost his case by a narrow 7–5 decision, but the trial publicised opposition to the tax."),
        M("Why did Archbishop William Laud's reforms worry Puritans?", ["His ceremonies, altars and decoration looked Catholic", "He made services simpler", "He banned bishops", "He closed all churches"], 0, "Puritans wanted plain worship. Laud's railed altars, ceremonies and vestments seemed like a move back towards Catholicism."),
        T("Charles I's wife, Henrietta Maria, was a Catholic.", true, "True. She was a French Catholic princess, which made Protestants suspicious that Catholic influence was growing at court."),
        M("What forced Charles to recall Parliament in 1640?", ["He needed money to fight the Scots after they rebelled against a new prayer book", "The Pope ordered it", "Cromwell captured London", "The Spanish invaded"], 0, "Charles tried to impose an English-style prayer book on Scotland (1637); the Scots rebelled (Bishops' Wars) and he needed Parliament's taxes."),
        M("What happened in January 1642?", ["Charles tried to arrest five MPs in the House of Commons", "Charles was executed", "The Battle of Naseby", "The Restoration"], 0, "Charles burst into the Commons with soldiers to arrest five leading MPs, but they had escaped. This breach of Parliament's privilege made war more likely."),
        S("In which year did the English Civil War begin?", "1642", [], "Charles raised his royal standard at Nottingham on 22 August 1642, the traditional start of the war."),
        MU("Which TWO were religious causes of the war?", ["Fear that Laud's reforms were bringing back Catholicism", "Charles's attempt to impose a prayer book on Scotland", "Ship money", "The arrest of the five members", "Charles's belief in Divine Right"], [0, 1], "Laud's reforms and the Scottish prayer book were religious. Ship money was financial; the five members and Divine Right were political."),
        O("Put these events in order.", ["Charles I becomes king", "Personal Rule begins", "Ship money extended inland", "Charles tries to arrest five MPs", "Standard raised at Nottingham"], "1625; 1629; 1635; January 1642; August 1642."),
        M("Which event in Ireland in 1641 increased distrust between king and Parliament?", ["A Catholic rebellion in which many Protestants were killed", "The Battle of the Boyne", "Cromwell's capture of Drogheda", "The Act of Union"], 0, "Parliament would not trust Charles with an army to crush the Irish rebellion, fearing he would use it against them. Drogheda (1649) and the Boyne (1690) were later."),
        T("Charles I called Parliament regularly throughout his reign.", false, "False. He dissolved several Parliaments and ruled without one from 1629 to 1640."),
        M("What was a Puritan?", ["A strict Protestant who wanted simpler worship", "A Catholic priest", "A royalist soldier", "A member of the House of Lords"], 0, "Puritans wanted to 'purify' the Church of remaining Catholic features. Many supported Parliament."),
        S("What name was given to a supporter of the king in the Civil War?", "Cavalier", ["cavaliers", "royalist", "royalists"], "Royalists were nicknamed Cavaliers; Parliamentarians were nicknamed Roundheads."),
      ] },
    { name: 'The war and the execution of the king', intro: "Parliament won the war thanks to the New Model Army, control of London and the navy, and alliance with the Scots. In January 1649 it put the king on trial and executed him.",
      items: [
        M("What was the first major battle of the Civil War (October 1642)?", ["Edgehill", "Naseby", "Marston Moor", "Bosworth"], 0, "Edgehill was indecisive. Marston Moor (1644) and Naseby (1645) were Parliamentarian victories."),
        S("Which battle in 1645 was the decisive Parliamentarian victory?", "Naseby", ["battle of naseby"], "At Naseby (14 June 1645) the New Model Army destroyed Charles's main army and captured his letters."),
        M("What was the New Model Army?", ["A professional, disciplined Parliamentarian army founded in 1645", "A royalist cavalry unit", "The Scottish army", "Cromwell's navy"], 0, "Commanded by Sir Thomas Fairfax with Cromwell leading cavalry, it was paid regularly and promoted by ability."),
        MU("Which TWO advantages helped Parliament win?", ["Control of London and its wealth", "Control of the navy", "Support from the French army", "A larger number of experienced cavalry in 1642", "The king's own Catholic soldiers"], [0, 1], "Parliament held London (money, people, ports) and the navy. It also allied with the Scots (1643). The Royalists had the better cavalry early on."),
        M("Who commanded the New Model Army?", ["Sir Thomas Fairfax", "Prince Rupert", "Charles I", "John Pym"], 0, "Fairfax was commander-in-chief; Cromwell was his lieutenant-general of horse. Prince Rupert led the Royalist cavalry."),
        T("Charles I was executed outside the Banqueting House in Whitehall.", true, "True. He was beheaded on 30 January 1649 on a scaffold outside the Banqueting House."),
        S("In which year was Charles I executed?", "1649", [], "Charles was executed on 30 January 1649 after being tried for treason against the people."),
        M("What was Pride's Purge (December 1648)?", ["Soldiers removed MPs who wanted to negotiate with the king", "A royalist massacre", "A plague outbreak", "Cromwell's invasion of Ireland"], 0, "Colonel Pride blocked over 100 MPs; the remaining 'Rump Parliament' voted to put the king on trial."),
        M("Why was the execution of Charles I so shocking?", ["A king had been tried and executed by his own subjects in public", "He was killed in battle", "He was murdered secretly", "He was the first king to die"], 0, "Many believed kings were appointed by God; a legal trial and public execution by subjects was unprecedented in England."),
        O("Put these events in chronological order.", ["Battle of Edgehill", "Battle of Marston Moor", "New Model Army created", "Battle of Naseby", "Execution of Charles I"], "1642; 1644; 1645 (early); June 1645; January 1649."),
        T("Every member of Parliament supported the execution of the king.", false, "False. Most MPs had been purged; 59 commissioners signed the death warrant, and many people were horrified."),
        W(src("Source A: a woodcut print published in London in 1649, described.", "A crowd watches as the executioner holds up the king's head. Some figures in the crowd are fainting; one woman covers her face."), M("What impression does Source A give of the execution?", ["It was shocking and distressing for onlookers", "It was a happy celebration", "Nobody watched it", "It happened in secret"], 0, "The fainting and covered faces suggest shock and horror. A royalist sympathiser might have made it to stir sympathy for the 'martyr king'.")),
        M("What charge was Charles I tried for?", ["Treason against the people of England", "Murder of Cromwell", "Heresy", "Stealing ship money"], 0, "He was accused of being a 'tyrant, traitor, murderer and public enemy'. He refused to plead, saying the court had no lawful authority."),
        M("Roughly how many people died in the civil wars in England, Scotland and Ireland?", ["Hundreds of thousands, a large share of the population", "About 100", "Under 1,000", "Nobody died"], 0, "Estimates suggest around 200,000 deaths in England and Wales alone from fighting and disease — proportionally a higher share than the First World War."),
        S("What nickname was given to Parliamentarians because of their short hair?", "Roundheads", ["roundhead"], "'Roundhead' mocked the short haircuts of some London apprentices who supported Parliament."),
      ] },
    { name: 'Republic, Restoration and Revolution', intro: "From 1649 to 1660 England was a republic, ruled for much of the time by Oliver Cromwell. After his death the monarchy returned in 1660, and in 1688 Parliament replaced James II.",
      items: [
        M("What was England called after the monarchy was abolished in 1649?", ["The Commonwealth", "The Empire", "The Protectorate of Spain", "The United Kingdom"], 0, "The republic was called the Commonwealth. From 1653 Cromwell's rule was called the Protectorate."),
        S("What title did Oliver Cromwell take in 1653?", "Lord Protector", ["protector"], "Cromwell became Lord Protector in December 1653 and ruled until his death in 1658. He refused the crown in 1657."),
        M("Why is Cromwell's campaign in Ireland (1649) remembered with anger?", ["His forces massacred garrisons and civilians at Drogheda and Wexford", "He gave Ireland independence", "He made Ireland Catholic", "He lost every battle"], 0, "Thousands were killed at Drogheda and Wexford, including civilians and priests. Irish Catholic land was also confiscated."),
        MU("Which TWO were Puritan measures during the 1650s?", ["Theatres were closed", "Celebrating Christmas with feasting was discouraged and banned", "Football became compulsory", "Catholic Mass was made the official service", "The House of Lords was enlarged"], [0, 1], "Theatres were closed from 1642 and Christmas festivities were banned. The Lords was abolished in 1649."),
        T("Cromwell made himself king in 1657.", false, "False. Parliament offered him the crown in 1657 but he refused it, though he ruled with many powers of a king."),
        S("In which year was the monarchy restored?", "1660", [], "Charles II returned in May 1660 after the collapse of the government following Oliver Cromwell's death."),
        M("Who was restored as king in 1660?", ["Charles II", "James I", "Charles I", "William III"], 0, "Charles II, son of the executed king, was invited back by Parliament. William III came in 1688."),
        M("What happened to Cromwell's body after the Restoration?", ["It was dug up, hanged and beheaded", "It was buried with honours in Westminster Abbey", "It was sent to Ireland", "It was never found"], 0, "In 1661 his body was exhumed and 'executed' as revenge for the regicide; his head was displayed at Westminster Hall."),
        M("Who were the Levellers?", ["Radicals who wanted votes for more men and equality before the law", "Royalist generals", "Catholic priests", "Scottish soldiers"], 0, "Levellers such as John Lilburne demanded wider voting rights and religious toleration. The Diggers went further, farming common land."),
        M("What was the 'Glorious Revolution' of 1688?", ["Parliament invited William of Orange to replace Catholic James II", "The execution of Charles I", "The Restoration of Charles II", "A peasant uprising"], 0, "James II fled and William III and Mary II took the throne — with little bloodshed in England, hence 'Glorious'."),
        S("Which 1689 law limited royal power and guaranteed regular Parliaments? (three words)", "Bill of Rights", ["the bill of rights"], "The Bill of Rights (1689) said the monarch could not raise taxes or keep an army in peacetime without Parliament's consent."),
        O("Put these in chronological order.", ["Execution of Charles I", "Cromwell becomes Lord Protector", "Death of Oliver Cromwell", "Restoration of Charles II", "Glorious Revolution"], "1649; 1653; 1658; 1660; 1688."),
        M("Which best describes the long-term significance of the civil wars?", ["Parliament's power grew and monarchs had to rule with Parliament", "England became a permanent republic", "The monarchy became absolute", "The Pope regained control of England"], 0, "Although the monarchy returned, kings could no longer rule without Parliament — confirmed in 1689."),
        T("Interpretations of Cromwell differ: some see him as a champion of Parliament, others as a military dictator.", true, "True. He defended Parliament against the king but later dissolved Parliaments and ruled through the army (the Major-Generals, 1655–57)."),
        M("Who ruled briefly after Oliver Cromwell died in 1658?", ["His son Richard Cromwell", "Thomas Fairfax", "John Lambert", "Charles II"], 0, "Richard Cromwell lacked his father's army support and resigned in 1659; Charles II returned the next year."),
      ] },
  ],
  {
    overview: "In 1642 England went to war with itself. Charles I's belief in Divine Right clashed with Parliament over money, religion and power. Parliament won, executed the king in 1649 and ruled as a republic until the Restoration of 1660; the Glorious Revolution of 1688 confirmed that monarchs must rule with Parliament.",
    objectives: ["I can explain the long- and short-term causes of the Civil War.", "I can explain why Parliament won.", "I can describe the execution of Charles I and its significance.", "I can evaluate interpretations of Oliver Cromwell."],
    keyWords: [
      { term: 'Divine Right of Kings', def: 'Belief that monarchs are chosen by God and answer only to Him.' },
      { term: 'Ship money', def: 'Tax for the navy that Charles extended inland without Parliament.' },
      { term: 'Puritan', def: 'Strict Protestant who wanted simpler worship.' },
      { term: 'New Model Army', def: 'Parliament’s professional army formed in 1645.' },
      { term: 'Regicide', def: 'Killing of a king.' },
      { term: 'Commonwealth', def: 'The English republic from 1649.' },
      { term: 'Restoration', def: 'Return of the monarchy under Charles II in 1660.' },
    ],
    sections: [
      { title: 'Causes', html: "<table class=\"qt\"><tr><th>Type</th><th>Cause</th></tr><tr><td>Money</td><td>Ship money (1635) and other taxes collected without Parliament.</td></tr><tr><td>Religion</td><td>Laud's 'Catholic-looking' reforms; Catholic queen; Scottish prayer book (1637).</td></tr><tr><td>Power</td><td>Divine Right; Personal Rule 1629–40; attempt to arrest five MPs (Jan 1642).</td></tr><tr><td>Trigger</td><td>Irish rebellion 1641 — who should control the army?</td></tr></table>" },
      { title: 'Timeline', html: timeline([["1625", "Charles I becomes king"], ["1629–40", "Personal Rule"], ["1637", "Scottish prayer book crisis"], ["Jan 1642", "Five members incident"], ["Aug 1642", "War begins at Nottingham"], ["1644", "Marston Moor"], ["1645", "New Model Army; Naseby"], ["30 Jan 1649", "Charles I executed; Commonwealth"], ["1653", "Cromwell Lord Protector"], ["1660", "Restoration of Charles II"], ["1688–89", "Glorious Revolution; Bill of Rights"]]) },
      { title: 'Key people', html: people([["Charles I", "Believed in Divine Right; executed 1649."], ["Oliver Cromwell", "MP and cavalry general; Lord Protector 1653–58."], ["Sir Thomas Fairfax", "Commander of the New Model Army."], ["Archbishop Laud", "Introduced ceremonial church reforms; executed 1645."], ["John Hampden", "Challenged ship money in court."]]) },
      { title: 'Model answer', html: worked("Explain why Parliament won the English Civil War. (8 marks)", ["Choose two or three factors: resources, New Model Army, Scottish alliance.", "Give detailed evidence for each.", "Explain the link to victory and judge which mattered most."], "Model paragraph: A key reason was Parliament's control of resources. Parliament held London, the richest city in England, with its customs revenue and population, and it controlled the navy, which allowed it to supply ports and stop foreign help reaching the king. This meant Parliament could afford to pay its soldiers regularly once the New Model Army was created in 1645, which made its troops more disciplined than the king's forces and helped it win decisively at Naseby.") },
    ],
    mistakes: ["Confusing Oliver Cromwell with Thomas Cromwell (Henry VIII's minister).", "Thinking England has been a republic ever since 1649.", "Saying Cromwell executed Charles single-handed — 59 commissioners signed the warrant.", "Listing causes without grouping or linking them."],
    examTips: ["Group causes (religion, money, power) and show how they combined.", "Distinguish long-term causes from the 1642 trigger.", "Use precise names and dates as evidence."],
    realLife: "When the monarch opens Parliament, the door of the Commons is slammed in the messenger's face — a reminder of Charles I's attempt to arrest the five members.",
  },
);

// ---- extra practice: The English Civil War and Republic ----
more('hist-y8-civil-war-1', [
  S('In which year did Charles I become king?', '1625', [], 'Charles I succeeded his father James I in 1625. Within a few years he had quarrelled with Parliament over money, war and religion.'),
  M('Who was the Duke of Buckingham?', ['Charles I’s unpopular favourite, blamed for failed wars and assassinated in 1628', 'The leader of the New Model Army', 'A Puritan who refused to pay ship money', 'The Archbishop of Canterbury'], 0, 'Parliament tried to impeach Buckingham, and Charles protected him. His murder in 1628 removed him, but trust between king and Parliament had already been damaged.'),
  M('What was the Petition of Right (1628)?', ['A statement by Parliament that the king could not tax without consent or imprison people without cause', 'Charles I’s declaration of war on Parliament', 'A Scottish prayer book', 'The charge against Charles at his trial'], 0, 'Charles accepted the Petition to get money, but then ignored much of it. In 1629 he dissolved Parliament and began his Personal Rule.'),
  M('What did the Scots do after Charles tried to impose a new prayer book on them in 1637?', ['Signed the National Covenant and rebelled in the Bishops’ Wars', 'Welcomed it and became Catholic', 'Invaded France', 'Asked Charles to become their Pope'], 0, 'Riots in Edinburgh led to the National Covenant (1638) and war. Charles could not pay for an army without Parliament, which ended the Personal Rule.'),
  M('Why is the ‘Short Parliament’ of 1640 so called?', ['Charles dissolved it after about three weeks when it refused money until grievances were addressed', 'It had very few members', 'It met in a small room', 'It passed only one law'], 0, 'Charles dissolved it quickly. After defeat by the Scots he had to call the Long Parliament in November 1640, which sat for years and attacked his policies.'),
  M('Which of Charles’s leading ministers was executed in 1641 after pressure from Parliament?', ['The Earl of Strafford (Thomas Wentworth)', 'Archbishop Laud', 'Oliver Cromwell', 'John Pym'], 0, 'Strafford was executed in May 1641; Charles signed the order, which he later regretted. Laud was imprisoned and executed in 1645. Pym led the opposition in Parliament.'),
  M('What was the Grand Remonstrance (1641)?', ['A long list of Parliament’s complaints against Charles’s rule', 'A royal order to arrest MPs', 'A peace treaty with Scotland', 'A Catholic plot to kill Charles'], 0, 'It passed by only 11 votes, showing Parliament itself was divided. Many moderate MPs began to side with the king, which helped make war possible.'),
  S('At which town did Charles I raise his royal standard in August 1642, marking the start of the war?', 'Nottingham', [], 'Charles raised his standard at Nottingham on 22 August 1642, calling his supporters to arms.'),
  MU('Which TWO were money-raising methods that angered people during Charles’s reign?', ['Ship money', 'Forced loans', 'Income tax', 'The poll tax of 1381', 'Value added tax (VAT)'], [0, 1], 'Ship money and forced loans were raised without Parliament’s approval. Income tax was introduced in 1799, the poll tax of 1381 was in the Middle Ages, and VAT is modern.'),
  T('The Triennial Act of 1641 said Parliament must meet at least once every three years.', true, 'True. This was meant to prevent another Personal Rule. Parliament also passed a law that it could not be dissolved without its own consent.'),
  O('Put these events in chronological order.', ['Charles I becomes king', 'Petition of Right', 'Personal Rule begins', 'Riots over the Scottish prayer book', 'Long Parliament meets'], '1625 accession; 1628 Petition of Right; 1629 Personal Rule; 1637 prayer book riots; November 1640 Long Parliament.'),
  W(src('Source A: an imaginary statement in the style of Charles I, 1640s.', 'A king is answerable to God alone. It is not for subjects to question how their sovereign governs.'), M('Which belief does Source A show?', ['The Divine Right of Kings', 'Puritanism', 'Republicanism', 'Support for the Levellers'], 0, 'Divine Right meant the king’s power came from God, so Parliament could not hold him to account. This clashed with MPs who believed the king should govern with Parliament.')),
  M('Which piece of evidence best supports the view that religion was a major cause of the war?', ['Puritans feared Laud’s reforms were bringing back Catholic practices', 'Charles needed money for ships', 'The king liked art and spent a lot on paintings', 'The Short Parliament lasted three weeks'], 0, 'Fear of ‘popery’ drove many Puritan MPs and ordinary people to oppose the king. Ship money and royal spending are financial causes; the Short Parliament is a political event.'),
  T('Charles I was born in Scotland.', true, 'True. Charles was born in Dunfermline in 1600, when his father James was King of Scotland only. James became King of England as well in 1603.'),
  M('Which is the best example of a long-term cause of the Civil War?', ['Disagreements over money, religion and royal power going back to James I', 'The king’s attempt to arrest five MPs in January 1642', 'The raising of the standard at Nottingham', 'The Irish rebellion of October 1641'], 0, 'Long-term causes built up over decades. The arrest attempt, the Irish rebellion and the raising of the standard were short-term triggers in 1641–42.'),
]);
more('hist-y8-civil-war-2', [
  M('Which city became Charles I’s headquarters during the Civil War?', ['Oxford', 'London', 'Manchester', 'Bristol'], 0, 'After failing to take London, Charles based his court at Oxford. Parliament held London, which gave it money, people and the main port.'),
  M('Who was Prince Rupert of the Rhine?', ['The king’s nephew and a famous Royalist cavalry commander', 'The leader of the Scottish army', 'A Parliamentarian general', 'The Speaker of the House of Commons'], 0, 'Rupert’s fast cavalry charges won early successes but often chased too far from the battlefield, as at Edgehill and Naseby.'),
  M('Why was the Battle of Marston Moor (1644) important?', ['Parliament and the Scots won, gaining control of the north of England', 'It ended the war', 'Charles I was captured there', 'It was the first battle of the war'], 0, 'Marston Moor, near York, was the largest battle of the war. Cromwell’s cavalry played a key role. The war did not end until 1646.'),
  M('What was the Solemn League and Covenant (1643)?', ['An alliance between Parliament and the Scots', 'A peace treaty between Charles and Parliament', 'The charge sheet at Charles’s trial', 'An agreement with France to support Charles'], 0, 'The Scots sent an army to help Parliament in return for promises about reforming the English Church on Presbyterian lines.'),
  M('To whom did Charles I surrender in 1646?', ['The Scottish army', 'Oliver Cromwell in person', 'The King of France', 'The Levellers'], 0, 'Charles surrendered to the Scots at Newark hoping to divide his enemies. In 1647 the Scots handed him over to Parliament.'),
  M('What was the Second Civil War (1648)?', ['Royalist risings and a Scottish invasion supporting Charles, defeated at Preston', 'A war between England and Spain', 'A war between Cromwell and the Levellers only', 'A rebellion against Charles II in 1660'], 0, 'Charles secretly allied with the Scots while negotiating. Cromwell defeated them at Preston. Many in the army then decided Charles could not be trusted and must be tried.'),
  M('What did the Self-Denying Ordinance (1645) do?', ['Made members of Parliament give up their army commands', 'Banned Christmas', 'Ended the Personal Rule', 'Gave Charles control of the army'], 0, 'It removed aristocratic commanders who seemed unwilling to win outright, clearing the way for professional leaders. Cromwell was given an exemption.'),
  S('How many commissioners signed Charles I’s death warrant?', '59', ['fifty-nine', 'fifty nine'], 'Fifty-nine signed. After the Restoration in 1660 those still alive were hunted down as ‘regicides’ and several were executed.'),
  T('At his trial, Charles I refused to plead because he said the court had no lawful authority to try a king.', true, 'True. Charles argued that no court could try a king. His refusal to plead meant he was treated as having confessed.'),
  S('Give the date of Charles I’s execution. (day, month and year)', '30 January 1649', ['30th january 1649', 'january 30 1649', '30 jan 1649', '30/01/1649'], 'Charles was beheaded in Whitehall on 30 January 1649.', [['30'], ['january', 'jan'], ['1649']]),
  T('Charles I is said to have worn two shirts at his execution so he would not shiver in the cold and appear afraid.', true, 'True. It was a bitterly cold January day. The story shows how carefully Charles tried to present himself as a dignified martyr.'),
  MU('Which TWO were advantages the Royalists had early in the war?', ['Experienced cavalry under Prince Rupert', 'Support from many nobles and gentry', 'Control of London', 'Control of the navy', 'The New Model Army'], [0, 1], 'The Royalists had good cavalry and many wealthy supporters. Parliament held London, the navy and later created the New Model Army.'),
  O('Put these events in chronological order.', ['Battle of Edgehill', 'Battle of Marston Moor', 'Battle of Naseby', 'Charles surrenders to the Scots', 'Battle of Preston'], '1642 Edgehill; 1644 Marston Moor; 1645 Naseby; 1646 surrender; 1648 Preston.'),
  M('Who were the Clubmen?', ['Local people who banded together to protect their areas from both armies', 'Royalist cavalry officers', 'Members of the House of Lords', 'Scottish soldiers'], 0, 'Clubmen were mostly ordinary country people angry at plundering and taxes from both sides. They show that many people wanted to be left alone rather than pick a side.'),
  M('Which change in printing happened during the Civil War?', ['Huge numbers of pamphlets and news-books were printed to spread news and propaganda', 'Printing was banned completely', 'The first printing press was invented', 'Only the king was allowed to read newspapers'], 0, 'With censorship breaking down, both sides produced pamphlets and weekly news-books. This is why historians have so many sources for the 1640s, many of them biased.'),
]);
more('hist-y8-civil-war-3', [
  M('What did Oliver Cromwell do to the Rump Parliament in April 1653?', ['He dissolved it with soldiers', 'He made it hereditary', 'He gave it control of the army', 'He moved it to Oxford'], 0, 'Frustrated at its slow progress, Cromwell entered with musketeers and dismissed it. It shows how the army held real power during the republic.'),
  M('What was ‘Barebones Parliament’ (1653)?', ['An assembly of godly men nominated rather than elected', 'The first parliament to include women', 'A parliament elected by all adults', 'A Royalist parliament in Oxford'], 0, 'It was named after one member, Praise-God Barebone. It quickly broke down, and Cromwell became Lord Protector under the Instrument of Government.'),
  M('What was the Instrument of Government (1653)?', ['A written constitution that made Cromwell Lord Protector', 'The order to execute Charles I', 'The Restoration settlement', 'A law closing theatres'], 0, 'It was Britain’s first written constitution, sharing power between the Lord Protector, a Council of State and Parliament.'),
  M('What was the Rule of the Major-Generals (1655–57)?', ['England was divided into regions run by army officers who enforced order and godly behaviour', 'A Royalist plan to invade Scotland', 'Government by the House of Lords', 'A rebellion led by army officers against Cromwell'], 0, 'The Major-Generals were very unpopular because they closed alehouses and enforced Puritan morals. It added to the idea of Cromwell as a military dictator.'),
  T('Jews were allowed to live in England again in the 1650s, more than 350 years after being expelled by Edward I.', true, 'True. Edward I expelled the Jews in 1290. Cromwell allowed their informal readmission in 1656.'),
  M('Who were the Diggers, led by Gerrard Winstanley?', ['A group who believed land should be held in common and farmed together', 'Royalist soldiers who dug trenches', 'Miners who went on strike', 'Catholic priests in hiding'], 0, 'In 1649 the Diggers began farming common land at St George’s Hill in Surrey. They were broken up by local landowners. They were more radical than the Levellers.'),
  M('Which general marched his army from Scotland to London in 1660 and helped bring about the Restoration?', ['General George Monck', 'Prince Rupert', 'Lord Fairfax', 'Richard Cromwell'], 0, 'Monck arrived in London and recalled the old Parliament, which invited Charles II back. Richard Cromwell had already resigned in 1659.'),
  M('What was the Declaration of Breda (1660)?', ['Charles II’s promise of pardons and religious toleration if he returned', 'The death warrant of Charles I', 'Cromwell’s plan to conquer Ireland', 'The Bill of Rights'], 0, 'Charles promised a general pardon (except for those Parliament named) and leaving key questions to Parliament. It made his return easier to accept.'),
  O('Put these events in chronological order.', ['The Restoration of Charles II', 'The Great Plague of London', 'The Great Fire of London', 'The Glorious Revolution', 'The Bill of Rights'], '1660 Restoration; 1665 Plague; 1666 Fire; 1688 Glorious Revolution; 1689 Bill of Rights.'),
  M('Why did the birth of a son to James II in 1688 alarm many Protestants?', ['It meant a Catholic heir and a continuing Catholic dynasty', 'The baby was born in France', 'It meant Mary would become queen immediately', 'James had promised not to have children'], 0, 'Before 1688 James’s heirs were his Protestant daughters Mary and Anne. A son would be raised Catholic and inherit first, so leading politicians invited William of Orange to intervene.'),
  S('Which Irish town did Cromwell’s army storm in 1649, killing much of the garrison and many civilians?', 'Drogheda', [], 'At Drogheda (and later Wexford) Cromwell’s forces killed thousands. The event is still remembered as a symbol of English brutality in Ireland.'),
  MU('Which TWO were Leveller ideas?', ['The vote for most adult men', 'Religious toleration for Protestants', 'Restoring the bishops’ power', 'Giving the king absolute power', 'Abolishing Parliament'], [0, 1], 'The Levellers, led by men like John Lilburne, wanted a wider vote, equality before the law and religious toleration. They wanted a stronger Parliament, not a stronger king.'),
  M('Which new religious group, founded in the 1650s, refused to take oaths or remove their hats for social superiors?', ['The Quakers', 'The Jesuits', 'The Methodists', 'The Lollards'], 0, 'George Fox’s Quakers believed in the ‘inner light’ and spiritual equality. Methodists came in the 1700s; Lollards in the 1300s–1400s; Jesuits were a Catholic order.'),
  M('In 1899 a statue of Oliver Cromwell was put up outside the Houses of Parliament. What does this suggest?', ['Many Victorians saw Cromwell as a champion of Parliament’s rights', 'Victorians all agreed he was a tyrant', 'Cromwell had just been rediscovered', 'Parliament wanted to restore the republic'], 0, 'The statue was controversial, but its placing reflects a 19th-century view of Cromwell as a defender of liberty against royal tyranny. Interpretations change with the times.'),
  M('How did Charles II escape after his defeat at the Battle of Worcester (1651)?', ['He hid in an oak tree and then escaped to France in disguise', 'He was rescued by the Spanish Armada', 'He surrendered and was pardoned by Cromwell', 'He fled to America'], 0, 'Charles hid in an oak at Boscobel, then travelled in disguise to the coast. The ‘Royal Oak’ became a popular symbol after the Restoration.'),
]);
// =====================================================================
// YEAR 8 — Industrial Revolution, reform and Empire
// =====================================================================
addTopic(
  { id: 'hist-y8-industry-empire', strand: 'hist-ks3', year: 8, term: 3, name: 'Industry, Reform and Empire 1750–1900',
    summary: 'How the Industrial Revolution changed work and towns, how ordinary people campaigned for rights, and how Britain built an empire based partly on the transatlantic slave trade.',
    specRef: 'DfE KS3 History: ideas, political power, industry and empire: Britain 1745–1901' },
  [
    { name: 'The Industrial Revolution', intro: "From about 1750 Britain changed from a mainly farming country to the world's first industrial nation. New machines, steam power, factories and railways transformed work and towns.",
      items: [
        M("Which invention by James Hargreaves (c.1764) let one worker spin several threads at once?", ["Spinning jenny", "Water frame", "Steam hammer", "Flying shuttle"], 0, "The spinning jenny multiplied spinning output. Arkwright's water frame (1769) used water power; Kay's flying shuttle (1733) sped up weaving."),
        M("Who built one of the first water-powered cotton mills at Cromford in 1771?", ["Richard Arkwright", "James Watt", "George Stephenson", "Isambard Kingdom Brunel"], 0, "Arkwright's Cromford Mill used his water frame and is often called the first modern factory."),
        M("What did James Watt improve?", ["The steam engine, making it far more efficient", "The spinning jenny", "The railway signal", "The telephone"], 0, "Watt's separate condenser (patented 1769) cut fuel use; later rotary engines could drive factory machines."),
        S("Which locomotive, built by George and Robert Stephenson, won the Rainhill Trials in 1829?", "Rocket", ["the rocket", "stephensons rocket"], "Rocket won the Rainhill Trials and pulled trains on the Liverpool and Manchester Railway, which opened in 1830."),
        MU("Which TWO helped Britain industrialise first?", ["Plentiful coal and iron ore", "A growing population providing workers and customers", "A ban on all trade with other countries", "No rivers or ports", "A shortage of investors"], [0, 1], "Britain had coal, iron, rivers, ports, capital, empire markets and a growing population. Trade bans or a lack of investors would have slowed growth."),
        T("Many children worked long hours in factories and mines in the early 1800s.", true, "True. Children were cheap, small and nimble; some started work aged five or six and worked twelve-hour days."),
        M("What did the Factory Act of 1833 do?", ["Banned children under 9 from textile mills and appointed inspectors", "Banned all child labour", "Gave workers the vote", "Closed all factories on Sundays"], 0, "The 1833 Act banned under-9s in textile mills, limited hours for older children and appointed four inspectors. It did not end child labour."),
        M("What did the Mines Act of 1842 ban?", ["Women, girls and boys under 10 working underground", "Coal mining", "Steam engines in mines", "Miners' trade unions"], 0, "Shocking reports with illustrations of children hauling coal led Parliament to ban women and young boys underground."),
        O("Put these in chronological order.", ["Spinning jenny", "Cromford Mill opens", "Rainhill Trials", "Factory Act", "Mines Act"], "c.1764; 1771; 1829; 1833; 1842."),
        M("Why did towns like Manchester grow so fast?", ["People moved from the countryside to work in factories", "The government ordered everyone to move", "The Black Death had ended", "Farming became more profitable than ever"], 0, "Urbanisation: Manchester grew from about 25,000 people in the 1770s to over 300,000 by 1850 as workers moved to the mills."),
        S("What word means the growth of towns and cities as people move from the countryside?", "Urbanisation", ["urbanization"], "Urbanisation was a key feature of the Industrial Revolution. By 1851 over half of Britain's people lived in towns."),
        T("Living conditions in the new industrial towns were usually clean and healthy.", false, "False. Back-to-back houses, shared privies, polluted water and overcrowding led to cholera, typhoid and high death rates."),
        M("Who were the Luddites (1811–16)?", ["Workers who smashed new machines they believed threatened their jobs", "Factory owners", "Railway engineers", "Members of Parliament"], 0, "Skilled textile workers broke machines that replaced their labour. The government made machine-breaking punishable by death in 1812."),
        M("Roughly how did the population of England and Wales change between 1801 and 1901?", ["It rose from about 9 million to about 32 million", "It halved", "It stayed the same", "It rose from 1 million to 2 million"], 0, "Census figures show around 9 million in 1801 and over 32 million in 1901, driven by higher birth rates and falling death rates later in the century."),
        S("Which great 1851 exhibition in the Crystal Palace showed off British industry?", "Great Exhibition", ["the great exhibition"], "The Great Exhibition of 1851 in Hyde Park displayed over 100,000 exhibits and attracted around 6 million visits."),
      ] },
    { name: 'Protest and reform: rights and votes', intro: "As industry grew, working people demanded better conditions and a say in government. Protest movements and Reform Acts slowly widened the vote during the 1800s.",
      items: [
        M("What happened at Peterloo in Manchester in 1819?", ["Cavalry charged a peaceful crowd demanding reform, killing around 15 people", "The first railway opened", "Workers burned a factory", "Parliament passed the Reform Act"], 0, "About 60,000 people gathered at St Peter's Field; yeomanry charged and around 15–18 were killed and hundreds injured. It was nicknamed Peterloo after Waterloo."),
        S("Which 1832 Act abolished many 'rotten boroughs' and gave the vote to more middle-class men?", "Great Reform Act", ["reform act", "the great reform act", "1832 reform act"], "The Great Reform Act (1832) redistributed seats to industrial towns, but only about 1 in 5 adult men could vote afterwards."),
        M("What was a 'rotten borough'?", ["A constituency with very few voters that still elected MPs", "A town full of disease", "A borough controlled by Chartists", "A factory town"], 0, "Old Sarum had almost no inhabitants but elected two MPs, while Manchester had none before 1832."),
        M("What was Chartism (1838–48)?", ["A working-class movement demanding six political reforms including votes for all men", "A movement to abolish slavery", "A trade union for miners", "A Conservative party"], 0, "The People's Charter demanded votes for all men, secret ballots, payment of MPs, equal constituencies, no property qualification and annual Parliaments."),
        MU("Which TWO were points of the People's Charter?", ["A vote for every man aged 21 and over", "A secret ballot", "Votes for women", "The abolition of the monarchy", "Free schools for all"], [0, 1], "The six points included universal male suffrage and the secret ballot. Votes for women were not one of the six points."),
        T("All the Chartists' demands were achieved immediately in 1848.", false, "False. Their petitions were rejected; but by 1918 five of the six points had become law (annual Parliaments never did)."),
        M("Who were the Tolpuddle Martyrs (1834)?", ["Dorset farm labourers transported to Australia for forming a union", "Factory owners who reformed conditions", "Chartist leaders killed at Peterloo", "MPs who abolished slavery"], 0, "Six labourers were sentenced to transportation for swearing a secret oath to their union. Public protest won their release in 1836."),
        O("Put these in chronological order.", ["Peterloo Massacre", "Great Reform Act", "Tolpuddle Martyrs", "Chartist mass meeting at Kennington Common", "Second Reform Act"], "1819; 1832; 1834; 1848; 1867."),
        M("What did the 1867 Reform Act do?", ["Gave the vote to many working-class men in towns", "Gave all women the vote", "Abolished the House of Lords", "Ended the secret ballot"], 0, "The Second Reform Act roughly doubled the electorate by enfranchising male householders in boroughs. Women waited until 1918 and 1928."),
        S("In what year did the Ballot Act introduce secret voting?", "1872", [], "The Ballot Act (1872) introduced secret ballots, reducing bribery and intimidation of voters."),
        M("Which is a reason the government feared reform movements in the early 1800s?", ["The French Revolution had shown that protest could overthrow a monarchy", "Reformers wanted to restore the Pope", "Reformers supported Napoleon's invasion", "Factories had stopped working"], 0, "After 1789 many in power feared revolution in Britain, so they responded harshly to protest, e.g. at Peterloo."),
        T("Before 1832 most adult men in Britain could not vote.", true, "True. Only a small minority of men, mainly property owners, could vote; no women could vote in general elections."),
        M("Which reformer campaigned for the Ten Hours Act and better factory and mine conditions?", ["Lord Shaftesbury (Anthony Ashley-Cooper)", "Wat Tyler", "William Pitt", "Henry VIII"], 0, "Lord Ashley (later Shaftesbury) pushed for the Mines Act (1842) and Ten Hours Act (1847)."),
        S("What word means the right to vote?", "Suffrage", ["franchise", "enfranchisement"], "Suffrage (or the franchise) is the right to vote. Suffragists and suffragettes campaigned for women's suffrage."),
        M("What was the main limit of the 1832 Great Reform Act?", ["Most working-class men still could not vote", "It gave the vote to everyone", "It abolished Parliament", "It only applied to Scotland"], 0, "Voting depended on owning or renting property worth £10 a year in boroughs, which excluded most workers — fuelling Chartism."),
      ] },
    { name: 'Empire and the transatlantic slave trade', intro: "Britain's wealth was linked to empire and to the enslavement of Africans. Campaigns by abolitionists and resistance by enslaved people ended the slave trade in 1807 and slavery in the British Empire from 1834.",
      items: [
        M("What was the 'triangular trade'?", ["Ships carried goods from Britain to Africa, enslaved Africans to the Americas, and sugar and cotton back to Britain", "Trade between England, Scotland and Wales", "A shipping route around Africa to India", "Trade in triangles of cloth"], 0, "Each leg made profit for merchants in ports such as Bristol, Liverpool and London."),
        S("What name is given to the voyage across the Atlantic carrying enslaved Africans?", "Middle Passage", ["the middle passage"], "The Middle Passage often took 6–8 weeks. Many died from disease, cruelty and overcrowding."),
        M("Approximately how many Africans were forcibly transported across the Atlantic during the whole slave trade?", ["About 12 million", "About 12,000", "About 1 million", "About 100 million"], 0, "Historians estimate around 12.5 million people were embarked, of whom about 10.7 million survived the voyage. British ships carried over 3 million."),
        S("In which year did Parliament abolish the British slave trade?", "1807", [], "The Abolition of the Slave Trade Act (1807) banned British ships from trading enslaved people, but slavery itself continued in the colonies."),
        T("The 1807 Act freed all enslaved people in the British Empire.", false, "False. 1807 ended the trade; the Slavery Abolition Act of 1833 (in force 1834) ended slavery itself, with 'apprenticeship' lasting until 1838."),
        M("Who led the campaign against the slave trade in Parliament?", ["William Wilberforce", "Robert Clive", "Cecil Rhodes", "Lord Shaftesbury"], 0, "Wilberforce introduced abolition bills for nearly twenty years. Clive and Rhodes were empire builders."),
        M("Who was Olaudah Equiano?", ["A formerly enslaved African whose 1789 autobiography helped the abolition campaign", "A slave ship captain", "An MP who defended slavery", "An Indian prince"], 0, "Equiano bought his freedom and wrote an account of his experiences; it was a bestseller and powerful evidence for abolition."),
        MU("Which TWO helped bring about the end of slavery in the British Empire?", ["Resistance and rebellions by enslaved people, such as in Jamaica in 1831–32", "Campaigns by abolitionists, petitions and boycotts of sugar", "The Great Exhibition of 1851", "The invention of the spinning jenny", "The Battle of Naseby"], [0, 1], "Rebellions like Sam Sharpe's in Jamaica and campaigns by people such as Thomas Clarkson and Equiano both put pressure on Parliament."),
        M("Who received £20 million compensation when slavery was abolished in 1833?", ["Slave owners", "Formerly enslaved people", "Abolitionist societies", "The African kingdoms"], 0, "The government paid slave owners for their 'loss of property'; the formerly enslaved received nothing."),
        M("Which company controlled large parts of India before 1858?", ["The East India Company", "The Hudson's Bay Company", "The Royal African Company", "The Muscovy Company"], 0, "The East India Company gained control after battles such as Plassey (1757). After the 1857 rebellion the British government took direct control (the Raj)."),
        S("In which year did the British Crown take direct control of India after a major rebellion?", "1858", [], "After the Indian Rebellion of 1857, the Government of India Act (1858) began direct rule. Victoria became Empress of India in 1876."),
        M("What was the 'Scramble for Africa'?", ["European powers rapidly claiming African land in the late 1800s", "A race to reach the North Pole", "A football tournament", "A slave rebellion"], 0, "From about 1880 Britain, France, Germany, Belgium and others divided most of Africa; the Berlin Conference of 1884–85 set rules for it."),
        T("At its height around 1920 the British Empire covered roughly a quarter of the world's land.", true, "True. It included India, Canada, Australia, large parts of Africa and much more."),
        O("Put these events in chronological order.", ["Battle of Plassey", "Abolition of the slave trade", "Slavery Abolition Act", "Indian Rebellion", "Berlin Conference"], "1757; 1807; 1833; 1857; 1884–85."),
        M("Which interpretation of the British Empire is most supported by the evidence about slavery and famines?", ["The Empire brought great wealth to Britain but caused serious suffering to many colonised people", "The Empire was entirely beneficial for everyone", "The Empire had no effect on Britain", "The Empire was run by the colonised peoples"], 0, "Historians debate the Empire, but evidence of slavery, violence and famines shows major harm alongside the wealth and infrastructure it brought to Britain."),
      ] },
  ],
  {
    overview: "Between 1750 and 1900 Britain became the 'workshop of the world'. New machines and steam power created factories and fast-growing towns; workers campaigned for rights and the vote; and Britain built a global empire, with wealth partly drawn from the transatlantic slave trade until its abolition.",
    objectives: ["I can describe key inventions and their effects.", "I can explain why reformers campaigned and what they achieved.", "I can explain the triangular trade and why slavery was abolished.", "I can weigh up different interpretations of the British Empire."],
    keyWords: [
      { term: 'Industrial Revolution', def: 'The shift from hand production to machines, steam power and factories, c.1750–1850.' },
      { term: 'Urbanisation', def: 'Growth of towns as people move from the countryside.' },
      { term: 'Factory Act', def: 'Law regulating hours and conditions in factories (e.g. 1833).' },
      { term: 'Chartism', def: 'Working-class movement (1838–48) demanding six political reforms.' },
      { term: 'Suffrage', def: 'The right to vote.' },
      { term: 'Triangular trade', def: 'Trade route linking Britain, West Africa and the Americas.' },
      { term: 'Abolition', def: 'Officially ending something, e.g. the slave trade (1807).' },
      { term: 'Empire', def: 'A group of countries or territories ruled by one country.' },
    ],
    sections: [
      { title: 'Machines, factories and towns', html: "<p>Inventions such as the spinning jenny, water frame and Watt's steam engine moved textile production into <b>factories</b>. Railways after 1830 moved goods and people quickly. Towns grew rapidly, but housing was overcrowded and unhealthy. Children worked long hours until Factory Acts (1833, 1847) and the Mines Act (1842) set limits.</p>" },
      { title: 'Protest and reform', html: timeline([["1819", "Peterloo Massacre"], ["1832", "Great Reform Act"], ["1833", "Factory Act"], ["1834", "Tolpuddle Martyrs"], ["1838–48", "Chartism"], ["1867", "Second Reform Act"], ["1872", "Secret ballot"]]) },
      { title: 'Slavery, abolition and empire', html: "<p>British ships carried over 3 million Africans across the Atlantic. Profits from sugar and cotton enriched ports and investors. Abolition came from several factors working together:</p><ul><li><b>Resistance</b> by enslaved people (e.g. Haiti 1791, Jamaica 1831–32).</li><li><b>Campaigners</b> — Equiano, Clarkson, Wilberforce; petitions and sugar boycotts.</li><li><b>Economic change</b> — some argue slavery was becoming less profitable.</li></ul>" + people([["William Wilberforce", "MP who led the parliamentary campaign against the slave trade."], ["Olaudah Equiano", "Formerly enslaved writer whose 1789 book exposed the trade."], ["Samuel Sharpe", "Led the 1831–32 Jamaican rebellion; executed."], ["Robert Clive", "East India Company commander; victory at Plassey 1757."]]) },
      { title: 'Model answer', html: worked("Explain why the British slave trade was abolished in 1807. (8 marks)", ["Factor 1: campaigners and public opinion.", "Factor 2: resistance by enslaved people.", "Link them and reach a judgement."], "Model paragraph: One reason was the campaign that changed public opinion. Campaigners such as Thomas Clarkson collected evidence like the plan of the slave ship Brookes, which showed people packed like cargo, while Olaudah Equiano's autobiography of 1789 gave a first-hand account of the Middle Passage. Hundreds of thousands of people signed petitions and boycotted slave-grown sugar. This pressure meant MPs such as Wilberforce could eventually win a majority in Parliament for the 1807 Act.") },
    ],
    mistakes: ["Saying slavery ended in 1807 — that was the trade; slavery ended from 1834.", "Giving all the credit to Wilberforce and ignoring enslaved people's resistance.", "Thinking the 1832 Reform Act gave working men the vote.", "Forgetting that Factory Acts were gradual and limited."],
    examTips: ["Show how different factors worked together, not as separate lists.", "Use statistics carefully and precisely (e.g. population 9m → 32m).", "In interpretation questions on empire, support and challenge with evidence."],
    realLife: "Many British cities still have buildings, street names and statues linked to industry, empire and the slave trade, which are debated today.",
  },
);

// ---- extra practice: Industry, Reform and Empire ----
more('hist-y8-industry-empire-1', [
  M('Which invention by John Kay (1733) made weaving much faster?', ['The flying shuttle', 'The spinning mule', 'The steam hammer', 'The seed drill'], 0, 'The flying shuttle let weavers make wider cloth faster, which created a demand for more thread and encouraged inventions in spinning. The seed drill was a farming invention by Jethro Tull.'),
  M('What did Abraham Darby achieve at Coalbrookdale in 1709?', ['He smelted iron using coke instead of charcoal', 'He built the first steam locomotive', 'He invented the telephone', 'He opened the first canal'], 0, 'Coke, made from coal, was cheaper and more plentiful than charcoal from wood. This allowed far more iron to be produced, which was vital for machines, bridges and railways.'),
  M('What is the Iron Bridge (opened 1781) in Shropshire famous as?', ['The world’s first major bridge made of cast iron', 'The first railway bridge', 'The oldest Roman bridge in Britain', 'A suspension bridge by Brunel'], 0, 'Built near Coalbrookdale, it showed what iron could do. Brunel’s Clifton Suspension Bridge in Bristol came much later.'),
  M('Why was the Bridgewater Canal (opened 1761) so important?', ['It halved the price of coal in Manchester and started a canal-building boom', 'It was the first railway', 'It linked London and Paris', 'It carried passengers only'], 0, 'Built for the Duke of Bridgewater to carry coal from his mines, it cut transport costs dramatically. Canals were ideal for heavy goods until railways took over.'),
  M('What was the Liverpool and Manchester Railway (1830) the first to do?', ['Run a regular inter-city service using only steam locomotives, carrying passengers and goods', 'Use horses to pull wagons', 'Travel underground', 'Cross the Atlantic'], 0, 'The Stockton and Darlington (1825) was the first public railway to use steam, but the Liverpool and Manchester was the first inter-city line relying entirely on steam locomotives.'),
  M('Which machine, invented by Samuel Crompton in 1779, combined features of the spinning jenny and the water frame?', ['The spinning mule', 'The flying shuttle', 'The power loom', 'The cotton gin'], 0, 'The mule produced fine, strong thread. The power loom (Cartwright) mechanised weaving; the cotton gin (Whitney, USA) separated cotton fibres from seeds.'),
  M('What is the difference between the domestic system and the factory system?', ['In the domestic system people worked at home; in the factory system workers went to large buildings with powered machines', 'The domestic system used steam engines; the factory system did not', 'They are two names for the same thing', 'The factory system was used only for farming'], 0, 'Before industrialisation spinning and weaving were often done at home. Factories brought workers, machines and power together, with strict hours and discipline.'),
  M('What was special about Robert Owen’s mills at New Lanark?', ['He provided better housing, schools and shorter hours for his workers', 'He employed only very young children', 'They had no machinery', 'They were run by the government'], 0, 'Owen believed good conditions made better workers and stayed profitable. He was unusual among mill owners and showed that reform was possible.'),
  S('Which deadly disease, spread by dirty water, struck Britain’s industrial towns in 1832 and 1848?', 'Cholera', ['cholera'], 'Cholera spread through water polluted with sewage. People did not know this until John Snow’s work in 1854; most blamed bad air (miasma).'),
  M('What were back-to-back houses?', ['Cheap houses built in rows sharing back walls, with little light or ventilation', 'Large homes for factory owners', 'Houses built on canal boats', 'Country cottages for farm workers'], 0, 'Back-to-backs packed many families into small areas. With shared privies and no running water, they helped disease spread.'),
  MU('Which TWO sources of power drove early factories?', ['Water wheels', 'Steam engines', 'The National Grid', 'Petrol engines', 'Nuclear power'], [0, 1], 'Early mills used water power, so they were built by fast rivers. Improved steam engines later let factories be built in towns near coal. Electricity grids and petrol engines came much later.'),
  O('Put these developments in chronological order.', ['John Kay’s flying shuttle', 'Hargreaves’ spinning jenny', 'Arkwright’s mill at Cromford', 'The Stockton and Darlington Railway', 'The Great Exhibition'], '1733 flying shuttle; c.1764 spinning jenny; 1771 Cromford Mill; 1825 Stockton and Darlington; 1851 Great Exhibition.'),
  M('Which engineer built the Great Western Railway and the steamship SS Great Britain?', ['Isambard Kingdom Brunel', 'George Stephenson', 'James Brindley', 'Richard Arkwright'], 0, 'Brunel was a famous Victorian engineer. Stephenson built the Rocket; Brindley built canals; Arkwright built cotton mills.'),
  W('<table class="qt"><tr><th>Year</th><th>Approximate population of Manchester</th></tr><tr><td>1801</td><td>about 70,000</td></tr><tr><td>1851</td><td>about 300,000</td></tr></table>', M('What does the table show about Manchester between 1801 and 1851?', ['Its population grew roughly four times larger', 'Its population halved', 'Its population stayed about the same', 'Its population grew by about 10%'], 0, '300,000 is a bit over four times 70,000. This rapid urbanisation came from people moving to work in cotton mills, and it outpaced housing, water and sewerage.')),
  M('How did changes in farming (the Agricultural Revolution) help industrialisation?', ['More food was produced, supporting a growing population that could work in factories', 'Farms became factories', 'Farmers stopped growing food', 'It ended the need for coal'], 0, 'Enclosure, crop rotation and new tools raised food output. More food fed a growing population, and fewer workers were needed on farms, so many moved to towns.'),
]);
more('hist-y8-industry-empire-2', [
  M('Which radical speaker was due to address the crowd at St Peter’s Field (Peterloo) in 1819?', ['Henry Hunt', 'William Wilberforce', 'Feargus O’Connor', 'Emmeline Pankhurst'], 0, '‘Orator’ Hunt was arrested as the yeomanry charged. O’Connor was a later Chartist leader; Wilberforce campaigned against the slave trade; Pankhurst led the suffragettes.'),
  M('What were the Six Acts of 1819?', ['Laws passed after Peterloo to restrict meetings and radical newspapers', 'Six new rights for factory workers', 'Laws giving votes to six cities', 'The six points of the Charter'], 0, 'The government responded to Peterloo with repression, limiting public meetings and taxing radical newspapers. This shows its fear of revolution.'),
  M('What was the Cato Street Conspiracy (1820)?', ['A plot to murder the cabinet, discovered by a government spy', 'A Chartist petition', 'A strike by dock workers', 'A plan to build a new railway'], 0, 'Radicals planned to kill cabinet ministers at a dinner. A spy informed the government; five were executed. It increased fear of violent revolution.'),
  M('What happened at Newport in Wales in November 1839?', ['An armed Chartist rising was crushed by soldiers, killing over 20 people', 'The first trade union was formed', 'Women gained the vote', 'The Great Reform Act was passed'], 0, 'The Newport Rising was the most violent Chartist event. Its leaders were sentenced to death, later changed to transportation to Australia.'),
  M('What happened at the Chartist meeting on Kennington Common in 1848?', ['A huge petition was taken to Parliament, but the meeting passed off peacefully and the petition was rejected', 'The Chartists seized Parliament', 'Queen Victoria agreed to the Charter', 'Soldiers killed hundreds of people'], 0, 'The government prepared thousands of special constables, but the meeting was peaceful. The petition was found to contain fake signatures and was rejected, damaging the movement.'),
  M('Which group gained the vote in the 1884 Reform Act?', ['Many male agricultural workers in the countryside', 'All women over 21', 'Only factory owners', 'Peers in the House of Lords'], 0, 'The 1884 Act gave rural working men similar voting rights to town workers (from 1867). About 60% of adult men could then vote; women still could not.'),
  M('What did the Representation of the People Act 1918 do?', ['Gave the vote to all men over 21 and most women over 30', 'Gave the vote to all women over 21', 'Abolished the House of Lords', 'Introduced the secret ballot'], 0, 'The 1918 Act was partly a reward for war service. Women gained equal voting rights with men (at 21) only in 1928. The secret ballot came in 1872.'),
  S('In which year did women gain the vote on the same terms as men (at age 21)?', '1928', [], 'The Equal Franchise Act of 1928 lowered women’s voting age from 30 to 21, giving equal voting rights with men.'),
  M('What was the main difference between the suffragists and the suffragettes?', ['Suffragists used peaceful, legal methods; suffragettes used direct action and sometimes violence', 'Suffragists wanted the vote only for men', 'Suffragettes were led by Millicent Fawcett', 'There was no difference'], 0, 'Millicent Fawcett’s NUWSS (suffragists) campaigned peacefully. Emmeline Pankhurst’s WSPU (from 1903) used militant tactics such as window smashing and arson.'),
  M('Which suffragette died after running onto the course at the 1913 Epsom Derby?', ['Emily Wilding Davison', 'Emmeline Pankhurst', 'Millicent Fawcett', 'Mary Seacole'], 0, 'Emily Davison was hit by the king’s horse and died days later. Her intentions are still debated. Mary Seacole was a nurse in the Crimean War.'),
  M('What did the ‘Cat and Mouse Act’ (1913) do?', ['Released hunger-striking suffragettes when weak, then re-arrested them when they recovered', 'Banned cats from parliament', 'Gave women the vote', 'Ended force-feeding in prisons for all prisoners forever'], 0, 'Officially the Prisoners (Temporary Discharge for Ill-Health) Act, it was designed to avoid the bad publicity of force-feeding and of suffragettes dying in prison.'),
  M('What did the Poor Law Amendment Act of 1834 introduce?', ['Workhouses with harsh conditions for people who needed poor relief', 'Free schools for all children', 'Old age pensions', 'A minimum wage'], 0, 'Workhouses were made deliberately unpleasant to discourage people from asking for help. They were hated and fed anger that helped Chartism grow. Pensions came in 1908.'),
  T('Trade unions became legal in Britain when the Combination Acts were repealed in 1824–25.', true, 'True. Unions could now exist legally, but their actions were still restricted. The Tolpuddle Martyrs were prosecuted in 1834 for swearing secret oaths, not simply for forming a union.'),
  O('Put these events in chronological order.', ['Peterloo', 'Great Reform Act', 'Tolpuddle Martyrs transported', 'First Chartist petition', 'Second Reform Act', 'Ballot Act'], '1819 Peterloo; 1832 Reform Act; 1834 Tolpuddle; 1839 first Chartist petition; 1867 Second Reform Act; 1872 Ballot Act.'),
  MU('Which TWO were typical Chartist methods?', ['Collecting huge petitions to Parliament', 'Holding large public meetings', 'Hunger strikes in prison', 'Smashing shop windows in the 1910s', 'Refusing to pay the poll tax of 1381'], [0, 1], 'Most Chartists used ‘moral force’: petitions, newspapers and mass meetings. Hunger strikes and window smashing were suffragette tactics decades later; the poll tax was medieval.'),
  W(src('Source A: a description of a cartoon published soon after Peterloo, 1819.', 'Fat, red-faced yeomanry on horseback swing their swords at unarmed men, women and a baby, while one officer shouts “Down with them! The more you kill the less poor rates you’ll have to pay.”'), M('What is the message of the cartoon?', ['The authorities brutally attacked peaceful, defenceless people', 'The crowd attacked the soldiers first', 'The yeomanry were heroes who saved Manchester', 'Peterloo was a peaceful celebration'], 0, 'The cartoonist contrasts armed, well-fed soldiers with unarmed families and suggests the rich wanted the poor dead. It is radical propaganda, but it reflects widespread anger at the deaths.')),
]);
more('hist-y8-industry-empire-3', [
  M('What was carried on the first leg of the triangular trade, from Britain to West Africa?', ['Manufactured goods such as guns, cloth and metal goods', 'Enslaved Africans', 'Sugar and tobacco', 'Gold from the Americas'], 0, 'British ships took manufactured goods to trade for enslaved people in Africa, then carried them to the Americas (the Middle Passage), and returned with sugar, tobacco and cotton.'),
  MU('Which TWO British ports grew rich from the slave trade?', ['Liverpool', 'Bristol', 'Aberdeen', 'Belfast', 'Inverness'], [0, 1], 'Liverpool, Bristol and London were the main slave-trading ports. Liverpool dominated by the later 1700s. Wealth from the trade helped build these cities.'),
  M('Which crop was the most important product of the British Caribbean plantations?', ['Sugar', 'Rice', 'Potatoes', 'Tea'], 0, 'Sugar was hugely profitable and very labour-intensive, which drove the demand for enslaved workers. Tea came mainly from China and later India.'),
  M('What happened on the slave ship Zong in 1781?', ['The crew threw over 130 enslaved Africans overboard and the owners claimed insurance for them', 'Enslaved people took over the ship and sailed home', 'The ship carried the first abolitionists to Africa', 'It sank in a storm with no survivors'], 0, 'The Zong case shocked people because the court treated the murdered Africans as cargo. Olaudah Equiano brought it to the attention of the abolitionist Granville Sharp.'),
  W(src('Source A: the motto on a medallion produced by the potter Josiah Wedgwood in 1787.', 'Am I not a man and a brother?'), M('Why was this image and motto effective for the abolition campaign?', ['It reminded the public that enslaved Africans were fellow human beings', 'It advertised sugar', 'It argued slavery was good for Britain', 'It was a royal order to end slavery'], 0, 'The medallion showed a kneeling, chained African. It was copied on jewellery and other items, spreading the abolitionist message widely in a simple, emotional way.')),
  M('What was the sugar boycott of the 1790s?', ['Hundreds of thousands of Britons refused to buy slave-grown sugar', 'A ban on sugar by the government', 'A tax on sugar to pay for the navy', 'Plantation owners refusing to grow sugar'], 0, 'The boycott showed that ordinary people, including many women who controlled household shopping, could put economic pressure on the slave system.'),
  M('Who led the successful revolution of enslaved people in the French colony of Saint-Domingue (Haiti) in the 1790s?', ['Toussaint Louverture', 'Olaudah Equiano', 'Sam Sharpe', 'Napoleon Bonaparte'], 0, 'Toussaint Louverture was the best-known leader of the Haitian Revolution, which created an independent Haiti in 1804. Sam Sharpe led a rebellion in Jamaica in 1831.'),
  M('What was the significance of the Jamaican rebellion of 1831–32, led by Sam Sharpe?', ['Its scale and brutal suppression increased pressure on Parliament to end slavery', 'It restored the slave trade', 'It made Jamaica independent', 'It had no effect on British opinion'], 0, 'Around 60,000 enslaved people took part. The harsh punishments and the fear of further risings helped persuade Parliament to pass the Slavery Abolition Act in 1833.'),
  T('After the 1833 Act, many formerly enslaved people had to continue working for their former owners as ‘apprentices’ until 1838.', true, 'True. The apprenticeship system was meant to last longer but ended early in 1838 after protests. Freedom also brought no compensation for the enslaved.'),
  M('Who was Mary Prince?', ['A formerly enslaved woman whose account of her life was published in Britain in 1831', 'The leader of the Haitian Revolution', 'A plantation owner who supported slavery', 'A Victorian nurse in the Crimea'], 0, 'Mary Prince’s narrative was the first account of the life of a Black woman published in Britain. It gave powerful first-hand evidence to the anti-slavery campaign.'),
  M('Which spark helped trigger the Indian Rebellion of 1857?', ['Rumours that new rifle cartridges were greased with cow and pig fat', 'The British closed all Indian ports', 'A famine caused by a volcanic eruption', 'The death of Queen Victoria'], 0, 'Sepoys had to bite cartridges, and the rumour offended both Hindus and Muslims. Deeper causes included annexation of Indian states and resentment at British rule.'),
  M('Which title was Queen Victoria given in 1876?', ['Empress of India', 'Queen of America', 'Empress of China', 'Queen of France'], 0, 'Disraeli’s government gave Victoria the title Empress of India (proclaimed in India in 1877), showing how important India was to the British Empire.'),
  M('During the Boer War (1899–1902), what did the British set up that caused many deaths of Boer and Black African civilians?', ['Concentration camps', 'Workhouses', 'Factories', 'Prisoner exchanges'], 0, 'The British moved civilians into camps to cut off support for Boer fighters. Poor food and disease killed tens of thousands, causing outrage when Emily Hobhouse reported it.'),
  O('Put these events in chronological order.', ['The Zong massacre', 'Abolition of the British slave trade', 'The Slavery Abolition Act', 'End of the apprenticeship system', 'The Indian Rebellion'], '1781 Zong; 1807 slave trade abolished; 1833 Slavery Abolition Act; 1838 apprenticeship ends; 1857 Indian Rebellion.'),
  M('What was decided at the Berlin Conference (1884–85)?', ['European powers set rules for claiming African territory', 'African leaders divided Europe', 'Britain agreed to leave India', 'The slave trade was restarted'], 0, 'No African rulers were invited. The conference sped up the ‘Scramble for Africa’, in which European powers took control of most of the continent by 1914.'),
  T('Enslaved Africans did not resist slavery.', false, 'False. Resistance took many forms: rebellions on ships and plantations, running away, breaking tools, keeping their cultures alive, and revolutions such as Haiti. Resistance helped bring slavery to an end.'),
]);
// =====================================================================
// YEAR 9 — The First World War
// =====================================================================
addTopic(
  { id: 'hist-y9-first-world-war', strand: 'hist-c20', year: 9, term: 1, name: 'The First World War 1914–1918',
    summary: 'The long- and short-term causes of the war, life and death on the Western Front, and the impact of total war on Britain.',
    specRef: 'DfE KS3 History: challenges for Britain, Europe and the wider world 1901 to the present day (the First World War)' },
  [
    { name: 'Causes of the First World War', intro: "Historians often group the long-term causes as MAIN: Militarism, Alliances, Imperialism and Nationalism. The assassination in Sarajevo on 28 June 1914 was the trigger.",
      items: [
        M("What does the 'M' in the MAIN causes stand for?", ["Militarism", "Monarchy", "Migration", "Manufacturing"], 0, "MAIN = Militarism, Alliances, Imperialism, Nationalism. Militarism means building up armed forces and glorifying war."),
        M("Which countries made up the Triple Entente?", ["Britain, France and Russia", "Germany, Austria-Hungary and Italy", "Britain, Germany and Russia", "France, Italy and the USA"], 0, "The Entente linked Britain, France and Russia. Germany, Austria-Hungary and Italy formed the Triple Alliance (Italy joined the Allies in 1915)."),
        S("Who was assassinated in Sarajevo on 28 June 1914?", "Archduke Franz Ferdinand", ["franz ferdinand", "archduke franz ferdinand", "the archduke"], "Franz Ferdinand, heir to the Austro-Hungarian throne, and his wife Sophie were shot by Gavrilo Princip, a Bosnian Serb nationalist."),
        M("Which group was Gavrilo Princip linked to?", ["The Black Hand, a Serbian nationalist secret society", "The German army", "The Bolsheviks", "The British secret service"], 0, "The Black Hand wanted Bosnia freed from Austria-Hungary and joined to Serbia."),
        M("What was the naval race?", ["Britain and Germany competing to build Dreadnought battleships", "A sailing competition", "France and Russia racing to Africa", "A race to cross the Atlantic"], 0, "After HMS Dreadnought (1906), Britain and Germany raced to build more of these battleships, increasing tension."),
        M("Why did Britain declare war on Germany on 4 August 1914?", ["Germany invaded Belgium, whose neutrality Britain had promised to protect", "Germany attacked London", "Austria-Hungary invaded France", "Russia ordered Britain to fight"], 0, "The 1839 Treaty of London guaranteed Belgian neutrality. Germany invaded Belgium as part of the Schlieffen Plan."),
        S("What was the name of Germany's plan to defeat France quickly through Belgium before turning to Russia?", "Schlieffen Plan", ["schlieffen", "the schlieffen plan"], "The Schlieffen Plan aimed to knock France out in about six weeks. It failed at the Battle of the Marne in September 1914."),
        O("Put the July Crisis in order.", ["Franz Ferdinand assassinated", "Austria-Hungary declares war on Serbia", "Germany declares war on Russia", "Germany invades Belgium", "Britain declares war on Germany"], "28 June; 28 July; 1 August; 3–4 August; 4 August 1914."),
        MU("Which TWO are examples of imperialism as a cause?", ["Rivalry between European powers for colonies in Africa", "Germany's wish for 'a place in the sun' — an empire like Britain's", "Women campaigning for votes", "The invention of the tank", "The Russian Revolution"], [0, 1], "Imperialism means competing for empire. Germany's ambitions clashed with Britain and France, e.g. in the Moroccan Crises (1905, 1911)."),
        T("The alliance system meant that a local conflict could quickly involve all the great powers.", true, "True. Russia backed Serbia, Germany backed Austria-Hungary, France was allied to Russia, and Britain was linked to France and Belgium."),
        M("What is nationalism?", ["Strong pride in, and loyalty to, one's nation, sometimes wanting independence", "Belief in sharing all property", "Loyalty to a religion above all else", "A type of weapon"], 0, "Serbian nationalism threatened Austria-Hungary; German and French nationalism encouraged hostility."),
        M("Which statement is a SHORT-TERM cause of the war?", ["The assassination of Franz Ferdinand", "The naval race since 1906", "The formation of alliances", "Imperial rivalry in Africa"], 0, "The assassination was the trigger in 1914; the others built up over years."),
        S("In which year did the First World War begin?", "1914", [], "War began in late July–August 1914 and ended with the armistice on 11 November 1918."),
        T("The USA joined the war in 1914.", false, "False. The USA joined in April 1917, after German unrestricted submarine warfare and the Zimmermann Telegram."),
        M("Which country was Britain's main naval rival before 1914?", ["Germany", "France", "Russia", "Belgium"], 0, "Kaiser Wilhelm II wanted a navy to rival Britain's, which alarmed a country that relied on the sea."),
      ] },
    { name: 'The Western Front', intro: "After the Schlieffen Plan failed, both sides dug trenches from the Channel to Switzerland. Attacks across no man's land cost huge numbers of lives for little ground.",
      items: [
        S("What name was given to the land between the opposing trenches?", "No man's land", ["no mans land", "no-mans land"], "No man's land was the shell-cratered, wire-filled zone between the front lines."),
        M("Which battle began on 1 July 1916 with the worst single day in British army history?", ["The Somme", "Ypres", "Verdun", "Gallipoli"], 0, "On 1 July 1916 the British suffered over 57,000 casualties, including about 19,000 dead. Verdun was mainly a French–German battle."),
        M("Why did the first day of the Somme go so badly for the British?", ["The week-long bombardment failed to destroy German wire and deep dugouts", "The Germans had already surrendered", "British troops had no rifles", "It was fought at night in snow"], 0, "Many shells were duds or shrapnel that could not cut wire, and Germans sheltered in deep dugouts, then machine-gunned advancing troops."),
        M("When were tanks first used in battle?", ["September 1916 at the Somme", "August 1914 at Mons", "1918 at Amiens only", "1939 in Poland"], 0, "British tanks were first used at Flers-Courcelette on 15 September 1916. They were later used more effectively, e.g. Cambrai 1917 and Amiens 1918."),
        S("Which gas was first used by Germany at Ypres in April 1915?", "Chlorine", ["chlorine gas"], "Chlorine gas was first used on a large scale at the Second Battle of Ypres. Phosgene and mustard gas followed."),
        M("What was 'trench foot'?", ["A condition where feet rotted from standing in cold, wet trenches", "A type of boot", "A way of kicking footballs in trenches", "A name for the front line"], 0, "Constant wet conditions caused swelling and infection; soldiers were ordered to change socks and rub whale oil into feet."),
        MU("Which TWO weapons made attacking across no man's land extremely dangerous?", ["Machine guns", "Barbed wire", "Longbows", "Swords", "Cavalry lances"], [0, 1], "Machine guns and barbed wire, with artillery, gave defenders a huge advantage."),
        T("Soldiers usually spent all their time in the front-line trench.", false, "False. Units rotated between front-line, support and reserve trenches and rest areas behind the lines."),
        M("Which general commanded the British Expeditionary Force from December 1915?", ["Sir Douglas Haig", "Lord Kitchener", "Erich Ludendorff", "Ferdinand Foch"], 0, "Haig led the BEF at the Somme and Passchendaele. Kitchener was War Secretary; Ludendorff was German; Foch became Allied supreme commander in 1918."),
        M("The phrase 'lions led by donkeys' expresses which interpretation?", ["Brave soldiers were sacrificed by incompetent generals", "Generals were brilliant", "Animals were used in battle", "The war was won quickly"], 0, "This interpretation, popular from the 1960s, criticises generals like Haig. Other historians argue they learned and adapted, leading to victory in 1918."),
        O("Put these battles in chronological order.", ["Battle of the Marne", "Gallipoli landings", "Battle of the Somme", "Battle of Passchendaele", "Hundred Days Offensive"], "September 1914; April 1915; July–November 1916; July–November 1917; August–November 1918."),
        S("On what date did the armistice end the fighting? (day and month)", "11 November", ["11th november", "november 11", "11 nov", "armistice day"], "The armistice came into effect at 11 a.m. on 11 November 1918 — remembered on Armistice Day."),
        M("Roughly how many British and Empire servicemen died in the war?", ["About 1 million", "About 10,000", "About 100,000", "About 10 million"], 0, "Around 880,000 from the UK and about 1 million from the Empire as a whole. Total military deaths for all nations were around 9–10 million."),
        W(src("Source A: a letter home from a British private, November 1917.", "We are up to our knees in mud. The duckboards slide away into the shell holes, and a man who slips in may never get out. Do not believe the papers that say we are winning."), M("Source A is most useful for showing…", ["Conditions at Passchendaele and some soldiers' distrust of newspaper reports", "Exact casualty figures for 1917", "The views of German generals", "Life on the Home Front"], 0, "A private letter from late 1917 (Passchendaele) gives first-hand detail of mud and attitudes. It cannot give statistics, and letters were censored, so soldiers may have held back even more.")),
        T("Most soldiers' letters home were read by army censors.", true, "True. Censors removed military information and sometimes negative comments, which affects how useful letters are as sources."),
      ] },
    { name: 'The Home Front and the end of the war', intro: "The First World War was a 'total war': civilians were mobilised, controlled and sometimes attacked. It brought conscription, rationing and new roles for women.",
      items: [
        S("Which 1914 law gave the government wide powers over people's lives during the war? (four-letter abbreviation)", "DORA", ["defence of the realm act", "the defence of the realm act"], "The Defence of the Realm Act (August 1914) allowed censorship, control of land and industry, and even cut pub opening hours."),
        M("When was conscription introduced in Britain?", ["1916", "1914", "1918", "1939"], 0, "The Military Service Act (January 1916) conscripted single men aged 18–41; it was extended to married men in May 1916."),
        M("What was a conscientious objector?", ["Someone who refused to fight because of moral or religious beliefs", "A soldier who deserted", "A German spy", "A factory owner"], 0, "About 16,000 men refused; some did non-combat work, others were imprisoned."),
        MU("Which TWO jobs did many women take on during the war?", ["Working in munitions factories", "Working as bus and tram conductors", "Serving as front-line infantry", "Becoming MPs in 1915", "Leading army regiments"], [0, 1], "Women worked in munitions ('munitionettes'), transport, farming and nursing. They did not serve as infantry, and none were MPs until 1918–19."),
        M("Why were some munitions workers called 'canaries'?", ["TNT turned their skin yellow", "They sang while working", "They worked in coal mines", "They wore yellow uniforms"], 0, "Handling TNT turned skin yellow and could cause poisoning."),
        M("How was Britain attacked from the air during the war?", ["By Zeppelin airships and later Gotha bombers", "By V2 rockets", "By jet aircraft", "By atomic bombs"], 0, "Zeppelin raids began in 1915; Gotha bomber raids on London started in 1917. V2s were used in the Second World War."),
        S("Which national system was introduced in 1918 to share out sugar, meat and butter fairly?", "Rationing", ["food rationing"], "German U-boats caused shortages; rationing of sugar began in January 1918 and later meat, butter and margarine."),
        T("In 1918 some women gained the right to vote in general elections.", true, "True. The Representation of the People Act (1918) gave the vote to women over 30 who met a property qualification, and to almost all men over 21."),
        M("Why did German U-boat warfare matter for Britain's Home Front?", ["Sinking supply ships caused food shortages", "It stopped trains running", "It caused the Black Death", "It meant no letters reached soldiers"], 0, "Britain imported much of its food. Unrestricted submarine warfare (1917) brought Britain close to starvation until convoys were used."),
        O("Put these Home Front developments in order.", ["DORA passed", "First Zeppelin raids on Britain", "Conscription introduced", "Rationing introduced", "Women over 30 gain the vote"], "1914; 1915; 1916; 1918 (January); 1918 (Representation of the People Act, February)."),
        M("Which factor helped the Allies win in 1918?", ["Arrival of fresh American troops and the failure of Germany's Spring Offensive", "Russia joining the Allies in 1918", "Germany capturing Paris", "The invention of the atomic bomb"], 0, "Germany's Spring Offensive (March 1918) ran out of steam; the Allies, with US troops and tanks, pushed back in the Hundred Days. Russia had left the war in 1918."),
        M("What was the 'Pals' battalions' idea?", ["Men from the same town or workplace could join up and serve together", "Soldiers chose their own officers", "Women and men served together", "Germans and British shared trenches"], 0, "Friends and workmates enlisted together. When a Pals battalion suffered heavy losses, as at the Somme, whole communities were devastated."),
        S("Who was the War Secretary whose face appeared on the famous 'wants you' recruitment poster?", "Lord Kitchener", ["kitchener"], "Kitchener raised a huge volunteer army; his image with a pointing finger became an iconic recruitment poster."),
        T("Germany signed an armistice because its army had been completely destroyed and Germany occupied.", false, "False. No Allied troops were in Germany in November 1918; the German army was retreating and the home front was collapsing. This later fed the 'stab in the back' myth."),
        M("What was the 'stab in the back' myth?", ["The false claim that Germany's army was betrayed by politicians at home rather than defeated", "A story about Franz Ferdinand", "A British spy legend", "The claim that Britain lost the war"], 0, "Nationalists, later the Nazis, blamed the 'November Criminals' who signed the armistice — linking this topic to Weimar Germany."),
      ] },
  ],
  {
    overview: "The First World War (1914–18) was caused by long-term tensions — militarism, alliances, imperialism and nationalism — triggered by the assassination of Franz Ferdinand. Stalemate on the Western Front led to massive casualties, while at home it became a 'total war' that changed women's lives and the vote.",
    objectives: ["I can explain the MAIN causes and the trigger of the war.", "I can describe conditions and key battles on the Western Front.", "I can explain how the war affected people in Britain.", "I can evaluate interpretations of British generals."],
    keyWords: [
      { term: 'Militarism', def: 'Building up armed forces and glorifying military power.' },
      { term: 'Alliance', def: 'An agreement between countries to support each other.' },
      { term: 'Stalemate', def: 'A situation where neither side can win.' },
      { term: 'No man’s land', def: 'Ground between opposing trenches.' },
      { term: 'Conscription', def: 'Compulsory military service (Britain from 1916).' },
      { term: 'DORA', def: 'Defence of the Realm Act, 1914.' },
      { term: 'Total war', def: 'A war in which a country’s whole population and economy are mobilised.' },
      { term: 'Armistice', def: 'An agreement to stop fighting (11 November 1918).' },
    ],
    sections: [
      { title: 'Causes: MAIN and Sarajevo', html: "<ul><li><b>Militarism</b> — arms race and the Anglo-German naval race (Dreadnoughts).</li><li><b>Alliances</b> — Triple Entente v Triple Alliance.</li><li><b>Imperialism</b> — rivalry for colonies; Moroccan Crises.</li><li><b>Nationalism</b> — Serbian nationalism in the Balkans.</li></ul><div class=\"rule\">Trigger: assassination of Franz Ferdinand, 28 June 1914 → Austria declares war on Serbia → alliances drag in Russia, Germany, France and Britain (4 August, over Belgium).</div>" },
      { title: 'Key dates', html: timeline([["28 Jun 1914", "Assassination in Sarajevo"], ["4 Aug 1914", "Britain declares war"], ["Sep 1914", "Battle of the Marne; trenches dug"], ["Apr 1915", "Gas at Ypres; Gallipoli landings"], ["1 Jul 1916", "First day of the Somme"], ["Apr 1917", "USA enters the war"], ["Jul–Nov 1917", "Passchendaele"], ["Mar 1918", "German Spring Offensive"], ["11 Nov 1918", "Armistice"]]) },
      { title: 'Life on the Western Front and at home', html: "<p>Trench life meant mud, rats, lice, trench foot and constant danger from shells and snipers. Attacks faced machine guns and barbed wire. At home, DORA, conscription, air raids and rationing touched everyone, and women took on new work in munitions, transport and farming.</p>" + people([["Sir Douglas Haig", "Commander of the BEF from 1915; debated as 'butcher' or 'architect of victory'."], ["Lord Kitchener", "War Secretary who raised a volunteer army."], ["Gavrilo Princip", "Assassin of Franz Ferdinand."]]) },
      { title: 'Model answer: interpretation', html: worked("'The British generals were lions leading donkeys.' How far do you agree? (16 marks)", ["Support: first day of the Somme — 57,000 casualties; repeated costly attacks at Passchendaele.", "Challenge: generals learned — creeping barrage, tanks, air cover, all-arms tactics in the Hundred Days 1918.", "Judgement: the interpretation fits 1916 better than 1918."], "Model paragraph: There is evidence to challenge this interpretation. By 1918 the British army had developed new tactics, combining creeping artillery barrages, tanks, aircraft and infantry. At Amiens in August 1918 these methods broke through German lines, beginning the Hundred Days Offensive that forced Germany to seek an armistice. This suggests that generals such as Haig learned from earlier failures, so the claim that they were simply incompetent 'donkeys' is too harsh.") },
    ],
    mistakes: ["Saying Britain went to war because of Franz Ferdinand — it was over Belgium.", "Giving one cause only; examiners want several linked causes.", "Thinking women got the vote on equal terms in 1918 (equal only from 1928).", "Assuming all generals were careless — this is an interpretation, not a fact."],
    examTips: ["Explain how each MAIN factor made war more likely, then show how the trigger set it off.", "In 'how far do you agree' questions argue both sides and reach a supported judgement.", "Comment on provenance (e.g. censorship) when judging letters and posters."],
    realLife: "Remembrance Sunday and poppies each November commemorate those who died in the First World War and later conflicts.",
  },
);

// ---- extra practice: The First World War ----
more('hist-y9-first-world-war-1', [
  M('Which countries formed the Triple Alliance of 1882?', ['Germany, Austria-Hungary and Italy', 'Britain, France and Russia', 'Germany, Russia and Japan', 'Austria-Hungary, Serbia and Belgium'], 0, 'The Triple Alliance faced the Triple Entente (Britain, France and Russia). Italy did not join Germany in 1914 and changed sides in 1915.'),
  M('Why was the launch of HMS <i>Dreadnought</i> in 1906 so important?', ['It made all older battleships out of date and sped up the naval race with Germany', 'It was the first submarine', 'It was the first aircraft carrier', 'It ended the arms race'], 0, 'Dreadnought was faster and more heavily armed than any earlier battleship. Britain and Germany then raced to build dreadnoughts, increasing tension.'),
  M('What were the Moroccan Crises of 1905 and 1911?', ['German challenges to French influence in Morocco that pushed Britain and France closer together', 'Wars between Spain and Morocco', 'Revolutions in Russia', 'Disputes over Belgian neutrality'], 0, 'Germany hoped to split Britain and France, but both crises (Tangier 1905, Agadir 1911) strengthened the Entente instead.'),
  M('What did Austria-Hungary do in 1908 that angered Serbia and Russia?', ['Annexed Bosnia-Herzegovina', 'Invaded Belgium', 'Assassinated the Tsar', 'Signed an alliance with Britain'], 0, 'Bosnia had many Serbs, and Serbian nationalists wanted it to join a greater Serbia. The annexation increased tension in the Balkans and helps explain the 1914 assassination.'),
  M('What was the ‘blank cheque’ of July 1914?', ['Germany’s promise of full support to Austria-Hungary in dealing with Serbia', 'Britain’s promise to pay for the French army', 'A loan from the USA to Russia', 'Serbia’s offer to pay compensation'], 0, 'Germany’s unconditional backing encouraged Austria-Hungary to take a hard line against Serbia, turning a local crisis into a wider war.'),
  M('Which 1839 treaty guaranteed Belgian neutrality, which Britain went to war to defend?', ['The Treaty of London', 'The Treaty of Versailles', 'The Treaty of Paris', 'The Treaty of Brest-Litovsk'], 0, 'Britain, France and Prussia guaranteed Belgium’s neutrality in 1839. The German chancellor reportedly dismissed it as a ‘scrap of paper’. Versailles (1919) and Brest-Litovsk (1918) came at the end of the war.'),
  M('What did Kaiser Wilhelm II mean by wanting Germany to have ‘a place in the sun’?', ['He wanted Germany to have an overseas empire like Britain and France', 'He wanted to move Germany’s capital south', 'He wanted to stop the naval race', 'He wanted more holidays for workers'], 0, 'This policy, Weltpolitik (world policy), meant colonies and a large navy, which alarmed Britain and contributed to imperial and naval rivalry.'),
  M('Why did Russia mobilise its army in July 1914?', ['To support Serbia, a fellow Slavic nation, against Austria-Hungary', 'To attack Britain', 'To defend Belgium', 'To help Germany against France'], 0, 'Russia saw itself as protector of the Slavs. Russian mobilisation led Germany to declare war on Russia and then France, following the Schlieffen Plan.'),
  T('The Balkan Wars of 1912–13 increased Serbia’s size and confidence, which worried Austria-Hungary.', true, 'True. Serbia gained territory in the Balkan Wars. Austria-Hungary feared a stronger Serbia would encourage Slav nationalists inside its own empire.'),
  M('What does ‘militarism’ mean as a cause of the war?', ['A belief in building strong armed forces and being ready to use them', 'A refusal to fight', 'A plan to share colonies fairly', 'A type of alliance'], 0, 'Militarism includes arms races, large conscript armies and military plans such as the Schlieffen Plan, which made war more likely and harder to stop.'),
  O('Put these events in chronological order.', ['Entente Cordiale between Britain and France', 'HMS Dreadnought launched', 'Anglo-Russian Entente completes the Triple Entente', 'Austria-Hungary annexes Bosnia', 'Agadir Crisis'], '1904 Entente Cordiale; 1906 Dreadnought; 1907 Anglo-Russian Entente; 1908 Bosnia; 1911 Agadir.'),
  MU('Which TWO countries fought on the side of the Central Powers (Germany and Austria-Hungary)?', ['The Ottoman Empire', 'Bulgaria', 'Italy', 'Japan', 'The USA'], [0, 1], 'The Ottoman Empire joined in 1914 and Bulgaria in 1915. Italy joined the Allies in 1915, Japan was an ally of Britain and the USA joined the Allies in 1917.'),
  M('In the 1960s a German historian argued that Germany deliberately sought a war of expansion. Others have argued that the great powers ‘slid’ into war by accident. Why do these interpretations differ?', ['They emphasise different evidence about the aims and decisions of 1914', 'One of them did not know the war happened', 'They are writing about different wars', 'One uses only fiction'], 0, 'Historians weigh the same crisis differently: some stress German war aims documents, others stress the alliance system, mobilisation timetables and miscalculation by all sides.'),
  M('Why did many French people want revenge on Germany before 1914?', ['France had lost Alsace-Lorraine to Germany in 1871', 'Germany had invaded Paris in 1913', 'Germany had stolen France’s navy', 'Germany had refused to trade with France'], 0, 'France lost Alsace-Lorraine after the Franco-Prussian War. The wish to regain it fed French nationalism and hostility towards Germany.'),
  T('In August 1914 Germany declared war on Russia before it declared war on France.', true, 'True. Germany declared war on Russia on 1 August and on France on 3 August, then invaded Belgium, which brought Britain in on 4 August.'),
]);
more('hist-y9-first-world-war-2', [
  M('Which battle in September 1914 stopped the German advance on Paris?', ['The First Battle of the Marne', 'The Somme', 'Passchendaele', 'Verdun'], 0, 'At the Marne, French and British forces halted the Germans, ending the Schlieffen Plan’s hope of a quick victory. Both sides then dug in.'),
  M('What was the ‘Race to the Sea’ in autumn 1914?', ['Each side tried to outflank the other northwards, creating a trench line from the Channel to Switzerland', 'A naval race between Britain and Germany', 'A swimming competition between soldiers', 'The evacuation of troops by sea'], 0, 'Neither side could get round the other’s flank, so by late 1914 a continuous line of trenches stretched about 700 km across Belgium and France.'),
  T('In some places along the Western Front, British and German soldiers stopped fighting and met in no man’s land at Christmas 1914.', true, 'True. The unofficial Christmas truce saw soldiers exchange gifts and bury their dead. Commanders made sure it did not happen on the same scale again.'),
  MU('Which TWO were types of trench in a typical British trench system?', ['Support trenches', 'Communication trenches', 'Motorway trenches', 'Railway trenches', 'Underground cities'], [0, 1], 'Trench systems had front-line, support and reserve trenches, joined by communication trenches that let men, food and supplies move forward safely.'),
  M('What were duckboards used for in the trenches?', ['To give soldiers something firm to walk on above mud and water', 'To shoot ducks for food', 'To build aircraft', 'To signal to other trenches'], 0, 'Wooden duckboards on the trench floor helped against mud and flooding, though they could not stop trench foot in wet conditions.'),
  M('What was ‘shell shock’?', ['A mental and physical breakdown caused by the stress of war', 'An injury from a single shell fragment', 'A type of gas', 'A disease carried by rats'], 0, 'Today we would recognise many cases as post-traumatic stress. At first some officers saw it as cowardice, but by the end of the war it was more widely accepted as a real condition.'),
  O('Put the stages of the chain of evacuation for a wounded soldier in order.', ['Regimental Aid Post', 'Dressing Station', 'Casualty Clearing Station', 'Base Hospital'], 'A wounded man was treated first near the front at the Regimental Aid Post, then at a Dressing Station, then at a Casualty Clearing Station, and finally at a Base Hospital near the coast or in Britain.'),
  M('Which 1917 battle near Ypres is especially remembered for its terrible mud?', ['Passchendaele (Third Battle of Ypres)', 'The Marne', 'Cambrai', 'Mons'], 0, 'Heavy rain and shelling turned the ground into deep mud in which men and horses drowned. The battle cost huge casualties for small gains.'),
  M('Which 1916 battle was a long German attack on the French fortress city of Verdun?', ['Verdun', 'The Somme', 'Arras', 'Loos'], 0, 'Verdun (February–December 1916) was mainly French against German. One aim of the British Somme attack was to relieve pressure on the French at Verdun.'),
  M('What was significant about the Battle of Cambrai (November 1917)?', ['It was the first mass use of tanks, which broke through German lines at first', 'It was the first use of gas', 'It ended the war', 'It was fought entirely at sea'], 0, 'Over 400 tanks attacked at Cambrai and advanced quickly, but gains were soon lost. Tanks had first been used in smaller numbers at the Somme in September 1916.'),
  M('Which gas, used from 1917, caused severe blisters on the skin and in the lungs?', ['Mustard gas', 'Chlorine', 'Oxygen', 'Carbon dioxide'], 0, 'Mustard gas burned the skin and eyes and could lie in the soil for days. Chlorine (1915) caused choking; gas masks gave some protection.'),
  M('What was a ‘creeping barrage’?', ['Artillery fire that moved forward just ahead of advancing infantry', 'A slow-moving tank', 'A type of trench raid at night', 'A wall of barbed wire'], 0, 'By 1917–18 gunners had learned to fire a barrage that moved forward in stages, keeping defenders’ heads down as the infantry advanced behind it.'),
  S('What phrase described soldiers climbing out of their trench to attack? (three words: going …)', 'over the top', ['going over the top', 'over top'], 'Going ‘over the top’ meant climbing out of the trench and crossing no man’s land into enemy fire.', [['over'], ['top']]),
  W(src('Source B: an imaginary letter in the style of a British private on the Western Front, 1916.', 'The rats here are as big as cats. They run over us when we try to sleep and eat anything we leave. The smell of the trench never leaves you.'), M('What can you infer from Source B about conditions in the trenches?', ['They were dirty and unhealthy, making rest difficult', 'Soldiers were very comfortable', 'Food was carefully stored and safe', 'Soldiers slept in proper beds'], 0, 'Rats feeding on scraps and the dead, together with the smell, show unhygienic conditions. Letters were censored, so soldiers often played down the worst horrors.')),
  M('Approximately how many British casualties (killed, wounded and missing) were there on 1 July 1916, the first day of the Somme?', ['About 57,000, of whom about 19,000 were killed', 'About 570', 'About 5,700', 'About 570,000'], 0, 'About 57,000 casualties, including about 19,000 dead, made it the worst day in British army history. The battle lasted until November.'),
  M('Which offensive, beginning at Amiens in August 1918, pushed the German army back towards defeat?', ['The Hundred Days Offensive', 'The Schlieffen Plan', 'The Spring Offensive', 'The Gallipoli campaign'], 0, 'From August 1918 the Allies, using tanks, aircraft, artillery and infantry together, advanced steadily. The German Spring Offensive earlier in 1918 had failed, and Gallipoli was in 1915.'),
]);
more('hist-y9-first-world-war-3', [
  M('What was the purpose of the white feather campaign?', ['To shame men not in uniform into joining the army', 'To celebrate soldiers returning home', 'To mark houses hit by bombs', 'To show support for conscientious objectors'], 0, 'Some women handed white feathers, a symbol of cowardice, to men not in uniform. Sometimes they gave them to men home on leave or unfit to serve.'),
  M('Which British towns were shelled by German warships in December 1914?', ['Scarborough, Hartlepool and Whitby', 'London, Paris and Rome', 'Glasgow and Edinburgh', 'Belfast and Dublin'], 0, 'The raid killed over 100 civilians and caused outrage. Recruitment posters used it to urge men to ‘remember Scarborough’.'),
  T('From 1917 German Gotha aircraft carried out bombing raids on London.', true, 'True. Earlier raids were by Zeppelin airships; by 1917 Gotha bombers attacked in daylight. A raid in June 1917 killed over 160 people in London.'),
  M('What happened to the liner <i>Lusitania</i> in May 1915?', ['It was sunk by a German U-boat, killing nearly 1,200 people including 128 Americans', 'It carried the BEF to France', 'It sank after hitting an iceberg', 'It was captured by the Royal Navy'], 0, 'The sinking turned American opinion against Germany, though the USA did not join the war until 1917. The Titanic hit an iceberg in 1912.'),
  M('Which two factors brought the USA into the war in April 1917?', ['Unrestricted submarine warfare and the Zimmermann Telegram', 'The assassination of Franz Ferdinand and the Schlieffen Plan', 'The Christmas truce and the Somme', 'The Russian Revolution and Gallipoli'], 0, 'Germany resumed attacking all ships in British waters, and the Zimmermann Telegram revealed a German offer to help Mexico regain land from the USA.'),
  M('Why was the Treaty of Brest-Litovsk (March 1918) important?', ['Russia left the war, allowing Germany to move troops to the Western Front', 'It brought the USA into the war', 'It ended the war in the west', 'It gave Alsace-Lorraine back to France'], 0, 'After the Bolshevik revolution, Russia made peace and gave up huge territories. Germany used the extra troops for its Spring Offensive in 1918.'),
  M('What was the German Spring Offensive (March 1918)?', ['A major German attack that gained ground but exhausted the German army', 'An Allied attack at the Somme', 'A naval battle in the North Sea', 'The first use of gas'], 0, 'Ludendorff hoped to win before American troops arrived in large numbers. His forces advanced far but suffered heavy losses and outran their supplies.'),
  M('What happened in Germany in early November 1918?', ['Sailors mutinied at Kiel, revolution spread and the Kaiser abdicated', 'Germany won the war', 'Hitler became chancellor', 'The Kaiser declared war on the USA'], 0, 'Mutiny, strikes and hunger spread revolution. Wilhelm II abdicated on 9 November and the new government signed the armistice on 11 November.'),
  T('British Summer Time (putting the clocks forward) was first introduced during the First World War.', true, 'True. It was introduced in 1916 to give more daylight working hours and save fuel.'),
  MU('Which TWO were measures taken under the Defence of the Realm Act (DORA)?', ['Shorter pub opening hours and weaker beer', 'Censorship of newspapers', 'Giving all women the vote', 'Abolishing income tax', 'Creating the NHS'], [0, 1], 'DORA let the government control pubs, censor news and take over factories and land. Some women got the vote in 1918 through a separate Act; the NHS came in 1948.'),
  M('What was the government’s response to the ‘shell crisis’ of 1915?', ['It created a Ministry of Munitions under David Lloyd George', 'It ended the war', 'It banned the use of shells', 'It closed all factories'], 0, 'Reports of a shortage of shells led to the Ministry of Munitions, which greatly increased production, often using women workers.'),
  O('Put these events in chronological order.', ['Sinking of the Lusitania', 'First day of the Somme', 'The USA enters the war', 'Treaty of Brest-Litovsk', 'Armistice'], 'May 1915 Lusitania; July 1916 Somme; April 1917 USA; March 1918 Brest-Litovsk; November 1918 Armistice.'),
  W(src('Source A: a description of a British poster from 1915.', 'A ruined Belgian village burns in the background. In front, a German soldier with a cruel face stands over a frightened mother and child. The caption calls on British men to enlist.'), M('What was the main purpose of this poster?', ['To make people hate the enemy and persuade men to join up', 'To give accurate news of the fighting in Belgium', 'To encourage peace talks', 'To recruit women into the army'], 0, 'This is propaganda: it uses exaggerated stories of German atrocities to stir emotions and boost recruitment. It is useful as evidence of government methods, not of what happened in a particular village.')),
  S('Who became British Prime Minister in December 1916?', 'David Lloyd George', ['lloyd george', 'david lloyd-george', 'lloyd-george'], 'Lloyd George replaced Asquith and led a coalition government until 1922. He was seen as a dynamic war leader.', [['lloyd']]),
  T('An influenza pandemic in 1918–19 killed more people worldwide than the fighting of the First World War.', true, 'True. The ‘Spanish flu’ killed tens of millions around the world, more than the war’s military deaths, including over 200,000 in Britain.'),
]);
// =====================================================================
// YEAR 9 — The Second World War and the Holocaust
// =====================================================================
addTopic(
  { id: 'hist-y9-second-world-war', strand: 'hist-c20', year: 9, term: 2, name: 'The Second World War and the Holocaust',
    summary: 'The key turning points of the Second World War, life on the British Home Front, and the Holocaust.',
    specRef: 'DfE KS3 History: the Second World War and the wartime leadership of Winston Churchill; the Holocaust (statutory)' },
  [
    { name: 'The course of the war 1939–45', intro: "The war began when Germany invaded Poland in September 1939. Britain stood almost alone in 1940–41 before the USSR and USA joined, and the Allies won in 1945.",
      items: [
        M("Which event caused Britain and France to declare war on Germany in September 1939?", ["Germany's invasion of Poland", "The bombing of Pearl Harbor", "Germany's invasion of the USSR", "The Anschluss with Austria"], 0, "Germany invaded Poland on 1 September 1939; Britain declared war on 3 September. The Anschluss (1938) did not lead to war; Pearl Harbor and Barbarossa came in 1941."),
        S("What German word, meaning 'lightning war', describes fast attacks using tanks, aircraft and infantry together?", "Blitzkrieg", ["blitz krieg"], "Blitzkrieg brought quick victories over Poland (1939) and France (1940)."),
        M("What happened at Dunkirk in 1940?", ["Over 300,000 Allied soldiers were evacuated from France by sea", "Britain invaded Germany", "The RAF defeated the Luftwaffe", "Hitler signed a peace treaty"], 0, "Between 26 May and 4 June 1940, about 338,000 troops were rescued by naval and civilian 'little ships', though equipment was left behind."),
        S("Who became British Prime Minister in May 1940?", "Winston Churchill", ["churchill"], "Churchill replaced Neville Chamberlain on 10 May 1940, the day Germany attacked the Low Countries and France."),
        M("Why was the Battle of Britain (summer–autumn 1940) important?", ["The RAF's victory stopped a German invasion of Britain", "It ended the war", "Britain captured Berlin", "It brought the USA into the war"], 0, "Germany needed air superiority to invade (Operation Sealion). RAF Fighter Command, helped by radar, prevented this."),
        MU("Which TWO helped the RAF win the Battle of Britain?", ["Radar early-warning stations", "Spitfire and Hurricane fighters", "Atomic bombs", "American aircraft carriers in the Channel", "Tanks"], [0, 1], "Radar (the Chain Home system) and Spitfires and Hurricanes were key, along with Germany's switch to bombing cities."),
        M("What was Operation Barbarossa?", ["Germany's invasion of the Soviet Union in June 1941", "The D-Day landings", "The evacuation of children", "Japan's attack on Pearl Harbor"], 0, "Barbarossa began on 22 June 1941 — the largest invasion in history — opening the Eastern Front."),
        S("Which US naval base did Japan attack on 7 December 1941?", "Pearl Harbor", ["pearl harbour"], "The attack on Pearl Harbor in Hawaii brought the USA into the war."),
        M("Which battle (1942–43) is seen as the turning point on the Eastern Front?", ["Stalingrad", "El Alamein", "Midway", "Arnhem"], 0, "The German Sixth Army surrendered at Stalingrad in February 1943. El Alamein (1942) was a turning point in North Africa; Midway in the Pacific."),
        S("On what date did the D-Day landings take place? (day, month and year)", "6 June 1944", ["6th june 1944", "june 6 1944", "6 june 1944"], "On 6 June 1944 Allied forces landed on five beaches in Normandy (Operation Overlord)."),
        O("Put these events in chronological order.", ["Invasion of Poland", "Dunkirk evacuation", "Operation Barbarossa", "Pearl Harbor", "D-Day", "VE Day"], "September 1939; May–June 1940; June 1941; December 1941; June 1944; 8 May 1945."),
        M("What does VE Day (8 May 1945) mark?", ["Victory in Europe — Germany's surrender", "Victory over Japan", "The start of the Blitz", "The end of rationing"], 0, "Germany surrendered unconditionally; Japan surrendered in August 1945 (VJ Day)."),
        T("Atomic bombs were dropped on Hiroshima and Nagasaki in August 1945.", true, "True. The USA bombed Hiroshima (6 August) and Nagasaki (9 August); Japan announced its surrender on 15 August."),
        T("Britain declared war on Germany at the same time as the USA.", false, "False. Britain declared war in September 1939; the USA entered in December 1941 after Pearl Harbor (Germany then declared war on the USA)."),
        M("Who was the British Prime Minister who followed appeasement until 1939?", ["Neville Chamberlain", "Winston Churchill", "Clement Attlee", "David Lloyd George"], 0, "Chamberlain signed the Munich Agreement (1938). He declared war in September 1939 and resigned in May 1940."),
      ] },
    { name: 'The British Home Front', intro: "Civilians in Britain faced evacuation, bombing and rationing. The 'Blitz spirit' is a powerful memory, but historians also point to fear, looting and inequality.",
      items: [
        M("What was evacuation?", ["Moving children and vulnerable people from cities to the countryside for safety", "Sending soldiers to France", "Bombing German cities", "Moving the government to Canada"], 0, "Operation Pied Piper began on 1 September 1939; around 1.5 million people were moved in the first few days."),
        S("What name is given to the German bombing campaign on British cities from September 1940 to May 1941?", "The Blitz", ["blitz"], "The Blitz killed about 43,000 civilians. London was bombed for 57 nights in a row, and cities such as Coventry, Liverpool and Glasgow were badly hit."),
        M("Which city was devastated in a raid on 14 November 1940, destroying its cathedral?", ["Coventry", "Edinburgh", "Oxford", "Bath"], 0, "The Coventry raid killed over 500 people and destroyed the medieval cathedral."),
        M("When did food rationing begin in Britain?", ["January 1940", "September 1939", "June 1944", "1950"], 0, "Bacon, butter and sugar were rationed from 8 January 1940; rationing finally ended in 1954."),
        MU("Which TWO were common ways civilians sheltered during air raids?", ["Anderson shelters in gardens", "London Underground stations", "Castles", "Hot-air balloons", "Ships at sea"], [0, 1], "Anderson shelters, Morrison shelters (indoors) and Tube stations were used."),
        T("Evacuation was compulsory for all children.", false, "False. It was voluntary; many children returned home during the 'Phoney War' when bombing did not come."),
        M("What was the purpose of the blackout?", ["To make it harder for enemy bombers to find targets at night", "To save electricity for factories", "To stop people going out", "To hide soldiers"], 0, "All lights had to be hidden. Road accidents rose sharply in the dark."),
        S("What campaign slogan encouraged people to grow their own vegetables? (three words)", "Dig for Victory", ["dig for victory"], "Dig for Victory turned parks and gardens into allotments to reduce reliance on imports."),
        M("What did the Women's Land Army do?", ["Women worked on farms to grow food", "Women flew fighter planes in combat", "Women commanded infantry", "Women ran the government"], 0, "'Land Girls' replaced male farm workers. Women also worked in factories and served in the ATS, WAAF and WRNS."),
        M("Why might some historians question the 'Blitz spirit' interpretation?", ["There is evidence of fear, looting and some low morale as well as courage", "The Blitz never happened", "No one was hurt", "Everyone left Britain"], 0, "Morale held overall, but Mass Observation diaries and police records show fear, anger and crime too. Wartime propaganda emphasised unity."),
        W(src("Source A: a government poster, 1940, described.", "A smiling mother and children stand in a sunny country garden. The caption reads: 'Leave the children where they are — they are safer in the country.'"), M("What was the purpose of Source A?", ["To persuade parents not to bring evacuees home", "To recruit soldiers", "To advertise holidays", "To encourage rationing"], 0, "Many evacuees drifted home during the Phoney War. The government used posters to persuade parents to keep children in the countryside.")),
        T("Rationing was intended to share food fairly and was generally seen as fair by the public.", true, "True. Surveys suggest most people accepted rationing as fair, and some poorer families ate a more balanced diet than before the war."),
        O("Put these in chronological order.", ["Evacuation begins", "Rationing begins", "Battle of Britain", "Coventry raid", "V1 flying bombs hit London"], "September 1939; January 1940; July–October 1940; November 1940; June 1944."),
        S("What was the name of the volunteer force of older men and others not in the army, formed in 1940?", "Home Guard", ["the home guard", "local defence volunteers", "ldv"], "First called the Local Defence Volunteers, the Home Guard was formed to resist invasion."),
        M("What was a long-term effect of the war on Britain?", ["Support for the welfare state and the NHS (1948)", "Return of the feudal system", "Abolition of Parliament", "Britain joined the USSR"], 0, "Shared wartime sacrifice and the Beveridge Report (1942) helped Labour win in 1945 and create the welfare state."),
      ] },
    { name: 'The Holocaust', intro: "The Holocaust was the systematic, state-sponsored murder of around six million Jews by Nazi Germany and its collaborators. Persecution grew in stages from discrimination to genocide.",
      items: [
        M("Approximately how many Jewish people were murdered in the Holocaust?", ["Around 6 million", "Around 60,000", "Around 600,000", "Around 60 million"], 0, "About six million Jews — roughly two-thirds of Europe's Jewish population — were murdered."),
        S("What word means the deliberate attempt to destroy a whole national, ethnic or religious group?", "Genocide", [], "The term was coined in 1944 by lawyer Raphael Lemkin to describe Nazi crimes."),
        M("What were the Nuremberg Laws (1935)?", ["Laws that removed German citizenship from Jews and banned marriage between Jews and non-Jews", "Laws setting up the death camps", "Laws giving Jews equal rights", "Trials of Nazi leaders after the war"], 0, "The 1935 Nuremberg Laws took away citizenship and banned mixed marriages. The Nuremberg Trials (1945–46) were post-war trials — don't mix them up."),
        M("What happened on Kristallnacht (9–10 November 1938)?", ["Nazis attacked Jewish homes, shops and synagogues across Germany", "The war began", "Hitler became Chancellor", "Jews were given the vote"], 0, "The 'Night of Broken Glass': around 91 Jews were killed, synagogues burned, and about 30,000 Jewish men sent to concentration camps."),
        O("Put these stages of Nazi persecution in chronological order.", ["Boycott of Jewish shops", "Nuremberg Laws", "Kristallnacht", "Mass shootings by Einsatzgruppen in the USSR", "Wannsee Conference"], "April 1933; September 1935; November 1938; from June 1941; January 1942."),
        M("What were the Einsatzgruppen?", ["Mobile killing squads that shot Jews and others in occupied Eastern Europe", "Jewish resistance groups", "British spies", "German doctors"], 0, "Following the invasion of the USSR in 1941, they murdered over a million people, e.g. at Babi Yar (33,771 Jews in two days)."),
        S("At which 1942 conference did Nazi officials coordinate the 'Final Solution'?", "Wannsee", ["wannsee conference", "the wannsee conference"], "On 20 January 1942, at Wannsee near Berlin, officials planned the deportation and murder of Europe's Jews."),
        M("Which was the largest Nazi death camp, liberated by Soviet troops on 27 January 1945?", ["Auschwitz-Birkenau", "Dachau", "Bergen-Belsen", "Colditz"], 0, "About 1.1 million people were murdered at Auschwitz. 27 January is now Holocaust Memorial Day. British troops liberated Bergen-Belsen in April 1945."),
        MU("Which TWO other groups were also persecuted and murdered by the Nazis?", ["Roma and Sinti people", "Disabled people", "Members of the Nazi Party", "SS officers", "German generals"], [0, 1], "Roma and Sinti, disabled people (the T4 programme), Soviet prisoners of war, Poles, gay men and political opponents were also victims."),
        M("What were ghettos?", ["Closed-off areas of cities where Jews were forced to live in overcrowded conditions", "Holiday camps", "Army barracks", "Jewish schools"], 0, "The Warsaw ghetto held over 400,000 people; many died of starvation and disease before deportation to death camps."),
        T("Jewish people in the Warsaw ghetto staged an armed uprising in 1943.", true, "True. In April–May 1943 fighters resisted the Germans for about a month. Resistance also took the form of hiding, smuggling and preserving culture and records."),
        M("What was the Kindertransport (1938–39)?", ["A rescue that brought about 10,000 mainly Jewish children to Britain", "A Nazi deportation train", "A school trip", "A wartime evacuation in Britain"], 0, "After Kristallnacht, Britain admitted around 10,000 children without their parents; most never saw their families again."),
        S("Which teenage girl's diary, written while hiding in Amsterdam, became a famous record of the Holocaust?", "Anne Frank", ["anne", "frank"], "Anne Frank hid from 1942 to 1944; she died in Bergen-Belsen in early 1945. Her diary was published by her father, Otto."),
        T("The Holocaust happened suddenly in 1942 without any earlier persecution.", false, "False. It developed in stages from 1933: boycotts, laws, violence, ghettos, mass shootings and then death camps."),
        M("Why is it important to study the Holocaust?", ["To understand how prejudice and state power can lead to genocide, and to remember the victims", "Because it was a minor event", "Because it only affected Germany", "Because it has no lessons today"], 0, "Studying the Holocaust helps us recognise warning signs such as scapegoating and dehumanisation, and honours those who were murdered."),
      ] },
  ],
  {
    overview: "The Second World War (1939–45) was the deadliest conflict in history. Britain faced defeat in 1940 but survived through Dunkirk, the Battle of Britain and the Blitz; with the USSR and USA the Allies won in 1945. During the war the Nazis carried out the Holocaust, murdering around six million Jews.",
    objectives: ["I can explain the key turning points of the war.", "I can describe the British Home Front and evaluate the 'Blitz spirit'.", "I can explain how Nazi persecution escalated into genocide.", "I can use precise dates and terminology about the Holocaust."],
    keyWords: [
      { term: 'Blitzkrieg', def: 'Fast attack combining tanks, aircraft and infantry.' },
      { term: 'Evacuation', def: 'Moving people away from danger, e.g. children from cities.' },
      { term: 'The Blitz', def: 'German bombing of British cities, 1940–41.' },
      { term: 'Rationing', def: 'Limiting how much of certain goods each person can buy.' },
      { term: 'Antisemitism', def: 'Hostility to or prejudice against Jewish people.' },
      { term: 'Genocide', def: 'Deliberate destruction of a national, ethnic or religious group.' },
      { term: 'Ghetto', def: 'Closed area where Jews were forced to live.' },
      { term: 'Final Solution', def: 'Nazi term for the plan to murder all of Europe’s Jews.' },
    ],
    sections: [
      { title: 'Key turning points', html: timeline([["1 Sep 1939", "Germany invades Poland"], ["May–Jun 1940", "Fall of France; Dunkirk"], ["Jul–Oct 1940", "Battle of Britain"], ["Sep 1940–May 1941", "The Blitz"], ["22 Jun 1941", "Operation Barbarossa"], ["7 Dec 1941", "Pearl Harbor"], ["1942–43", "El Alamein; Stalingrad"], ["6 Jun 1944", "D-Day"], ["8 May 1945", "VE Day"], ["Aug 1945", "Atomic bombs; Japan surrenders"]]) },
      { title: 'The Home Front', html: "<p>Evacuation, the blackout, rationing, air-raid shelters and new work for women changed daily life. Propaganda celebrated the 'Blitz spirit'. Historians agree morale broadly held, but evidence also shows fear, exhaustion and crime.</p>" },
      { title: 'The Holocaust: from persecution to genocide', html: "<ol><li><b>1933–35:</b> boycotts; Jews removed from jobs; Nuremberg Laws.</li><li><b>1938:</b> Kristallnacht.</li><li><b>1939–41:</b> ghettos in occupied Poland.</li><li><b>1941:</b> Einsatzgruppen mass shootings in the USSR.</li><li><b>1942–45:</b> Wannsee Conference; death camps such as Auschwitz-Birkenau, Treblinka, Sobibor.</li></ol><div class=\"note\">Use precise, respectful language: victims were murdered, not 'died'.</div>" },
      { title: 'Model answer', html: worked("Explain why the Battle of Britain was a turning point. (8 marks)", ["State what was at stake (invasion).", "Explain why Britain won (radar, fighters, German switch to cities).", "Explain the consequence (Britain stays in the war as a base)."], "Model paragraph: The Battle of Britain was a turning point because it prevented a German invasion. Hitler's plan, Operation Sealion, needed control of the skies over the Channel. Using radar to spot incoming raids and Spitfires and Hurricanes to intercept them, Fighter Command inflicted heavy losses on the Luftwaffe. When Germany switched to bombing London in September 1940, the RAF airfields recovered. As a result Britain stayed in the war, and later served as the base for the D-Day invasion in 1944.") },
    ],
    mistakes: ["Confusing the Nuremberg Laws (1935) with the Nuremberg Trials (1945–46).", "Thinking the Holocaust began in 1942 without earlier stages.", "Saying the USA was in the war from 1939.", "Treating the 'Blitz spirit' as a simple fact rather than an interpretation."],
    examTips: ["For turning points, explain what changed before and after.", "Use precise dates to show chronological understanding.", "Evaluate wartime sources by considering propaganda and censorship."],
    realLife: "Holocaust Memorial Day (27 January) marks the liberation of Auschwitz.",
  },
);

// ---- extra practice: The Second World War and the Holocaust ----
more('hist-y9-second-world-war-1', [
  M('What was the ‘Phoney War’ (September 1939 – spring 1940)?', ['A period with little fighting in western Europe after war was declared', 'A war fought only with propaganda', 'A fake invasion of Britain', 'The war between Japan and China'], 0, 'After Poland fell, there was little land fighting in the west for months. It ended when Germany invaded Denmark and Norway (April 1940) and then France and the Low Countries (May 1940).'),
  M('What happened to France in June 1940?', ['It surrendered to Germany after a rapid Blitzkrieg campaign', 'It invaded Germany', 'It joined the Axis powers willingly in 1939', 'It stayed neutral'], 0, 'France fell in about six weeks. Northern France was occupied and the Vichy government in the south collaborated with Germany. Britain and its empire fought on alone.'),
  M('What was Operation Sea Lion?', ['Germany’s planned invasion of Britain in 1940', 'The D-Day landings', 'The evacuation from Dunkirk', 'The bombing of Dresden'], 0, 'Sea Lion needed German control of the air. The RAF’s victory in the Battle of Britain led Hitler to postpone it indefinitely. Dunkirk was Operation Dynamo; D-Day was Operation Overlord.'),
  M('What was the Battle of the Atlantic?', ['The long struggle to protect Allied supply convoys from German U-boats', 'A single day’s fighting near Iceland', 'A battle between the USA and Japan', 'The D-Day landings'], 0, 'It lasted the whole war. Britain depended on imported food and supplies; convoys, radar, air cover and code-breaking eventually defeated the U-boat threat by 1943.'),
  M('What was Lend-Lease (1941)?', ['A US scheme to supply Britain and its allies with war materials, to be paid for later', 'A British loan to Germany', 'An agreement to share Poland', 'A plan to evacuate children to America'], 0, 'Lend-Lease let the USA support Britain before joining the war in December 1941. Later it also supplied the USSR.'),
  M('Which British commander won the Second Battle of El Alamein in Egypt (1942)?', ['Bernard Montgomery', 'Douglas Haig', 'Erwin Rommel', 'Dwight Eisenhower'], 0, 'Montgomery defeated Rommel’s Afrika Korps. Churchill later said that before Alamein ‘we never had a victory’ and after it ‘we never had a defeat’. Haig commanded in the First World War.'),
  M('Which 1942 naval battle was the turning point of the war in the Pacific?', ['Midway', 'Jutland', 'Trafalgar', 'Pearl Harbor'], 0, 'At Midway in June 1942 the US Navy sank four Japanese aircraft carriers. Jutland (1916) and Trafalgar (1805) were earlier wars; Pearl Harbor was the attack that began the Pacific war.'),
  S('At which country house in Buckinghamshire did British code-breakers work on German Enigma messages?', 'Bletchley Park', ['bletchley'], 'Code-breakers at Bletchley Park, including Alan Turing, read many German messages. Their intelligence, called Ultra, helped especially in the Battle of the Atlantic.', [['bletchley']]),
  S('What was the codename for the Allied invasion of Normandy in 1944? (Operation …)', 'Overlord', ['operation overlord'], 'Operation Overlord was the overall invasion plan; the landings themselves on 6 June 1944 are known as D-Day.'),
  M('What was the Battle of the Bulge (December 1944)?', ['Germany’s last major offensive in the west, through the Ardennes', 'The D-Day landings', 'The Soviet capture of Berlin', 'A battle in North Africa'], 0, 'Germany attacked through the Ardennes and created a ‘bulge’ in the Allied line, but was pushed back by January 1945. It used up Germany’s last reserves.'),
  T('Hitler killed himself in his Berlin bunker on 30 April 1945 as Soviet troops approached.', true, 'True. Germany surrendered a week later, and VE Day was celebrated on 8 May 1945.'),
  M('When was the end of the war against Japan (VJ Day) celebrated in Britain?', ['15 August 1945', '8 May 1945', '11 November 1945', '6 June 1945'], 0, 'Japan announced its surrender on 15 August after the atomic bombs and the Soviet declaration of war; the formal surrender was signed on 2 September 1945.'),
  MU('Besides Churchill, which TWO leaders made up the Allied ‘Big Three’?', ['Franklin D. Roosevelt', 'Joseph Stalin', 'Charles de Gaulle', 'Benito Mussolini', 'Neville Chamberlain'], [0, 1], 'Churchill, Roosevelt (USA) and Stalin (USSR) met at Tehran (1943) and Yalta (1945). De Gaulle led the Free French; Mussolini was Hitler’s ally; Chamberlain resigned in 1940.'),
  O('Put these events in chronological order.', ['Germany invades Poland', 'Evacuation from Dunkirk', 'Japan attacks Pearl Harbor', 'Second Battle of El Alamein', 'Battle of the Bulge'], 'September 1939 Poland; May–June 1940 Dunkirk; December 1941 Pearl Harbor; October–November 1942 El Alamein; December 1944 the Bulge.'),
  M('Dunkirk is described by some as a ‘miracle’ and by others as a ‘disaster’. Which statement best supports the ‘disaster’ view?', ['The army left behind most of its tanks, guns and vehicles in France', 'Over 330,000 soldiers were rescued', 'Small civilian boats helped in the rescue', 'It boosted British morale'], 0, 'Rescuing over 330,000 men was remarkable, but Britain lost huge amounts of equipment and France was about to fall. Churchill warned that ‘wars are not won by evacuations’.'),
]);
more('hist-y9-second-world-war-2', [
  M('What was the name of the government’s plan to evacuate children from cities in September 1939?', ['Operation Pied Piper', 'Operation Overlord', 'Operation Dynamo', 'Operation Barbarossa'], 0, 'Operation Pied Piper moved about 1.5 million people, mostly children, in the first few days of September 1939. Dynamo was Dunkirk; Barbarossa was the invasion of the USSR.'),
  M('What was the difference between an Anderson shelter and a Morrison shelter?', ['Anderson shelters were dug into gardens; Morrison shelters were steel cages used indoors as tables', 'Anderson shelters were for the army only', 'Morrison shelters were underground railway stations', 'They were the same thing'], 0, 'Anderson shelters (from 1939) were curved metal sheets half-buried in the garden. Morrison shelters (1941) suited homes without gardens. Many Londoners also used Tube stations.'),
  M('What did ARP wardens do?', ['Enforced the blackout, helped people to shelters and reported bomb damage', 'Flew Spitfires', 'Ran the rationing system in shops', 'Guarded prisoners of war'], 0, 'Air Raid Precautions wardens were mostly part-time volunteers. They patrolled streets, shouted ‘Put that light out!’ and helped rescue people after raids.'),
  M('What change came in December 1941 for women in Britain?', ['Unmarried women aged 20–30 could be conscripted into war work or the services', 'All women were given the vote', 'Women were banned from factory work', 'Women were sent to fight on the front line'], 0, 'Britain was the first country to conscript women. They could choose the auxiliary services, civil defence or industry. Women had already gained equal voting rights in 1928.'),
  M('Who were the ‘Bevin Boys’?', ['Young men conscripted to work in coal mines instead of the armed forces', 'Child evacuees in Wales', 'RAF pilots in the Battle of Britain', 'Soldiers rescued at Dunkirk'], 0, 'Named after Ernest Bevin, Minister of Labour, they were chosen by ballot from 1943 to solve a shortage of miners. Coal was vital for the war economy.'),
  M('What new weapons hit south-east England from June 1944?', ['V-1 flying bombs and V-2 rockets', 'Zeppelin airships', 'Atomic bombs', 'Gotha bombers'], 0, 'Germany launched V-1s (‘doodlebugs’) and later V-2 rockets, which were too fast to intercept. Zeppelins and Gothas were used in the First World War.'),
  M('Which government department controlled propaganda and censorship in Britain during the war?', ['The Ministry of Information', 'The Ministry of Food', 'The Home Guard', 'The Treasury'], 0, 'The Ministry of Information produced posters and films and censored news to keep up morale. The Ministry of Food ran rationing.'),
  M('What did the Beveridge Report (1942) propose?', ['A welfare state to defeat the ‘five giants’ of want, disease, ignorance, squalor and idleness', 'A plan to invade France', 'Ending rationing immediately', 'Abolishing the House of Lords'], 0, 'The report was hugely popular and shaped the welfare reforms after 1945, including the NHS (1948).'),
  M('Approximately how many British civilians were killed in the Blitz (September 1940 – May 1941)?', ['About 43,000', 'About 430', 'About 4,300,000', 'About 430,000'], 0, 'Around 43,000 civilians died, nearly half of them in London, and over a million homes were damaged or destroyed.'),
  M('What was the ‘black market’ during the war?', ['Illegal buying and selling of rationed goods, often at high prices', 'A market run by the government for the poor', 'A shop selling blackout material', 'A place to buy war bonds'], 0, 'Dealers, sometimes called ‘spivs’, sold goods without coupons. It was illegal and undermined the fairness of rationing.'),
  S('In which year did all food rationing in Britain finally end?', '1954', [], 'Rationing continued after the war because of shortages and debt; some items, such as bread, were even rationed after 1945. It finally ended in July 1954.'),
  MU('Which TWO foods were rationed from January 1940?', ['Bacon', 'Sugar', 'Bread', 'Potatoes', 'Fish'], [0, 1], 'Bacon, butter and sugar were rationed first; meat and others followed. Bread and potatoes were not rationed during the war, and fish was never rationed, though it was often scarce.'),
  O('Put these events in chronological order.', ['First evacuation of children', 'Rationing begins', 'Battle of Britain', 'Coventry Blitz', 'Beveridge Report', 'First V-1 attacks'], 'September 1939 evacuation; January 1940 rationing; summer 1940 Battle of Britain; November 1940 Coventry; December 1942 Beveridge Report; June 1944 V-1s.'),
  W(src('Source A: a description of an official photograph released in 1940.', 'Smiling Londoners sit in an Underground station during an air raid, drinking tea and singing.'), M('Why should a historian be careful using Source A as evidence of how people felt during the Blitz?', ['It was an official photo approved by censors to keep morale high', 'Photographs did not exist in 1940', 'It shows a different war', 'It was taken by German propaganda'], 0, 'The government wanted to show the ‘Blitz spirit’, so cheerful images were chosen and fear or panic was hidden. The photo is useful for showing propaganda aims, but may not be typical.')),
  T('Many evacuated children returned home during the ‘Phoney War’ when the expected bombing did not come.', true, 'True. By January 1940 a large proportion had gone home. A second wave of evacuation followed when the Blitz began in September 1940.'),
  M('What was the result of the 1945 general election?', ['A Labour landslide, with Clement Attlee as Prime Minister', 'A Conservative victory for Churchill', 'A hung parliament', 'No election was held'], 0, 'Voters wanted the reforms promised in the Beveridge Report. Attlee’s government created the NHS and expanded the welfare state, despite Churchill’s wartime popularity.'),
]);
more('hist-y9-second-world-war-3', [
  M('What happened on 1 April 1933 in Germany?', ['The Nazis organised a boycott of Jewish shops and businesses', 'The Nuremberg Laws were passed', 'Kristallnacht took place', 'The Wannsee Conference met'], 0, 'SA men stood outside Jewish-owned shops to stop customers entering. It was one of the first official acts of persecution, two months after Hitler became Chancellor.'),
  S('What word means hostility to, or prejudice against, Jewish people?', 'Antisemitism', ['anti-semitism', 'anti semitism', 'antisemitic'], 'Antisemitism had a long history in Europe, but the Nazis made it state policy, leading from discrimination to genocide.', [['antisemit', 'anti-semit', 'antisemitism', 'semitism']]),
  MU('Which TWO were Nazi death camps in occupied Poland, built mainly to murder Jewish people?', ['Treblinka', 'Sobibor', 'Dachau', 'Colditz', 'Bergen-Belsen'], [0, 1], 'Treblinka, Sobibor and Belzec were built for mass murder. Dachau and Bergen-Belsen were concentration camps in Germany where many died; Colditz was a prisoner-of-war camp.'),
  M('Which was the first Nazi concentration camp, opened in March 1933?', ['Dachau', 'Auschwitz', 'Treblinka', 'Sobibor'], 0, 'Dachau, near Munich, first held political opponents such as communists. Auschwitz and the death camps came after the war began.'),
  M('Which camp was liberated by British troops in April 1945, revealing thousands of unburied bodies?', ['Bergen-Belsen', 'Auschwitz', 'Treblinka', 'Dachau'], 0, 'British soldiers found around 60,000 starving prisoners and thousands of dead at Belsen. Film and reports shocked the British public. Auschwitz was liberated by the Soviets.'),
  M('What were the Nuremberg Trials (1945–46)?', ['Trials of leading Nazis for war crimes and crimes against humanity', 'The trials of Jewish people under the Nuremberg Laws', 'Sporting events at the Nazi rallies', 'Trials of Allied leaders'], 0, 'An international tribunal tried senior Nazis; 12 were sentenced to death. This established that following orders was no defence for crimes against humanity.'),
  M('What does the title ‘Righteous Among the Nations’ honour?', ['Non-Jewish people who risked their lives to save Jews during the Holocaust', 'Allied generals', 'Nazi officials who changed sides', 'Countries that stayed neutral'], 0, 'Israel’s Holocaust memorial, Yad Vashem, gives this title to rescuers such as Oskar Schindler. They show that individuals could choose to help.'),
  M('Which British stockbroker organised trains that brought 669 mainly Jewish children from Czechoslovakia to Britain in 1939?', ['Nicholas Winton', 'Winston Churchill', 'Neville Chamberlain', 'Alan Turing'], 0, 'Winton’s work was little known until 1988. It was part of the wider Kindertransport, which brought about 10,000 children to Britain.'),
  M('What did the Nazis mean by the ‘Final Solution’?', ['The plan to murder all the Jews of Europe', 'Their plan to end the war with Britain', 'A peace treaty with the USSR', 'The emigration of all Germans to America'], 0, '‘Final Solution to the Jewish Question’ was a euphemism (a mild-sounding phrase hiding something terrible) for genocide, coordinated at Wannsee in January 1942.'),
  M('What were the ‘death marches’ of 1944–45?', ['Forced marches of camp prisoners away from advancing Allied armies, in which many died', 'Military parades in Berlin', 'Marches by Allied soldiers to Berlin', 'Protests against the war in Britain'], 0, 'As the Soviets advanced, the SS forced prisoners to march long distances in winter with little food. Those who fell behind were often shot.'),
  T('Prisoners staged an uprising and mass escape at the Sobibor death camp in October 1943.', true, 'True. About 300 prisoners escaped, though many were caught and killed. Resistance also took place at Treblinka, Auschwitz and in ghettos such as Warsaw.'),
  O('Put these events in chronological order.', ['Hitler becomes Chancellor', 'Boycott of Jewish shops', 'Nuremberg Laws', 'Kristallnacht', 'Mass shootings by Einsatzgruppen in the USSR', 'Wannsee Conference'], 'January 1933 Hitler; April 1933 boycott; 1935 Nuremberg Laws; November 1938 Kristallnacht; from June 1941 mass shootings; January 1942 Wannsee.'),
  M('Who first created the word ‘genocide’, in 1944?', ['Raphael Lemkin, a Polish-Jewish lawyer', 'Winston Churchill', 'Anne Frank', 'Adolf Hitler'], 0, 'Lemkin combined the Greek ‘genos’ (people or race) and Latin ‘cide’ (killing). Genocide was made a crime under international law in 1948.'),
  M('Why is Holocaust Memorial Day held on 27 January?', ['It is the anniversary of the liberation of Auschwitz-Birkenau in 1945', 'It is the date of Kristallnacht', 'It is Hitler’s birthday', 'It is the date of the Wannsee Conference'], 0, 'Soviet troops liberated Auschwitz on 27 January 1945. The day remembers the victims of the Holocaust and of later genocides.'),
  M('Why is survivor testimony important evidence about the Holocaust?', ['It gives first-hand accounts of experiences the Nazis tried to hide', 'It is the only evidence that exists', 'It was written by the Nazis', 'Survivors never disagree on details'], 0, 'The Nazis destroyed many records, so testimony is vital. Historians use it alongside Nazi documents, photographs and physical evidence; memories may differ on details but together they build a full picture.'),
]);
// =====================================================================
// YEAR 10 — Germany 1890–1929: Kaiser and Weimar democracy
// =====================================================================
addTopic(
  { id: 'hist-y10-germany-weimar', strand: 'hist-germany', year: 10, term: 1, name: 'Germany 1890–1929: Kaiser and Weimar Democracy',
    summary: 'Kaiser Wilhelm II’s Germany, the impact of the First World War, the birth of the Weimar Republic, its crises of 1919–23 and recovery under Stresemann.',
    specRef: 'AQA 8145 1A Germany, 1890–1945: Part one — Germany and the growth of democracy' },
  [
    { name: 'Kaiser Wilhelm II and the Second Reich', intro: "Germany was united in 1871. Under Kaiser Wilhelm II (1888–1918) it industrialised rapidly, built a navy to rival Britain's and faced growing demands for democracy from the socialists.",
      items: [
        M("Which powerful Chancellor did Wilhelm II force to resign in 1890?", ["Otto von Bismarck", "Gustav Stresemann", "Alfred von Tirpitz", "Friedrich Ebert"], 0, "Bismarck had dominated German politics since 1862. Wilhelm wanted to rule personally, so he forced him out in 1890."),
        M("How much power did the Reichstag have under the Kaiser?", ["It could pass or reject laws and the budget, but the Kaiser appointed the Chancellor and controlled the army and foreign policy", "It chose the Kaiser", "It had no elected members", "It controlled the army"], 0, "The Reichstag was elected by men over 25 but the Kaiser appointed and dismissed the Chancellor, who did not need the Reichstag's support. It was a limited democracy."),
        S("Which German state, with a strong military tradition, dominated the Second Reich?", "Prussia", ["prussian"], "Prussia was the largest state; its king was the Kaiser and its army officers had huge influence. This is called Prussian militarism."),
        M("Which party had become the largest in the Reichstag by 1912?", ["The SPD (Social Democrats)", "The Nazi Party", "The Communist Party (KPD)", "The Conservatives"], 0, "The SPD won 110 seats in 1912, worrying the Kaiser, who feared socialism. The Nazis and KPD did not yet exist."),
        S("What was the name of Wilhelm II's policy of making Germany a world power with colonies and a navy (German word)?", "Weltpolitik", ["welt politik"], "Weltpolitik ('world policy') from 1897 aimed for an empire and a 'place in the sun'."),
        M("Who was the admiral behind the Navy Laws of 1898 and 1900?", ["Alfred von Tirpitz", "Paul von Hindenburg", "Erich Ludendorff", "Kurt Eisner"], 0, "Tirpitz planned a battle fleet to challenge Britain. The Navy Laws were funded by taxes and popular with nationalists."),
        MU("Which TWO were effects of rapid industrialisation in Germany before 1914?", ["The growth of a large industrial working class", "Increased support for socialism", "A return to farming", "A fall in coal output", "The abolition of the Reichstag"], [0, 1], "Industry grew dramatically (by 1914 Germany produced more steel than Britain). Workers in cities supported trade unions and the SPD."),
        T("Wilhelm II introduced some social reforms partly to reduce support for socialism.", true, "True. Building on Bismarck's insurance schemes, laws such as the 1891 Workers' Protection Act limited working hours, aiming to win workers away from the SPD."),
        M("What did the Zabern Affair (1913) reveal?", ["The army could act above the law with the Kaiser's support, despite Reichstag protests", "The navy had mutinied", "Germany was a full democracy", "The SPD had taken power"], 0, "Soldiers mistreated civilians in Alsace; the Reichstag passed a vote of no confidence but the Chancellor stayed because the Kaiser backed him."),
        W(src("Source A: a German cartoon published in a satirical magazine, 1890, described.", "The Kaiser, wearing a huge plumed helmet, stands on the deck of a small boat. An old pilot, Bismarck, is walking down the gangway. The caption reads 'Dropping the Pilot'."), M("What is the message of Source A?", ["Wilhelm II was getting rid of an experienced leader and would now steer Germany himself", "Bismarck was sailing to war", "Wilhelm was leaving Germany", "The navy was being built"], 0, "The 'pilot' is Bismarck, who had guided Germany; the cartoon suggests Wilhelm was taking personal control — a risky move.")),
        M("Which statement best describes Wilhelm II's personality, according to most historians?", ["Impulsive and keen on military display", "Calm and cautious", "Uninterested in the army", "Committed to full democracy"], 0, "Wilhelm loved uniforms and military parades and made impulsive statements (e.g. the Daily Telegraph interview, 1908)."),
        O("Put these in chronological order.", ["German unification", "Wilhelm II becomes Kaiser", "Bismarck resigns", "First Navy Law", "Zabern Affair"], "1871; 1888; 1890; 1898; 1913."),
        S("What title was given to the head of the German government appointed by the Kaiser?", "Chancellor", ["the chancellor", "reich chancellor"], "The Chancellor was appointed by and answerable to the Kaiser, not the Reichstag."),
        T("By 1914 Germany was the most democratic state in Europe.", false, "False. Germany had universal male suffrage for the Reichstag, but real power lay with the Kaiser, the army and the Prussian elite."),
        M("Why did the SPD's growth create a problem for the Kaiser?", ["It wanted greater democracy and social reform, which threatened the power of the Kaiser and elites", "It wanted to restore Bismarck", "It wanted Germany to give up its army", "It supported the Kaiser's naval plans"], 0, "The SPD challenged autocracy. This tension between autocracy and democracy is a key theme of this period."),
      ] },
    { name: 'War, revolution and the Weimar Republic', intro: "Defeat in 1918 brought revolution, the Kaiser's abdication and a new democratic republic. The Treaty of Versailles and the new constitution created lasting problems.",
      items: [
        M("What happened to Kaiser Wilhelm II on 9 November 1918?", ["He abdicated and fled to the Netherlands", "He was executed", "He became President", "He signed the Treaty of Versailles"], 0, "Faced with mutiny and revolution, Wilhelm abdicated and went into exile in the Netherlands, where he died in 1941."),
        S("Who was the SPD leader who became the first President of the Weimar Republic?", "Friedrich Ebert", ["ebert"], "Ebert led the new government from November 1918 and was President from 1919 until his death in 1925."),
        M("Why was the new republic named after the town of Weimar?", ["The National Assembly met there because Berlin was too dangerous in early 1919", "It was Hitler's birthplace", "The Kaiser lived there", "It was the capital of Prussia"], 0, "The Spartacist uprising made Berlin unsafe, so the Assembly met in Weimar in February 1919."),
        M("What was proportional representation (PR)?", ["A voting system giving parties seats in proportion to their votes", "A system where only one party could stand", "Voting only for men over 30", "Rule by the President alone"], 0, "PR was fair but led to many small parties and coalition governments that were often weak."),
        S("Which article of the Weimar Constitution let the President rule by decree in an emergency?", "Article 48", ["48", "article forty eight"], "Article 48 was a weakness: later Presidents used it to bypass the Reichstag, and Hitler exploited it in 1933."),
        MU("Which TWO were weaknesses of the Weimar Constitution?", ["Proportional representation led to unstable coalitions", "Article 48 allowed rule by decree", "Women could vote", "It had a bill of rights", "Elections were held regularly"], [0, 1], "Votes for women over 20 and rights for citizens were strengths. PR and Article 48 created instability and a route to dictatorship."),
        S("On what date was the Treaty of Versailles signed? (day, month, year)", "28 June 1919", ["28th june 1919", "june 28 1919"], "It was signed in the Hall of Mirrors at Versailles on 28 June 1919, exactly five years after the Sarajevo assassination."),
        M("What did Article 231 of the Treaty of Versailles say?", ["Germany accepted blame for causing the war", "Germany must pay £6.6 billion", "The Rhineland was demilitarised", "Germany's army was limited to 100,000"], 0, "Article 231, the 'war guilt clause', justified reparations. It caused deep resentment."),
        MU("Which TWO military terms were imposed on Germany by the Treaty of Versailles?", ["Army limited to 100,000 men", "No air force", "Navy limited to 50 battleships", "Conscription made compulsory", "The Rhineland occupied permanently by Germany's army"], [0, 1], "Germany was limited to 100,000 men, no conscription, no air force, six battleships and no submarines; the Rhineland was demilitarised."),
        M("Why did many Germans call the treaty a 'Diktat'?", ["It was a dictated peace — Germany was not allowed to negotiate", "It was written in German", "It was signed by a dictator", "It gave Germany new land"], 0, "Germany was excluded from the negotiations and forced to sign or face invasion."),
        S("What were the people who signed the armistice and treaty called by nationalists? (two words)", "November Criminals", ["november criminal", "the november criminals"], "Nationalists blamed Weimar politicians for 'stabbing the army in the back', calling them the November Criminals."),
        T("Germany lost about 13% of its European territory under the Treaty of Versailles.", true, "True. Losses included Alsace-Lorraine to France and West Prussia (the 'Polish Corridor') to Poland; all colonies were lost too."),
        O("Put these events in chronological order.", ["Kiel naval mutiny", "Kaiser abdicates", "Armistice", "Spartacist uprising", "Treaty of Versailles signed"], "Late Oct–early Nov 1918; 9 Nov 1918; 11 Nov 1918; January 1919; 28 June 1919."),
        W(src("Source B: a German newspaper, Deutsche Zeitung, 28 June 1919.", "Vengeance, German nation! Today in the Hall of Mirrors the disgraceful treaty is being signed. Do not forget it! The German people will push forward to regain their place among nations."), M("How useful is Source B for understanding German reactions to Versailles?", ["Very useful for showing nationalist anger, though it is one newspaper's view written on the day of signing", "Useless, because it is biased", "Useful only for the military terms", "It proves every German agreed"], 0, "Its content (calls for vengeance) and provenance (a nationalist paper on the day of signing) show strong anger. Its bias is what makes it useful for nationalist opinion — but it does not prove every German felt the same.")),
        M("What was a strength of the Weimar Constitution?", ["All men and women over 20 could vote", "The President had no powers", "Only one party was allowed", "The Kaiser kept his throne"], 0, "Weimar was one of the most democratic systems in the world, with votes for women and guaranteed civil rights."),
      ] },
    { name: 'Crises of 1919–1923', intro: "The young republic faced attacks from the left and right, the French occupation of the Ruhr and hyperinflation. It survived, but the crises left lasting bitterness.",
      items: [
        M("Who led the Spartacist uprising of January 1919?", ["Rosa Luxemburg and Karl Liebknecht", "Adolf Hitler and Ernst Röhm", "Wolfgang Kapp", "Gustav Stresemann"], 0, "The Spartacists were communists. The government used the Freikorps to crush them; Luxemburg and Liebknecht were murdered."),
        S("What were the right-wing volunteer units of ex-soldiers used to crush the Spartacists called?", "Freikorps", ["freikorp", "free corps"], "The Freikorps were nationalist and anti-communist; some later joined the Kapp Putsch against the government itself."),
        M("How was the Kapp Putsch (March 1920) defeated?", ["A general strike by workers paralysed Berlin", "The army attacked the rebels", "Britain invaded", "Hitler stopped it"], 0, "The army refused to fire on the Freikorps, but trade unions called a general strike; Kapp fled after four days."),
        M("Why did France and Belgium occupy the Ruhr in January 1923?", ["Germany had failed to pay reparations", "Germany had invaded France", "The Kaiser had returned", "The League of Nations ordered it"], 0, "Germany defaulted on reparations, so France and Belgium seized the industrial Ruhr to take coal and goods."),
        M("What was the German government's response to the Ruhr occupation?", ["It ordered passive resistance and printed money to pay striking workers", "It declared war on France", "It paid all reparations immediately", "It invited the British to help"], 0, "Workers went on strike; the government printed money to pay them, which fuelled hyperinflation."),
        S("What word describes extremely rapid price rises, like those in Germany in 1923?", "Hyperinflation", ["hyper inflation"], "By November 1923 a loaf of bread cost around 200 billion marks and one US dollar was worth over 4 trillion marks."),
        MU("Which TWO groups were hit hardest by hyperinflation?", ["People with savings", "People on fixed incomes such as pensioners", "People with large debts", "Owners of land and property", "Foreigners with dollars"], [0, 1], "Savings became worthless and fixed pensions bought nothing. Debtors could pay off loans easily, and those with land or foreign currency did relatively well."),
        T("Hyperinflation helped some Germans, such as those who had borrowed money.", true, "True. Debts became easy to repay; some businessmen bought up property cheaply. Not everyone suffered equally."),
        M("What happened in the Munich Putsch of November 1923?", ["Hitler and the Nazis tried to seize power in Bavaria but were stopped by police", "The Kaiser returned", "The communists took Berlin", "Stresemann was assassinated"], 0, "On 8–9 November Hitler declared a revolution in a Munich beer hall; the next day police fired on marchers and 16 Nazis were killed."),
        M("What were the consequences of the Munich Putsch for Hitler?", ["He was sentenced to five years but served only about nine months, and wrote Mein Kampf", "He was executed", "He became Chancellor", "He was deported to Austria"], 0, "The lenient trial gave him national publicity. In prison he wrote Mein Kampf and decided to win power through elections."),
        O("Put these crises in chronological order.", ["Spartacist uprising", "Kapp Putsch", "Reparations figure set at £6.6 billion", "French occupation of the Ruhr", "Munich Putsch"], "January 1919; March 1920; 1921; January 1923; November 1923."),
        W(src("Source C: a photograph from 1923, described.", "A woman is feeding banknotes into a kitchen stove. The caption explains that money was cheaper to burn than firewood."), M("What does Source C show about hyperinflation?", ["Money had lost almost all its value", "People were rich", "Germany had too much firewood", "Banks were refusing to print money"], 0, "Burning banknotes as fuel shows they were worth less than wood. Photographs like this are vivid but may be staged, so check provenance.")),
        M("Why did the political murders of 1919–22 weaken Weimar?", ["Right-wing judges often gave the killers light sentences, showing the judiciary did not support the republic", "The killers were all communists who were executed", "No one was killed", "Ebert ordered them"], 0, "Over 350 political murders, such as of Walther Rathenau in 1922, were mostly by the right; many judges were sympathetic to nationalists."),
        T("The Weimar Republic collapsed in 1923.", false, "False. It survived the crises of 1919–23, and under Stresemann entered a period of recovery from 1924."),
        S("Which Jewish Foreign Minister was assassinated by right-wing extremists in 1922?", "Walther Rathenau", ["rathenau"], "Rathenau's murder caused outrage and a wave of protest, but showed the threat from the extreme right."),
      ] },
    { name: 'Stresemann and the Golden Years 1924–29', intro: "Gustav Stresemann ended hyperinflation, secured American loans and restored Germany's international standing. But the recovery depended heavily on US money.",
      items: [
        M("Which new currency did Stresemann introduce in November 1923 to end hyperinflation?", ["The Rentenmark", "The euro", "The Deutschmark", "The thaler"], 0, "The Rentenmark was backed by land and industrial assets; it was replaced by the Reichsmark in 1924. The Deutschmark came after 1948."),
        S("Which 1924 plan reorganised reparations payments and arranged American loans?", "Dawes Plan", ["dawes", "the dawes plan"], "The Dawes Plan reduced annual payments and provided 800 million gold marks in US loans to rebuild industry."),
        M("What did the Young Plan (1929) do?", ["Reduced the total reparations bill and gave Germany 59 years to pay", "Cancelled all reparations", "Set up the Rentenmark", "Ended the Ruhr occupation"], 0, "The Young Plan cut the bill to about £2 billion over 59 years. Nationalists, including Hitler, campaigned against it."),
        M("What did Germany agree in the Locarno Treaties (1925)?", ["To accept its western borders with France and Belgium", "To give up the Rhineland to France", "To leave the League of Nations", "To rebuild its navy"], 0, "Locarno improved relations; in return Germany was accepted as an equal and joined the League of Nations in 1926."),
        S("In which year did Germany join the League of Nations?", "1926", [], "Germany joined in 1926 with a permanent seat on the Council — a sign of restored status."),
        T("Stresemann was awarded the Nobel Peace Prize.", true, "True. He shared the 1926 prize with France's Aristide Briand for the Locarno agreements."),
        MU("Which TWO were achievements of the 'Golden Years'?", ["Stable currency and rising industrial production", "Flourishing culture such as the Bauhaus and cinema", "Ending all unemployment", "Abolishing reparations entirely", "A one-party state"], [0, 1], "The economy stabilised and culture flourished. However unemployment never fell below about 1.3 million and reparations continued."),
        M("Why is the recovery sometimes described as 'dancing on a volcano'?", ["It depended on short-term American loans that could be recalled", "Germany had active volcanoes", "Stresemann loved dancing", "Extremist parties were banned"], 0, "Stresemann himself warned that Germany's prosperity rested on borrowed US money; when the Wall Street Crash came in 1929, the loans were recalled."),
        M("What was the Bauhaus?", ["A school of art and design founded by Walter Gropius in 1919", "A Nazi youth group", "A German warship", "A bank"], 0, "The Bauhaus mixed art, craft and modern technology. Conservatives and the Nazis disliked such modern culture."),
        M("Which of these suggests the Golden Years were NOT golden for everyone?", ["Farmers faced falling prices and many lived in poverty", "The Rentenmark was stable", "Germany joined the League", "Wages rose for many industrial workers"], 0, "Agriculture was depressed throughout the 1920s; the middle classes who lost savings in 1923 never recovered."),
        S("Who was elected President in 1925 after Ebert's death?", "Paul von Hindenburg", ["hindenburg", "von hindenburg"], "Hindenburg, a wartime field marshal and monarchist, was elected in 1925 — a sign that many Germans still admired the old order."),
        O("Put these in chronological order.", ["Rentenmark introduced", "Dawes Plan", "Locarno Treaties", "Germany joins the League", "Death of Stresemann"], "November 1923; 1924; 1925; 1926; October 1929."),
        W(src("Interpretation A: a historian writing in 2010.", "The Stresemann years were a period of genuine recovery. Germany's economy grew, its culture was the envy of Europe and it regained its place among the great powers."), M("Which knowledge best SUPPORTS Interpretation A?", ["Germany joined the League of Nations in 1926 and industrial production regained pre-war levels by 1928", "Unemployment never fell below 1.3 million", "The Nazis won 2.6% of the vote in 1928", "Farmers' incomes fell"], 0, "League membership and production recovering support 'genuine recovery'. The unemployment and farming points challenge it. (The Nazis' small 1928 vote suggests stability, but option A is the most direct support.)")),
        T("In the 1928 election the Nazis won only 12 seats.", true, "True. The Nazis won 2.6% of the vote and 12 seats, showing how little support extremists had during the Golden Years."),
        M("How convincing is the view that Stresemann's recovery was 'built on sand'? Which evidence supports it?", ["Dependence on US loans that were withdrawn after the 1929 Wall Street Crash", "Germany joined the League", "The Bauhaus flourished", "Hyperinflation ended"], 0, "Dependence on foreign loans meant the recovery collapsed quickly after 1929. The other options are evidence of genuine achievement."),
      ] },
  ],
  {
    overview: "Between 1890 and 1929 Germany moved from the autocratic rule of Kaiser Wilhelm II to the democratic Weimar Republic. Defeat in 1918, the Treaty of Versailles and the crises of 1919–23 shook the new republic, but Stresemann's policies brought recovery — a recovery that rested on American loans.",
    objectives: ["I can explain the tensions between autocracy and democracy in Kaiser Wilhelm's Germany.", "I can explain the strengths and weaknesses of the Weimar Constitution.", "I can explain the impact of the Treaty of Versailles on Germany.", "I can describe and explain the crises of 1919–23.", "I can judge how far Germany recovered under Stresemann."],
    keyWords: [
      { term: 'Kaiser', def: 'German emperor.' },
      { term: 'Reichstag', def: 'German parliament.' },
      { term: 'Weltpolitik', def: 'Wilhelm II’s policy of making Germany a world power.' },
      { term: 'Proportional representation', def: 'Seats shared according to the percentage of votes.' },
      { term: 'Article 48', def: 'Emergency power for the President to rule by decree.' },
      { term: 'Diktat', def: 'Dictated peace — how Germans described Versailles.' },
      { term: 'Putsch', def: 'An attempt to seize power by force.' },
      { term: 'Hyperinflation', def: 'Extremely rapid price rises; money becomes worthless.' },
      { term: 'Reparations', def: 'Compensation Germany had to pay for war damage.' },
    ],
    sections: [
      { title: 'Kaiser Wilhelm II’s Germany', html: "<p>Wilhelm II ruled as an autocrat, appointing the Chancellor himself. Rapid <b>industrialisation</b> created a big working class that supported the <b>SPD</b>, the largest party by 1912. Wilhelm pursued <b>Weltpolitik</b> and Tirpitz's <b>Navy Laws</b> (1898, 1900), which were popular with nationalists but cost money and alarmed Britain.</p><div class=\"rule\">Key theme: tension between the Kaiser's autocracy and growing demands for democracy.</div>" },
      { title: 'Revolution, Weimar and Versailles', html: "<p>By autumn 1918 Germany faced defeat, food shortages and naval mutiny. The Kaiser abdicated on 9 November; the armistice followed on 11 November. The new <b>Weimar Constitution</b> (1919) gave votes to men and women over 20 but used <b>PR</b> and <b>Article 48</b>. The <b>Treaty of Versailles</b> imposed war guilt, reparations (£6.6 billion), territorial losses and military limits.</p>" },
      { title: 'Key dates', html: timeline([["1888", "Wilhelm II becomes Kaiser"], ["1890", "Bismarck dismissed"], ["1898/1900", "Navy Laws"], ["9 Nov 1918", "Kaiser abdicates; republic declared"], ["Jan 1919", "Spartacist uprising"], ["28 Jun 1919", "Treaty of Versailles"], ["Mar 1920", "Kapp Putsch"], ["Jan 1923", "Ruhr occupied; hyperinflation"], ["Nov 1923", "Munich Putsch; Rentenmark"], ["1924", "Dawes Plan"], ["1925–26", "Locarno; Germany joins League"], ["1929", "Young Plan; Stresemann dies; Wall Street Crash"]]) + people([["Wilhelm II", "Kaiser 1888–1918; Weltpolitik; abdicated 1918."], ["Friedrich Ebert", "SPD leader; first President 1919–25."], ["Gustav Stresemann", "Chancellor 1923, Foreign Minister 1923–29."], ["Rosa Luxemburg", "Spartacist leader murdered in 1919."]]) },
      { title: 'Model answer: source utility (AQA Q2)', html: worked("How useful is Source B (the Deutsche Zeitung, 28 June 1919) to a historian studying German reactions to the Treaty of Versailles? (8 marks)", ["Content: what does it say? Link to own knowledge.", "Provenance: nationalist newspaper; written on the day of signing — purpose to stir anger.", "Judgement: useful for nationalist reaction; limited for all Germans."], "Model paragraph: Source B is useful because its content shows the fury many Germans felt, calling the treaty 'disgraceful' and urging 'vengeance'. This fits my knowledge that Germans saw the treaty as a Diktat, resenting Article 231's war guilt and the £6.6 billion of reparations. Its provenance adds to its usefulness: it was published on the day the treaty was signed, so it captures immediate reaction, and as a nationalist paper it was written to stir readers' anger. This purpose means it is especially useful for showing how nationalists used the treaty to attack the new republic, although it may not represent the views of all Germans.") },
    ],
    mistakes: ["Saying Germany was a democracy under the Kaiser — the Reichstag's powers were limited.", "Blaming hyperinflation only on reparations — the Ruhr occupation and printing money were key.", "Mixing up the Kapp Putsch (1920) and the Munich Putsch (1923).", "Writing that the Golden Years solved all problems."],
    examTips: ["AQA Paper 1 Section A: Q1–3 use two interpretations (how they differ, why they differ, which is more convincing); Q4 'Describe two…'; Q5 'In what ways…'; Q6 'Which of the following was the more important reason…' (12 marks).", "In utility answers, make provenance work: explain HOW the author, date and purpose affect usefulness.", "Use specific figures (£6.6 billion; 100,000 men; 4.2 trillion marks to the dollar) as evidence."],
    realLife: "Germany's modern constitution (1949) deliberately removed Weimar's weaknesses, such as the President's emergency powers.",
  },
);

// ---- extra practice: Germany 1890–1929 ----
more('hist-y10-germany-weimar-1', [
  S('In which year was Germany unified as a single empire (the Second Reich)?', '1871', [], 'Germany was unified in 1871 after Prussia’s victory over France, with the King of Prussia becoming German Kaiser. Wilhelm II inherited this system in 1888.'),
  M('What was the Bundesrat in the Second Reich?', ['A federal council of representatives from the German states, dominated by Prussia', 'The elected lower house chosen by all men over 25', 'The Kaiser’s private army', 'The supreme court'], 0, 'The Bundesrat represented the states and had to agree to new laws. Prussia had enough votes to block changes. The elected chamber was the Reichstag.'),
  M('Who were the Junkers?', ['Prussian landowning aristocrats who dominated the army and government', 'Factory workers in the Ruhr', 'Members of the SPD', 'Navy officers who mutinied in 1918'], 0, 'The Junkers were conservative nobles from eastern Prussia. They filled many top army and civil service posts and opposed democracy and socialism.'),
  M('In which year did Wilhelm II become Kaiser?', ['1888', '1871', '1890', '1914'], 0, 'Wilhelm II became Kaiser in 1888, aged 29. 1871 was unification; in 1890 he forced Bismarck to resign.'),
  T('Kaiser Wilhelm II had a damaged left arm from birth, which some historians think affected his personality.', true, 'True. His withered arm resulted from a difficult birth. Some historians link it to his need to appear strong and military, though this is debated.'),
  M('What was the Navy League?', ['A popular pressure group that campaigned for a bigger German navy', 'A naval alliance with Britain', 'A group of sailors who mutinied', 'The Kaiser’s personal yacht club'], 0, 'Founded in 1898, the Navy League grew to over a million members (including affiliated groups) and helped win public support for Tirpitz’s Navy Laws.'),
  M('How many seats did the SPD win in the Reichstag in 1912?', ['110', '12', '230', '1'], 0, 'With 110 seats, the SPD became the largest party. This alarmed the Kaiser and conservatives, who saw socialism as a threat to the empire.'),
  M('Which power did the Reichstag have under the Kaiser?', ['It could approve or reject laws and the budget, but could not appoint or dismiss the Chancellor', 'It could appoint the Chancellor', 'It controlled the army', 'It could dismiss the Kaiser'], 0, 'The Reichstag had some influence because it voted on taxes and spending, but the Kaiser appointed the Chancellor and controlled the army and foreign policy.'),
  T('By around 1900 Germany was producing more steel than Britain.', true, 'True. Germany’s rapid industrialisation made it Europe’s leading industrial power in steel, chemicals and electrical goods, which also boosted the working class and the SPD.'),
  M('What was the Daily Telegraph Affair (1908)?', ['An embarrassing newspaper interview by the Kaiser that damaged relations with Britain and his reputation at home', 'A British spy scandal', 'A strike by newspaper printers', 'The publication of the Navy Laws'], 0, 'Wilhelm’s careless remarks to a British newspaper angered both Britain and the Reichstag. It showed his unpredictable personality, though his powers were not reduced.'),
  M('Who was Chancellor of Germany from 1909 to 1917?', ['Theobald von Bethmann Hollweg', 'Otto von Bismarck', 'Friedrich Ebert', 'Gustav Stresemann'], 0, 'Bethmann Hollweg was Chancellor at the outbreak of the First World War. Bismarck left in 1890; Ebert and Stresemann were Weimar politicians.'),
  MU('Which TWO groups were strong supporters of the Kaiser’s authority?', ['The Junkers', 'Army officers', 'The SPD', 'Trade unions', 'The Spartacists'], [0, 1], 'The Junkers and the officer corps were the backbone of the conservative empire. The SPD and trade unions wanted more democracy; the Spartacists were revolutionary communists after 1914.'),
  O('Put these events in chronological order.', ['Unification of Germany', 'Wilhelm II becomes Kaiser', 'Bismarck resigns', 'First Navy Law', 'SPD becomes the largest party in the Reichstag'], '1871 unification; 1888 Wilhelm II; 1890 Bismarck resigns; 1898 first Navy Law; 1912 SPD largest party.'),
  W(src('Interpretation A: a historian writing in 2000.', 'Germany before 1914 had a parliament, but real power lay with the Kaiser, the army and the Prussian elite.'), M('Which piece of knowledge best SUPPORTS Interpretation A?', ['The Kaiser appointed the Chancellor and controlled the army and foreign policy', 'All men over 25 could vote for the Reichstag', 'The SPD won 110 seats in 1912', 'The Reichstag voted on the budget'], 0, 'The Kaiser’s control of the Chancellor, army and foreign policy supports the view that power lay with him and the elite. The other points show some democratic features, so they would challenge it.')),
  M('To whom did German army officers swear their oath of loyalty?', ['The Kaiser personally', 'The Reichstag', 'The SPD', 'The Bundesrat'], 0, 'The army was loyal to the Kaiser, not to parliament. This helps explain why the military was so powerful in Germany, as the Zabern Affair later showed.'),
]);
more('hist-y10-germany-weimar-2', [
  M('Where did German sailors mutiny in late October and early November 1918, sparking revolution?', ['Kiel (and Wilhelmshaven)', 'Munich', 'Berlin', 'Hamburg only'], 0, 'Sailors refused orders to attack the British fleet in a final battle. The mutiny at Kiel spread to other cities as workers’ and soldiers’ councils were set up.'),
  M('What was the Ebert–Groener agreement of November 1918?', ['The army agreed to support the new government if it resisted communist revolution', 'Germany agreed to pay reparations', 'Ebert agreed to restore the Kaiser', 'The SPD agreed to join the Spartacists'], 0, 'General Groener promised army support to Ebert. It protected the new republic from the left, but left the old, anti-democratic army leadership in place.'),
  M('Who proclaimed Germany a republic on 9 November 1918?', ['Philipp Scheidemann of the SPD', 'Adolf Hitler', 'Paul von Hindenburg', 'Wolfgang Kapp'], 0, 'Scheidemann announced the republic from the Reichstag building, partly to prevent the communists from declaring a soviet republic first.'),
  M('Who led the German delegation that signed the armistice on 11 November 1918?', ['Matthias Erzberger', 'Paul von Hindenburg', 'Gustav Stresemann', 'Kaiser Wilhelm II'], 0, 'Erzberger, a Centre Party politician, signed the armistice. Nationalists blamed him for the defeat, and he was assassinated in 1921, while the generals avoided blame.'),
  M('Who could vote in Weimar Reichstag elections?', ['All men and women aged 20 and over', 'Only men over 25', 'Only property owners', 'Only members of the SPD'], 0, 'Weimar gave votes to women and lowered the voting age to 20, making it one of the most democratic systems in the world at the time.'),
  MU('Which TWO territorial losses did Germany suffer under the Treaty of Versailles?', ['Alsace-Lorraine to France', 'Land to Poland, including the ‘Polish Corridor’', 'Bavaria to Austria', 'Berlin to the League of Nations', 'Prussia to Russia'], [0, 1], 'Germany lost Alsace-Lorraine, West Prussia and Posen (the Corridor) and other areas; the Saar was run by the League for 15 years. Bavaria, Berlin and Prussia stayed German.'),
  M('In 1921 the reparations bill was fixed at which figure?', ['132 billion gold marks (about £6.6 billion)', '£6.6 million', '1 billion marks', 'Nothing at all'], 0, 'The Reparations Commission set the total in 1921. Germans saw it as impossible to pay, and missed payments led to the Ruhr crisis in 1923.'),
  M('What happened to Germany’s colonies under the Treaty of Versailles?', ['They were taken away and run by Allied countries as League of Nations mandates', 'They were given independence immediately', 'Germany kept them all', 'They were sold to the USA'], 0, 'Britain, France and others governed the former colonies as mandates. Losing them was another humiliation for nationalists.'),
  M('Why were Weimar governments usually coalitions?', ['Proportional representation meant many parties won seats and none had a majority', 'The constitution banned single-party government', 'The President chose ministers from every party', 'Elections were held only once every ten years'], 0, 'Under PR, a party with a small share of the vote still won seats. Coalitions often disagreed and collapsed, so there were frequent changes of government.'),
  M('What was the Reichsrat in the Weimar Republic?', ['A second chamber representing the German states, which could delay laws', 'The army high command', 'The President’s cabinet', 'The supreme court'], 0, 'The Reichsrat represented the German states (Länder). The Reichstag was the main, elected parliament that made laws.'),
  T('The Weimar Constitution guaranteed rights such as freedom of speech and freedom of religion.', true, 'True. These rights were a strength of the constitution, but under Article 48 the President could suspend them in an emergency, as happened in 1933.'),
  O('Put these events in chronological order.', ['Naval mutiny at Kiel', 'Kaiser abdicates', 'Armistice signed', 'Spartacist uprising', 'Treaty of Versailles signed', 'Weimar Constitution comes into force'], 'Late October/early November 1918 Kiel; 9 November abdication; 11 November armistice; January 1919 Spartacists; 28 June 1919 Versailles; August 1919 Constitution.'),
  W(src('Interpretation B: a historian writing in the 1990s.', 'The Weimar Republic was weakened from birth: it was blamed for a defeat it did not cause and a peace it could not refuse.'), M('Which piece of knowledge best SUPPORTS Interpretation B?', ['Nationalists called the politicians who signed the armistice the ‘November Criminals’', 'Women gained the vote in 1919', 'The constitution guaranteed freedom of speech', 'Weimar culture flourished in the 1920s'], 0, 'The ‘November Criminals’ label shows the republic was blamed for defeat and Versailles. The other points are strengths or achievements, so they do not support the claim of weakness from birth.')),
  M('Which leading general helped spread the ‘stab in the back’ myth after the war?', ['Paul von Hindenburg', 'Friedrich Ebert', 'Matthias Erzberger', 'Philipp Scheidemann'], 0, 'Hindenburg (and Ludendorff) claimed the army had not been defeated but betrayed by politicians at home. This protected the army’s reputation and undermined the republic.'),
  M('How long was a Weimar President’s term of office?', ['Seven years', 'Two years', 'For life', 'Four years'], 0, 'The President was elected by the people for seven years and had strong powers, including appointing the Chancellor and using Article 48.'),
]);
more('hist-y10-germany-weimar-3', [
  M('Who led the right-wing putsch in Berlin in March 1920?', ['Wolfgang Kapp', 'Adolf Hitler', 'Rosa Luxemburg', 'Walther Rathenau'], 0, 'Kapp, backed by Freikorps units, seized Berlin. The government fled, but a general strike by workers stopped the putsch after a few days.'),
  T('During the Kapp Putsch the army refused to fire on the Freikorps.', true, 'True. Army leaders refused to fight fellow soldiers. This showed the army could not be relied on to defend the republic against the right.'),
  M('Which politician, who signed the armistice, was assassinated by right-wing extremists in 1921?', ['Matthias Erzberger', 'Gustav Stresemann', 'Friedrich Ebert', 'Paul von Hindenburg'], 0, 'Erzberger was murdered by members of the secret nationalist group Organisation Consul, which also killed Rathenau in 1922.'),
  M('Most right-wing political murderers in 1919–22 received light sentences or none, while left-wing ones were punished harshly. What does this suggest?', ['Many judges were sympathetic to the right and hostile to the republic', 'Left-wing groups committed most murders', 'The courts were completely fair', 'The government controlled the judges strictly'], 0, 'Judges were left over from the Kaiser’s era and many disliked the republic. Unequal justice encouraged extremists and weakened faith in Weimar.'),
  M('Why did printing more money cause hyperinflation in 1923?', ['There was more money but not more goods, so prices rose rapidly', 'Printing money made goods cheaper', 'The French stole the money', 'Workers refused to accept banknotes'], 0, 'During passive resistance the government printed money to pay striking workers while Ruhr production fell. Too much money chasing too few goods made prices soar.'),
  W('<table class="qt"><tr><th>Date</th><th>Price of a loaf of bread in Berlin (marks)</th></tr><tr><td>1918</td><td>0.63</td></tr><tr><td>January 1923</td><td>250</td></tr><tr><td>November 1923</td><td>200,000,000,000</td></tr></table>', M('What does the table show?', ['Prices rose slowly at first, then astronomically during 1923', 'Prices fell during 1923', 'Prices doubled between 1918 and November 1923', 'Bread was free in November 1923'], 0, 'From 250 marks to 200 billion marks in ten months shows hyperinflation. Money became worthless, wiping out savings.')),
  M('Why did some Germans use banknotes as fuel or wallpaper in 1923?', ['Notes were worth less than the paper they were printed on', 'The government ordered them to', 'There was a shortage of paper', 'It was a protest against the Kaiser'], 0, 'Banknotes lost value so fast that burning them was cheaper than buying fuel. Workers were paid twice a day and rushed to spend wages before prices rose further.'),
  S('In which year did the Munich (Beer Hall) Putsch take place?', '1923', [], 'The Munich Putsch took place on 8–9 November 1923 at the height of the hyperinflation crisis.'),
  M('Which earlier event inspired Hitler’s plan to march on Berlin in 1923?', ['Mussolini’s March on Rome in 1922', 'The Russian Revolution of 1905', 'The French Revolution', 'The Kapp Putsch’s success'], 0, 'Mussolini had become Italian leader after threatening a march on Rome. Hitler hoped to copy this, but his putsch collapsed in Munich. The Kapp Putsch had failed.'),
  T('General Ludendorff took part in the Munich Putsch but was acquitted at the trial.', true, 'True. Ludendorff’s fame protected him. Hitler received the minimum five-year sentence and served less than a year, showing the courts’ leniency to the right.'),
  S('In which prison did Hitler write Mein Kampf?', 'Landsberg', ['landsberg prison', 'landsberg am lech'], 'Hitler was held in comfortable conditions at Landsberg, where he dictated Mein Kampf, setting out his ideas on race, living space and the Jews.', [['landsberg']]),
  T('There were communist uprisings in Germany in 1923, including one in Hamburg.', true, 'True. The KPD tried to exploit the crisis, with a rising in Hamburg in October 1923. The government also used the army against left-wing governments in Saxony and Thuringia.'),
  O('Put these events in chronological order.', ['Germany fails to pay a reparations instalment', 'French and Belgian troops occupy the Ruhr', 'Passive resistance is called off', 'The Rentenmark is introduced', 'The Dawes Plan is agreed'], 'Late 1922 default; January 1923 Ruhr; September 1923 passive resistance ends; November 1923 Rentenmark; 1924 Dawes Plan.'),
  M('Which factor best explains why the Weimar Republic survived the crises of 1923?', ['Stresemann ended passive resistance and stabilised the currency, and the army and police defeated the putsch', 'Hitler supported the government', 'France withdrew from the Ruhr immediately', 'Reparations were cancelled in 1923'], 0, 'Decisive action by Stresemann, plus the loyalty of the Bavarian police and army against Hitler in 1923, kept the republic alive. France left the Ruhr in 1925 and reparations continued.'),
  M('What was the main aim of the Spartacists in January 1919?', ['To create a communist state run by workers’ councils', 'To restore the Kaiser', 'To unite Germany with Austria', 'To make Hitler Chancellor'], 0, 'The Spartacists, inspired by the Russian Revolution, wanted a communist revolution. Their rising was crushed by the Freikorps, and Luxemburg and Liebknecht were murdered.'),
]);
more('hist-y10-germany-weimar-4', [
  M('Which two posts did Gustav Stresemann hold?', ['Chancellor (briefly in 1923) and then Foreign Minister until 1929', 'President and Führer', 'Kaiser and Chancellor', 'Head of the army and President'], 0, 'Stresemann was Chancellor for about 100 days in 1923 and Foreign Minister from 1923 until his death in 1929. Most of his ‘Golden Years’ work was in foreign policy.'),
  M('Why did people trust the Rentenmark?', ['It was backed by a mortgage on German land and industry', 'It was made of gold', 'It was printed by the USA', 'Unlimited amounts were printed'], 0, 'Tying the new currency to real assets and strictly limiting how much was printed restored confidence. It was replaced by the Reichsmark in 1924.'),
  T('The Reichsmark, backed by gold reserves, replaced the Rentenmark in 1924.', true, 'True. The Reichsmark was controlled by an independent Reichsbank, making the currency stable through the late 1920s.'),
  M('Roughly how much money in American loans did the Dawes Plan (1924) first provide?', ['800 million marks', '8 marks', '800 billion billion marks', 'Nothing; it only cut payments'], 0, 'The Dawes Plan reduced annual payments and arranged an initial loan of 800 million marks. Further US loans, about 25 billion marks by 1930, helped German recovery.'),
  M('When did French and Belgian troops leave the Ruhr?', ['1925', '1919', '1933', '1945'], 0, 'After Germany accepted the Dawes Plan and resumed payments, the occupation ended in 1925.'),
  M('Which nationalist leader joined Hitler in campaigning against the Young Plan in 1929?', ['Alfred Hugenberg', 'Friedrich Ebert', 'Gustav Stresemann', 'Rosa Luxemburg'], 0, 'Hugenberg, leader of the DNVP, owned many newspapers and cinemas. The campaign gave Hitler national publicity, although the referendum against the plan failed.'),
  M('What did the Kellogg-Briand Pact (1928) do?', ['Over 60 countries, including Germany, promised not to use war to settle disputes', 'It set Germany’s reparations', 'It created the League of Nations', 'It gave Germany back its colonies'], 0, 'Germany was among the original signatories, showing it was again accepted as a respected nation. The pact had no way of being enforced.'),
  T('Stresemann died in October 1929, only weeks before the Wall Street Crash.', true, 'True. He died on 3 October 1929. The Crash later that month led to the withdrawal of US loans and the Depression that helped the Nazis.'),
  M('Which artist painted shocking images of war veterans and city life in Weimar Germany?', ['Otto Dix', 'Albert Speer', 'Leni Riefenstahl', 'Joseph Goebbels'], 0, 'Dix’s paintings of disabled ex-soldiers and nightlife are typical of Weimar art. Speer was Hitler’s architect; Riefenstahl a Nazi filmmaker; Goebbels the propaganda minister.'),
  M('What did the 1927 unemployment insurance law provide?', ['Payments to unemployed workers funded by contributions from workers and employers', 'A job for every German', 'Free houses for all', 'Pensions for soldiers only'], 0, 'It covered around 17 million workers and was a major welfare advance. But it was not designed for mass unemployment, which overwhelmed it after 1929.'),
  M('Which statement about housing in the Weimar Golden Years is accurate?', ['Over 2 million new homes were built between 1924 and 1931', 'No new homes were built', 'Every German family received a new house', 'Housing was entirely provided by the Nazis'], 0, 'Government and local councils funded large building programmes, easing the housing shortage, though it was not solved.'),
  T('In the 1928 Reichstag election the SPD was the largest party.', true, 'True. The SPD won 153 seats while the Nazis won only 12, suggesting support for moderate parties had grown during the Golden Years.'),
  O('Put these events in chronological order.', ['Rentenmark introduced', 'Dawes Plan', 'Locarno Treaties', 'Germany joins the League of Nations', 'Kellogg-Briand Pact', 'Young Plan'], '1923 Rentenmark; 1924 Dawes; 1925 Locarno; 1926 League; 1928 Kellogg-Briand; 1929 Young Plan.'),
  M('Which evidence best shows political stability in Germany between 1924 and 1929?', ['There were no attempted putsches and support for extremist parties fell', 'Hyperinflation continued', 'There were frequent assassinations of ministers', 'The Nazis won the 1928 election'], 0, 'Compared with 1919–23, there were no violent attempts to seize power and the Nazis and communists lost support. Coalitions were still unstable, however.'),
  M('Why did many conservative Germans dislike Weimar culture?', ['They saw modern art, cabaret and changing roles for women as immoral and un-German', 'It glorified the Kaiser', 'It was controlled by the army', 'It was banned by the government'], 0, 'Traditionalists, especially in rural areas, disliked the freedom of Berlin’s culture. The Nazis later exploited this hostility.'),
]);
// =====================================================================
// YEAR 10 — Germany 1929–1945: Nazi rise and dictatorship
// =====================================================================
addTopic(
  { id: 'hist-y10-nazi-germany', strand: 'hist-germany', year: 10, term: 2, name: 'Germany 1929–1945: Nazi Rise and Dictatorship',
    summary: 'How the Depression helped Hitler into power, how he created a dictatorship, and what life was like for Germans under the Nazis, including persecution and war.',
    specRef: 'AQA 8145 1A Germany, 1890–1945: Part two — Germany and the Depression; Part three — The experiences of Germans under the Nazis' },
  [
    { name: 'The rise of Hitler 1929–33', intro: "The Wall Street Crash and Great Depression destroyed confidence in Weimar democracy. Nazi propaganda, the SA and backstairs deals among conservative elites brought Hitler to power in January 1933.",
      items: [
        M("Why did the Wall Street Crash (October 1929) hit Germany especially hard?", ["American banks recalled the short-term loans that Germany's recovery depended on", "Germany had invested all its money in Wall Street", "France invaded Germany", "Hitler caused it"], 0, "Germany's Golden Years were funded by US loans (Dawes Plan). When they were recalled, businesses collapsed and unemployment soared."),
        S("Roughly how many Germans were unemployed by early 1932? (in millions)", "6 million", ["6", "six million", "6m", "six"], "Registered unemployment reached about 6 million in 1932 — around a third of the workforce."),
        O("Put the Nazis' Reichstag seats in order, from fewest to most.", ["May 1928: 12 seats", "September 1930: 107 seats", "November 1932: 196 seats", "July 1932: 230 seats", "March 1933: 288 seats"], "The Nazis grew from 12 to 230 seats as the Depression deepened; they fell to 196 in November 1932 before reaching 288 in March 1933."),
        M("Which Chancellor (1930–32) ruled largely by presidential decree using Article 48?", ["Heinrich Brüning", "Gustav Stresemann", "Friedrich Ebert", "Joseph Goebbels"], 0, "Brüning's cuts earned him the nickname 'the Hunger Chancellor'. Ruling by decree weakened democracy before Hitler took power."),
        MU("Which TWO groups were particularly attracted to the Nazis?", ["Middle classes and farmers who feared communism and economic ruin", "Young people and the unemployed attracted by promises of work and action", "Committed communists", "Trade union leaders in the SPD", "Jewish business owners"], [0, 1], "The Nazis appealed widely, especially to the Protestant middle classes, farmers, the young and many unemployed. Most industrial workers still backed the SPD or KPD."),
        M("How did Nazi propaganda help them win votes?", ["Goebbels used simple slogans, posters, rallies, radio and Hitler's flights across Germany", "It promised to restore the Kaiser", "It promised to join the USSR", "It was banned so it had no effect"], 0, "Goebbels' modern methods targeted different groups with simple messages: 'Work and Bread', anti-communism and national revival."),
        M("Who were the SA?", ["The Nazi 'stormtroopers' (Brownshirts) who protected meetings and attacked opponents", "Hitler's personal bodyguard (Blackshirts)", "The secret police", "The German army"], 0, "The SA, led by Ernst Röhm, had around 400,000 members by 1932. The SS began as Hitler's bodyguard; the Gestapo were the secret police."),
        T("Hitler won the 1932 presidential election.", false, "False. Hindenburg won the run-off with about 53% to Hitler's 37%, but Hitler's strong showing increased his prestige."),
        S("On what date was Hitler appointed Chancellor? (day, month, year)", "30 January 1933", ["30th january 1933", "january 30 1933"], "Hindenburg appointed Hitler Chancellor on 30 January 1933, with Franz von Papen as Vice-Chancellor."),
        M("Why did Papen and Hindenburg agree to make Hitler Chancellor?", ["They thought they could control him and use his mass support", "Hitler had won a majority of seats", "The army forced them", "The Allies demanded it"], 0, "The Nazis were the largest party but never had a majority in free elections. Papen believed 'we have hired him' and could keep him boxed in."),
        T("The Nazis never won more than 50% of the vote in a free election.", true, "True. Their best free-election result was 37.3% (July 1932); even in March 1933, amid intimidation, they won 43.9%."),
        M("Which party also gained from the Depression, frightening the middle classes?", ["The Communist Party (KPD)", "The Liberal Party", "The Conservative Party of Britain", "The Bauhaus"], 0, "KPD support rose to 100 seats in November 1932, increasing fear of communism and pushing the elites towards Hitler."),
        W(src("Interpretation A: a historian writing in 2005.", "Hitler did not seize power — he was handed it. A small group of conservative politicians around Hindenburg made him Chancellor because they believed they could use him."), M("Which knowledge best SUPPORTS Interpretation A?", ["Papen persuaded Hindenburg to appoint Hitler in January 1933 after secret talks", "The Nazis won 230 seats in July 1932", "The Munich Putsch of 1923", "Goebbels' propaganda campaign"], 0, "The 'backstairs intrigue' between Papen and Hindenburg supports 'handed power'. Electoral success and propaganda support the different view that Hitler won mass support.")),
        O("Put these in chronological order.", ["Wall Street Crash", "Brüning becomes Chancellor", "Presidential election: Hindenburg defeats Hitler", "Papen dismissed; Schleicher Chancellor", "Hitler appointed Chancellor"], "October 1929; March 1930; April 1932; December 1932; January 1933."),
        M("Which was a weakness of Hitler's opponents that helped him?", ["The SPD and KPD refused to cooperate against the Nazis", "They were all in prison already", "They supported the Nazis", "They controlled the SA"], 0, "The left was split: the KPD, following Moscow, called the SPD 'social fascists', so they never united against Hitler."),
      ] },
    { name: 'Creating a dictatorship 1933–34', intro: "In just 18 months Hitler turned his chancellorship into a dictatorship, using the Reichstag Fire, the Enabling Act, the Night of the Long Knives and the death of Hindenburg.",
      items: [
        M("What happened on 27 February 1933?", ["The Reichstag building was burned and a Dutch communist was arrested", "Hitler became Führer", "The Enabling Act was passed", "The Night of the Long Knives"], 0, "Marinus van der Lubbe was arrested. Hitler used the fire to claim a communist revolution was imminent."),
        M("What did the Reichstag Fire Decree allow?", ["Suspension of civil liberties and the arrest of thousands of communists", "Hitler to become President", "New elections every year", "The return of the Kaiser"], 0, "The emergency decree (under Article 48) suspended rights such as free speech and allowed detention without trial."),
        S("Which March 1933 law allowed Hitler to make laws without the Reichstag for four years?", "Enabling Act", ["the enabling act"], "The Enabling Act (23 March 1933) passed by 444 votes to 94 — only the SPD voted against; KPD deputies were banned or arrested."),
        MU("Which TWO helped the Enabling Act pass?", ["Communist deputies were arrested or prevented from attending", "The Centre Party voted for it after promises about the Catholic Church", "The SPD voted for it", "Hindenburg vetoed it", "The army refused to support it"], [0, 1], "The KPD was excluded and the SA intimidated deputies; the Centre Party's support gave the two-thirds majority. The SPD voted against."),
        M("What happened to trade unions in May 1933?", ["They were banned and replaced by the German Labour Front (DAF)", "They were given more power", "They joined the SA", "They took over the government"], 0, "Union offices were occupied on 2 May 1933 and replaced by the DAF, led by Robert Ley."),
        T("By July 1933 the Nazi Party was the only legal party in Germany.", true, "True. The Law against the Formation of New Parties (14 July 1933) made Germany a one-party state."),
        S("What name was given to the purge of SA leaders on 30 June 1934? (four words: Night of the …)", "Night of the Long Knives", ["the night of the long knives", "long knives"], "Hitler had Röhm and other SA leaders, plus old enemies such as Schleicher, murdered by the SS."),
        M("Why did Hitler purge the SA in 1934?", ["Röhm wanted the SA to absorb the army, which threatened Hitler's support from army leaders", "The SA had joined the communists", "The SA had lost all its members", "Hindenburg ordered it publicly"], 0, "The army saw the SA as a threat; Hitler needed army support to become Führer. Removing Röhm also removed a rival."),
        M("What happened when Hindenburg died on 2 August 1934?", ["Hitler combined the posts of Chancellor and President as Führer", "New elections were held", "Papen became President", "The Kaiser returned"], 0, "Hitler became Führer, and the army swore a personal oath of loyalty to him rather than to the constitution."),
        O("Put the steps to dictatorship in order.", ["Hitler appointed Chancellor", "Reichstag Fire", "Enabling Act", "Trade unions banned", "Night of the Long Knives", "Hitler becomes Führer"], "30 Jan 1933; 27 Feb 1933; 23 Mar 1933; 2 May 1933; 30 Jun 1934; 2 Aug 1934."),
        S("What title did Hitler take, meaning 'leader'?", "Führer", ["fuhrer", "fuehrer", "the fuhrer"], "As Führer, Hitler held supreme power as head of state, government and armed forces."),
        T("The army opposed Hitler becoming Führer and refused to swear an oath to him.", false, "False. The army welcomed the destruction of the SA's leadership and swore a personal oath to Hitler in August 1934."),
        M("Which of these was the most important step in making Hitler a legal dictator?", ["The Enabling Act, because it let him pass laws without the Reichstag", "The Olympic Games", "The building of autobahns", "The founding of the Hitler Youth"], 0, "The Enabling Act gave a legal basis for dictatorship; other steps built on it."),
        W(src("Source B: a cartoon published in a British newspaper, July 1934, described.", "Hitler, in uniform, stands with a smoking gun over bodies in SA uniforms. Göring stands beside him. A caption has an SA man saying 'They salute with both hands now.'"), M("What is the message of Source B?", ["Hitler ruled through terror — even his own supporters were murdered and others were frightened into obedience", "The SA were celebrating", "Hitler was a peaceful leader", "The SA had defeated Hitler"], 0, "Saluting 'with both hands' suggests hands-up surrender from fear. The British cartoonist was criticising the brutality of the Night of the Long Knives.")),
        M("What was the purpose of the first concentration camps, such as Dachau (March 1933)?", ["To imprison political opponents such as communists and socialists", "To train soldiers", "To house the unemployed", "To hold prisoners of war from 1914"], 0, "Dachau opened in March 1933 for political prisoners. Later the camp system expanded to Jews and other groups."),
      ] },
    { name: 'Life in Nazi Germany', intro: "The Nazis aimed to create a racially pure Volksgemeinschaft (people's community). They used terror, propaganda and organisations for workers, women and young people — with mixed results.",
      items: [
        M("Who led the SS and later the Gestapo?", ["Heinrich Himmler", "Joseph Goebbels", "Hermann Göring", "Ernst Röhm"], 0, "Himmler headed the SS from 1929 and controlled all police, including the Gestapo, from 1936. Goebbels ran propaganda."),
        S("What was the name of the Nazi secret police?", "Gestapo", [], "The Gestapo relied heavily on denunciations by ordinary citizens; it had relatively few officers."),
        M("Who was Minister of Public Enlightenment and Propaganda?", ["Joseph Goebbels", "Hermann Göring", "Albert Speer", "Hjalmar Schacht"], 0, "Goebbels controlled press, radio, film and the arts from March 1933."),
        MU("Which TWO were Nazi propaganda methods?", ["Cheap 'People's Receiver' radios", "Mass rallies at Nuremberg", "A free and independent press", "Allowing jazz music on the radio", "Encouraging foreign newspapers"], [0, 1], "Cheap radios and huge rallies spread the message. The press was controlled, and jazz was condemned as 'degenerate'."),
        M("What were the 'three Ks' expected of women?", ["Kinder, Küche, Kirche — children, kitchen, church", "Kaiser, Krieg, Kultur", "Kraft, Kunst, Kino", "Kampf, Kraft, Kinder"], 0, "Nazi ideology wanted women to be wives and mothers. Women were encouraged to leave professions such as medicine and law."),
        M("What did the Law for the Encouragement of Marriage (1933) offer?", ["A loan of 1,000 marks, a quarter of which was written off for each child born", "Free cars to every family", "Higher wages for working women", "Divorce for all"], 0, "Four children meant the loan was fully cancelled. The Mother's Cross (from 1938) rewarded large families."),
        S("What was the name of the Nazi youth organisation for boys?", "Hitler Youth", ["hitler jugend", "hitlerjugend", "the hitler youth"], "The Hitler Youth trained boys for military service; girls joined the League of German Maidens (BDM). Membership became compulsory by law in 1936 and fully enforced in 1939."),
        M("How did the Nazis reduce unemployment from about 4.8 million in 1933 to about 0.3 million in 1939?", ["Public works like autobahns, the National Labour Service (RAD), rearmament and conscription", "Abolishing all factories", "Paying people not to work", "Joining the League of Nations"], 0, "These measures created jobs — but 'invisible unemployment' (women and Jews removed from the figures) also lowered the official total."),
        M("What was Strength Through Joy (KdF)?", ["A DAF scheme offering cheap holidays, concerts and leisure to workers", "A military unit", "A propaganda film", "A Catholic youth group"], 0, "KdF aimed to keep workers loyal despite longer hours and frozen wages. The Volkswagen saving scheme was linked to it — but no saver received a car."),
        T("German workers' real wages rose sharply between 1933 and 1939.", false, "False. Wages were controlled; hours rose and real wages only just recovered to 1928 levels by 1938, though employment rose."),
        M("What was the Concordat of July 1933?", ["An agreement with the Pope that the Nazis would not interfere with the Catholic Church if it stayed out of politics", "A treaty with Britain", "A law banning all churches", "A Protestant prayer book"], 0, "Hitler broke the agreement, closing Catholic youth groups and schools; Pope Pius XI condemned Nazism in 1937."),
        S("Which Protestant pastor helped form the Confessing Church and was imprisoned in concentration camps from 1937 to 1945?", "Martin Niemöller", ["niemoller", "niemoeller", "martin niemoller", "niemöller"], "Niemöller opposed Nazi control of the Protestant Church; he was arrested in 1937 and held in camps until 1945."),
        MU("Which TWO were youth groups that opposed or rebelled against Nazi control?", ["The Edelweiss Pirates", "The Swing Youth", "The League of German Maidens", "The Hitler Youth", "The SS"], [0, 1], "Edelweiss Pirates rejected the Hitler Youth and sometimes attacked patrols; Swing Youth listened to banned jazz. The BDM and HJ were Nazi organisations."),
        W(src("Source C: a report by an SPD agent inside Germany, 1938.", "Workers grumble about long hours and poor pay, but most are glad to have a job. The KdF trips are popular. Few dare to speak openly against the regime."), M("What does Source C suggest about workers' attitudes?", ["A mix of grumbling, acceptance and fear", "Total enthusiasm for the Nazis", "Open revolution", "No interest in jobs"], 0, "It shows complaints alongside gratitude for jobs and fear of speaking out — useful because SPD agents were hostile to the Nazis yet still reported some popularity.")),
        M("Which statement best describes the experience of Germans under the Nazis?", ["It varied: some benefited from jobs and stability, others faced persecution and terror", "Everyone suffered equally", "Everyone was better off", "Nothing changed after 1933"], 0, "Experiences depended on race, politics, gender, age and class — a key idea for 'In what ways…' questions."),
      ] },
    { name: 'Persecution and wartime Germany', intro: "Nazi racial policy excluded Jews and others from the Volksgemeinschaft. War from 1939 brought rationing, total war and bombing, as well as genocide and some resistance.",
      items: [
        M("What did the Nuremberg Laws of 1935 do?", ["Took German citizenship away from Jews and banned marriage between Jews and 'Aryans'", "Created the death camps", "Gave Jews new rights", "Ended the persecution of Jews"], 0, "The Reich Citizenship Law and the Law for the Protection of German Blood and Honour defined Jews legally and stripped them of rights."),
        S("What name is given to the attacks on Jewish property on 9–10 November 1938?", "Kristallnacht", ["night of broken glass", "the night of broken glass", "crystal night"], "Kristallnacht followed the killing of a German diplomat in Paris; synagogues were burned and about 30,000 Jewish men sent to camps."),
        M("Which Nazi programme murdered disabled people from 1939?", ["Aktion T4", "Strength Through Joy", "Lebensborn", "Four-Year Plan"], 0, "Around 70,000 were murdered by 1941 under T4; killing continued secretly. Bishop von Galen spoke out against it in 1941."),
        M("When did food rationing begin in Germany?", ["At the start of the war, 1939", "In 1933", "In 1943 only", "Never"], 0, "Rationing began in late August/September 1939. Germans generally ate reasonably until late in the war, partly by taking food from occupied countries."),
        M("What did Goebbels' 'Total War' speech of February 1943 call for?", ["Full mobilisation of the economy and population after the defeat at Stalingrad", "Peace with Britain", "Disbanding the army", "The return of the Kaiser"], 0, "After Stalingrad, non-essential businesses were closed and more women were drafted into war work."),
        S("Who became Minister of Armaments in 1942 and greatly increased war production?", "Albert Speer", ["speer"], "Speer's reforms more than tripled armaments output by 1944 despite Allied bombing."),
        M("Which German city suffered a firestorm in July 1943 that killed around 40,000 people?", ["Hamburg", "Munich", "Nuremberg", "Weimar"], 0, "Operation Gomorrah created a firestorm in Hamburg. Dresden was bombed in February 1945 (around 25,000 dead)."),
        MU("Which TWO were examples of opposition to the Nazis during the war?", ["The White Rose leaflets of Hans and Sophie Scholl", "The July Bomb Plot of 1944", "The Night of the Long Knives", "The Nuremberg rallies", "The Enabling Act"], [0, 1], "The White Rose students were executed in 1943; Stauffenberg's bomb (20 July 1944) failed to kill Hitler. The other options were Nazi actions."),
        S("Which army officer planted the bomb in the July 1944 plot?", "Claus von Stauffenberg", ["stauffenberg", "von stauffenberg", "claus von stauffenberg"], "Colonel Stauffenberg left a briefcase bomb at Hitler's headquarters on 20 July 1944; Hitler survived and around 5,000 people were later executed."),
        T("Many German women were already working by the war years, and more were drafted into war work after 1943.", true, "True. Despite ideology, the needs of war pushed the regime to register women aged 17–45 for work in 1943."),
        O("Put these in chronological order.", ["Nuremberg Laws", "Kristallnacht", "War and rationing begin", "Wannsee Conference", "Total War speech", "July Bomb Plot"], "1935; 1938; 1939; 1942; 1943; 1944."),
        M("What was the Volkssturm (1944)?", ["A people's militia of older men and boys", "A youth music group", "An SS division", "A type of rationing"], 0, "Men aged 16–60 not already serving were called up to defend Germany in the final months."),
        W(src("Interpretation B: a historian writing in 1998.", "The majority of Germans were neither committed Nazis nor active resisters. They kept their heads down, accepted the benefits and looked away from the persecution."), M("Which knowledge would CHALLENGE Interpretation B?", ["Thousands joined resistance groups like the Edelweiss Pirates and the Confessing Church", "Most Germans enjoyed KdF holidays", "The Gestapo relied on denunciations", "Unemployment fell"], 0, "Active resistance challenges the claim that most just 'kept their heads down' — though resisters were a minority. The other options broadly support the interpretation.")),
        T("Hitler killed himself in Berlin on 30 April 1945.", true, "True. With Soviet forces in Berlin, Hitler died by suicide in his bunker; Germany surrendered on 7–8 May 1945."),
        M("Why is 'how far did the war change life for Germans?' a good topic for a 'how far' question?", ["There was continuity (propaganda, terror) and change (rationing, bombing, women's work, total war)", "Nothing happened in wartime", "Only soldiers were affected", "Life became easier for everyone"], 0, "Balanced answers weigh change against continuity and reach a judgement."),
      ] },
  ],
  {
    overview: "The Great Depression after 1929 gave Hitler his chance. Mass unemployment, Nazi propaganda and the fear of communism brought votes; conservative politicians then handed him the chancellorship in January 1933. By August 1934 he was Führer. Life under the Nazis combined jobs and propaganda for some with terror and persecution for others, culminating in war and genocide.",
    objectives: ["I can explain why support for the Nazis grew after 1929.", "I can explain how Hitler became Chancellor and then Führer.", "I can describe how the Nazis controlled Germany through terror and propaganda.", "I can explain how different groups' lives were affected by Nazi rule and by war.", "I can answer 'In what ways…' and 'Which was more important…' questions."],
    keyWords: [
      { term: 'Depression', def: 'A severe economic downturn with mass unemployment.' },
      { term: 'Enabling Act', def: 'March 1933 law letting Hitler pass laws without the Reichstag.' },
      { term: 'Führer', def: 'Leader — Hitler’s title from August 1934.' },
      { term: 'Gestapo', def: 'Nazi secret police.' },
      { term: 'Volksgemeinschaft', def: 'The Nazi ideal of a united, racially pure people’s community.' },
      { term: 'Propaganda', def: 'Information designed to persuade, often misleading.' },
      { term: 'Total war', def: 'Mobilising the whole economy and society for war.' },
      { term: 'Concordat', def: 'Agreement between Hitler and the Pope, 1933.' },
    ],
    sections: [
      { title: 'Why did the Nazis rise?', html: "<table class=\"qt\"><tr><th>Factor</th><th>Evidence</th></tr><tr><td>Depression</td><td>US loans recalled; 6 million unemployed by 1932.</td></tr><tr><td>Weakness of Weimar</td><td>Rule by decree under Brüning; unstable coalitions.</td></tr><tr><td>Propaganda and Hitler</td><td>Goebbels' rallies, posters, 'Hitler over Germany' flights.</td></tr><tr><td>Fear of communism</td><td>KPD rose to 100 seats in November 1932.</td></tr><tr><td>Backstairs intrigue</td><td>Papen and Hindenburg appoint Hitler, January 1933.</td></tr></table>" },
      { title: 'From Chancellor to Führer', html: timeline([["30 Jan 1933", "Hitler appointed Chancellor"], ["27 Feb 1933", "Reichstag Fire"], ["Mar 1933", "Election (Nazis 43.9%); Dachau opens; Enabling Act"], ["May 1933", "Trade unions banned"], ["Jul 1933", "One-party state; Concordat"], ["30 Jun 1934", "Night of the Long Knives"], ["2 Aug 1934", "Hindenburg dies; Hitler becomes Führer"], ["1935", "Nuremberg Laws"], ["1938", "Kristallnacht"], ["1939–45", "War; rationing; Total War 1943; Holocaust"]]) },
      { title: 'Control and experience', html: "<ul><li><b>Terror:</b> SS, Gestapo, concentration camps, informers.</li><li><b>Propaganda:</b> Goebbels; radio, rallies, film, the 1936 Olympics; book burning.</li><li><b>Workers:</b> jobs via autobahns, RAD and rearmament; DAF, KdF; but no unions and frozen wages.</li><li><b>Women:</b> Kinder, Küche, Kirche; marriage loans; Mother's Cross.</li><li><b>Youth:</b> Hitler Youth and BDM; Nazified schools; Edelweiss Pirates rebelled.</li><li><b>Churches:</b> Concordat; Reich Church; Niemöller and the Confessing Church.</li></ul>" + people([["Joseph Goebbels", "Propaganda minister."], ["Heinrich Himmler", "Head of the SS and police."], ["Ernst Röhm", "SA leader, murdered 1934."], ["Paul von Hindenburg", "President who appointed Hitler; died 1934."], ["Albert Speer", "Armaments minister from 1942."]]) },
      { title: 'Model answer: ‘Which was the more important reason?’ (12 marks)', html: worked("Which of the following was the more important reason why Hitler became Chancellor in January 1933: the Depression; the actions of Papen and Hindenburg?", ["Explain the Depression with evidence (unemployment, Nazi seats rising).", "Explain the role of Papen/Hindenburg with evidence.", "Judge: link them — the Depression made Hitler powerful enough to be offered the job; the elites gave it to him."], "Model judgement paragraph: Although the Depression was essential because it turned the Nazis from a fringe party with 12 seats into the largest party with 230, it did not on its own make Hitler Chancellor. In November 1932 the Nazi vote was actually falling and Hindenburg had refused him the post. It was Papen's deal with Hindenburg in January 1933, based on the belief that Hitler could be controlled, that put him in power. So the actions of Papen and Hindenburg were more important as the direct cause, but they only acted because the Depression had given Hitler mass support.") },
    ],
    mistakes: ["Saying Hitler was elected Chancellor or won a majority — he was appointed and never won 50%.", "Confusing the SA (Brownshirts) and the SS (Blackshirts).", "Claiming all Germans supported or all opposed the Nazis.", "Ignoring invisible unemployment when discussing jobs."],
    examTips: ["For 12-mark 'more important' questions, explain BOTH bullets fully and then compare them directly in a judgement.", "For 'In what ways…' (8 marks), give two clearly explained ways with specific evidence.", "Use statistics: 6 million unemployed; 230 seats; 444–94 vote."],
    realLife: "Germany's post-war 'militant democracy' allows the banning of parties that seek to destroy democracy — a lesson drawn from 1933.",
  },
);

// ---- extra practice: Germany 1929–1945 ----
more('hist-y10-nazi-germany-1', [
  M('What did Hitler decide about winning power after the failure of the Munich Putsch?', ['The Nazis would win power legally through elections, while still using propaganda and the SA', 'The Nazis would never stand in elections', 'The Nazis would join the SPD', 'He would leave politics'], 0, 'Hitler said it would be better to ‘hold our noses’ and enter the Reichstag. He rebuilt the party with a national structure, ready to exploit any crisis.'),
  M('How many Reichstag seats did the Nazis win in September 1930?', ['107', '12', '230', '288'], 0, 'The Nazis jumped from 12 seats (1928) to 107 as the Depression bit. They won 230 in July 1932 and 288 in March 1933.'),
  M('Roughly what share of the vote did the Nazis win in July 1932, their best result in a fully free election?', ['About 37%', 'About 3%', 'About 51%', 'About 90%'], 0, 'At about 37% the Nazis were the largest party but never had a majority in a free election. This is why Hitler needed a deal with conservative politicians.'),
  T('Nazi seats in the Reichstag fell from 230 to 196 in the November 1932 election.', true, 'True. The Nazis lost about two million votes and were short of money. Some historians argue the party might have declined had Hitler not been appointed in January 1933.'),
  M('Who was Chancellor immediately before Hitler (December 1932 – January 1933)?', ['Kurt von Schleicher', 'Franz von Papen', 'Heinrich Brüning', 'Gustav Stresemann'], 0, 'Schleicher, a general and political schemer, failed to split the Nazis or win Reichstag support. Papen then persuaded Hindenburg to appoint Hitler, with Papen as Vice-Chancellor.'),
  M('What was the result of the 1932 presidential election?', ['Hindenburg won with about 53% in the second round; Hitler came second with about 37%', 'Hitler won outright', 'Thälmann of the KPD won', 'The election was cancelled'], 0, 'Hindenburg was re-elected, but Hitler’s strong showing made him a national figure. The KPD’s Ernst Thälmann came third.'),
  M('What was new about Hitler’s 1932 election campaigning?', ['He flew between cities by aeroplane to speak at many rallies in one day', 'He refused to make speeches', 'He only used newspapers', 'He campaigned only in Bavaria'], 0, 'The ‘Hitler over Germany’ tours, organised by Goebbels, presented Hitler as a modern, dynamic leader who was everywhere at once.'),
  M('Roughly how many Reichstag seats did the Communist Party (KPD) win in November 1932?', ['100', '1', '10', '300'], 0, 'The KPD’s 100 seats frightened the middle classes, businessmen and landowners, who saw Hitler as a barrier against communism.'),
  M('Why did some wealthy industrialists give money to the Nazis?', ['They feared communism and trade unions and hoped Hitler would protect their businesses', 'Hitler promised to nationalise their factories', 'They wanted to restore the Weimar Republic', 'The Nazis promised to raise taxes on business'], 0, 'Business leaders such as Fritz Thyssen funded the party, allowing expensive propaganda campaigns. They expected Hitler to crush the left.'),
  M('Why was Brüning nicknamed the ‘hunger chancellor’?', ['He cut wages, unemployment benefits and government spending during the Depression', 'He went on hunger strike', 'He introduced rationing', 'He banned food imports to help farmers'], 0, 'Brüning’s austerity aimed to balance the budget and show Germany could not pay reparations, but it deepened poverty and boosted the extremes.'),
  T('Hitler only became a German citizen in 1932, shortly before standing for President.', true, 'True. Hitler was born in Austria and had been stateless. He gained German citizenship in February 1932 through an appointment as a civil servant in Brunswick.'),
  M('How many Nazis were in Hitler’s first cabinet in January 1933 (including Hitler)?', ['Three', 'All of them', 'One', 'Ten'], 0, 'Only Hitler, Frick and Göring were Nazis. Papen and the conservatives believed they could control Hitler — a serious miscalculation.'),
  W(src('Interpretation A: a historian writing in the 1950s.', 'Hitler did not seize power: he was manoeuvred into office by a small group of conservative politicians acting behind the scenes.'), M('Which piece of knowledge best SUPPORTS Interpretation A?', ['Papen persuaded Hindenburg to appoint Hitler, believing he could control him', 'The Nazis won 37% of the vote in July 1932', 'The SA had around 400,000 members in 1932', 'Nazi propaganda was very effective'], 0, 'The backroom deal between Papen and Hindenburg fits the view of Hitler being placed in power by elites. Votes, SA strength and propaganda support the view that Hitler’s own popularity mattered more.')),
  O('Put these events in chronological order.', ['Wall Street Crash', 'Brüning becomes Chancellor', 'Nazis win 107 seats', 'Nazis win 230 seats', 'Hitler appointed Chancellor'], 'October 1929 Crash; March 1930 Brüning; September 1930 107 seats; July 1932 230 seats; January 1933 Chancellor.'),
  S('What did the Nazi party’s initials NSDAP stand for in English?', 'National Socialist German Workers’ Party', ['national socialist german workers party'], 'NSDAP stands for Nationalsozialistische Deutsche Arbeiterpartei. Despite ‘socialist’ and ‘workers’ in the name, the Nazis attacked socialist and trade union organisations.', [['national'], ['socialist'], ['workers', 'worker']]),
]);
more('hist-y10-nazi-germany-2', [
  M('Who was arrested and executed for starting the Reichstag Fire?', ['Marinus van der Lubbe, a young Dutch communist', 'Ernst Röhm', 'Hermann Göring', 'Franz von Papen'], 0, 'Van der Lubbe was found at the scene. Historians still debate whether he acted alone; the Nazis used the fire to claim a communist revolution was coming.'),
  M('How did the Nazis do in the election of 5 March 1933?', ['They won 288 seats (about 44%), still short of a majority on their own', 'They won every seat', 'They won fewer seats than in 1928', 'They did not stand'], 0, 'Despite terror and propaganda, the Nazis needed the DNVP to have a majority. They then needed a two-thirds majority to pass the Enabling Act.'),
  M('Which party voted against the Enabling Act in March 1933?', ['The SPD', 'The Centre Party', 'The DNVP', 'The Nazi Party'], 0, 'The SPD’s 94 deputies voted against. The KPD deputies were already arrested or in hiding. The Centre Party voted for it in return for promises about the Catholic Church.'),
  S('What German word, meaning ‘coordination’, describes the Nazi policy of bringing all organisations under Nazi control?', 'Gleichschaltung', ['coordination'], 'Gleichschaltung brought state governments, unions, professional bodies, youth groups and the media under Nazi control in 1933–34.'),
  M('What happened to the German state (Länder) parliaments by early 1934?', ['They were abolished and the states run by Nazi governors', 'They gained more power', 'They were merged with the trade unions', 'They elected Hitler President'], 0, 'Nazi Reich governors took over the states in 1933, and the state parliaments were abolished in January 1934, ending Germany’s federal system.'),
  M('Which organisation replaced the trade unions in 1933?', ['The German Labour Front (DAF), led by Robert Ley', 'The Hitler Youth', 'The SS', 'The Reichsrat'], 0, 'The DAF controlled workers, set wages and hours, and banned strikes. Its leisure section, Strength Through Joy, offered rewards in place of rights.'),
  M('What did Ernst Röhm want for the SA in 1934?', ['To merge it with the army under his leadership and push a ‘second revolution’', 'To disband it', 'To make it part of the police', 'To send it abroad'], 0, 'With several million members, the SA threatened the army leadership and big business. Hitler needed the army’s support, so he chose to destroy Röhm.'),
  MU('Besides Ernst Röhm, which TWO political figures were killed in the Night of the Long Knives?', ['Kurt von Schleicher', 'Gregor Strasser', 'Franz von Papen', 'Heinrich Himmler', 'Hermann Göring'], [0, 1], 'Hitler used the purge to settle old scores, killing former Chancellor Schleicher and his ex-rival in the party, Strasser. Papen was placed under house arrest; Himmler and Göring helped organise the killings.'),
  M('What was the result of the referendum held in August 1934 on Hitler becoming Führer?', ['About 90% voted in favour', 'About 10% voted in favour', 'It was rejected', 'No vote was held'], 0, 'With propaganda and pressure, about 90% voted yes. The result gave Hitler’s new position a show of popular approval.'),
  M('What were the People’s Courts, set up in 1934?', ['Special courts to try political enemies, with Nazi judges and few rights for the accused', 'Courts elected by ordinary people', 'Church courts', 'Courts run by the League of Nations'], 0, 'The People’s Courts dealt with ‘treason’ cases. Defendants had little chance of a fair trial, and death sentences became common, especially in wartime.'),
  M('What was the ‘Day of Potsdam’ (21 March 1933)?', ['A ceremony where Hitler bowed to Hindenburg to link the Nazis with Prussian traditions', 'The day the Reichstag burned', 'The start of the Night of the Long Knives', 'The day the Nazis left the League of Nations'], 0, 'Staged by Goebbels at the opening of the new Reichstag, it reassured conservatives that Hitler respected the old order, two days before the Enabling Act.'),
  W(src('Source C: adapted from a Nazi newspaper, 2 July 1934.', 'The Führer has saved the nation from a traitorous plot. Röhm and his corrupt gang planned to seize power and plunge Germany into chaos.'), M('What was the purpose of Source C?', ['To justify the killings by claiming the SA leaders were plotting a revolt', 'To criticise Hitler', 'To give a balanced account of the purge', 'To announce Hindenburg’s death'], 0, 'There is no good evidence of a Röhm plot. The Nazi press presented the murders as a necessary rescue of the nation, which tells historians how the regime wanted the purge to be seen.')),
  M('Which knowledge best CHALLENGES the view that Hitler took power entirely legally in 1933?', ['SA and SS men surrounded the Reichstag during the Enabling Act vote, and KPD deputies had been arrested', 'Hitler was appointed by Hindenburg', 'The Enabling Act was passed by a vote', 'The Nazis won the most seats in March 1933'], 0, 'Intimidation and the arrest of opponents undermined the idea of a fully legal process. The other points are the ‘legal’ features that the Nazis liked to stress.'),
  T('After the Reichstag Fire thousands of communists were arrested and the KPD was effectively banned.', true, 'True. Using the Reichstag Fire Decree, the Nazis arrested KPD leaders and members, many of whom were sent to early concentration camps.'),
  M('Who was Heinrich Himmler in 1934?', ['Leader of the SS, which carried out the Night of the Long Knives', 'The leader of the SA', 'President of Germany', 'Head of the German army'], 0, 'After the purge the SS became independent of the SA and grew into the main instrument of terror. Röhm led the SA; Hindenburg was President until August 1934.'),
]);
more('hist-y10-nazi-germany-3', [
  M('When did membership of the Hitler Youth become compulsory for young Germans?', ['1939', '1923', '1945', '1919'], 0, 'The Hitler Youth Law of 1936 made it the official youth organisation and banned rivals; in 1939 membership became compulsory. Many young people joined earlier.'),
  S('What was the Nazi organisation for girls aged 14 to 18 called? (League of German …)', 'League of German Maidens', ['bdm', 'bund deutscher madel', 'league of german girls'], 'The League of German Maidens (BDM) trained girls for their role as healthy wives and mothers, with sports, camps and household skills.', [['maidens', 'maiden', 'girls', 'bdm']]),
  M('Which subject was added to school timetables to teach Nazi racial ideas?', ['Race studies (eugenics)', 'Latin', 'Computer science', 'French'], 0, 'Race studies taught that Aryans were superior. Textbooks were rewritten and PE given more time to make pupils fit for military service.'),
  M('What was expected of teachers in Nazi Germany?', ['To join the National Socialist Teachers’ League and teach Nazi ideas', 'To criticise the government in lessons', 'To ignore politics completely', 'To become members of the SPD'], 0, 'Almost all teachers joined the Teachers’ League; Jewish and politically unreliable teachers were dismissed.'),
  M('What was the Reich Labour Service (RAD)?', ['A scheme that from 1935 made young men do six months of labour on public projects', 'A trade union', 'A holiday company', 'The Nazi secret police'], 0, 'RAD workers built roads, drained marshes and planted forests for low pay in military-style camps. It helped cut unemployment figures.'),
  M('What was Beauty of Labour (SdA)?', ['A scheme to improve working conditions such as canteens and washrooms', 'A beauty contest for workers', 'A propaganda film', 'A women’s magazine'], 0, 'Part of the DAF, it improved factories, but workers often had to do the improvements themselves in their own time.'),
  M('What happened to the money workers saved in the Volkswagen scheme?', ['It was used for the war effort and no ordinary saver received a car', 'Every saver received a car by 1939', 'It was returned with interest in 1940', 'It was used to build schools'], 0, 'Workers paid instalments for the ‘people’s car’, but the factory switched to military vehicles. The scheme shows the gap between Nazi promises and reality.'),
  M('Why did the Nazis build the autobahns (motorways)?', ['To create jobs and help move troops and goods quickly', 'Only to attract tourists', 'Because most Germans owned cars', 'To connect Germany to Britain'], 0, 'Autobahn building employed many workers and had military value. Few Germans owned cars in the 1930s.'),
  M('Why do historians talk about ‘invisible unemployment’ in Nazi Germany?', ['Groups such as women and Jews who lost jobs were not counted in the figures', 'Unemployed people were made to wear masks', 'Unemployment figures were never published', 'Everyone had two jobs'], 0, 'Women pushed out of work and Jews dismissed did not appear in statistics, and men in the RAD or army were not counted as unemployed. Official figures therefore overstate the success.'),
  M('What was the Mother’s Cross?', ['An award for women who had four or more children', 'A Christian charity', 'A medal for nurses', 'A Hitler Youth badge'], 0, 'Bronze was for four or five children, silver for six or seven and gold for eight or more. It promoted the Nazi aim of a rising ‘Aryan’ birth rate.'),
  M('Who became Reich Bishop of the Nazi-controlled Protestant Reich Church?', ['Ludwig Müller', 'Martin Niemöller', 'Clemens von Galen', 'Pope Pius XI'], 0, 'Müller led the ‘German Christians’ who blended Nazism with Protestantism. Niemöller opposed this by forming the Confessing Church.'),
  S('What was the cheap radio set produced so that Germans could hear Nazi broadcasts called? (People’s …)', 'People’s Receiver', ['volksempfanger', 'volksempfaenger', 'peoples receiver', 'people’s radio', 'peoples radio'], 'The People’s Receiver had a short range, making it hard to pick up foreign stations. By 1939 about 70% of households had a radio.', [['receiver', 'radio', 'volksempfanger']]),
  M('How did the Nazis use the 1936 Berlin Olympics?', ['To show the world a strong, efficient, welcoming Germany', 'To protest against the League of Nations', 'To recruit foreign soldiers', 'They boycotted them'], 0, 'Antisemitic signs were temporarily removed. Germany won the most medals, though the Black American athlete Jesse Owens’ four gold medals undermined Nazi racial claims.'),
  M('What was the Reich Chamber of Culture?', ['A body that all writers, artists and musicians had to join, allowing the Nazis to censor them', 'A museum of modern art', 'The German parliament', 'A university for Nazi leaders'], 0, 'Set up by Goebbels in 1933, it excluded Jews and opponents from cultural life. Banned ‘degenerate’ art was mocked in a 1937 exhibition.'),
  T('In May 1933 students and Nazis publicly burned books by Jewish and anti-Nazi authors.', true, 'True. Book burnings took place in Berlin and other university cities, symbolising the destruction of free thought under the Nazis.'),
]);
more('hist-y10-nazi-germany-4', [
  M('What did the Law for the Restoration of the Professional Civil Service (April 1933) do?', ['Removed Jews and political opponents from government jobs', 'Gave Jews equal rights', 'Banned the SA', 'Created the Gestapo'], 0, 'This was one of the first legal steps of persecution. Jewish teachers, judges and officials lost their posts, with some temporary exceptions for war veterans.'),
  M('Which event did the Nazis use as an excuse for Kristallnacht in November 1938?', ['The shooting of a German diplomat in Paris by a young Polish Jew, Herschel Grynszpan', 'The Reichstag Fire', 'The start of the Second World War', 'The death of Hindenburg'], 0, 'Grynszpan shot Ernst vom Rath after his family was expelled from Germany. Goebbels presented the pogrom as a spontaneous reaction, but it was organised by the Nazis.'),
  M('What did the Nazis do to the Jewish community after Kristallnacht?', ['Fined it 1 billion Reichsmarks for the damage', 'Paid compensation for the damage', 'Apologised publicly', 'Gave Jews full citizenship'], 0, 'Jews were made to pay for damage done to them, and insurance payouts were seized by the state. Jews were then pushed out of the economy completely.'),
  T('After Kristallnacht about 30,000 Jewish men were sent to concentration camps.', true, 'True. Many were released only if they agreed to emigrate. This marked a shift from legal discrimination to open violence.'),
  M('Which other minority group, also seen as ‘racially inferior’, was persecuted and later murdered by the Nazis?', ['The Roma and Sinti (Gypsies)', 'Catholic bishops', 'Bavarian farmers', 'Prussian army officers'], 0, 'Roma and Sinti were forced into camps and, in wartime, murdered in large numbers. Catholic bishops faced pressure but were not targeted for racial reasons.'),
  M('Which law of July 1933 allowed compulsory sterilisation of people with certain disabilities and illnesses?', ['The Law for the Prevention of Hereditarily Diseased Offspring', 'The Enabling Act', 'The Nuremberg Laws', 'The Reich Citizenship Law'], 0, 'Around 400,000 people were sterilised. It was a step towards the murder of disabled people under Aktion T4 from 1939.'),
  M('Which Catholic bishop publicly protested against the murder of disabled people in 1941?', ['Clemens von Galen, Bishop of Münster', 'Ludwig Müller', 'Martin Niemöller', 'Dietrich Bonhoeffer'], 0, 'Galen’s sermons led Hitler to officially stop the T4 programme, though killings continued in secret. Niemöller and Bonhoeffer were Protestant pastors.'),
  S('What was the name of the Munich student group, including Hans and Sophie Scholl, that distributed anti-Nazi leaflets? (two words)', 'White Rose', ['the white rose'], 'The White Rose spread leaflets in 1942–43. Hans and Sophie Scholl were caught and executed in February 1943.', [['white'], ['rose']]),
  M('What happened to some Edelweiss Pirates in Cologne in November 1944?', ['Thirteen were publicly hanged', 'They were made Hitler Youth leaders', 'They were given medals', 'They escaped to Britain'], 0, 'The Edelweiss Pirates were working-class youths who rejected the Hitler Youth. Some in Cologne helped deserters and attacked officials, and 13 were hanged in public.'),
  M('Roughly how many foreign forced labourers and prisoners of war were working in Germany by 1944?', ['About 7 million', 'About 7,000', 'About 700', 'None'], 0, 'The war economy relied heavily on forced labour from occupied countries, held in harsh conditions. This shows how Nazi rule depended on exploiting conquered peoples.'),
  M('Which German city was devastated by Allied bombing in February 1945?', ['Dresden', 'Munich', 'Nuremberg', 'Bonn'], 0, 'The bombing of Dresden caused a firestorm that killed about 25,000 people. Hamburg’s firestorm had come in July 1943.'),
  M('What happened to millions of Germans living in the east as the Red Army advanced in 1944–45?', ['They fled or were later expelled westwards as refugees', 'They were made Soviet citizens and stayed', 'They were evacuated to Britain', 'Nothing changed for them'], 0, 'Millions fled in terrible conditions in winter 1944–45, and many more were expelled after the war. It was one of the largest population movements in history.'),
  O('Put these events in chronological order.', ['Jews removed from the civil service', 'Nuremberg Laws', 'Kristallnacht', 'Aktion T4 begins', 'Goebbels’ Total War speech', 'July Bomb Plot'], '1933 civil service law; 1935 Nuremberg Laws; 1938 Kristallnacht; 1939 T4; February 1943 Total War; July 1944 Bomb Plot.'),
  M('Which Protestant pastor, linked to the resistance, was executed in April 1945?', ['Dietrich Bonhoeffer', 'Martin Niemöller', 'Ludwig Müller', 'Clemens von Galen'], 0, 'Bonhoeffer was involved with plotters against Hitler and was hanged at Flossenbürg weeks before the war ended. Niemöller survived the camps; Galen survived the war.'),
  MU('Which TWO groups were made to wear identifying badges in Nazi concentration camps alongside Jewish prisoners?', ['Homosexual men (pink triangle)', 'Jehovah’s Witnesses (purple triangle)', 'Nazi Party officials', 'SS guards', 'Army generals'], [0, 1], 'Prisoners were classified by coloured triangles. Jehovah’s Witnesses were persecuted for refusing military service and the Hitler salute; gay men were persecuted under Paragraph 175.'),
]);
// =====================================================================
// YEAR 10 — Conflict and tension 1918–1939: peacemaking and the League
// =====================================================================
addTopic(
  { id: 'hist-y10-peace-league', strand: 'hist-conflict', year: 10, term: 3, name: 'Peacemaking and the League of Nations 1918–1936',
    summary: 'The aims of the Big Three, the Treaty of Versailles and other treaties, and the successes and failures of the League of Nations, including Manchuria and Abyssinia.',
    specRef: 'AQA 8145 1B Conflict and tension, 1918–1939: Part one — Peacemaking; Part two — The League of Nations and international peace' },
  [
    { name: 'The Big Three and their aims', intro: "At the Paris Peace Conference (1919) Wilson, Clemenceau and Lloyd George had very different aims. The Treaty of Versailles was a compromise that fully satisfied none of them.",
      items: [
        M("Which leader wanted the harshest treaty to weaken Germany and protect France?", ["Georges Clemenceau", "Woodrow Wilson", "David Lloyd George", "Vittorio Orlando"], 0, "Clemenceau ('the Tiger') wanted security: France had been invaded in 1870 and 1914 and suffered enormous damage."),
        M("What were Woodrow Wilson's Fourteen Points (January 1918)?", ["His plan for a fair peace including self-determination and a League of Nations", "France's list of demands", "The terms of the armistice", "The military terms imposed on Germany"], 0, "Wilson wanted a fair peace to prevent future war, based on self-determination, free trade, disarmament and a League."),
        S("What term means the right of national groups to rule themselves?", "Self-determination", ["self determination", "selfdetermination"], "Self-determination was one of Wilson's key ideas, applied to new states such as Poland and Czechoslovakia (but not to Germans)."),
        M("Which leader took a middle position, wanting Germany punished but able to recover as a trading partner?", ["David Lloyd George", "Georges Clemenceau", "Woodrow Wilson", "Kaiser Wilhelm II"], 0, "Lloyd George had promised voters to 'make Germany pay' but privately feared a harsh treaty would cause revenge and help communism spread."),
        MU("Which TWO aims did Lloyd George have?", ["Protecting Britain's navy and empire", "Keeping Germany as a trading partner", "Returning Alsace-Lorraine to Germany", "Giving Germany a larger army", "Abolishing the British Empire"], [0, 1], "He wanted Germany's navy and colonies removed (protecting British interests) but feared crippling Germany's economy."),
        T("The USA's Senate refused to ratify the Treaty of Versailles.", true, "True. Isolationists in the Senate rejected the treaty and the USA never joined the League — a blow to Wilson."),
        M("Why did Clemenceau think Wilson's ideas were unrealistic?", ["The USA had not suffered as much as France and was far from Germany", "Wilson wanted to destroy Germany", "Wilson was a communist", "Wilson supported the Kaiser"], 0, "Clemenceau reportedly mocked that even God had only Ten Commandments. France's losses — around 1.4 million soldiers dead — shaped his demands."),
        O("Put these events in chronological order.", ["Fourteen Points announced", "Armistice", "Paris Peace Conference opens", "Treaty of Versailles signed", "League of Nations begins work"], "January 1918; 11 November 1918; January 1919; 28 June 1919; January 1920."),
        M("Which statement best describes the Treaty of Versailles?", ["A compromise between the Big Three that fully satisfied none of them", "Exactly what Wilson wanted", "Exactly what Germany wanted", "A treaty Germany helped write"], 0, "Clemenceau thought it too lenient, Wilson too harsh, Lloyd George was partly satisfied; Germany was excluded."),
        S("Which country did Woodrow Wilson lead?", "USA", ["united states", "america", "the usa", "united states of america", "us"], "Wilson was the Democratic President of the USA (1913–21)."),
        W(src("Source A: a cartoon published in a British newspaper, 1919, described.", "The Big Three leave the peace conference. Clemenceau says 'Curious! I seem to hear a child weeping.' Behind a pillar a small child labelled '1940 Class' is crying over the treaty."), M("What is the message of Source A?", ["The treaty was so harsh it would lead to another war affecting the next generation", "The Big Three loved children", "Germany was happy with the treaty", "The war would end all wars"], 0, "The cartoonist predicts that children who would be of military age in 1940 would suffer because Versailles would cause another war. It shows that some in Britain criticised the treaty as too harsh.")),
        M("What was Clemenceau's main concern about Germany?", ["Security — preventing another German invasion of France", "Trade with Germany", "Spreading democracy to Germany", "Building a German navy"], 0, "French priorities were security (demilitarised Rhineland, small German army) and reparations to rebuild."),
        T("Germany was invited to negotiate the terms of the Treaty of Versailles.", false, "False. Germany was excluded from the talks and told to sign; this is why it was called a Diktat."),
        M("Who was the fourth leader sometimes included as one of the 'Big Four'?", ["Vittorio Orlando of Italy", "Lenin of Russia", "Friedrich Ebert of Germany", "Kaiser Wilhelm II"], 0, "Orlando was Italian PM; Italy felt cheated of land it had been promised and later turned to Mussolini."),
        M("What was a main reason Lloyd George feared a harsh treaty?", ["Germany might seek revenge or turn communist", "Britain would lose its navy", "France would become too weak", "The USA would invade"], 0, "His Fontainebleau Memorandum (March 1919) warned that injustice would lead to revenge and communism."),
      ] },
    { name: 'Versailles terms and the other treaties', intro: "Remember the terms with BRAT: Blame, Reparations, Army, Territory. Separate treaties dealt with Austria, Hungary, Bulgaria and Turkey.",
      items: [
        M("In BRAT, what does the 'B' stand for?", ["Blame — Article 231 war guilt", "Belgium", "Battleships", "Britain"], 0, "BRAT = Blame (Article 231), Reparations (£6.6bn), Army (100,000), Territory (13% of land, colonies)."),
        S("How much were Germany's reparations set at in 1921 (in pounds)?", "£6.6 billion", ["6.6 billion", "6.6bn", "6.6", "£6.6bn", "6.6 billion pounds"], "The Reparations Commission set the figure at 132 billion gold marks (£6.6 billion) in 1921."),
        M("What happened to Alsace-Lorraine?", ["It was returned to France", "It was given to Belgium", "It became independent", "It stayed German"], 0, "Germany had taken Alsace-Lorraine in 1871; Versailles returned it to France."),
        M("What was the Saar?", ["A coal-rich German region run by the League for 15 years with France taking its coal", "A German warship", "Part of Austria", "A Polish port"], 0, "A plebiscite in 1935 returned the Saar to Germany (over 90% voted to rejoin)."),
        MU("Which TWO territorial terms were part of the Treaty of Versailles?", ["The Polish Corridor gave Poland access to the sea", "Anschluss (union) with Austria was forbidden", "Germany gained the Sudetenland", "Germany kept all its colonies", "Germany took Alsace-Lorraine from France"], [0, 1], "West Prussia formed the Polish Corridor and Anschluss was banned. Germany lost all colonies and Alsace-Lorraine."),
        M("What happened to the Rhineland under Versailles?", ["It was demilitarised — no German troops allowed", "It was given to France permanently", "It became part of Belgium", "It was the site of the new German army"], 0, "The Rhineland was demilitarised and occupied by Allied troops for 15 years to protect France."),
        M("Which treaty dealt with Austria (1919)?", ["Saint-Germain", "Trianon", "Neuilly", "Sèvres"], 0, "Saint-Germain broke up the Austro-Hungarian empire, limited Austria's army to 30,000 and forbade union with Germany."),
        M("Which treaty took about two-thirds of Hungary's territory (1920)?", ["Trianon", "Saint-Germain", "Neuilly", "Lausanne"], 0, "Trianon gave land to Czechoslovakia, Romania and Yugoslavia; millions of Hungarians ended up in other countries."),
        S("Which 1919 treaty dealt with Bulgaria?", "Neuilly", ["treaty of neuilly"], "Neuilly cost Bulgaria land, limited its army to 20,000 and imposed reparations."),
        M("Why was the Treaty of Sèvres (1920) with Turkey replaced by Lausanne (1923)?", ["Turkish nationalists under Atatürk fought and forced a revision", "The League of Nations cancelled it", "Germany objected", "The USA rewrote it"], 0, "Mustafa Kemal (Atatürk) resisted Sèvres; Lausanne gave Turkey better terms — showing treaties could be overturned by force."),
        T("Germany was allowed to keep an air force of 1,000 planes.", false, "False. Germany was banned from having any air force, submarines or tanks; its navy was limited to six battleships."),
        W(src("Interpretation A: a British economist, J. M. Keynes, writing in 1919.", "The policy of reducing Germany to servitude for a generation is abhorrent and detestable. It will sow the seeds of the decay of the whole civilised life of Europe."), M("How convincing is Interpretation A? Which knowledge best SUPPORTS it?", ["Reparations contributed to German resentment and economic crises in 1923", "Germany's economy recovered strongly in 1924–29", "The reparations total was reduced by the Young Plan in 1929", "Germany paid only part of the reparations"], 0, "Resentment and the 1923 crisis support Keynes. Recovery in the 1920s and reductions in reparations challenge the view that Germany was reduced to 'servitude'.")),
        M("Why did many Germans particularly resent Article 231?", ["It forced them to accept sole blame for the war", "It took their colonies", "It limited their army", "It made them pay France only"], 0, "Many Germans believed they had fought a defensive war; the war guilt clause was a national humiliation and justified reparations."),
        O("Put these treaties in chronological order of signing.", ["Versailles", "Saint-Germain", "Neuilly", "Trianon", "Lausanne"], "June 1919; September 1919; November 1919; June 1920; July 1923."),
        T("Some historians argue Versailles was not as harsh as Germany claimed, compared with the treaty Germany imposed on Russia at Brest-Litovsk in 1918.", true, "True. Brest-Litovsk took about a third of Russia's population and much of its industry — evidence used to challenge German complaints."),
      ] },
    { name: 'The League of Nations in the 1920s', intro: "The League was set up in 1920 to keep peace through collective security. It had some successes in the 1920s, but structural weaknesses limited it.",
      items: [
        S("In which Swiss city was the League of Nations based?", "Geneva", [], "The League's headquarters were in Geneva, Switzerland, a neutral country."),
        M("What is 'collective security'?", ["Members act together to protect any member that is attacked", "Each country builds its own large army", "The USA protects Europe", "Only Britain and France keep peace"], 0, "The idea was that aggression against one member would be resisted by all, through moral pressure, sanctions or force."),
        MU("Which TWO were weaknesses of the League?", ["The USA never joined", "It had no army of its own", "It was based in Geneva", "It had a Council", "It had agencies like the ILO"], [0, 1], "Without the USA, sanctions were less effective, and the League relied on members' armies. Germany and the USSR were also excluded at first."),
        M("Which body of the League met once a year with every member having one vote?", ["The Assembly", "The Council", "The Secretariat", "The Permanent Court"], 0, "The Assembly needed unanimous decisions, which made action slow. The Council met more often."),
        M("Which countries were the original permanent members of the Council?", ["Britain, France, Italy and Japan", "USA, Britain, France and Germany", "Britain, USSR, USA and China", "France, Germany, Spain and Italy"], 0, "The USA was meant to be a member but never joined. Germany joined the Council in 1926."),
        M("What were 'sanctions'?", ["Penalties such as banning trade with an aggressor", "Rewards for peace", "A type of treaty", "League soldiers"], 0, "The League's three steps were moral condemnation, economic sanctions and, in theory, military force."),
        M("Which dispute (1921) was a League SUCCESS?", ["The Åland Islands — Sweden accepted the League's ruling that they belonged to Finland", "Corfu", "Vilna", "Manchuria"], 0, "Both sides accepted the ruling. Vilna (1920) and Corfu (1923) were failures; Manchuria came in 1931."),
        M("What happened in the Corfu crisis (1923)?", ["Mussolini occupied Corfu and Greece was forced to pay compensation, undermining the League", "Greece invaded Italy", "The League sent an army", "Britain annexed Corfu"], 0, "The Conference of Ambassadors overruled the League and Greece paid 50 million lire — a major power got its way."),
        T("The League successfully settled the 1925 dispute between Greece and Bulgaria.", true, "True. When Greece invaded Bulgaria, the League condemned it; Greece withdrew and paid compensation. But critics noted large and small powers were treated differently compared with Corfu."),
        MU("Which TWO were humanitarian successes of League agencies?", ["Helping hundreds of thousands of refugees and prisoners of war return home", "Freeing about 200,000 slaves in Sierra Leone", "Stopping Japan in Manchuria", "Preventing Italian aggression in Abyssinia", "Bringing the USA into the League"], [0, 1], "The Refugees Committee (Nansen passports) and the Slavery Commission were notable successes, as was the Health Committee's work against diseases like leprosy."),
        S("What was the name of the League agency that worked to improve working conditions?", "International Labour Organisation", ["ilo", "international labour organization", "the ilo"], "The ILO still exists today as part of the United Nations."),
        M("What was the Kellogg–Briand Pact (1928)?", ["An agreement eventually signed by over 60 countries renouncing war as a policy", "The founding document of the League", "A trade deal between the USA and France", "A peace treaty with Turkey"], 0, "It was symbolic but had no way of enforcing itself."),
        O("Put these League events in chronological order.", ["League begins work", "Vilna seized by Poland", "Åland Islands ruling", "Corfu crisis", "Greece–Bulgaria dispute"], "January 1920; October 1920; 1921; 1923; 1925."),
        W(src("Source B: a cartoon published in a British magazine, December 1919, described.", "A bridge labelled 'League of Nations' spans a gap but has a large hole in the middle. Uncle Sam (the USA) lounges nearby, refusing to put in the keystone."), M("What is the message of Source B?", ["The League would be weakened because the USA refused to join", "The USA built the League", "The League was complete and strong", "Bridges were needed in Europe"], 0, "The missing keystone is the USA; without it the League would be fundamentally weak.")),
        M("Why were decisions in the League often slow?", ["Key bodies needed unanimous agreement and met infrequently", "It had too many soldiers", "The USA vetoed everything", "It met every day"], 0, "Unanimity and infrequent meetings meant crises could develop before the League acted."),
      ] },
    { name: 'Manchuria and Abyssinia: the League fails', intro: "In the 1930s the Depression encouraged aggression. Japan's invasion of Manchuria (1931) and Italy's invasion of Abyssinia (1935) exposed the League's weakness.",
      items: [
        M("What incident did Japan use as an excuse to invade Manchuria in September 1931?", ["The Mukden Incident — an explosion on a Japanese-owned railway", "The Wal Wal incident", "The Reichstag Fire", "The sinking of a Japanese ship"], 0, "Japanese officers staged the explosion near Mukden and blamed the Chinese."),
        S("What was the name of the League's report on Manchuria, published in 1932?", "Lytton Report", ["lytton", "the lytton report"], "Lord Lytton's commission took about a year; it said Japan should leave Manchuria. Japan refused."),
        M("How did Japan respond to the League's condemnation in 1933?", ["It left the League", "It withdrew from Manchuria", "It paid compensation", "It joined the Council"], 0, "Japan left the League in March 1933 and kept Manchuria (renamed Manchukuo)."),
        MU("Why did the League fail to act effectively over Manchuria? Choose TWO.", ["Sanctions would mean little without the USA, Japan's main trading partner", "Britain and France were unwilling to risk war so far away during the Depression", "Japan had already left the League", "The League had a large army in Asia", "China asked the League not to help"], [0, 1], "The USA was not a member and Britain and France had no wish to fight in the Far East. Japan left only after being condemned."),
        S("Which African country did Italy invade in October 1935?", "Abyssinia", ["ethiopia"], "Mussolini invaded Abyssinia (Ethiopia), one of the few independent African states, to build an empire and avenge Italy's defeat at Adowa (1896)."),
        M("What was the main weakness of the League's sanctions against Italy?", ["They did not include oil, and the Suez Canal was left open", "They included all goods", "Italy was not a member", "The USA enforced them strictly"], 0, "Oil was crucial for Italy's war; Britain kept the Suez Canal (its route) open, so Italian supplies flowed."),
        M("What was the Hoare–Laval Pact (December 1935)?", ["A secret plan by Britain and France to give Italy much of Abyssinia", "A treaty ending the Manchurian crisis", "A Nazi–Soviet agreement", "A plan to expel Italy from the League"], 0, "When the plan leaked, public outrage forced Hoare and Laval to resign — it showed Britain and France were undermining their own League."),
        S("Who was the Emperor of Abyssinia who appealed to the League in 1936?", "Haile Selassie", ["selassie", "haile selassie i"], "Haile Selassie addressed the Assembly in June 1936, warning 'It is us today. It will be you tomorrow.'"),
        T("Abyssinia did more damage to the League than Manchuria because it was close to Europe and involved a Council member.", true, "True. Many historians argue Abyssinia was the 'death blow' — Britain and France put self-interest before collective security in a crisis on their doorstep."),
        O("Put these events in chronological order.", ["Mukden Incident", "Lytton Report published", "Japan leaves the League", "Italy invades Abyssinia", "Hoare–Laval Pact revealed", "Italy leaves the League"], "Sept 1931; Oct 1932; March 1933; Oct 1935; Dec 1935; Dec 1937."),
        M("How did the Abyssinian crisis help Hitler?", ["It distracted Britain and France and pushed Mussolini towards Hitler", "It made Britain stronger", "It led the USA to join the League", "It ended appeasement"], 0, "Hitler remilitarised the Rhineland in March 1936 during the crisis; Italy and Germany formed the Rome–Berlin Axis later in 1936."),
        W(src("Source C: a cartoon published in a British newspaper, 1935, described.", "A figure labelled 'League of Nations' bows politely to Mussolini, saying 'We must not be too hard on him.' Behind Mussolini an Abyssinian village is burning."), M("Source C criticises…", ["The League for being weak and too polite to an aggressor", "Mussolini's love of peace", "Abyssinia for starting the war", "The USA for joining the League"], 0, "The bowing figure suggests appeasement of Mussolini while he commits aggression.")),
        M("What did the failure of the Disarmament Conference (1932–34) show?", ["Countries would not disarm, and Germany used the failure to leave the League and rearm", "Everyone had disarmed", "The League had an army", "The USA joined"], 0, "Germany walked out in 1933, demanding equality in arms."),
        T("The Great Depression made it harder for the League to impose economic sanctions.", true, "True. Countries struggling economically were unwilling to give up trade, and the Depression encouraged nationalist, aggressive governments."),
        M("Which is the BEST overall judgement about why the League failed in the 1930s?", ["Its structural weaknesses were exposed when great powers chose aggression during the Depression", "It had too much power", "It was too popular", "It was abolished in 1931"], 0, "Weaknesses (no USA, no army, unanimity) mattered most when Japan and Italy — powerful states — acted, and Britain and France would not risk war."),
      ] },
  ],
  {
    overview: "The peace settlement of 1919–20 tried to prevent another war but left many grievances. The League of Nations, created to keep peace through collective security, had successes in the 1920s but failed when major powers — Japan in Manchuria and Italy in Abyssinia — turned to aggression during the Depression.",
    objectives: ["I can explain the aims of the Big Three and judge how far they were achieved.", "I can describe the terms of Versailles and the other treaties and explain reactions to them.", "I can explain the League's structure, successes and weaknesses.", "I can explain why the League failed over Manchuria and Abyssinia.", "I can analyse cartoons and write an account."],
    keyWords: [
      { term: 'Big Three', def: 'Wilson (USA), Clemenceau (France), Lloyd George (Britain).' },
      { term: 'Fourteen Points', def: 'Wilson’s 1918 plan for a fair peace.' },
      { term: 'Reparations', def: 'Payments for war damage; £6.6 billion for Germany.' },
      { term: 'Self-determination', def: 'Right of nations to govern themselves.' },
      { term: 'Collective security', def: 'Members acting together against an aggressor.' },
      { term: 'Sanctions', def: 'Penalties such as trade bans.' },
      { term: 'Isolationism', def: 'US policy of staying out of world affairs.' },
      { term: 'Mandate', def: 'Former colony administered by a League member.' },
    ],
    sections: [
      { title: 'The Big Three', html: "<table class=\"qt\"><tr><th>Leader</th><th>Aims</th><th>Satisfied?</th></tr><tr><td>Wilson (USA)</td><td>Fair peace; Fourteen Points; League; self-determination</td><td>Partly — League created but USA did not join</td></tr><tr><td>Clemenceau (France)</td><td>Harsh treaty; security; reparations</td><td>Partly — wanted the Rhineland separated from Germany</td></tr><tr><td>Lloyd George (Britain)</td><td>Punish but not cripple; protect navy and empire</td><td>Mostly — German navy and colonies removed</td></tr></table>" },
      { title: 'The treaties', html: "<div class=\"rule\">BRAT: Blame (Art. 231) · Reparations (£6.6bn) · Army (100,000; no air force; 6 battleships; Rhineland demilitarised) · Territory (Alsace-Lorraine, Polish Corridor, Saar under League, colonies, no Anschluss)</div><p>Other treaties: <b>Saint-Germain</b> (Austria, 1919), <b>Neuilly</b> (Bulgaria, 1919), <b>Trianon</b> (Hungary, 1920), <b>Sèvres</b> (Turkey, 1920, replaced by Lausanne 1923).</p>" },
      { title: 'The League: timeline', html: timeline([["Jan 1920", "League begins work in Geneva"], ["1920", "Vilna — failure"], ["1921", "Åland Islands — success; Upper Silesia — success"], ["1923", "Corfu — failure"], ["1925", "Greece–Bulgaria — success"], ["1926", "Germany joins"], ["1931–33", "Manchuria; Japan leaves"], ["1932–34", "Disarmament Conference fails"], ["1935–36", "Abyssinia; Hoare–Laval Pact"]]) + people([["Woodrow Wilson", "US President; Fourteen Points."], ["Georges Clemenceau", "French PM; wanted a harsh peace."], ["David Lloyd George", "British PM; compromise position."], ["Benito Mussolini", "Italian dictator; Corfu 1923, Abyssinia 1935."], ["Haile Selassie", "Emperor of Abyssinia; appealed to the League."]]) },
      { title: 'Model answer: write an account (8 marks)', html: worked("Write an account of how events in Abyssinia (1935–36) weakened the League of Nations.", ["Narrate in order: invasion → limited sanctions → Hoare–Laval → conquest.", "At each stage explain HOW it weakened the League.", "Finish with the consequence."], "Model paragraph: In October 1935 Italy invaded Abyssinia. The League condemned Italy and imposed sanctions, but these did not include oil, and Britain kept the Suez Canal open, so Italian troops and supplies continued to flow. This showed that leading members would not take measures that hurt their own interests. Then, in December 1935, the Hoare–Laval Pact was leaked, revealing that Britain and France had secretly planned to give Italy much of Abyssinia. As a result, the League's two most powerful members were exposed as undermining collective security, and when Italy captured Addis Ababa in May 1936, the League's credibility was destroyed.") },
    ],
    mistakes: ["Saying the USA was in the League — it never joined.", "Confusing Lloyd George's public 'make Germany pay' with his private moderate views.", "Thinking the League had its own army.", "Writing that Abyssinian sanctions included oil."],
    examTips: ["Paper 1 Section B: Q1 'how do you know' from a source; Q2 'How useful are Sources B and C?' (12); Q3 'Write an account' (8); Q4 'How far do you agree?' (16 + 4 SPaG).", "For accounts, sequence events and explain consequences — narrative with analysis.", "For cartoons, identify symbols, then link the message to the date and context."],
    realLife: "The United Nations (1945) was designed to fix the League's weaknesses, e.g. a Security Council with powers to use force.",
  },
);

// ---- extra practice: Peacemaking and the League of Nations ----
more('hist-y10-peace-league-1', [
  M('Why was the Hall of Mirrors at Versailles a deliberately symbolic place for Germany to sign the treaty?', ['The German Empire had been proclaimed there in 1871 after France’s defeat', 'It was where the war had started', 'It was in neutral Switzerland', 'It was Wilson’s favourite building'], 0, 'Signing in the room where Germany humiliated France in 1871 reversed that humiliation. It shows Clemenceau’s wish for revenge and French security.'),
  M('Why was 28 June 1919 a significant date for signing the treaty?', ['It was exactly five years after the assassination of Franz Ferdinand', 'It was Clemenceau’s birthday', 'It was the date of the armistice', 'It was the first day of the Somme'], 0, 'Franz Ferdinand was killed on 28 June 1914. The armistice was 11 November 1918; the Somme began on 1 July 1916.'),
  S('What was Clemenceau’s nickname? (two words: The …)', 'The Tiger', ['tiger'], 'Clemenceau was called ‘the Tiger’ for his fierce determination. He had seen France invaded twice, in 1870 and 1914.'),
  M('Why did Lloyd George face pressure at home to be harsh on Germany?', ['He had just won the 1918 election, in which many promised to ‘make Germany pay’', 'The British public wanted Germany to join the British Empire', 'Parliament had voted to occupy Berlin', 'The USA demanded he punish Germany'], 0, 'Public anger was high after huge losses. Privately Lloyd George wanted a less harsh peace so that Germany could recover and trade, and to avoid future revenge.'),
  M('What was the fourteenth of Wilson’s Fourteen Points?', ['The creation of a League of Nations', 'Reparations from Germany', 'An independent Poland', 'Return of Alsace-Lorraine to France'], 0, 'Point 14 called for an association of nations to keep peace. Poland and Alsace-Lorraine were also among the points, but not the fourteenth; reparations were not one of the points.'),
  M('Which of Wilson’s Fourteen Points did Britain particularly oppose?', ['Freedom of the seas', 'Creation of the League of Nations', 'Self-determination for Poland', 'Evacuation of Belgium'], 0, 'Britain relied on its navy and the blockade, so it rejected a principle of freedom of the seas for all in wartime. Britain supported Belgium’s freedom, which was why it entered the war.'),
  M('Why was Clemenceau determined to weaken Germany?', ['France had suffered around 1.4 million military deaths and much of north-east France was devastated', 'Germany had refused to trade with France', 'France had lost its empire to Germany', 'The French public wanted a friendly treaty'], 0, 'Fighting on French soil had destroyed towns, mines and farms. France wanted security and compensation so this could never happen again.'),
  M('What did the German navy do at Scapa Flow in June 1919?', ['Its crews deliberately sank (scuttled) the interned German fleet', 'It surrendered to the USA', 'It attacked the British fleet', 'It sailed to join the Russians'], 0, 'Rather than hand their ships to the Allies, German crews sank 52 ships on 21 June 1919. Britain was pleased to see the German fleet gone, though angry at the defiance.'),
  M('What did Lloyd George warn in the Fontainebleau Memorandum (March 1919)?', ['A harsh peace could drive Germany towards revenge or communism', 'Germany should lose all its land', 'Britain should leave the conference', 'The League should be abolished'], 0, 'Lloyd George argued that injustice would breed future war. This shows his middle position between Wilson and Clemenceau.'),
  M('Why could Wilson afford to be less harsh on Germany than Clemenceau?', ['The USA joined late, suffered far fewer deaths and its land was not damaged', 'The USA had won the war alone', 'Germany had promised to pay the USA', 'Wilson was German'], 0, 'The USA lost about 116,000 servicemen compared with France’s roughly 1.4 million and was never invaded. This shaped Wilson’s more idealistic approach.'),
  MU('Which TWO were aims of Clemenceau?', ['Separating the Rhineland from Germany as a buffer', 'Large reparations for French damage', 'Self-determination for Germans in all areas', 'Freedom of the seas', 'Allowing Germany a large army'], [0, 1], 'Clemenceau wanted security (a buffer zone) and compensation. He did not get the Rhineland separated, only demilitarised, with Allied occupation for 15 years.'),
  O('Put these events in chronological order.', ['Armistice', 'Paris Peace Conference opens', 'German fleet scuttled at Scapa Flow', 'Treaty of Versailles signed', 'US Senate first votes against the treaty'], 'November 1918 armistice; January 1919 conference opens; 21 June 1919 Scapa Flow; 28 June 1919 treaty signed; November 1919 Senate vote.'),
  W(src('Interpretation A: a historian writing in 2001.', 'The Treaty of Versailles was a compromise that satisfied none of the peacemakers fully.'), M('Which knowledge best SUPPORTS Interpretation A?', ['Clemenceau was criticised in France for being too lenient, while Germans said it was too harsh', 'Germany accepted the treaty happily', 'Wilson got all Fourteen Points included', 'Lloyd George got everything he wanted'], 0, 'Criticism from both sides shows a compromise. Wilson saw many points ignored, and Lloyd George worried it was too harsh, so the other options are inaccurate.')),
  T('Wilson wanted general disarmament, but under the peace treaties only the defeated powers were forced to disarm.', true, 'True. Germans resented being disarmed while the Allies kept their forces, which Hitler later used to justify rearmament.'),
  M('Why did the Italian Prime Minister, Orlando, walk out of the conference for a time?', ['Italy was not given all the land it had been promised, including the port of Fiume', 'Italy wanted harsher terms for Britain', 'He disagreed about the League’s headquarters', 'He wanted Germany to keep its colonies'], 0, 'Italy had joined the Allies in 1915 after promises of territory. Disappointment fed Italian nationalism and helped Mussolini rise to power.'),
]);
more('hist-y10-peace-league-2', [
  M('What limits did Versailles place on the German navy?', ['Six battleships and no submarines', 'No limits at all', 'Unlimited submarines but no battleships', 'Twenty battleships and a hundred submarines'], 0, 'Germany could have six battleships and no submarines. Its army was limited to 100,000 and it was forbidden an air force.'),
  M('What did Versailles say about union (Anschluss) between Germany and Austria?', ['It was forbidden', 'It had to happen within five years', 'It was allowed if France agreed', 'Austria became part of Germany immediately'], 0, 'The Allies did not want a larger, stronger Germany, so union was banned even though many Austrians wanted it. Hitler achieved Anschluss in 1938.'),
  S('Which Baltic port became a ‘free city’ under League of Nations control?', 'Danzig', ['gdansk'], 'Danzig had a mainly German population, but it gave Poland access to the sea. Hitler’s demands for it became a cause of war in 1939.'),
  M('Which small area was given to Belgium by the Treaty of Versailles?', ['Eupen and Malmedy', 'The Saar', 'Alsace-Lorraine', 'Danzig'], 0, 'Eupen-Malmedy went to Belgium. The Saar was run by the League; Alsace-Lorraine went to France; Danzig became a free city.'),
  M('How was it decided that North Schleswig would go to Denmark?', ['By a plebiscite (a vote of the local people) in 1920', 'By a war', 'By the Kaiser’s decision', 'By a coin toss at Versailles'], 0, 'Plebiscites let people choose in some border areas, applying self-determination. Germans complained this was not applied where it would have helped Germany.'),
  M('Roughly how many people did Germany lose in its European territory under Versailles?', ['About 6 million', 'About 60,000', 'About 60 million', 'None'], 0, 'Germany lost about 13% of its territory and around 6 million people, together with important coal and iron resources.'),
  M('Which terms did the Treaty of Saint-Germain (1919) impose on Austria?', ['Its army was limited to 30,000 and union with Germany was forbidden', 'It had to join Germany', 'It gained land from Italy', 'It had no restrictions'], 0, 'Austria lost large territories to new states such as Czechoslovakia and Yugoslavia, and to Italy. It became a small, economically weak country.'),
  M('What did Bulgaria lose under the Treaty of Neuilly (1919)?', ['Its coastline on the Aegean Sea, to Greece', 'Its capital city', 'All of its land', 'Its access to the Black Sea'], 0, 'Bulgaria lost its Aegean coast to Greece and land to Yugoslavia, and had to pay reparations. It kept its Black Sea coast.'),
  M('What happened to the Arab lands of the Ottoman Empire after the war?', ['They became mandates run by Britain (e.g. Iraq, Palestine) and France (e.g. Syria, Lebanon)', 'They became fully independent at once', 'They were given to Germany', 'They stayed part of Turkey'], 0, 'The League of Nations gave these mandates to Britain and France. Many Arabs felt betrayed, since they had been promised independence for helping against the Ottomans.'),
  MU('Which TWO new states were created or recreated in central and eastern Europe by the peace settlement?', ['Czechoslovakia', 'Yugoslavia', 'Austria-Hungary', 'Prussia', 'The Ottoman Empire'], [0, 1], 'Poland, Czechoslovakia and Yugoslavia emerged from the collapsed empires. Austria-Hungary and the Ottoman Empire were broken up; Prussia remained part of Germany.'),
  O('Put these events in chronological order.', ['Germany scuttles its fleet at Scapa Flow', 'Germany signs the Treaty of Versailles', 'The reparations bill is fixed', 'Germany defaults on a payment', 'France and Belgium occupy the Ruhr'], 'June 1919 scuttling; 28 June 1919 treaty; 1921 bill fixed; 1922 default; January 1923 Ruhr.'),
  W(src('Interpretation B: adapted from a British economist who resigned from the peace conference in 1919.', 'The treaty will reduce Germany to poverty and ruin the economy of all Europe. It is a peace of revenge, not of justice.'), M('Which knowledge would best SUPPORT Interpretation B?', ['Germany’s hyperinflation in 1923 followed the crisis over reparations', 'Germany recovered strongly in 1924–29', 'Germany kept most of its industrial areas', 'Reparations were reduced by the Dawes and Young Plans'], 0, 'The 1923 crisis seemed to prove the warning about economic ruin. Germany’s recovery and the reduction of reparations would challenge it.')),
  M('About three million German speakers lived in the Sudetenland of Czechoslovakia after 1919. Why did this cause later trouble?', ['Hitler used it to argue self-determination had been denied to Germans', 'They wanted to join Hungary', 'They had no language in common with Germany', 'They were evacuated to Britain'], 0, 'Germans complained that self-determination was applied to others but not to them. Hitler exploited this in 1938, leading to the Munich crisis.'),
  T('Under Versailles the Saar coalfield was run by the League of Nations for 15 years, with France taking its coal.', true, 'True. A plebiscite was to decide its future. In 1935 over 90% voted to return to Germany, a propaganda victory for Hitler.'),
  M('Which was a criticism of the peace treaties from the defeated countries?', ['They were not invited to negotiate and had to accept terms dictated to them', 'They gained too much land', 'They were allowed huge armies', 'They received reparations from the Allies'], 0, 'All the defeated powers were presented with terms. This sense of a dictated peace made the treaties seem unjust and fuelled nationalist anger.'),
]);
more('hist-y10-peace-league-3', [
  S('What was the founding document of the League of Nations, setting out its rules, called?', 'The Covenant', ['covenant', 'covenant of the league of nations', 'the covenant of the league'], 'The Covenant formed the first part of each peace treaty. Article 10 committed members to protect each other’s territory against aggression.', [['covenant']]),
  M('How many countries were founding members of the League in 1920?', ['42', '4', '200', '12'], 0, 'The League started with 42 members, rising to around 58 at its peak in the 1930s. The USA never joined.'),
  M('What was the Secretariat of the League?', ['Its civil service, which kept records and carried out decisions', 'Its army', 'The meeting of all member states', 'The court for legal disputes'], 0, 'The Secretariat handled administration. It was often too small for the work, which slowed the League down.'),
  M('Where was the Permanent Court of International Justice, linked to the League?', ['The Hague, in the Netherlands', 'Geneva', 'London', 'New York'], 0, 'The Court gave rulings on legal disputes between countries, but it could not force members to obey.'),
  M('What was the job of the League’s Mandates Commission?', ['To oversee the former colonies of Germany and Turkey run by Britain and France', 'To organise sanctions', 'To control the League’s army', 'To fix reparations'], 0, 'Mandates were meant to be prepared for independence. In practice they often looked like colonies, and the Commission had little power to change that.'),
  M('Which Norwegian explorer led the League’s work for refugees and prisoners of war?', ['Fridtjof Nansen', 'Roald Amundsen', 'Woodrow Wilson', 'Aristide Briand'], 0, 'Nansen helped return around 400,000 prisoners of war home and created the ‘Nansen passport’ for stateless refugees.'),
  M('What did the League’s Slavery Commission achieve in Sierra Leone?', ['It helped free around 200,000 enslaved people', 'It started a war', 'It opened new plantations', 'It ended all trade with Africa'], 0, 'The Commission worked to end slavery and forced labour. Its humanitarian work is often seen as the League’s most successful area.'),
  M('Why is the Vilna dispute (1920) seen as a League failure?', ['Poland seized Vilna from Lithuania and the League did not force it to withdraw', 'The League sent an army that lost', 'Lithuania invaded Germany', 'The League gave Vilna to Russia'], 0, 'Britain and France did not want to act against Poland, a likely ally against Germany or Russia. Poland kept Vilna, showing that aggression could succeed.'),
  M('How did the League deal with Upper Silesia (1921)?', ['It organised a plebiscite and divided the area between Germany and Poland', 'It gave all of it to France', 'It sent troops to occupy it permanently', 'It ignored the problem'], 0, 'After a plebiscite and violence, the League divided the region, and both countries accepted. It is usually counted as a success.'),
  M('What was the outcome of the Mosul dispute (1924–26) between Turkey and British-run Iraq?', ['The League awarded Mosul to Iraq and Turkey accepted', 'Turkey seized Mosul by force', 'Mosul became independent', 'The League gave it to Germany'], 0, 'This was a success, though critics point out it suited Britain, a leading League power.'),
  O('Put these events in chronological order.', ['The League’s first meeting', 'Germany joins the League', 'Japan leaves the League', 'The USSR joins the League', 'Italy leaves the League'], '1920 first meeting; 1926 Germany joins; 1933 Japan leaves; 1934 USSR joins; 1937 Italy leaves.'),
  T('Decisions in the League’s Assembly and Council usually had to be unanimous.', true, 'True. Every member had to agree, which made decisive action slow and difficult, especially when the powerful members disagreed.'),
  M('Which important 1921–22 agreement to limit navies was made outside the League?', ['The Washington Naval Conference', 'The Treaty of Versailles', 'The Dawes Plan', 'The Corfu settlement'], 0, 'The USA, Britain, Japan, France and Italy agreed to limit battleship sizes. That it took place outside the League suggests powerful states did not always use it.'),
  W(src('Source C: a description of a British cartoon from December 1919.', 'A bridge labelled ‘League of Nations’ has a large gap in the middle. Uncle Sam, representing America, sits lazily beside the missing keystone.'), M('What is the message of Source C?', ['The League would be weak without the USA, which had refused to join', 'The USA was building the League alone', 'The League was strong and complete', 'Britain had refused to join the League'], 0, 'The missing keystone represents the USA, whose absence leaves the bridge (the League) incomplete and unable to work. Britain was a leading member.')),
  M('Why do some historians argue that the Locarno Treaties (1925) showed a weakness of the League?', ['Major agreements were made by the great powers directly rather than through the League', 'Locarno was signed by the USA', 'Locarno started a war', 'Locarno ended the League'], 0, 'Locarno improved relations and led to Germany joining the League in 1926, but it showed that big powers preferred to make deals among themselves.'),
]);
more('hist-y10-peace-league-4', [
  S('What name did Japan give to the puppet state it created in Manchuria in 1932?', 'Manchukuo', ['manchuguo'], 'Japan made Puyi, the last Chinese emperor, the figurehead ruler of Manchukuo, but the Japanese army held real control.'),
  M('How long did the Lytton Commission take to report on Manchuria?', ['About a year', 'About a week', 'About ten years', 'It never reported'], 0, 'The commission travelled by ship and spent months investigating. By the time it reported in October 1932, Japan had already secured control of Manchuria.'),
  T('In 1932 Japanese forces also attacked the Chinese city of Shanghai.', true, 'True. Fighting at Shanghai in early 1932 showed Japan’s aggression was spreading beyond Manchuria while the League debated.'),
  M('What was the Walwal incident (December 1934)?', ['A clash between Italian and Abyssinian troops that Mussolini used as an excuse for war', 'The bombing of Shanghai', 'The Japanese seizure of Mukden', 'A border clash between Germany and Poland'], 0, 'Walwal was an oasis well inside Abyssinia. Mussolini demanded compensation and prepared for invasion, which came in October 1935.'),
  M('Why did Britain and France not close the Suez Canal to Italian ships?', ['They feared it might provoke war with Italy', 'They did not own the canal', 'The canal was already closed', 'Italy did not need it'], 0, 'Closing the canal would have cut Italy’s supply route to East Africa. Britain and France held back, which made the League’s response look half-hearted.'),
  M('What was the Stresa Front (April 1935)?', ['An agreement between Britain, France and Italy to stand together against German expansion', 'An Italian invasion plan', 'A League sanction', 'A naval agreement between Britain and Germany'], 0, 'Britain and France wanted Italy as an ally against Hitler, which made them reluctant to punish Mussolini over Abyssinia. The Front collapsed after the invasion.'),
  T('Italian forces used poison gas against Abyssinian soldiers and civilians.', true, 'True. Italy used mustard gas, breaking international agreements. Abyssinian forces were poorly equipped against tanks, aircraft and gas.'),
  M('When did Italian troops capture the Abyssinian capital, Addis Ababa?', ['May 1936', 'October 1935', 'September 1939', 'January 1935'], 0, 'Italy invaded in October 1935 and captured Addis Ababa in May 1936. Haile Selassie went into exile.'),
  M('What happened to the League’s sanctions against Italy in July 1936?', ['They were lifted', 'They were extended to include oil', 'They became a full military blockade', 'Italy agreed to obey them'], 0, 'With Abyssinia conquered, the sanctions were dropped. This showed the League could not reverse aggression by a major power.'),
  S('In which year did Italy leave the League of Nations?', '1937', [], 'Italy left in December 1937 and moved closer to Germany, joining the Anti-Comintern Pact the same year.'),
  MU('Which TWO factors help explain why Japan invaded Manchuria in 1931?', ['The Depression hit Japan’s trade, and Manchuria had valuable raw materials', 'The Japanese army had great influence and acted without full government control', 'The League had ordered Japan to occupy Manchuria', 'China had invaded Japan', 'The USA asked Japan to invade'], [0, 1], 'Manchuria offered coal, iron and land, and army officers pushed expansion. The League condemned the invasion; China had not attacked Japan.'),
  O('Put these events in chronological order.', ['Mukden Incident', 'Manchukuo set up', 'Lytton Report published', 'Japan leaves the League', 'Walwal incident', 'Italy invades Abyssinia'], 'September 1931 Mukden; 1932 Manchukuo; October 1932 Lytton Report; 1933 Japan leaves; December 1934 Walwal; October 1935 invasion.'),
  W(src('Source D: words of Emperor Haile Selassie to the League of Nations, 1936.', 'It is us today. It will be you tomorrow.'), M('What was Haile Selassie warning the League about?', ['If aggression against Abyssinia went unpunished, other countries would be attacked next', 'Abyssinia planned to attack Europe', 'He would leave the League immediately', 'The League should help Italy'], 0, 'He argued that the failure of collective security threatened every small nation. Events from 1936 to 1939 seemed to prove him right.')),
  M('Which piece of evidence best supports the view that the Depression was the main reason for the League’s failure in the 1930s?', ['Economic hardship pushed Japan and Italy to seek empires, and made members unwilling to impose sanctions', 'The League was based in Geneva', 'The League had a Slavery Commission', 'Germany joined the League in 1926'], 0, 'The Depression encouraged aggression and made countries put their own economies first. Other reasons, such as the absence of the USA, also matter in a ‘how far’ judgement.'),
  M('Why was Britain reluctant to take strong action against Japan over Manchuria?', ['It had trade interests with Japan and no strong forces in the area', 'Britain was allied with China against the League', 'Britain wanted to join Japan in the invasion', 'Britain had left the League'], 0, 'Manchuria was far away, Britain’s navy was stretched and it was badly hit by the Depression. It did not want a war in the Far East.'),
]);
// =====================================================================
// YEAR 11 — Conflict and tension: the road to war 1933–1939
// =====================================================================
addTopic(
  { id: 'hist-y11-road-to-war', strand: 'hist-conflict', year: 11, term: 1, name: 'The Road to War 1933–1939',
    summary: 'Hitler’s aims and actions, the policy of appeasement, the Munich Agreement, the Nazi–Soviet Pact and the outbreak of war in 1939.',
    specRef: 'AQA 8145 1B Conflict and tension, 1918–1939: Part three — The origins and outbreak of the Second World War' },
  [
    { name: "Hitler's aims and early actions 1933–36", intro: "Hitler aimed to overturn Versailles, unite all German speakers and win Lebensraum in the east. Between 1933 and 1936 he tested how far Britain and France would let him go.",
      items: [
        S("What German word means 'living space', which Hitler wanted in Eastern Europe?", "Lebensraum", ["lebensraum"], "Lebensraum meant taking land in the east (Poland, USSR) for German settlers — an aim set out in Mein Kampf."),
        MU("Which TWO were Hitler's foreign policy aims?", ["Overturn the Treaty of Versailles", "Unite all German-speaking people in one Reich", "Restore the Kaiser", "Join the League permanently", "Give colonies to Britain"], [0, 1], "Hitler's aims were: destroy Versailles, create a Greater Germany (Grossdeutschland), win Lebensraum and defeat communism."),
        M("What did Germany do in October 1933?", ["Left the League of Nations and the Disarmament Conference", "Invaded Poland", "Remilitarised the Rhineland", "Signed the Nazi–Soviet Pact"], 0, "Hitler claimed Germany was not treated equally on armaments; leaving freed him to rearm."),
        M("What happened in the Saar plebiscite of January 1935?", ["Over 90% voted to return to Germany", "The Saar joined France", "The vote was cancelled", "The Saar became independent"], 0, "This was allowed under Versailles and was a huge propaganda boost for Hitler."),
        T("In March 1935 Hitler openly announced conscription and the existence of the Luftwaffe, breaking Versailles.", true, "True. Britain, France and Italy protested (the Stresa Front, April 1935) but took no action."),
        M("What did the Anglo-German Naval Agreement (June 1935) allow?", ["Germany a navy up to 35% the size of Britain's surface fleet", "Britain to take Germany's navy", "Germany to have no navy", "France to control the Baltic"], 0, "Britain accepted a breach of Versailles without consulting France, undermining the Stresa Front."),
        S("Which demilitarised area did German troops enter on 7 March 1936?", "Rhineland", ["the rhineland"], "Hitler gambled that France would not resist; his generals had orders to withdraw if opposed. Nobody acted."),
        M("Why did Britain and France not stop the Rhineland remilitarisation?", ["France was in an election campaign and Britain felt Germany was 'walking into its own back garden'", "They had already invaded Germany", "The League ordered them not to", "The USA threatened them"], 0, "France would not act without Britain; many in Britain thought the Rhineland was German territory anyway. The Abyssinian crisis was also a distraction."),
        M("What did Germany and Italy do in the Spanish Civil War (1936–39)?", ["Helped Franco's Nationalists, giving German forces battle practice", "Supported the Republicans", "Stayed neutral", "Joined the League's peace force"], 0, "The Condor Legion bombed Guernica in April 1937, testing new tactics."),
        O("Put these events in chronological order.", ["Germany leaves the League", "Saar plebiscite", "Conscription announced", "Rhineland remilitarised", "Rome–Berlin Axis"], "October 1933; January 1935; March 1935; March 1936; October 1936."),
        M("What was the Anti-Comintern Pact (1936)?", ["An agreement between Germany and Japan (later Italy) against communism", "A pact between Britain and the USSR", "The League's anti-war treaty", "A trade deal between Germany and France"], 0, "It linked the future Axis powers against the Communist International."),
        W(src("Source A: a cartoon published in a British newspaper, March 1936, described.", "German soldiers goose-step over stepping stones labelled 'Rearmament', 'Saar' and 'Rhineland'. Hitler, holding a goose, smiles: 'The goose-step.' The next stones lie ahead."), M("What is the cartoonist suggesting?", ["Each unopposed step encouraged Hitler to take further steps", "Hitler had finished his plans", "The Rhineland was the last step", "Britain had stopped Hitler"], 0, "The stepping stones imply a sequence: each success led to the next — a criticism of letting Hitler get away with breaking Versailles.")),
        T("Mussolini protected Austria from Hitler in 1934 by moving troops to the Austrian border.", true, "True. After Austrian Nazis murdered Chancellor Dollfuss in July 1934, Mussolini moved troops to the Brenner Pass and Hitler backed down."),
        M("Why was rearmament popular in Germany?", ["It created jobs and restored national pride", "It reduced taxes to zero", "It was required by Versailles", "It ended all trade"], 0, "Rearmament helped cut unemployment and symbolised breaking the 'shameful' Diktat."),
        S("In which year did Germany remilitarise the Rhineland?", "1936", [], "7 March 1936 — Hitler later said the 48 hours afterwards were the most nerve-racking of his life."),
      ] },
    { name: 'Anschluss, Munich and appeasement', intro: "In 1938 Hitler united Germany with Austria and demanded the Sudetenland. Britain's Prime Minister Neville Chamberlain followed appeasement, culminating in the Munich Agreement.",
      items: [
        S("What German word describes the union of Germany and Austria in March 1938?", "Anschluss", [], "German troops entered Austria on 12 March 1938; a controlled plebiscite in April claimed 99.7% approval. It was forbidden by Versailles."),
        M("What is appeasement?", ["Giving in to reasonable demands to avoid war", "Declaring war immediately", "Joining the League", "Building alliances with the USSR"], 0, "Chamberlain believed some of Hitler's grievances about Versailles were reasonable and that satisfying them would keep peace."),
        MU("Which TWO were reasons for Britain's policy of appeasement?", ["Britain was not ready for war and needed time to rearm", "Many people thought Versailles had been too harsh on Germany", "Britain had a huge, modern army ready in 1935", "The USA demanded war", "Hitler had promised to give Germany's navy to Britain"], [0, 1], "Other reasons: memories of the First World War, the cost during the Depression, fear of communism and lack of support from the Empire."),
        M("Why did Hitler claim the Sudetenland?", ["About three million German speakers lived there and he said they were mistreated", "It had been German before 1919", "It was part of Austria", "The League gave it to him"], 0, "The Sudetenland had been part of Austria-Hungary, not Germany. Hitler used Henlein's Sudeten German Party to stir unrest."),
        O("Put Chamberlain's meetings with Hitler in order.", ["Berchtesgaden", "Bad Godesberg", "Munich"], "15 September 1938; 22 September 1938; 29–30 September 1938."),
        M("Which countries signed the Munich Agreement?", ["Britain, France, Germany and Italy", "Britain, France, Czechoslovakia and the USSR", "Germany, the USSR, Poland and Italy", "The USA, Britain, France and Germany"], 0, "Czechoslovakia and the USSR were not invited — the Czechs called it 'about us, without us'."),
        S("What phrase did Chamberlain use about the agreement on returning from Munich? (three words: 'peace for …')", "Peace for our time", ["peace for our time", "our time"], "Chamberlain waved the Anglo-German Declaration and said he believed it was 'peace for our time'. Crowds cheered."),
        T("At Munich, Czechoslovakia was given a full say in the decisions.", false, "False. Czechoslovakia was not represented and had to accept the loss of the Sudetenland and its border defences."),
        M("What did Hitler do in March 1939?", ["Occupied the rest of Czechoslovakia", "Invaded Poland", "Signed peace with Britain", "Withdrew from the Sudetenland"], 0, "On 15 March 1939 German troops took Prague. This was not German-speaking land, so it destroyed the justification for appeasement."),
        M("What was Britain's response to the occupation of Prague?", ["It guaranteed to defend Poland", "It declared war immediately", "It joined the Axis", "It recognised Hitler as Emperor"], 0, "On 31 March 1939 Britain and France guaranteed Polish independence — appeasement was over."),
        W(src("Interpretation A: a historian writing in 1961 (critic of appeasement).", "Appeasement was a policy of cowardice. Each surrender made Hitler stronger and more certain that Britain would never fight."), M("Which knowledge SUPPORTS Interpretation A?", ["After Munich Hitler took the rest of Czechoslovakia within six months", "Britain doubled spending on aircraft between 1938 and 1939", "Public opinion strongly supported Chamberlain in 1938", "The Empire's dominions did not want war in 1938"], 0, "Hitler's swift seizure of Prague suggests appeasement encouraged him. The other options support the opposite view — that Chamberlain was buying time or reflecting opinion.")),
        W(src("Interpretation B: a historian writing in 1990s (defender of appeasement).", "Chamberlain was a realist. Britain in 1938 was not ready to fight; Munich bought a year to build the radar and fighters that won the Battle of Britain."), M("Which knowledge CHALLENGES Interpretation B?", ["Germany also used the year to rearm, and gained Czech arms factories and fortifications", "Spitfire production increased in 1939", "Radar stations were completed in 1939", "The dominions were more willing to fight in 1939"], 0, "Germany gained the Skoda works and Czech defences, so the extra year helped Germany too. The other points support Interpretation B.")),
        M("Which British politician strongly criticised appeasement in the 1930s?", ["Winston Churchill", "Neville Chamberlain", "Lord Halifax", "Stanley Baldwin"], 0, "Churchill warned against German rearmament and called Munich 'a total and unmitigated defeat'."),
        T("Many British people were relieved and supportive when Chamberlain returned from Munich.", true, "True. Crowds cheered and newspapers praised him, though a minority (including Duff Cooper, who resigned) opposed it."),
        S("In which year was the Munich Agreement signed?", "1938", [], "The agreement was signed in the early hours of 30 September 1938."),
      ] },
    { name: 'The Nazi–Soviet Pact and the outbreak of war', intro: "In August 1939 the Nazi–Soviet Pact shocked the world and cleared the way for Hitler's invasion of Poland. Britain and France declared war on 3 September 1939.",
      items: [
        S("On what date was the Nazi–Soviet Pact signed? (day, month, year)", "23 August 1939", ["23rd august 1939", "august 23 1939", "23 august 1939"], "Foreign Ministers Ribbentrop and Molotov signed the pact in Moscow on 23 August 1939."),
        M("What did the secret part of the Nazi–Soviet Pact agree?", ["To divide Poland between Germany and the USSR", "That the USSR would attack Britain", "That Germany would give the USSR the Rhineland", "That both would join the League"], 0, "The secret protocol divided Eastern Europe into spheres of influence, including splitting Poland."),
        MU("Which TWO reasons explain why Stalin signed the pact?", ["He distrusted Britain and France after being excluded from Munich", "He needed time to build up the Red Army", "He admired Nazi ideology", "Britain had asked him to", "He wanted to defend Czechoslovakia"], [0, 1], "Stalin believed the West wanted Hitler to attack the USSR; slow British negotiations (sending a low-ranking delegation by ship) confirmed his suspicion. The pact bought time and land."),
        M("Why did Hitler want the pact?", ["To avoid fighting a war on two fronts when he invaded Poland", "Because he admired communism", "To join the League", "To protect Czechoslovakia"], 0, "With the USSR neutral, Hitler could invade Poland without facing Soviet opposition."),
        S("Which country did Germany invade on 1 September 1939?", "Poland", [], "German forces invaded Poland on 1 September; the USSR invaded from the east on 17 September."),
        M("On what date did Britain declare war on Germany?", ["3 September 1939", "1 September 1939", "30 September 1938", "15 March 1939"], 0, "Germany ignored a British ultimatum to withdraw from Poland; Chamberlain announced war on 3 September 1939."),
        T("Hitler believed Britain and France would not fight over Poland.", true, "True. After their inaction over the Rhineland, Austria and Czechoslovakia, Hitler doubted they would act — he reportedly called them 'little worms' he had seen at Munich."),
        O("Put these events in chronological order.", ["Anschluss", "Munich Agreement", "Occupation of Prague", "British guarantee to Poland", "Nazi–Soviet Pact", "Invasion of Poland"], "March 1938; September 1938; March 1939; 31 March 1939; 23 August 1939; 1 September 1939."),
        M("Which was the dispute over Danzig and the Polish Corridor about?", ["Hitler demanded the German-speaking free city of Danzig and a route across the Corridor", "Poland demanded Berlin", "Britain wanted Danzig", "The USSR wanted the Corridor for itself only"], 0, "Versailles had made Danzig a free city under the League and given Poland a corridor to the sea, separating East Prussia from Germany."),
        M("Which statement is the best judgement about the causes of war in 1939?", ["Hitler's aims were the main cause, but appeasement and the Nazi–Soviet Pact made war more likely and decided its timing", "Only Versailles caused the war", "Britain caused the war", "The League caused the war"], 0, "Strong answers link factors: Hitler's expansionist aims drove events, while appeasement encouraged him and the pact removed the last obstacle."),
        W(src("Source B: a cartoon published in a British newspaper, September 1939, described.", "Hitler and Stalin bow politely to each other over the body of a soldier labelled 'Poland'. Hitler says 'The scum of the earth, I believe?' Stalin replies 'The bloody assassin of the workers, I presume?'"), M("What is the message of Source B?", ["The pact was a cynical deal between bitter enemies at Poland's expense", "Hitler and Stalin were genuine friends", "Poland had defeated both", "The cartoonist admired the pact"], 0, "The polite bows contrast with their insults, showing the pact was opportunistic; the dead soldier shows Poland was the victim.")),
        T("The USSR joined the League of Nations in 1934.", true, "True. Stalin joined in 1934 seeking collective security against Hitler; the USSR was expelled in December 1939 after invading Finland."),
        M("What was the 'Pact of Steel' (May 1939)?", ["A military alliance between Germany and Italy", "A Soviet–Polish alliance", "An Anglo-French trade agreement", "The Nazi–Soviet Pact"], 0, "Germany and Italy promised to support each other in war."),
        S("Who was the Soviet Foreign Minister who signed the 1939 pact?", "Molotov", ["vyacheslav molotov"], "Molotov signed with Ribbentrop; the pact is often called the Molotov–Ribbentrop Pact."),
        M("For the essay 'The main reason for war in 1939 was appeasement. How far do you agree?' which plan is best?", ["Explain how appeasement encouraged Hitler, then other factors (Hitler's aims, Nazi–Soviet Pact, Versailles, League failure), then judge", "Only describe Munich", "Only list dates", "Argue just one side"], 0, "AQA 16-mark answers need balanced, developed explanation of the stated factor and others, with a sustained judgement."),
      ] },
  ],
  {
    overview: "Between 1933 and 1939 Hitler steadily dismantled the Treaty of Versailles: rearmament, the Rhineland, Anschluss and the Sudetenland. Britain and France followed appeasement until Hitler seized Prague in March 1939. The Nazi–Soviet Pact of August 1939 cleared the way for the invasion of Poland and war.",
    objectives: ["I can explain Hitler's aims and how he achieved them step by step.", "I can explain why Britain followed appeasement and evaluate interpretations of it.", "I can explain the significance of the Nazi–Soviet Pact.", "I can write a balanced 'How far do you agree?' essay on the causes of war."],
    keyWords: [
      { term: 'Appeasement', def: 'Giving in to demands to avoid war.' },
      { term: 'Anschluss', def: 'Union of Germany and Austria, March 1938.' },
      { term: 'Lebensraum', def: 'Living space in the east.' },
      { term: 'Remilitarisation', def: 'Putting troops back into a demilitarised area (the Rhineland, 1936).' },
      { term: 'Sudetenland', def: 'German-speaking border area of Czechoslovakia.' },
      { term: 'Munich Agreement', def: 'September 1938 deal giving Germany the Sudetenland.' },
      { term: 'Nazi–Soviet Pact', def: 'August 1939 non-aggression pact between Germany and the USSR.' },
    ],
    sections: [
      { title: 'Hitler’s steps', html: timeline([["Oct 1933", "Leaves League and Disarmament Conference"], ["Jan 1935", "Saar plebiscite"], ["Mar 1935", "Conscription announced"], ["Jun 1935", "Anglo-German Naval Agreement"], ["Mar 1936", "Rhineland remilitarised"], ["1936", "Spanish Civil War; Rome–Berlin Axis"], ["Mar 1938", "Anschluss"], ["Sep 1938", "Munich Agreement"], ["Mar 1939", "Prague occupied; guarantee to Poland"], ["23 Aug 1939", "Nazi–Soviet Pact"], ["1–3 Sep 1939", "Poland invaded; Britain and France declare war"]]) },
      { title: 'Why appeasement?', html: "<ul><li>Horror of another world war; strong public pacifism.</li><li>Belief that Versailles was too harsh.</li><li>Britain unready militarily; Depression made rearmament costly.</li><li>Fear of communism — Germany as a barrier against the USSR.</li><li>No support from the USA; the dominions reluctant to fight.</li></ul><div class=\"note\">Interpretations differ: 'guilty men' (cowardly, encouraged Hitler) versus 'realists' (bought time to rearm).</div>" },
      { title: 'Key people', html: people([["Adolf Hitler", "Aimed to destroy Versailles and win Lebensraum."], ["Neville Chamberlain", "British PM 1937–40; architect of appeasement."], ["Édouard Daladier", "French PM at Munich."], ["Joseph Stalin", "Soviet leader; signed the Nazi–Soviet Pact."], ["Winston Churchill", "Critic of appeasement."]]) },
      { title: 'Model answer: ‘How far do you agree?’ (16 marks)', html: worked("'The Nazi–Soviet Pact was the main reason war broke out in 1939.' How far do you agree?", ["Agree: the pact removed the threat of a two-front war — Hitler invaded Poland nine days later.", "Disagree: Hitler's long-term aims; appeasement encouraged him; Versailles grievances.", "Judgement: the pact explains the timing; Hitler's aims explain why war happened at all."], "Model judgement: The Nazi–Soviet Pact was the immediate reason war began in September 1939, because it guaranteed that the USSR would not defend Poland and gave Hitler confidence to invade just nine days later. However, it was not the main reason. Hitler had planned for Lebensraum in the east since Mein Kampf, and appeasement had convinced him that Britain and France would not fight. The pact therefore decided when war started, but Hitler's aims, encouraged by appeasement, explain why it happened.") },
    ],
    mistakes: ["Saying the Sudetenland was German before 1919 — it was part of Austria-Hungary.", "Thinking Britain declared war over Czechoslovakia — it was over Poland.", "Writing a one-sided 16-mark essay.", "Forgetting the USSR was excluded from Munich."],
    examTips: ["In 16-mark essays, explain the named factor AND other factors, then reach a clear, supported judgement.", "Spelling, punctuation and grammar earn 4 extra marks on this question.", "Use precise dates to show the sequence of Hitler's actions."],
    realLife: "'Appeasement' is still used in debates about how to deal with aggressive states today.",
  },
);

// ---- extra practice: The Road to War 1933–1939 ----
more('hist-y11-road-to-war-1', [
  M('What agreement did Hitler make with Poland in January 1934?', ['A ten-year non-aggression pact', 'A military alliance against the USSR', 'An agreement to return Danzig to Poland', 'A plan to divide Czechoslovakia'], 0, 'The pact made Hitler look peaceful and weakened France’s alliances in eastern Europe. He broke it when he invaded Poland in 1939.'),
  M('What happened in Austria in July 1934?', ['Austrian Nazis murdered Chancellor Dollfuss in a failed attempt to seize power', 'Germany and Austria united', 'Austria joined the League of Nations for the first time', 'Mussolini invaded Austria'], 0, 'Hitler had to disown the plotters because Mussolini moved troops to the border to protect Austria. In 1934 Hitler was not yet strong enough to defy Italy.'),
  M('In March 1935 Hitler announced plans for an army of what size, far beyond the Versailles limit of 100,000?', ['About 550,000 (36 divisions)', 'About 5,000', 'About 50 million', 'Exactly 100,000'], 0, 'Hitler announced conscription and a target of 36 divisions. Britain, France and Italy protested at Stresa but took no action.'),
  M('Which agreement did Hitler use as an excuse for remilitarising the Rhineland in 1936?', ['The Franco-Soviet Pact of 1935', 'The Treaty of Locarno', 'The Anglo-German Naval Agreement', 'The Kellogg-Briand Pact'], 0, 'Hitler claimed the Franco-Soviet mutual assistance treaty threatened Germany. In fact, sending troops into the Rhineland broke both Versailles and Locarno.'),
  MU('Which TWO factors made March 1936 a good moment for Hitler to enter the Rhineland?', ['Britain and France were distracted by the Abyssinian crisis', 'France was about to hold a general election', 'Germany had a larger army than France', 'The USA had promised to support Germany', 'The League had invited Germany to send troops'], [0, 1], 'The League was focused on Abyssinia and the French government was a caretaker before an election, so neither wanted to act. The German army was still weaker than the French army.'),
  M('Roughly how many German troops first entered the Rhineland in March 1936?', ['About 22,000, with orders to withdraw if the French resisted (according to some accounts)', 'About 2 million', 'About 200', 'None; only police went in'], 0, 'The force was small and Hitler later admitted the 48 hours afterwards were the most nerve-racking of his life. The gamble showed how far bluff could succeed.'),
  M('Which Spanish town was bombed by the German Condor Legion in April 1937?', ['Guernica', 'Madrid', 'Barcelona', 'Seville'], 0, 'The bombing of Guernica killed many civilians and shocked the world. For Germany the Spanish Civil War was a chance to test new aircraft and tactics.'),
  M('What was the Rome–Berlin Axis (1936)?', ['An agreement of friendship and cooperation between Italy and Germany', 'A railway line built by the Nazis', 'A military alliance between Germany and Britain', 'A League of Nations treaty'], 0, 'After Abyssinia and Spain drew them together, Mussolini spoke of an axis around which Europe would turn. It became a full military alliance in the Pact of Steel (1939).'),
  M('What was the aim of Göring’s Four-Year Plan (1936)?', ['To make Germany ready for war within four years and self-sufficient in key materials', 'To end rearmament', 'To pay back all reparations', 'To give workers four weeks’ holiday'], 0, 'The Four-Year Plan pushed rearmament and autarky (self-sufficiency), such as making synthetic oil and rubber. It shows that preparations for war were central to Nazi policy.'),
  S('What word describes the 1935 vote in which the people of the Saar chose to return to Germany?', 'Plebiscite', ['referendum'], 'A plebiscite is a direct vote by the people on a single issue. Over 90% in the Saar voted to rejoin Germany, a major propaganda success.'),
  O('Put these events in chronological order.', ['Germany leaves the League of Nations', 'Non-aggression pact with Poland', 'Murder of Dollfuss', 'Saar plebiscite', 'Conscription announced', 'Rhineland remilitarised'], 'October 1933 League; January 1934 Poland; July 1934 Dollfuss; January 1935 Saar; March 1935 conscription; March 1936 Rhineland.'),
  W(src('Interpretation A: a British historian writing in 1961.', 'Hitler had no detailed timetable for war. He was an opportunist who took advantage of the mistakes and weaknesses of others.'), M('Which knowledge best SUPPORTS Interpretation A?', ['Hitler moved into the Rhineland when Britain and France were distracted by Abyssinia', 'Hitler set out aims for living space in Mein Kampf in the 1920s', 'The Four-Year Plan aimed to prepare Germany for war', 'Hitler told his generals of his plans for expansion in 1937'], 0, 'Seizing a chance created by others’ distraction fits the idea of an opportunist. Mein Kampf, the Four-Year Plan and the 1937 meeting suggest long-term planning, which would challenge it.')),
  W(src('Source B: an imaginary extract in the style of a speech by Hitler to the Reichstag, May 1935.', 'Germany needs peace and desires peace. We have no wish to interfere in the affairs of other nations.'), M('Why might Hitler have made speeches like Source B in 1935?', ['To reassure Britain and France while Germany rearmed', 'Because he had given up his aims', 'To announce the invasion of Poland', 'To ask to rejoin the Treaty of Versailles'], 0, 'Peaceful words calmed foreign opinion and made appeasement seem reasonable, while rearmament continued. Historians compare such statements with his actions.')),
  T('The Anglo-German Naval Agreement (1935) angered France because Britain accepted a German breach of Versailles without consulting it.', true, 'True. By agreeing that Germany could build a navy up to 35% of Britain’s, Britain showed it would make its own deals, which weakened the Stresa Front.'),
  M('Which group of people did Hitler want to unite in one state (Grossdeutschland)?', ['All German-speaking people, including those in Austria and Czechoslovakia', 'All Slavic peoples', 'All Europeans', 'Only the people of Prussia'], 0, 'Uniting German speakers was a key aim and a reason for the Anschluss and the Sudeten crisis. Hitler saw Slavs as inferior and wanted their land, not to unite with them.'),
]);
more('hist-y11-road-to-war-2', [
  M('Who was the Austrian Chancellor who planned a plebiscite on independence in March 1938?', ['Kurt Schuschnigg', 'Engelbert Dollfuss', 'Arthur Seyss-Inquart', 'Konrad Henlein'], 0, 'Schuschnigg hoped Austrians would vote for independence. Hitler forced him to resign and German troops crossed the border before the vote could take place. Dollfuss had been murdered in 1934.'),
  M('Which Austrian Nazi was made Chancellor and invited German troops into Austria?', ['Arthur Seyss-Inquart', 'Kurt Schuschnigg', 'Ernst Röhm', 'Konrad Henlein'], 0, 'Seyss-Inquart’s ‘invitation’ gave the invasion a cover of legality. He later governed the occupied Netherlands and was executed after Nuremberg.'),
  M('What did the official result of the April 1938 plebiscite on Anschluss claim?', ['Over 99% approved of union with Germany', 'Most Austrians rejected union', 'About half approved', 'No vote was ever held'], 0, 'The Nazi-controlled vote recorded over 99% approval, with Jews and opponents excluded and intimidation widespread. Even so, many Austrians did welcome the union.'),
  M('Who led the Sudeten German Party, which demanded self-rule and then union with Germany?', ['Konrad Henlein', 'Edvard Beneš', 'Kurt Schuschnigg', 'Neville Chamberlain'], 0, 'Henlein worked closely with Hitler, making demands that the Czech government could not accept. Beneš was President of Czechoslovakia.'),
  MU('Which TWO factors made the Sudetenland valuable to Czechoslovakia?', ['It contained the country’s main border fortifications', 'It contained important industries and resources', 'It was the location of the capital, Prague', 'It was the country’s only coastline', 'It had no German speakers'], [0, 1], 'Losing the Sudetenland left Czechoslovakia almost defenceless and weakened its economy. Prague was not in the Sudetenland, and Czechoslovakia had no coastline.'),
  W(src('Source C: from a radio broadcast by Neville Chamberlain, 27 September 1938.', 'a quarrel in a faraway country between people of whom we know nothing'), M('What attitude does Chamberlain show in Source C?', ['Britain should not risk war over a distant dispute that most Britons knew little about', 'Britain must go to war at once to save Czechoslovakia', 'Czechoslovakia was Britain’s closest ally', 'The Sudeten Germans were British citizens'], 0, 'Chamberlain reflected the feeling that war over the Sudetenland was not worth British lives. Critics argue this ignored the strategic importance of Czechoslovakia.')),
  M('Which British Cabinet minister resigned in protest at the Munich Agreement?', ['Duff Cooper', 'Lord Halifax', 'Stanley Baldwin', 'Clement Attlee'], 0, 'Duff Cooper, First Lord of the Admiralty, resigned. Halifax was Foreign Secretary and supported Chamberlain; Attlee led the Labour opposition.'),
  T('After Munich, Poland and Hungary also took parts of Czechoslovak territory.', true, 'True. Poland took Teschen and Hungary took southern areas, so Czechoslovakia was dismembered by several neighbours, not only Germany.'),
  T('The USSR was not invited to the Munich Conference.', true, 'True. Stalin, who had an alliance with Czechoslovakia, was excluded. This increased his distrust of Britain and France and helps explain the Nazi–Soviet Pact.'),
  M('What did Hitler claim about the Sudetenland in September 1938?', ['It was his last territorial demand in Europe', 'He did not want it', 'He would give it back after one year', 'It belonged to Poland'], 0, 'Hitler said the Sudetenland was his last territorial demand. Six months later he occupied the rest of Czechoslovakia, proving he could not be trusted.'),
  W(src('Interpretation C: from a book published in July 1940, attacking the politicians who had led Britain in the 1930s.', 'These guilty men left Britain unprepared and handed Hitler victory after victory.'), M('Which context best explains the angry tone of Interpretation C?', ['It was written just after Dunkirk and the fall of France, when Britain faced invasion', 'It was written during the Golden Years of Weimar', 'It was written by Chamberlain himself', 'It was written after Britain won the war'], 0, 'In 1940 Britain was in danger and people looked for someone to blame. The book helped create the long-lasting view of appeasement as a shameful failure.')),
  M('What happened to Slovakia in March 1939?', ['It became a separate state under German protection', 'It joined Poland', 'It joined the USSR', 'It became part of Austria'], 0, 'Hitler encouraged Slovak independence, then occupied Bohemia and Moravia (the Czech lands) as a German ‘protectorate’, ending Czechoslovakia.'),
  M('Which port did Germany take from Lithuania in March 1939?', ['Memel', 'Danzig', 'Riga', 'Gdynia'], 0, 'Lithuania handed Memel to Germany under pressure days after the occupation of Prague. Danzig was a free city; Riga is in Latvia; Gdynia was Polish.'),
  O('Put these events in chronological order.', ['German troops enter Austria', 'Chamberlain’s first meeting with Hitler at Berchtesgaden', 'The Munich Agreement', 'German troops occupy Prague', 'Britain guarantees Poland'], 'March 1938 Anschluss; 15 September 1938 Berchtesgaden; 29–30 September Munich; 15 March 1939 Prague; 31 March 1939 guarantee to Poland.'),
  M('Which of these was a reason many in Britain sympathised with Germany over the Sudetenland in 1938?', ['They felt the Treaty of Versailles had been too harsh and that German speakers had a right to join Germany', 'They wanted Germany to have colonies in Africa', 'They believed Czechoslovakia had attacked Germany', 'They wanted Britain to join the Axis'], 0, 'Many believed Versailles was unfair and that self-determination supported Germany’s claim. This made appeasement seem fair as well as practical.'),
]);
more('hist-y11-road-to-war-3', [
  M('Why did the Anglo-French military mission to Moscow in August 1939 fail to impress Stalin?', ['It travelled slowly by ship and its members lacked the power to make decisions', 'It offered Stalin control of Germany', 'It arrived by aeroplane with Chamberlain', 'It refused to meet Soviet leaders'], 0, 'The slow, low-level mission suggested Britain and France were not serious. Meanwhile Hitler sent his Foreign Minister to sign a deal quickly.'),
  M('Which country refused to allow Soviet troops onto its territory, blocking an Anglo-French–Soviet alliance?', ['Poland', 'Britain', 'Italy', 'Spain'], 0, 'Poland feared that Soviet troops, once inside, would never leave. Without this access, an alliance to protect Poland was hard to make work.'),
  M('What was the Gleiwitz incident (31 August 1939)?', ['A fake Polish attack on a German radio station staged by the SS as an excuse for invasion', 'The first battle of the Battle of Britain', 'A British air raid on Berlin', 'A Soviet attack on Finland'], 0, 'SS men in Polish uniforms ‘attacked’ the station. Hitler used such incidents to claim Germany was acting in self-defence.'),
  M('On what date did the USSR invade eastern Poland?', ['17 September 1939', '1 September 1939', '3 September 1939', '22 June 1941'], 0, 'The Soviet invasion followed the secret protocol of the Nazi–Soviet Pact. 22 June 1941 was when Germany invaded the USSR.'),
  M('By when had organised Polish resistance largely ended?', ['Early October 1939', 'Christmas 1939', 'Summer 1940', 'Within one day'], 0, 'Attacked from both sides, Poland was defeated within about five weeks. Britain and France gave little direct military help.'),
  M('What did Britain’s ultimatum to Germany on 3 September 1939 demand?', ['That Germany withdraw from Poland by 11 a.m. or a state of war would exist', 'That Germany hand over its navy', 'That Hitler resign', 'That Germany leave Austria'], 0, 'No reply came, so Chamberlain announced on the radio that Britain was at war with Germany. France declared war later the same day.'),
  T('Italy did not enter the war until June 1940, despite the Pact of Steel.', true, 'True. Mussolini said Italy was not ready in 1939. He declared war on Britain and France on 10 June 1940, as France was collapsing.'),
  S('Who was the German Foreign Minister who signed the Nazi–Soviet Pact?', 'Joachim von Ribbentrop', ['ribbentrop', 'von ribbentrop'], 'Ribbentrop flew to Moscow and signed with Molotov on 23 August 1939, which is why it is also called the Molotov–Ribbentrop Pact.', [['ribbentrop']]),
  M('What did the Nazi–Soviet Pact include besides a promise not to attack each other?', ['Trade arrangements for Soviet raw materials to go to Germany', 'A joint invasion of Britain', 'Soviet membership of the Axis', 'A promise to restore the Kaiser'], 0, 'Trade agreements supplied Germany with oil, grain and other materials, which helped it resist the British blockade during 1939–41.'),
  O('Put these events of 1939 in chronological order.', ['Nazi–Soviet Pact signed', 'Anglo-Polish alliance signed', 'Gleiwitz incident', 'Germany invades Poland', 'Britain declares war on Germany', 'USSR invades Poland'], '23 August pact; 25 August Anglo-Polish alliance; 31 August Gleiwitz; 1 September invasion; 3 September war declared; 17 September Soviet invasion.'),
  M('What was the Hossbach Memorandum (November 1937)?', ['A record of a meeting at which Hitler told his military leaders of plans to expand by force', 'A British plan for appeasement', 'A Soviet offer of alliance to Britain', 'The agreement ending the Spanish Civil War'], 0, 'It records Hitler discussing seizing Austria and Czechoslovakia. Historians who blame Hitler’s long-term aims for the war often use it as evidence, though some debate how far it was a fixed plan.'),
  MU('Which TWO reasons explain why Britain went to war over Poland when it had not over Czechoslovakia?', ['The occupation of Prague showed Hitler’s promises could not be trusted', 'Britain had rearmed considerably since 1938', 'Poland had a larger German population than the Sudetenland', 'The USA had promised to join immediately', 'Hitler had asked Britain to declare war'], [0, 1], 'After Prague, appeasement was discredited and Britain gave a guarantee to Poland. Rearmament, especially of the RAF, gave Britain more confidence. The USA stayed neutral until December 1941.'),
  M('Why did Hitler believe Britain and France would not fight for Poland?', ['They had backed down over the Rhineland, Austria and Czechoslovakia', 'They had signed an alliance with Germany', 'They had no armies at all', 'Poland had asked them not to help'], 0, 'Repeated appeasement convinced Hitler the democracies were weak. He reportedly said he had seen the British and French leaders at Munich and thought them ‘little worms’.'),
  M('Which statement best describes the importance of the Nazi–Soviet Pact as a cause of war?', ['It removed the threat of a two-front war, so Hitler felt free to invade Poland', 'It made war impossible', 'It forced Britain to join the Axis', 'It was unimportant because Hitler never invaded Poland'], 0, 'With the USSR neutral and sharing Poland, Hitler could attack without fearing war in the east, which made war in 1939 far more likely.'),
  T('Britain and France sent large armies into Poland to defend it in September 1939.', false, 'False. Britain and France declared war but could do little to help Poland directly. France made only a brief, limited advance into the Saar.'),
]);
// =====================================================================
// YEAR 11 — Britain: Health and the people c1000–present
// =====================================================================
addTopic(
  { id: 'hist-y11-health-people', strand: 'hist-health', year: 11, term: 2, name: 'Britain: Health and the People c1000–Present',
    summary: 'How ideas about the causes and treatment of disease, surgery and public health changed from medieval times to today, and the factors that drove change.',
    specRef: 'AQA 8145 2A Britain: Health and the people, c1000 to the present day' },
  [
    { name: 'Medieval medicine c1000–c1500', intro: "Medieval medicine was based on the ancient ideas of Hippocrates and Galen, supported by the Church. Explanations mixed the Four Humours, religion, astrology and miasma.",
      items: [
        M("What were the Four Humours?", ["Blood, phlegm, yellow bile and black bile", "Earth, air, fire and water only", "Bacteria, viruses, fungi and parasites", "Heart, lungs, liver and brain"], 0, "The theory said illness came from an imbalance of the four humours. It linked to the elements and seasons but the humours themselves were the body fluids."),
        S("Which Greek doctor (c.460–370 BC) developed the Theory of the Four Humours and stressed observation?", "Hippocrates", [], "Hippocrates encouraged clinical observation; his oath is still referenced today."),
        M("Who was Galen?", ["A Greek doctor in the Roman Empire whose ideas dominated medicine for 1,400 years", "A medieval English king", "An Islamic surgeon", "A 19th-century scientist"], 0, "Galen (2nd century AD) developed the Theory of Opposites and wrote extensively on anatomy, mostly from animal dissection."),
        M("What was Galen's Theory of Opposites?", ["Treat an imbalance with its opposite, e.g. cucumber for a fever", "Bleed everyone", "Pray for the opposite of an illness", "Opposite blood groups"], 0, "If a patient had too much hot, wet blood, a doctor might prescribe something cold, e.g. cucumber, or bleed them."),
        MU("Why did the Church support Galen's ideas? Choose TWO.", ["Galen believed in a single creator, which fitted Christian teaching", "The Church controlled education and discouraged challenging ancient authorities", "Galen was a Christian saint", "Galen had proved germ theory", "Galen worked for the Pope"], [0, 1], "Galen's idea that the body was designed by a creator suited the Church, which ran universities and discouraged dissent."),
        M("Which of these was a medieval treatment based on the Four Humours?", ["Bloodletting", "Vaccination", "Antibiotics", "Chemotherapy"], 0, "Bloodletting (cutting a vein or using leeches) removed 'excess' blood to rebalance humours."),
        S("What was the name for bad air believed to cause disease?", "Miasma", [], "Miasma theory lasted from ancient times to the 1860s. It led to some useful measures, like cleaning streets, for the wrong reasons."),
        M("Who was Ibn Sina (Avicenna)?", ["A Persian doctor whose Canon of Medicine was used in European universities", "A Roman emperor", "The founder of St Bartholomew's Hospital", "The inventor of the printing press"], 0, "Ibn Sina's Canon (c.1025) organised Greek and Islamic knowledge and was translated into Latin."),
        M("Who mainly cared for the sick in medieval England?", ["Women in the home, using herbal remedies", "Trained hospital doctors", "The government", "Pharmacists in chain stores"], 0, "Most people were treated at home by women. Physicians were expensive and few."),
        T("Medieval hospitals mainly focused on caring for patients rather than curing them.", true, "True. Most hospitals were run by the Church and offered rest, food and prayer — care, not cure. Many refused contagious patients."),
        M("What was a urine chart used for?", ["Diagnosing illness by the colour, smell and taste of urine", "Measuring rainfall", "Recording deaths", "Counting patients"], 0, "Physicians compared urine samples with a chart to diagnose imbalances — part of Galenic medicine."),
        M("Which statement about the Black Death (1348) is correct?", ["People blamed God, miasma and the planets; treatments did not work", "It was cured by vaccination", "Doctors knew rats spread it", "It killed only the rich"], 0, "Lack of germ theory meant treatments were ineffective; some measures (quarantine in some towns) helped by chance."),
        O("Put these in chronological order.", ["Hippocrates", "Galen", "Ibn Sina's Canon of Medicine", "Black Death reaches England", "Printing press used in England"], "c.400 BC; 2nd century AD; c.1025; 1348; 1476 (Caxton)."),
        T("Galen's anatomy was always accurate because he dissected human bodies.", false, "False. Galen dissected mainly animals (pigs, apes), so he made mistakes — e.g. about the human jawbone and the septum of the heart."),
        M("Which factor most held back medical progress in the Middle Ages?", ["Belief in ancient authorities, supported by the Church", "Too many scientists", "Government investment", "Microscopes"], 0, "Respect for Galen and Church control of learning discouraged new ideas."),
        S("What word describes a doctor who had trained at university, rather than a barber-surgeon?", "Physician", ["physicians"], "Physicians trained at university for years and were expensive; surgeons and barber-surgeons learned by apprenticeship."),
      ] },
    { name: 'Renaissance and early modern medicine c1500–c1800', intro: "The Renaissance encouraged questioning. Vesalius, Paré and Harvey challenged Galen, while the printing press spread ideas. Jenner's vaccination of 1796 was a major breakthrough.",
      items: [
        S("Who published 'The Fabric of the Human Body' in 1543, correcting Galen's anatomy?", "Andreas Vesalius", ["vesalius"], "Vesalius dissected human bodies and found over 300 errors in Galen, e.g. the jawbone is one bone, not two."),
        M("What did William Harvey discover (published 1628)?", ["Blood circulates around the body, pumped by the heart", "Germs cause disease", "Chloroform anaesthetic", "Vaccination"], 0, "Harvey showed the heart acts as a pump and blood circulates — contradicting Galen, who thought blood was made in the liver and used up."),
        M("Which surgeon replaced cauterisation with ligatures and a soothing ointment?", ["Ambroise Paré", "Joseph Lister", "John Snow", "Edward Jenner"], 0, "Paré, a French army surgeon, ran out of boiling oil in 1537 and used an egg yolk, rose oil and turpentine mix, finding wounds healed better."),
        MU("Which TWO factors helped Renaissance medicine?", ["The printing press spread new ideas quickly and accurately", "Better artistic skill improved anatomical drawings", "The Church banned all dissection", "Germ theory was understood", "Antibiotics were available"], [0, 1], "Printing (from the 1440s) and artistic realism helped Vesalius's ideas spread. Germ theory came in the 1860s and antibiotics in the 20th century."),
        T("Harvey's discovery immediately transformed the treatment of patients.", false, "False. Bloodletting continued for 200 years. Harvey's work improved understanding of the body, but did not lead to new treatments at the time."),
        M("What did people believe caused the Great Plague of 1665?", ["Miasma and God's punishment, among other ideas", "Bacteria spread by fleas", "A virus", "Poor diet only"], 0, "Ideas had changed little since 1348. Responses were more organised: searchers, quarantine of houses (marked with a red cross) and killing cats and dogs."),
        S("In which year did Edward Jenner test his smallpox vaccination on James Phipps?", "1796", [], "Jenner infected Phipps with cowpox and then smallpox; the boy did not catch smallpox."),
        M("Why did some people oppose Jenner's vaccination?", ["He could not explain how it worked, and some doctors earned money from inoculation", "It had no effect on anyone", "It was too cheap", "The government banned it"], 0, "Germ theory did not yet exist. Inoculators lost income, and some people feared using animal material."),
        M("What did the government do about smallpox vaccination in 1853?", ["Made it compulsory for babies", "Banned it", "Paid people to avoid it", "Gave it only to soldiers"], 0, "Parliament gave grants for vaccination in 1840 and made it compulsory in 1853, an early example of government action on health."),
        M("What was the Royal Society (founded 1660)?", ["A group that encouraged scientific experiment and shared findings", "The royal family's doctors", "A hospital for the poor", "A church charity"], 0, "Its journal spread ideas; Charles II's support helped make science respectable."),
        T("Thomas Sydenham, 'the English Hippocrates', emphasised observing patients' symptoms closely.", true, "True. Sydenham (1624–89) stressed careful observation and classifying diseases, but still believed in the humours."),
        O("Put these in chronological order.", ["Paré's new treatment of wounds", "Vesalius publishes The Fabric of the Human Body", "Harvey publishes on circulation", "Great Plague of London", "Jenner's vaccination"], "1537; 1543; 1628; 1665; 1796."),
        M("How did vaccination differ from inoculation?", ["Vaccination used cowpox, which was much safer than giving people a mild dose of smallpox", "Inoculation used cowpox", "There was no difference", "Vaccination used antibiotics"], 0, "Inoculation (popularised by Lady Mary Wortley Montagu around 1721) gave a mild smallpox infection that could kill or spread. Cowpox was far safer."),
        W(src("Source A: an illustration from Vesalius's book, 1543, described.", "A detailed drawing of a standing human skeleton, accurately showing bones and muscles, drawn by a trained artist from a real dissection."), M("Why is Source A useful for studying Renaissance medicine?", ["It shows the new emphasis on accurate observation of the human body, made possible by dissection, art and printing", "It proves germ theory", "It shows medieval urine charts", "It shows treatments for plague"], 0, "Its accuracy, its origin in human dissection and its printed reproduction show the key Renaissance factors.")),
        M("Which factor is best shown by Jenner's breakthrough?", ["The role of an individual's observation and experiment", "The role of war", "The role of the Church", "The role of the NHS"], 0, "Jenner investigated a milkmaid's claim that cowpox protected against smallpox — individual genius plus observation."),
      ] },
    { name: 'The 19th century: germs, surgery and public health', intro: "The 1800s brought germ theory, anaesthetics, antiseptics and government action on public health. Pasteur, Koch, Simpson, Lister, Nightingale, Snow and Chadwick all played key roles.",
      items: [
        S("Which French scientist published germ theory in 1861?", "Louis Pasteur", ["pasteur"], "Pasteur's swan-neck flask experiments showed microbes in the air caused decay, disproving spontaneous generation."),
        M("What was Robert Koch's contribution?", ["He identified the specific bacteria that cause diseases such as anthrax, TB and cholera", "He invented chloroform", "He built London's sewers", "He discovered penicillin"], 0, "Koch identified anthrax (1876), TB (1882) and cholera (1883) bacteria and developed staining techniques."),
        M("What did James Simpson discover in 1847?", ["The anaesthetic properties of chloroform", "Carbolic acid", "Germ theory", "X-rays"], 0, "Chloroform solved the problem of pain, though early use could be dangerous and some opposed it — until Queen Victoria used it in childbirth in 1853."),
        S("Which antiseptic did Joseph Lister use from 1865?", "Carbolic acid", ["carbolic", "phenol"], "Lister sprayed carbolic acid in operating theatres and on wounds; death rates after amputation fell sharply."),
        MU("What were the 'three problems' of surgery before the late 1800s? Choose TWO of them.", ["Pain", "Infection", "Shortage of hospital beds", "Lack of surgeons' uniforms", "Too many antibiotics"], [0, 1], "The three problems were pain, infection and bleeding. Anaesthetics, antiseptics and later blood transfusions solved them."),
        T("The 'black period' of surgery refers to a rise in deaths after anaesthetics allowed longer, more complex operations without antiseptics.", true, "True. Surgeons attempted deeper operations, but without antiseptics infection killed many patients until Lister's methods spread."),
        M("How did John Snow prove that cholera spread through water (1854)?", ["He mapped deaths around the Broad Street pump and had its handle removed", "He found the cholera bacterium under a microscope", "He vaccinated the people of London", "He built new sewers"], 0, "Snow's map showed deaths clustered around the pump; after the handle was removed cases fell. He did not identify the bacterium (Koch did, 1883)."),
        M("What did Edwin Chadwick's 1842 report argue?", ["Poor living conditions caused disease, and cleaning up towns would save money", "Germs did not exist", "Doctors were overpaid", "Cholera came from planets"], 0, "His Report on the Sanitary Condition of the Labouring Population linked dirt, disease and poverty and led to the 1848 Public Health Act."),
        M("What was the key difference between the 1848 and 1875 Public Health Acts?", ["The 1848 Act was voluntary; the 1875 Act made councils provide clean water and sewers", "The 1848 Act was compulsory; the 1875 Act was voluntary", "Both created the NHS", "Neither had any effect"], 0, "Laissez-faire attitudes made the 1848 Act weak. By 1875, after the vote was extended to working men in 1867 and germ theory emerged, compulsion was accepted."),
        S("What 1858 event in London pushed Parliament to fund Bazalgette's sewers? (two words)", "Great Stink", ["the great stink"], "The smell of the Thames in the hot summer of 1858 reached Parliament; Joseph Bazalgette's sewer system followed."),
        M("Florence Nightingale's work at Scutari during the Crimean War improved…", ["Hygiene, sanitation and nursing, cutting the death rate dramatically", "Surgical anaesthesia", "Vaccination", "X-ray technology"], 0, "She cleaned the hospital, improved diet and ventilation; later she founded a nursing school at St Thomas' (1860)."),
        O("Put these in chronological order.", ["Chadwick's report", "Simpson uses chloroform", "Snow and the Broad Street pump", "Pasteur's germ theory", "Lister uses carbolic acid", "Public Health Act made compulsory"], "1842; 1847; 1854; 1861; 1865–67; 1875."),
        T("Mary Seacole ran the 'British Hotel' near the front line in the Crimean War, caring for soldiers.", true, "True. Seacole, a Jamaican-born nurse, funded her own trip after being rejected by the War Office."),
        W(src("Source B: a cartoon in Punch magazine, 1858, described.", "Father Thames, filthy and ragged, rises from the river and presents his children — cholera, diphtheria and scrofula — to the City of London."), M("What does Source B suggest?", ["The polluted Thames was spreading deadly diseases in London", "The Thames was clean", "London had beaten cholera", "Doctors were to blame"], 0, "Published in the year of the Great Stink, it shows growing public anger — useful for showing pressure on the government to act.")),
        M("Which factor best explains the 1875 Public Health Act?", ["Government — growing acceptance of state responsibility, helped by working men gaining the vote", "War", "Religion", "Chance alone"], 0, "After 1867 many working men could vote, so politicians had more reason to improve conditions in towns."),
      ] },
    { name: 'Modern medicine and the NHS', intro: "The 20th century saw the development of antibiotics, the welfare state and the NHS, and new technology such as DNA research. Government and science became the main drivers of change.",
      items: [
        S("Who discovered penicillin in 1928?", "Alexander Fleming", ["fleming"], "Fleming noticed mould killing bacteria on a petri dish, but could not purify or mass-produce it."),
        M("Who developed penicillin into a usable drug around 1940?", ["Howard Florey and Ernst Chain", "Pasteur and Koch", "Watson and Crick", "Simpson and Lister"], 0, "Florey and Chain purified it and tested it on mice and a human patient (Albert Alexander, 1941)."),
        M("Which factor was most important in the mass production of penicillin?", ["War — the US government funded production to treat soldiers before D-Day", "Religion", "The Black Death", "The printing press"], 0, "By D-Day (1944) US factories produced enough penicillin for the Allied forces."),
        MU("Which TWO Liberal reforms (1906–14) improved health?", ["Free school meals (1906)", "National Insurance Act (1911)", "The NHS (1948)", "The Public Health Act (1848)", "The Clean Air Act (1956)"], [0, 1], "The Liberals also introduced old age pensions (1908). These reforms followed reports by Booth and Rowntree and the poor health of Boer War recruits."),
        M("Why was the government alarmed by recruits for the Boer War (1899–1902)?", ["A large proportion of volunteers were too unhealthy to serve", "Too many volunteers were doctors", "Recruits were too old", "Recruits refused to fight"], 0, "In some cities over a third of volunteers were rejected as unfit, raising concerns about national efficiency."),
        S("Which 1942 report identified five 'giants' including disease and want?", "Beveridge Report", ["beveridge", "the beveridge report"], "William Beveridge's report proposed a welfare state 'from cradle to grave'."),
        S("Who was the Labour Minister of Health who created the NHS?", "Aneurin Bevan", ["bevan", "nye bevan", "aneurin nye bevan"], "Bevan launched the NHS on 5 July 1948 after negotiating with doctors who feared losing income and independence."),
        M("What were the three core principles of the NHS in 1948?", ["Universal, comprehensive and free at the point of use", "Private, paid and limited", "Only for children, only in London, only for workers", "Run by the Church"], 0, "The NHS was for everyone, covered all treatment and was free when used, funded by taxation."),
        T("Many doctors initially opposed the creation of the NHS.", true, "True. The BMA feared losing private income; Bevan said he 'stuffed their mouths with gold' by letting consultants keep private patients."),
        M("What did Watson and Crick discover in 1953?", ["The double-helix structure of DNA", "Penicillin", "Insulin", "Germ theory"], 0, "Their work, using Rosalind Franklin's X-ray images, led eventually to the Human Genome Project (completed 2003)."),
        M("What was the Clean Air Act (1956) a response to?", ["The Great Smog of London (1952), which killed around 4,000 people within days", "Cholera outbreaks", "The Black Death", "The First World War"], 0, "Smokeless zones were introduced; later estimates suggest the smog contributed to around 12,000 deaths in all."),
        O("Put these in chronological order.", ["Fleming discovers penicillin", "Beveridge Report", "NHS founded", "Structure of DNA discovered", "Smoking ban in enclosed public places in England"], "1928; 1942; 1948; 1953; 2007."),
        W(src("Source C: a government leaflet delivered to homes, 1948.", "Your new National Health Service begins on 5th July. It will provide you with all medical, dental and nursing care. Everyone — rich or poor, man, woman or child — can use it."), M("How useful is Source C for studying the NHS?", ["Useful for showing the principles the government promised, though as official publicity it does not show problems such as cost", "Useless because it is from the government", "It proves the NHS never had problems", "It shows NHS waiting lists in the 1990s"], 0, "The leaflet shows the aims (universal, comprehensive, free). Its purpose was to inform and reassure, so it would not mention difficulties like rising costs that led to prescription charges in 1952.")),
        M("Which is a challenge facing the NHS today?", ["Rising costs from an ageing population and expensive new treatments", "No patients", "Too few medicines discovered", "The Black Death"], 0, "People living longer and costly technology put pressure on funding — a continuity of the debate since prescription charges in 1952."),
        M("In a factors essay, which factor is best shown by the creation of the NHS?", ["Government (and the impact of war)", "Religion", "Chance", "Superstition"], 0, "Labour's government, helped by wartime experience of the Emergency Medical Service and the Beveridge Report, created the NHS."),
      ] },
  ],
  {
    overview: "This thematic study covers about a thousand years. Medieval medicine relied on Hippocrates, Galen and the Church; the Renaissance challenged old ideas; the 19th century brought germ theory, anaesthetics, antiseptics and public health laws; and the 20th century saw antibiotics, the NHS and genetic science. Exam questions focus on change, continuity, significance and factors.",
    objectives: ["I can explain medieval ideas about disease and why they lasted.", "I can explain the significance of Vesalius, Harvey, Paré and Jenner.", "I can explain how germ theory, anaesthetics and antiseptics transformed medicine and surgery.", "I can explain why the government took increasing responsibility for public health.", "I can evaluate the role of factors such as war, government, science and individuals."],
    keyWords: [
      { term: 'Four Humours', def: 'Blood, phlegm, yellow bile, black bile — imbalance thought to cause illness.' },
      { term: 'Miasma', def: 'Bad air believed to cause disease.' },
      { term: 'Germ theory', def: 'Pasteur’s 1861 theory that microbes cause decay and disease.' },
      { term: 'Anaesthetic', def: 'Substance that removes pain or consciousness during surgery.' },
      { term: 'Antiseptic', def: 'Chemical that kills germs on wounds and surfaces.' },
      { term: 'Aseptic surgery', def: 'Preventing germs entering (sterile instruments, gowns) rather than killing them.' },
      { term: 'Laissez-faire', def: 'The belief that government should not interfere in people’s lives.' },
      { term: 'Welfare state', def: 'System in which the government looks after citizens’ health and welfare.' },
    ],
    sections: [
      { title: 'Medieval and Renaissance ideas', html: "<p>Medieval doctors followed <b>Hippocrates</b> and <b>Galen</b>: the Four Humours, Theory of Opposites, bloodletting and purging. The <b>Church</b> controlled learning and backed Galen. The Renaissance brought challenge: <b>Vesalius</b> (anatomy, 1543), <b>Paré</b> (surgery), <b>Harvey</b> (circulation, 1628). The printing press spread these ideas, but treatments changed little until <b>Jenner</b>'s vaccination (1796).</p><div class=\"rule\">Key point: new knowledge did not always lead to new treatments straight away.</div>" },
      { title: 'Timeline of key developments', html: timeline([["c.1025", "Ibn Sina's Canon of Medicine"], ["1348", "Black Death"], ["1543", "Vesalius"], ["1628", "Harvey's circulation"], ["1665", "Great Plague"], ["1796", "Jenner's vaccination"], ["1842", "Chadwick's report"], ["1847", "Simpson: chloroform"], ["1854", "Snow: Broad Street pump"], ["1861", "Pasteur's germ theory"], ["1867", "Lister publishes on antiseptics"], ["1875", "Public Health Act"], ["1906–11", "Liberal reforms"], ["1928", "Fleming: penicillin"], ["1948", "NHS"], ["1953", "Structure of DNA"]]) },
      { title: 'Key people and factors', html: people([["Galen", "Ideas dominated for 1,400 years."], ["Vesalius", "Corrected Galen's anatomy through human dissection."], ["Jenner", "Smallpox vaccination."], ["Pasteur / Koch", "Germ theory; identified specific bacteria."], ["Lister", "Antiseptic surgery."], ["Nightingale", "Hygienic nursing."], ["Fleming, Florey, Chain", "Penicillin."], ["Aneurin Bevan", "Founded the NHS."]]) + "<p><b>Factors:</b> war (Paré, penicillin, Boer War, NHS), government (Public Health Acts, NHS), science and technology (microscopes, printing, DNA), individuals, religion (both hindered and helped), chance (Fleming, Paré), communication.</p>" },
      { title: 'Model answer: factor essay (16 marks)', html: worked("'War has been the main factor in the development of medicine in Britain.' How far do you agree? Refer to the period from medieval times to the present day.", ["Agree: Paré's ointment; penicillin's mass production; Boer War leading to Liberal reforms; WWII and the NHS.", "Disagree: science and individuals — Pasteur, Lister, Jenner; government acting in peacetime (1875); chance.", "Judgement: war often sped up change, but depended on science and government."], "Model paragraph: War played an important role in speeding up the development of penicillin. Fleming discovered it by chance in 1928 but lacked the funding to produce it. Florey and Chain proved it worked by 1941, but it was the Second World War that made it a priority: the US government funded factories so that enough penicillin existed to treat Allied soldiers by D-Day in 1944. However, war did not create penicillin — it accelerated a discovery already made by science, which suggests war was a catalyst rather than the main factor.") },
    ],
    mistakes: ["Saying Snow discovered the cholera germ — he linked cholera to water; Koch identified the bacterium.", "Thinking Harvey's discovery changed treatments immediately.", "Assuming the Church only held back medicine — it also ran hospitals and cared for the sick.", "Writing narrative in factor essays without linking to the factor in the question."],
    examTips: ["Paper 2 Section A: Q1 'How useful is Source A?' (8); Q2 'Explain the significance of…' (8); Q3 'Compare…' explain two ways similar/different (8); Q4 factor essay (16 + 4 SPaG).", "Significance = impact at the time AND long-term impact.", "Use examples from different periods (medieval, renaissance, industrial, modern) in the essay."],
    realLife: "Vaccination programmes, from Jenner's smallpox to modern vaccines, are a continuing story of medical progress and public debate.",
  },
);

// =====================================================================
// YEAR 11 — Elizabethan England c1568–1603
// =====================================================================
addTopic(
  { id: 'hist-y11-elizabethan-england', strand: 'hist-elizabeth', year: 11, term: 2, name: 'Elizabethan England c1568–1603',
    summary: 'Elizabeth I’s court and Parliament, life in the ‘Golden Age’, poverty and exploration, the Catholic threat and Mary Queen of Scots, and the Spanish Armada.',
    specRef: 'AQA 8145 2B Elizabethan England, c1568–1603' },
  [
    { name: "Elizabeth's court and Parliament", intro: "Elizabeth ruled through her Privy Council, patronage and a careful relationship with Parliament. The questions of marriage and succession, and the rivalry of favourites like Essex, caused tension.",
      items: [
        M("What was the Privy Council?", ["The queen's group of closest advisers who helped run the government", "The House of Commons", "The Church's ruling body", "Elizabeth's army"], 0, "Around 19 members (fewer later) advised on policy and carried out the queen's decisions; Elizabeth chose and could dismiss them."),
        S("Who was Elizabeth's chief minister, made Lord Burghley in 1571?", "William Cecil", ["cecil", "lord burghley", "burghley"], "Cecil served Elizabeth from 1558 until his death in 1598, as Secretary of State and then Lord Treasurer."),
        M("Who was Elizabeth's 'spymaster', who uncovered Catholic plots?", ["Sir Francis Walsingham", "Robert Dudley", "Francis Drake", "Walter Raleigh"], 0, "Walsingham, Principal Secretary from 1573, ran a network of agents and code-breakers."),
        M("Which favourite led a rebellion against Elizabeth's government in 1601?", ["Robert Devereux, Earl of Essex", "Robert Dudley, Earl of Leicester", "William Cecil", "Francis Walsingham"], 0, "After failing in Ireland (1599) and losing his monopoly on sweet wines, Essex tried to raise London in February 1601. He was executed."),
        S("What word describes the queen's power to grant titles, offices and lands to reward loyalty?", "Patronage", [], "Patronage bound nobles to Elizabeth; competition for it created factions at court."),
        M("Why did Elizabeth not marry?", ["Marriage risked giving power to a foreign prince or a rival English faction", "No one asked her", "Parliament banned it", "The Pope forbade it"], 0, "A foreign husband might drag England into his wars; an English one might create jealousy. Remaining single kept her independent — but left the succession uncertain."),
        MU("Which TWO areas did Elizabeth say were part of her royal prerogative, not for Parliament to discuss?", ["Her marriage and the succession", "Religion and foreign policy", "Taxation", "Local poor relief", "Road repairs"], [0, 1], "Elizabeth considered marriage, succession, religion and foreign policy to be her prerogative. Parliament's main role was to grant taxes and pass laws."),
        M("Who was the Puritan MP imprisoned for arguing for freedom of speech in Parliament?", ["Peter Wentworth", "William Cecil", "Thomas Babington", "Edmund Campion"], 0, "Wentworth was sent to the Tower several times and died there in 1597."),
        S("What was the name of Elizabeth's 1601 speech to Parliament after the monopolies dispute? (two words)", "Golden Speech", ["the golden speech"], "Elizabeth cancelled the worst monopolies and gave a speech praising her subjects' love — defusing a dangerous dispute."),
        T("Elizabeth called Parliament every year.", false, "False. Parliament met only 13 times in her 45-year reign, mainly when she needed taxes."),
        M("What was a monopoly?", ["The sole right to make or sell a product, granted by the monarch", "A board game", "A type of tax on land", "A church office"], 0, "Monopolies rewarded courtiers but raised prices, causing anger in Parliament by 1597–1601."),
        O("Put these events in chronological order.", ["Elizabeth becomes queen", "Cecil becomes Lord Burghley", "Walsingham becomes Principal Secretary", "Death of Robert Dudley", "Essex's rebellion"], "1558; 1571; 1573; 1588; 1601."),
        W(src("Interpretation A: a historian writing in 2004.", "Elizabeth was a skilful politician who managed her ministers and favourites with care, playing factions off against each other so that no one became too powerful."), M("Which knowledge best SUPPORTS Interpretation A?", ["She balanced cautious Cecil against more aggressive Dudley and Walsingham on the Council", "Essex launched a rebellion in 1601", "Parliament criticised monopolies", "She never married"], 0, "Balancing rival advisers supports the interpretation. Essex's rebellion could be used to challenge it — her control slipped in the 1590s.")),
        M("Why was Essex's rebellion a failure?", ["Londoners did not join him and he was quickly arrested", "The Spanish army defeated him", "Elizabeth joined him", "It succeeded"], 0, "Only around 300 followers marched; the government declared him a traitor and he surrendered the same day."),
        T("Robert Dudley was Elizabeth's long-standing favourite, and rumours suggested she might marry him.", true, "True. The mysterious death of his wife, Amy Robsart, in 1560 created scandal that made marriage impossible."),
      ] },
    { name: 'Life in Elizabethan England', intro: "The reign is often called a 'Golden Age' of theatre, architecture and exploration. But the 1590s also saw harvest failure, rising prices and poverty, which led to new Poor Laws.",
      items: [
        S("Which playwright's works were performed at the Globe Theatre, built in 1599?", "William Shakespeare", ["shakespeare"], "Shakespeare's company, the Lord Chamberlain's Men, built the Globe on the south bank of the Thames."),
        M("Who built The Theatre in Shoreditch in 1576, one of the first purpose-built playhouses in London?", ["James Burbage", "Christopher Marlowe", "Francis Drake", "Bess of Hardwick"], 0, "Burbage's Theatre was later dismantled and its timbers reused to build the Globe."),
        M("Why did Puritans oppose the theatre?", ["They thought plays encouraged immoral behaviour and drew people away from church", "They wanted more plays", "They owned the theatres", "Theatres were too quiet"], 0, "Puritan authorities in the City of London banned playhouses, so they were built outside the city's limits."),
        MU("Which TWO were causes of poverty in Elizabethan England?", ["Rapid population growth", "Inflation — rising prices, especially of food", "Huge increases in wages", "The end of the wool trade forever", "The NHS"], [0, 1], "Population rose from about 3 to over 4 million; prices rose faster than wages. Enclosure, bad harvests (1594–97) and the dissolution of monasteries also contributed."),
        M("How did Elizabethans view the 'deserving' poor?", ["People who could not work, such as the old, sick and orphans, who should be helped", "Vagabonds who refused to work", "Rich merchants", "Actors"], 0, "The 'undeserving' poor — able-bodied people who did not work — were feared and punished."),
        S("In which year was the Elizabethan Poor Law passed, lasting over 200 years?", "1601", [], "The 1601 Act made each parish collect a compulsory poor rate and appoint overseers to help the deserving poor."),
        M("What did the 1572 Vagabonds Act do?", ["Ordered beggars to be whipped and have a hole bored through their ear", "Gave vagabonds free houses", "Abolished all punishments", "Paid vagabonds to travel"], 0, "It was harsh, but it also required a local tax to help the deserving poor."),
        T("Sir Francis Drake was the first Englishman to sail around the world (1577–80).", true, "True. Drake returned in the Golden Hind with Spanish treasure worth a fortune; Elizabeth knighted him on board in 1581."),
        M("What happened to Walter Raleigh's colony at Roanoke (1585–87)?", ["It failed — the first colonists returned home and the later settlers disappeared", "It became New York", "It was a great success", "It was captured by France"], 0, "The 'lost colony' showed the difficulties of settlement; lasting English colonies came under James I (Jamestown 1607)."),
        MU("Which TWO helped encourage exploration?", ["Better navigational instruments and ships", "The hope of trade and wealth, including Spanish treasure", "A ban on all trade with Asia", "The Black Death", "The Poor Law"], [0, 1], "Improved astrolabes, maps and galleons, plus profits from trade and privateering, drove exploration."),
        M("What is a 'prodigy house'?", ["A large, showy country house built to impress, e.g. Hardwick Hall", "A poorhouse", "A theatre", "A ship"], 0, "Nobles built grand houses with lots of glass to display wealth and host the queen on her summer progresses."),
        M("What were the queen's 'progresses'?", ["Summer tours of southern England, staying with nobles", "Military campaigns", "Voyages of exploration", "Church services"], 0, "Progresses let Elizabeth be seen by her people and reduced court costs — hosts paid."),
        O("Put these events in chronological order.", ["Vagabonds Act", "The Theatre built", "Drake returns from circumnavigation", "Roanoke colony founded", "Globe Theatre built", "Poor Law"], "1572; 1576; 1580; 1585; 1599; 1601."),
        W(src("Source B: a description of a beggar, written by a magistrate in Somerset, 1596.", "Rogues and sturdy beggars wander in great troops, robbing and stealing. The poor husbandmen dare not refuse them for fear of having their barns burned."), M("Source B is useful for showing…", ["How some officials feared vagabonds as a threat to order during the hard 1590s", "That there was no poverty in 1596", "The views of the beggars themselves", "Poverty in London only"], 0, "A magistrate's view during the bad harvests shows fear among the authorities. Its provenance means it may exaggerate and does not show beggars' own experiences.")),
        T("The 'Golden Age' was golden for everyone in Elizabethan England.", false, "False. It was golden for the wealthy and for culture, but the 1590s brought famine, plague and poverty for many — an interpretation question favourite."),
      ] },
    { name: 'The Catholic threat and Mary Queen of Scots', intro: "Many Catholics saw Elizabeth's cousin Mary Queen of Scots as the rightful queen. From 1568 Mary was a prisoner in England and became the focus of rebellion and plots.",
      items: [
        S("In which year did Mary Queen of Scots flee to England?", "1568", [], "Mary fled after defeat by Scottish Protestant lords in May 1568. Elizabeth kept her in captivity for nearly 19 years."),
        M("Why was Mary Queen of Scots a threat to Elizabeth?", ["She was Catholic and had a strong claim to the English throne", "She commanded the Spanish army", "She was Elizabeth's daughter", "She was Protestant"], 0, "Mary was a great-granddaughter of Henry VII. Catholics who thought Elizabeth illegitimate saw Mary as the rightful queen."),
        M("What was the Revolt of the Northern Earls (1569)?", ["A Catholic rising in northern England aiming to free Mary and restore Catholicism", "A Puritan protest", "A peasants' revolt over taxes", "A Spanish invasion"], 0, "The Earls of Northumberland and Westmorland captured Durham and held a Catholic Mass, but the rebellion collapsed; around 450 rebels were executed."),
        M("What did the papal bull of 1570 do?", ["Excommunicated Elizabeth and released Catholics from obedience to her", "Made Elizabeth head of the Catholic Church", "Approved her marriage", "Ended the Reformation"], 0, "The bull Regnans in Excelsis made loyalty harder for English Catholics and led to harsher laws against them."),
        O("Put these Catholic plots in chronological order.", ["Ridolfi Plot", "Throckmorton Plot", "Babington Plot"], "1571; 1583; 1586."),
        M("What happened as a result of the Babington Plot?", ["Mary was tried and executed in 1587", "Elizabeth was assassinated", "Mary became queen", "Spain invaded immediately"], 0, "Walsingham intercepted letters (smuggled in beer barrels) in which Mary approved the plot. She was executed at Fotheringhay Castle on 8 February 1587."),
        S("Which Elizabethan minister set the trap that caught Mary in the Babington Plot?", "Francis Walsingham", ["walsingham", "sir francis walsingham"], "Walsingham's double agent Gilbert Gifford and code-breaker Thomas Phelippes read all the letters."),
        M("Who were the Jesuits and seminary priests?", ["Catholic priests trained abroad to secretly minister to English Catholics", "Puritan preachers", "Spanish soldiers", "Elizabeth's bodyguards"], 0, "Seminary priests came from Douai (from 1574); Jesuits such as Edmund Campion arrived in 1580. Campion was executed in 1581."),
        T("Elizabeth hesitated to execute Mary because killing an anointed queen set a dangerous precedent.", true, "True. Elizabeth delayed for months and later claimed the warrant was sent without her permission, punishing her secretary Davison."),
        MU("Which TWO were consequences of Mary's execution?", ["The main Catholic focus for plots in England was removed", "Philip II of Spain was more determined to invade", "England became Catholic", "Scotland declared war on Spain", "The Pope supported Elizabeth"], [0, 1], "Mary's death removed a figurehead but strengthened Philip's resolve; Mary had left her claim to him."),
        M("What did the Puritans want?", ["To remove remaining Catholic features from the Church of England", "To restore the Pope", "To close Parliament", "To ban the Bible in English"], 0, "Puritans wanted simpler services, no vestments and no bishops in some cases. Elizabeth saw them as a threat to her Settlement."),
        S("Which Archbishop of Canterbury was suspended for refusing to ban Puritan 'prophesyings' in 1577?", "Edmund Grindal", ["grindal", "archbishop grindal"], "Grindal refused Elizabeth's order and was suspended; his successor Whitgift took a harder line."),
        W(src("Interpretation B: a historian writing in 2010.", "The Catholic threat to Elizabeth was always exaggerated by Walsingham, who needed plots to justify his spies and to persuade the queen to act against Mary."), M("Which knowledge best CHALLENGES Interpretation B?", ["The Northern Rebellion of 1569 involved thousands of armed Catholics", "Walsingham used agents provocateurs in the Babington Plot", "Most English Catholics remained loyal during the Armada", "Plots were small and quickly uncovered"], 0, "A real armed rising challenges the claim that the threat was exaggerated. The other options support it.")),
        M("Why did Elizabeth's policy towards Catholics become harsher after 1570?", ["The papal bull made Catholicism look like treason", "Catholics had become Protestant", "Spain asked her to", "Parliament abolished the Church"], 0, "From 1581 fines for recusancy rose to £20 a month, and it became treason to convert anyone to Catholicism."),
        T("Mary Queen of Scots was Elizabeth's sister.", false, "False. She was her cousin once removed: Mary's grandmother, Margaret Tudor, was Henry VIII's sister."),
      ] },
    { name: 'Spain and the Armada', intro: "Religious rivalry, trade, piracy and the Dutch revolt brought England and Spain to war in 1585. In 1588 Philip II sent the Armada, which was defeated by English tactics, Spanish problems and the weather.",
      items: [
        M("Who was the King of Spain who launched the Armada?", ["Philip II", "Charles V", "Ferdinand", "Louis XIV"], 0, "Philip II had been married to Mary I and had once proposed to Elizabeth."),
        MU("Which TWO were causes of war between England and Spain?", ["English privateers such as Drake attacked Spanish treasure ships and colonies", "England sent troops to help the Dutch rebels (Treaty of Nonsuch, 1585)", "Spain had become Protestant", "Elizabeth married Philip II", "England invaded Spain in 1580"], [0, 1], "Privateering, support for the Dutch Protestant revolt, religious rivalry and Mary's execution all contributed."),
        S("What was the 1585 treaty in which Elizabeth agreed to send an army to the Netherlands?", "Treaty of Nonsuch", ["nonsuch", "the treaty of nonsuch"], "Robert Dudley led around 7,000 troops — effectively war with Spain."),
        M("What was Drake's raid on Cádiz (1587) called?", ["'Singeing the King of Spain's beard'", "'The Protestant wind'", "'The Golden Speech'", "'The Great Stink'"], 0, "Drake destroyed around 30 ships and barrel-making supplies, delaying the Armada by a year."),
        M("Who commanded the Spanish Armada?", ["The Duke of Medina Sidonia", "The Duke of Parma", "Francis Drake", "Lord Howard of Effingham"], 0, "Medina Sidonia was a nobleman with little naval experience. Parma commanded the Spanish army in the Netherlands; Howard led the English fleet."),
        S("In which year did the Spanish Armada sail?", "1588", [], "The Armada of about 130 ships left Lisbon in May 1588 and reached the Channel in July."),
        M("What was the Armada's plan?", ["Sail up the Channel, meet Parma's army in the Netherlands and escort it to invade England", "Attack Ireland only", "Blockade London for a year", "Sail around the world"], 0, "The plan depended on linking with Parma, but there was no deep-water port and Dutch ships blocked his barges."),
        M("What did the English do on the night the Armada anchored at Calais?", ["Sent in fireships, breaking up the Spanish crescent formation", "Surrendered", "Boarded every ship", "Sailed home"], 0, "Eight fireships caused panic; Spanish ships cut their anchors and scattered, then were attacked at Gravelines."),
        S("At which battle off the Flemish coast was the Armada defeated in 1588?", "Gravelines", ["battle of gravelines"], "At Gravelines English ships used long-range guns and manoeuvrability to damage the scattered Spanish fleet."),
        MU("Which TWO English advantages helped defeat the Armada?", ["Faster, more manoeuvrable ships", "Better long-range guns and gunners who reloaded quickly", "Many more soldiers on board", "Support from the French fleet", "A larger number of ships twice the size"], [0, 1], "English 'race-built' galleons and their guns outperformed the Spanish, whose tactics relied on grappling and boarding."),
        T("Many Armada ships were wrecked by storms off Scotland and Ireland on their way home.", true, "True. Forced to sail around the north of Britain, around a third of the fleet was lost, mainly to storms — the 'Protestant wind'."),
        M("Where did Elizabeth make her famous speech to troops in August 1588?", ["Tilbury", "Greenwich", "Plymouth", "Westminster"], 0, "She told the army she had 'the heart and stomach of a king' — powerful propaganda, even though the danger had largely passed."),
        O("Put these events in chronological order.", ["Treaty of Nonsuch", "Execution of Mary Queen of Scots", "Raid on Cádiz", "Armada sails from Lisbon", "Fireships at Calais", "Tilbury speech"], "1585; February 1587; April 1587; May 1588; July 1588 (late July Old Style); August 1588."),
        W(src("Source C: the 'Armada Portrait' of Elizabeth I, painted c.1588, described.", "Elizabeth sits in rich clothes covered in pearls. Her hand rests on a globe. Through one window English fireships attack the Armada; through the other Spanish ships are wrecked in a storm."), M("What was the purpose of Source C?", ["To celebrate victory and present Elizabeth as a powerful ruler with ambitions overseas", "To show Elizabeth was poor", "To mourn Mary Queen of Scots", "To criticise the navy"], 0, "Her hand on the globe suggests world power; pearls suggest purity and wealth. It is propaganda — useful for how Elizabeth wanted to be seen.")),
        M("Which statement best explains the defeat of the Armada?", ["A combination of English tactics and ships, Spanish planning problems and the weather", "Only the weather", "Spain chose not to fight", "Elizabeth fought personally"], 0, "Historians weigh several factors; strong answers explain how they combined."),
      ] },
  ],
  {
    overview: "Elizabeth I (1558–1603) ruled through skilful management of her council, favourites and Parliament. Her reign is remembered as a Golden Age of theatre, architecture and exploration, but it also faced poverty, a serious Catholic threat centred on Mary Queen of Scots, and war with Spain culminating in the Armada of 1588. AQA also sets a historic environment question on a specified site, which changes each year.",
    objectives: ["I can explain how Elizabeth governed through the Privy Council, patronage and Parliament.", "I can describe and evaluate the 'Golden Age' and explain why poverty increased.", "I can explain why Mary Queen of Scots was a threat and how plots were dealt with.", "I can explain the causes of war with Spain and the defeat of the Armada.", "I can judge how convincing interpretations of Elizabeth's reign are."],
    keyWords: [
      { term: 'Privy Council', def: 'Elizabeth’s main advisers.' },
      { term: 'Patronage', def: 'Rewarding loyalty with titles, offices and lands.' },
      { term: 'Royal prerogative', def: 'Powers belonging only to the monarch.' },
      { term: 'Recusant', def: 'Catholic who refused to attend Church of England services.' },
      { term: 'Papal bull', def: 'An official order from the Pope.' },
      { term: 'Privateer', def: 'A sea captain licensed by the Crown to attack enemy ships.' },
      { term: 'Vagabond', def: 'Homeless, wandering poor person.' },
      { term: 'Armada', def: 'A fleet of warships — the Spanish invasion fleet of 1588.' },
    ],
    sections: [
      { title: 'Government and the court', html: "<p>Elizabeth ruled with the <b>Privy Council</b> (Cecil, Walsingham, Dudley) and used <b>patronage</b> to secure loyalty. <b>Parliament</b> granted taxes and passed laws but she guarded her <b>prerogative</b> over marriage, succession, religion and foreign policy. In the 1590s faction grew, culminating in the <b>Essex Rebellion</b> (1601).</p>" },
      { title: 'Key dates', html: timeline([["1558", "Elizabeth becomes queen"], ["1559", "Religious Settlement"], ["1568", "Mary Queen of Scots flees to England"], ["1569", "Revolt of the Northern Earls"], ["1570", "Papal bull excommunicates Elizabeth"], ["1571", "Ridolfi Plot"], ["1577–80", "Drake's circumnavigation"], ["1583", "Throckmorton Plot"], ["1585", "Treaty of Nonsuch; war with Spain; Roanoke"], ["1586", "Babington Plot"], ["1587", "Mary executed; raid on Cádiz"], ["1588", "Spanish Armada"], ["1599", "Globe built; Essex fails in Ireland"], ["1601", "Essex Rebellion; Poor Law; Golden Speech"], ["1603", "Elizabeth dies; James VI of Scotland becomes James I"]]) },
      { title: 'Key people', html: people([["William Cecil", "Chief minister; cautious; Lord Burghley."], ["Francis Walsingham", "Spymaster; uncovered the Throckmorton and Babington plots."], ["Robert Dudley", "Favourite; led army to the Netherlands 1585."], ["Earl of Essex", "Favourite turned rebel; executed 1601."], ["Mary Queen of Scots", "Catholic claimant; executed 1587."], ["Francis Drake", "Privateer and explorer; vice-admiral against the Armada."], ["Philip II", "King of Spain; launched the Armada."]]) },
      { title: 'Model answer: ‘Explain what was important about…’ (8 marks)', html: worked("Explain what was important about the Babington Plot for Elizabeth's reign.", ["Importance 1: provided evidence to execute Mary — removing the Catholic figurehead.", "Importance 2: pushed Philip II towards the Armada.", "Use specific detail and explain the consequence."], "Model paragraph: The Babington Plot was important because it finally gave Elizabeth's government the evidence it needed to execute Mary Queen of Scots. Walsingham's agents intercepted Mary's letters, smuggled in beer barrels, in which she approved the plan to murder Elizabeth. This meant Mary could be tried for treason under the 1585 Act for the Queen's Safety and executed in February 1587, removing the main focus of Catholic plotting in England. However, it also gave Philip II a further motive to invade, since Mary had left him her claim to the throne.") },
    ],
    mistakes: ["Saying Mary Queen of Scots was Elizabeth's sister — she was her cousin.", "Calling the reign 'golden' for everyone without considering the poor.", "Explaining the Armada's defeat by the weather alone.", "Forgetting that Parliament met only occasionally."],
    examTips: ["Paper 2 Section B: Q1 'How convincing is Interpretation A?' (8); Q2 'Explain what was important about…' (8); Q3 'Write an account…' (8); Q4 historic environment essay (16).", "In interpretation answers, quote the interpretation and test its claims with precise knowledge.", "Revise the specified historic environment site for your exam year."],
    realLife: "Shakespeare's plays, first performed in Elizabethan playhouses, are still staged worldwide and at the rebuilt Globe in London.",
  },
);

// =====================================================================
// YEAR 11 — GCSE exam skills: sources, interpretations and question types
// =====================================================================
addTopic(
  { id: 'hist-y11-exam-skills', strand: 'hist-skills', year: 11, term: 3, name: 'GCSE Exam Skills: Sources, Interpretations and Question Types',
    summary: 'How to answer every AQA GCSE History question type: source utility, interpretations, describe, explain, write an account, significance and ‘how far do you agree’.',
    specRef: 'AQA 8145 Assessment objectives AO1–AO4 (Papers 1 and 2)' },
  [
    { name: 'Source utility and cartoons', intro: "AQA asks 'How useful is Source…?' and 'How useful are Sources B and C?'. Strong answers analyse content AND provenance, using contextual knowledge to judge usefulness for a specific enquiry.",
      items: [
        M("In a utility question, what does 'provenance' cover?", ["Nature, origin and purpose — what type of source, who made it, when and why", "The number of words", "The colour of the source", "Whether you agree with it"], 0, "AQA mark schemes reward analysis of content and provenance, supported by contextual knowledge."),
        M("Which sentence shows the strongest use of provenance?", ["Because it was published in a nationalist newspaper on the day the treaty was signed, it was written to stir anger, so it is useful for showing how nationalists exploited the treaty", "It is biased so it is not useful", "It is a newspaper so it is reliable", "It was written a long time ago"], 0, "The best answers explain HOW provenance affects usefulness for the enquiry, not simply label bias."),
        T("A source can be useful precisely because it is biased.", true, "True. A propaganda poster is very useful for showing the message a government wanted to spread."),
        MU("Which TWO things should a top answer to 'How useful are Sources B and C?' include?", ["Analysis of each source's content and provenance", "Contextual knowledge that tests what each source says", "A long description of the picture with no analysis", "A summary of the whole topic unrelated to the sources", "A statement that all sources are equally useless"], [0, 1], "Evaluate each source using content, provenance and context; you do not have to compare them directly but a judgement helps."),
        W(src("Source A: a cartoon published in a British magazine, 1934, described.", "A huge German soldier stands behind a tiny figure labelled 'Disarmament Conference', who is holding a sign saying 'Please disarm'. The soldier is laughing."), M("What is the message of the cartoon?", ["Efforts at disarmament were powerless against German rearmament", "Germany had disarmed", "The conference had defeated Germany", "Britain wanted to rearm Germany"], 0, "Size shows power; laughter shows contempt. Linking to context: Germany left the Disarmament Conference in October 1933 and began rearming openly.")),
        M("When analysing a cartoon, what should you do first?", ["Identify the symbols, labels and caption and what each represents", "Count the people", "Decide if it is funny", "Describe the style of drawing only"], 0, "Decode the symbols, then link them to what was happening at the date the cartoon was published."),
        M("Why does the DATE of a cartoon matter?", ["It tells you what events the cartoonist was reacting to", "Older cartoons are always more useful", "It doesn't matter", "Cartoons never have dates"], 0, "A cartoon from March 1936 is likely about the Rhineland; one from September 1938 about Munich."),
        S("What type of knowledge do you use to test what a source says? (one word, e.g. ___ knowledge)", "Contextual", ["context", "own", "own knowledge", "contextual knowledge"], "Contextual knowledge is what you know about the period; it lets you test the accuracy and typicality of a source."),
        W(src("Source B: a photograph published by the Nazi Propaganda Ministry, 1936, described.", "Smiling young men march with spades on their shoulders, building an autobahn. A banner reads 'Work and Bread'."), M("A historian is studying unemployment in Nazi Germany. Which is the best judgement about Source B?", ["Useful for showing how the Nazis publicised job creation, but staged, so it does not show the low pay or invisible unemployment", "Completely reliable evidence that everyone was happy", "Useless because it is a photograph", "Proves unemployment rose"], 0, "Its purpose (propaganda) limits what it shows, but makes it very useful for Nazi messages about work.")),
        T("A source written long after an event cannot be useful.", false, "False. Later sources can use hindsight and more evidence; memoirs can be useful but may be affected by memory or self-justification."),
        M("What is a weakness of using a diary as evidence?", ["It shows one person's view and may not be typical", "Diaries are always lies", "Diaries are secondary sources", "Diaries cannot be dated"], 0, "Ask whether the writer's experience was typical and what they could know."),
        M("Which question is about a source's typicality?", ["Would most people at the time have shared this view or experience?", "Who printed it?", "How long is it?", "Is it in colour?"], 0, "Typicality matters: one soldier's letter may or may not reflect the experience of many."),
        O("Put these steps for a utility answer in a sensible order.", ["Identify what the source says or shows", "Test the content with contextual knowledge", "Analyse provenance — nature, origin, purpose", "Explain how provenance affects usefulness", "Reach a judgement for the specific enquiry"], "Content → knowledge → provenance → effect on usefulness → judgement."),
        S("In which AQA paper section are you asked 'How useful are Sources B and C?' for 12 marks? (topic name)", "Conflict and tension", ["wider world depth study", "conflict", "conflict and tension 1918-1939", "paper 1 section b"], "The 12-mark two-source utility question is in Paper 1 Section B (wider world depth study, e.g. Conflict and tension)."),
        M("Which is the most precise inference from a poster saying 'Women of Britain say — Go!' (1915)?", ["The government used women to pressure men to volunteer before conscription", "Women were conscripted", "All men refused to fight", "The poster was made in 1939"], 0, "The date (1915, before conscription in 1916) and message show recruitment pressure through social expectation."),
      ] },
    { name: 'Interpretations: differ, why, how convincing', intro: "AQA Paper 1 Section A asks how two interpretations differ, why they might differ, and which is more convincing. Paper 2 Section B asks how convincing one interpretation is.",
      items: [
        M("For 'How does Interpretation B differ from Interpretation A?' (4 marks), what must you do?", ["Identify a difference in their views and support it with content from both", "Say which is right", "Describe the authors' lives", "Write about provenance only"], 0, "Pinpoint the difference in the arguments and support with details from both interpretations."),
        M("For 'Why might the authors have a different interpretation?' (4 marks), a strong answer focuses on…", ["Differences in provenance — e.g. the authors' situation, purpose, or the time and audience they wrote for", "Which one has more words", "Which one you prefer", "Spelling mistakes"], 0, "E.g. one author lived through the events as a supporter, the other is a later historian focusing on different evidence."),
        M("For 'Which interpretation is more convincing?' (8 marks) you should…", ["Test both against your own knowledge and reach a supported judgement", "Choose the longer one", "Describe both in detail without judgement", "Only discuss provenance"], 0, "The convincing question is mainly about how well each fits the historical evidence."),
        T("In a 'how convincing' answer you should only use knowledge that supports the interpretation.", false, "False. Top answers use knowledge both to support and to challenge before reaching a balanced judgement."),
        W(src("Interpretation C: from the memoirs of a woman who was a teenager in Nazi Germany, published in 1980.", "We loved the Hitler Youth camps — the singing, the hiking, the feeling that we mattered. Only later did I understand what it was all for."), M("Why might Interpretation C differ from a historian's interpretation of the Hitler Youth?", ["She is recalling her own experience as a young participant, while a historian studies many sources including opponents", "She had no experience", "Historians never study youth groups", "She was writing propaganda in 1936"], 0, "Personal experience and hindsight shape her view; she admits later understanding — a sign of reflection.")),
        S("What word describes a historian's later understanding of events, knowing what happened next?", "Hindsight", [], "Hindsight can explain why interpretations differ from views held at the time."),
        MU("Which TWO are valid reasons why two interpretations of Haig might differ?", ["One author was a soldier who lost friends at the Somme; the other is a military historian studying 1918 victories", "They were written for different purposes and audiences", "One is in a different font", "One author is taller", "Both used exactly the same evidence and purpose"], [0, 1], "Experience, purpose, audience and evidence all explain differences."),
        W(src("Interpretation D: a historian writing in 2009.", "Elizabeth's reign was a time of national triumph: the Armada defeated, the arts flourishing and England confident as never before."), M("Which knowledge best CHALLENGES Interpretation D?", ["The 1590s brought bad harvests, rising poverty and the need for the 1601 Poor Law", "Shakespeare's plays were performed at the Globe", "The Armada was defeated in 1588", "Drake sailed around the world"], 0, "Evidence of poverty and hardship challenges 'national triumph'. The other options support it.")),
        M("What is the best way to start a 'How convincing is Interpretation A?' answer?", ["State the interpretation's main argument and your overall view", "Copy out the whole interpretation", "Write about another topic", "Start with the date only"], 0, "A clear argument from the first line shows the examiner your judgement."),
        T("An interpretation from someone who lived through events is automatically more convincing.", false, "False. Being there gives first-hand insight but limited perspective; convincingness depends on how well it fits the wider evidence."),
        M("Which phrase signals evaluation rather than description?", ["'This is convincing to an extent because…, however…'", "'The interpretation says…'", "'The author is called…'", "'This was written in…'"], 0, "Evaluation language weighs strengths and limitations."),
        O("Put the parts of a 'which is more convincing' answer in order.", ["Explain what Interpretation A argues", "Test A with knowledge for and against", "Explain what Interpretation B argues", "Test B with knowledge for and against", "Judge which is more convincing and why"], "Analyse and test each, then reach a comparative judgement."),
        S("What word describes a view of the past written to make a person or regime look good?", "Propaganda", ["biased", "bias"], "Propaganda is deliberate persuasion; interpretations can also be shaped by political sympathies."),
        M("An interpretation says 'The Nazis came to power through popular votes.' Which is the most precise challenge?", ["The Nazis never won over 37.3% in a free election, and Hitler was appointed by Hindenburg", "Hitler wrote Mein Kampf", "The SA wore brown shirts", "The Olympic Games were in 1936"], 0, "Precise statistics directly test the claim — this is what 'precise and relevant knowledge' means."),
        M("Which mark range in AQA's 8-mark interpretation questions usually needs a sustained judgement?", ["The top level (7–8 marks)", "Level 1 (1–2 marks)", "No level", "Only the 4-mark questions"], 0, "Top-level answers give complex evaluation with a sustained, substantiated judgement."),
      ] },
    { name: 'Question types and command words', intro: "Each AQA question type rewards a different skill. Knowing the command words and mark allocations helps you write the right amount in the right way.",
      items: [
        M("For 'Describe two problems faced by…' (4 marks), what do you need?", ["Two problems, each with a specific supporting detail", "One long essay", "A judgement", "Analysis of sources"], 0, "Describe questions test knowledge: identify and add detail; no judgement needed."),
        M("What is the key skill in 'Explain why…' questions?", ["Showing HOW each factor caused the outcome, with evidence", "Listing as many facts as possible", "Describing the event", "Quoting sources"], 0, "Explanation means causation: point → evidence → explain link to the question."),
        M("'Write an account of how…' (8 marks) asks you to…", ["Create a narrative that explains how events led to an outcome", "Describe one picture", "Compare two sources", "Give your opinion only"], 0, "Accounts sequence events and use connectives like 'this led to' and 'as a result' to show causation."),
        M("In a 16-mark 'How far do you agree?' question, how many extra marks are given for spelling, punctuation and grammar?", ["4", "2", "8", "0"], 0, "SPaG gives 4 marks on the essay question in Paper 1 Section B and Paper 2 Section A."),
        S("How many hours long is each AQA GCSE History paper?", "2", ["two", "2 hours", "two hours"], "Each paper is 2 hours and worth 84 marks (including 4 for SPaG)."),
        MU("Which TWO features are needed for a top-level 16-mark answer?", ["Balanced explanation of the stated factor and other factors", "A sustained, substantiated judgement", "Only one side of the argument", "Bullet points without explanation", "A long introduction repeating the question"], [0, 1], "Explain both sides with precise knowledge and argue a consistent judgement throughout."),
        M("For 'Explain the significance of…' (Health and the people), what should you consider?", ["Its impact at the time and its long-term impact", "Only the date it happened", "Who opposed it only", "The cost of the event"], 0, "Significance is about consequences — short-term and long-term, and how far it changed things."),
        M("What does the Health question 'Explain two ways in which X and Y were similar' test?", ["Comparison across time using specific knowledge of both", "Description of one event", "Source analysis", "Spelling"], 0, "Identify a similarity (e.g. role of government or chance) and support with detail from both events."),
        T("In 'Which of the following was the more important reason…?' (12 marks) you should explain both bullet points before making a judgement.", true, "True. Explain each factor fully, then compare them directly and justify which mattered more."),
        O("Put the parts of a PEEL paragraph in order.", ["Point — answer the question directly", "Evidence — precise facts", "Explain — show how the evidence supports the point", "Link — back to the question"], "PEEL keeps paragraphs analytical rather than descriptive."),
        M("Which is the best opening for 'Explain why the League failed in Abyssinia'?", ["'One reason the League failed was that its sanctions were weak, because they excluded oil…'", "'Abyssinia is in Africa.'", "'Mussolini was born in 1883.'", "'I will now write about the League.'"], 0, "Start with a direct, analytical point answering the question."),
        S("What is the term for the 'thread' of argument that runs through a strong essay, starting in the introduction? (one word)", "Judgement", ["judgment", "argument", "line of argument"], "A sustained judgement is introduced early, developed through paragraphs and confirmed in the conclusion."),
        M("Roughly how long should you spend on a 4-mark question in a 2-hour, 84-mark paper?", ["About 5 minutes", "About 30 minutes", "About 1 minute", "About an hour"], 0, "Roughly 1¼–1½ minutes per mark, so a 4-mark question needs about 5 minutes."),
        W(src("Student answer extract (Write an account, 8 marks).", "In 1938 Germany took Austria. Then there was the Munich Agreement. Then Germany took Czechoslovakia. Then the war started."), M("How could this answer be improved?", ["Add precise detail and explain how each event led to the next and to war", "Make it shorter", "Remove the dates", "Add an unrelated paragraph"], 0, "It is a basic list. Strong accounts explain consequences: e.g. Munich encouraged Hitler, so he took Prague in March 1939, ending appeasement.")),
        M("Which connective best shows causation in an account?", ["'This led to…'", "'Also…'", "'Furthermore, in other news…'", "'Firstly, secondly…' only"], 0, "Causal connectives ('as a result', 'this meant that', 'consequently') show analysis."),
      ] },
    { name: 'Chronology and judgement across the course', intro: "Strong GCSE answers place events accurately in time and link them across topics. This style mixes the four AQA options to test chronology and judgement.",
      items: [
        O("Put these events from across the course in chronological order.", ["Spanish Armada", "Jenner's vaccination", "Pasteur's germ theory", "Treaty of Versailles", "Hitler becomes Chancellor"], "1588; 1796; 1861; 1919; 1933."),
        O("Put these German events in order.", ["Kaiser abdicates", "Hyperinflation", "Dawes Plan", "Wall Street Crash", "Enabling Act"], "1918; 1923; 1924; 1929; 1933."),
        O("Put these international events in order.", ["League of Nations begins work", "Corfu crisis", "Mukden Incident", "Italy invades Abyssinia", "Munich Agreement"], "1920; 1923; 1931; 1935; 1938."),
        O("Put these Elizabethan events in order.", ["Religious Settlement", "Northern Rebellion", "Execution of Mary Queen of Scots", "Spanish Armada", "Poor Law"], "1559; 1569; 1587; 1588; 1601."),
        O("Put these health developments in order.", ["Vesalius's anatomy", "Harvey's circulation", "Chloroform used as anaesthetic", "Penicillin discovered", "NHS founded"], "1543; 1628; 1847; 1928; 1948."),
        M("Which link across topics is accurate?", ["Wartime experience helped create the NHS, just as war sped up penicillin production", "The Armada caused the Black Death", "The League of Nations founded the NHS", "Pasteur fought in the Armada"], 0, "Linking war and medicine is a valid thematic connection."),
        M("Which German event happened in the same year as Kristallnacht?", ["The Anschluss and the Munich Agreement (1938)", "The Enabling Act", "The Spartacist uprising", "The Treaty of Versailles"], 0, "1938: Anschluss (March), Munich (September), Kristallnacht (November)."),
        S("In which year did both the Wall Street Crash happen and Stresemann die?", "1929", [], "Stresemann died in October 1929, weeks before the Wall Street Crash — a double blow to Weimar."),
        T("The Great Depression contributed both to the rise of Hitler and to the failure of the League of Nations.", true, "True. It increased Nazi support and pushed Japan and Italy towards aggression while making Britain and France reluctant to impose sanctions."),
        M("Which statement shows a sustained judgement?", ["'Although the weather played a part, the Armada was defeated mainly because English ships and guns outclassed the Spanish, which the weather only completed.'", "'There were many reasons.'", "'The weather was bad.'", "'I think it was all of them equally.'"], 0, "A sustained judgement weighs factors and states which mattered most and why."),
        MU("Which TWO are examples of the factor 'government' in Health and the people?", ["The 1875 Public Health Act", "The creation of the NHS in 1948", "Fleming noticing mould", "Paré running out of oil", "Harvey's experiments"], [0, 1], "Fleming and Paré illustrate chance; Harvey illustrates science/individuals."),
        M("Which of these is a change, rather than a continuity, between 1890 and 1933 in Germany?", ["Germany moved from rule by a Kaiser to a democratic republic", "Germany had a strong army tradition", "Nationalists wanted a powerful Germany", "Industry remained important"], 0, "The others are continuities across the period."),
        S("What word means things staying the same over time?", "Continuity", ["continuities"], "Historians balance change and continuity, e.g. Galen's ideas showed continuity for 1,400 years."),
        M("Which is the best example of a TURNING POINT?", ["Germ theory (1861), which transformed understanding of the cause of disease", "A single bad harvest", "Elizabeth's progress to a country house", "A cartoon about the League"], 0, "A turning point causes a fundamental change in direction."),
        W(src("Exam question.", "'The main reason why Hitler was able to achieve his aims between 1933 and 1938 was the weakness of Britain and France.' How far do you agree?"), M("Which plan would score highest?", ["Explain appeasement and Anglo-French weakness, then other factors (League failure, Hitler's skill, Versailles grievances, the USSR), and judge consistently", "Describe the Rhineland only", "List dates from 1933 to 1938", "Write about the Armada"], 0, "A balanced, analytical plan with a sustained judgement is needed for the top level.")),
      ] },
  ],
  {
    overview: "AQA GCSE History (8145) is assessed in two 2-hour papers. Each question type rewards a particular skill: knowledge (describe), explanation (explain, account, significance), source analysis (how useful), interpretation analysis (differ, why, how convincing) and extended judgement (how far do you agree; which was more important). This topic trains all of them across the four options.",
    objectives: ["I can analyse sources for content, provenance and usefulness.", "I can explain how and why interpretations differ and judge how convincing they are.", "I can recognise every AQA question type and know how to structure answers.", "I can write a sustained judgement in extended answers.", "I can place key events from all four options in chronological order."],
    keyWords: [
      { term: 'Provenance', def: 'Nature, origin and purpose of a source.' },
      { term: 'Utility', def: 'How useful a source is for a specific enquiry.' },
      { term: 'Interpretation', def: 'A later view or argument about the past.' },
      { term: 'Contextual knowledge', def: 'Your own knowledge of the period used to test sources and interpretations.' },
      { term: 'Significance', def: 'The importance of an event or person, judged by its impact.' },
      { term: 'Judgement', def: 'A reasoned conclusion that answers the question.' },
      { term: 'SPaG', def: 'Spelling, punctuation and grammar — 4 marks on certain essays.' },
    ],
    sections: [
      { title: 'The papers at a glance', html: "<table class=\"qt\"><tr><th>Paper / section</th><th>Questions</th></tr><tr><td>Paper 1A Germany 1890–1945</td><td>Q1 differ (4) · Q2 why differ (4) · Q3 more convincing (8) · Q4 describe (4) · Q5 in what ways (8) · Q6 which more important (12)</td></tr><tr><td>Paper 1B Conflict and tension</td><td>Q1 source inference (4) · Q2 how useful are B and C (12) · Q3 write an account (8) · Q4 how far do you agree (16 + 4 SPaG)</td></tr><tr><td>Paper 2A Health and the people</td><td>Q1 how useful (8) · Q2 significance (8) · Q3 compare (8) · Q4 factor essay (16 + 4 SPaG)</td></tr><tr><td>Paper 2B Elizabethan England</td><td>Q1 how convincing (8) · Q2 what was important (8) · Q3 write an account (8) · Q4 historic environment (16)</td></tr></table><div class=\"note\">Each paper: 2 hours, 84 marks including 4 for SPaG.</div>" },
      { title: 'Sources and interpretations', html: "<ul><li><b>Sources:</b> content + provenance (nature, origin, purpose) + context → usefulness for this enquiry.</li><li><b>Interpretations:</b> identify the argument; explain differences through provenance; test with knowledge for and against; judge.</li></ul><div class=\"rule\">Never write 'it is biased so it is useless'. Ask: useful for what?</div>" },
      { title: 'Writing explanations and essays', html: "<p>Use <b>PEEL</b> paragraphs. In accounts, use causal connectives. In 12- and 16-mark questions, explain each factor fully, compare their importance and state a clear judgement in the introduction, through the paragraphs and in the conclusion.</p>" },
      { title: 'Model answer: how convincing (8 marks)', html: worked("How convincing is Interpretation D about Elizabeth's reign being a time of 'national triumph'?", ["Support: Armada defeated 1588; Shakespeare and the Globe; Drake's circumnavigation.", "Challenge: poverty and harvest failure in the 1590s; Essex Rebellion 1601; costly war in Ireland.", "Judgement: convincing for the elite and for England's international standing, less so for the poor."], "Model paragraph: Interpretation D is convincing to an extent because the defeat of the Armada in 1588 was a genuine triumph that ended the immediate threat of Spanish invasion and was celebrated in propaganda such as the Armada Portrait. However, it is less convincing as a description of the whole reign, because the 1590s saw four bad harvests, soaring food prices and growing vagrancy, which forced Parliament to pass the 1601 Poor Law. For ordinary people the final years were hardly a 'triumph', so the interpretation reflects the experience of the elite more than that of the nation.") },
    ],
    mistakes: ["Describing a source without evaluating its usefulness.", "Writing a one-sided essay for a 'how far' question.", "Spending too long on low-mark questions.", "Leaving the judgement only to the final sentence."],
    examTips: ["Spend roughly 1¼–1½ minutes per mark.", "Underline the command word and the focus of the enquiry before writing.", "Plan 16-mark essays for 2–3 minutes: factors for, factors against, judgement."],
    realLife: "Evaluating sources and testing arguments against evidence are key skills in law, journalism and everyday media literacy.",
  },
);
